fn main(input: Dir) -> Result<Str, Error> {
    let text: Str = input.read_to_string("text.txt")?;

    // Split the text into lowercase words made only of ASCII letters.
    let mut words: Vec<Str> = Vec::new();
    let mut cur: Str = Str::new();
    for c in text.chars() {
        if c.is_ascii_alphabetic() {
            cur.push(c.to_ascii_lowercase());
        } else {
            if cur.len() > 0 {
                words.push(cur.clone());
                cur = Str::new();
            }
        }
    }
    if cur.len() > 0 {
        words.push(cur.clone());
    }

    // Sort the words so that equal words sit next to each other.
    words.sort();

    // Count each run of equal words.
    let mut counts: Vec<(Str, i64)> = Vec::new();
    let mut i: usize = 0;
    while i < words.len() {
        let mut j: usize = i;
        while j < words.len() && words[j] == words[i] {
            j += 1;
        }
        counts.push((words[i].clone(), (j - i) as i64));
        i = j;
    }

    // Order by count, highest first; equal counts alphabetically.
    counts.sort_by(|a, b| {
        if a.1 != b.1 {
            b.1.cmp(&a.1)
        } else {
            a.0.cmp(&b.0)
        }
    });

    // Keep the top five, one per line as `word count`.
    let mut out: Str = Str::new();
    let mut k: usize = 0;
    while k < counts.len() && k < 5 {
        out.push_str(&counts[k].0);
        out.push_str(" ");
        out.push_str(&counts[k].1.to_string());
        out.push_str("\n");
        k += 1;
    }
    Ok(out)
}

