fn parse_int(s: &Str) -> Option<i64> {
    let t = s.trim();
    if t.len() == 0 {
        return None;
    }
    let mut neg = false;
    let mut val: i64 = 0;
    let mut digits = 0;
    let mut first = true;
    for c in t.chars() {
        if first && (c == '-' || c == '+') {
            neg = c == '-';
            first = false;
            continue;
        }
        first = false;
        if c >= '0' && c <= '9' {
            val = val * 10 + ((c as i64) - ('0' as i64));
            digits = digits + 1;
        } else {
            return None;
        }
    }
    if digits == 0 {
        return None;
    }
    if neg {
        Some(-val)
    } else {
        Some(val)
    }
}

fn dollars(cents: i64) -> Str {
    let mut c = cents;
    let mut sign = "";
    if c < 0 {
        sign = "-";
        c = -c;
    }
    let whole = c / 100;
    let frac = c % 100;
    if frac < 10 {
        format!("{}{}.0{}", sign, whole, frac)
    } else {
        format!("{}{}.{}", sign, whole, frac)
    }
}

fn main(input: Dir) -> Result<Str, Error> {
    let text = input.read_to_string("sales.csv")?;
    let mut names: Vec<Str> = Vec::new();
    let mut qtys: Vec<i64> = Vec::new();
    let mut revs: Vec<i64> = Vec::new();
    let mut skipped: i64 = 0;
    let mut is_header = true;

    for raw in text.lines() {
        if is_header {
            is_header = false;
            continue;
        }
        let line = raw.trim();
        if line.len() == 0 {
            continue;
        }
        let fields: Vec<Str> = line.split(',').map(|f| f.trim().to_string()).collect();
        if fields.len() != 5 {
            skipped = skipped + 1;
            continue;
        }
        let q = parse_int(&fields[3]);
        let u = parse_int(&fields[4]);
        if q.is_none() || u.is_none() {
            skipped = skipped + 1;
            continue;
        }
        let qv = q.unwrap();
        let uv = u.unwrap();
        let region = fields[1].clone();
        let mut found = false;
        let mut i = 0;
        while i < names.len() {
            if names[i] == region {
                qtys[i] = qtys[i] + qv;
                revs[i] = revs[i] + qv * uv;
                found = true;
                break;
            }
            i = i + 1;
        }
        if !found {
            names.push(region);
            qtys.push(qv);
            revs.push(qv * uv);
        }
    }

    // index order, insertion sort: revenue desc, then name asc
    let mut order: Vec<usize> = Vec::new();
    let mut k = 0;
    while k < names.len() {
        order.push(k);
        k = k + 1;
    }
    let mut a = 1;
    while a < order.len() {
        let mut b = a;
        while b > 0 {
            let x = order[b - 1];
            let y = order[b];
            let swap = revs[y] > revs[x] || (revs[y] == revs[x] && names[y] < names[x]);
            if swap {
                order[b - 1] = y;
                order[b] = x;
                b = b - 1;
            } else {
                break;
            }
        }
        a = a + 1;
    }

    let mut out = String::new();
    for idx in order {
        out.push_str(&format!("{} {} {}\n", names[idx], qtys[idx], dollars(revs[idx])));
    }
    out.push_str(&format!("skipped {}\n", skipped));
    Ok(out)
}

