fn main(input: Dir) -> Result<Str, Error> {
    let text = input.read_to_string("access.log")?;

    let mut statuses: Vec<(u32, u64)> = Vec::new();
    let mut paths: Vec<(String, u64)> = Vec::new();
    let mut errors: Vec<(String, u64)> = Vec::new();
    let mut total: u64 = 0;

    for line in text.lines() {
        let parts: Vec<&str> = line.split('"').collect();
        if parts.len() != 3 {
            continue;
        }

        let pre: Vec<&str> = parts[0].split_whitespace().collect();
        if pre.len() < 4 || !pre[3].starts_with('[') {
            continue;
        }
        let ip = pre[0];

        let req: Vec<&str> = parts[1].split_whitespace().collect();
        if req.len() != 3 {
            continue;
        }
        let path = match req[1].find('?') {
            Some(i) => &req[1][..i],
            None => req[1],
        };

        let tail: Vec<&str> = parts[2].split_whitespace().collect();
        if tail.len() != 2 {
            continue;
        }

        let st = tail[0];
        if st.len() != 3 || !st.chars().all(|c| c.is_ascii_digit()) {
            continue;
        }
        let status: u32 = match st.parse::<u32>() {
            Ok(v) => v,
            Err(_) => continue,
        };

        let size: u64 = if tail[1] == "-" {
            0
        } else {
            if !tail[1].chars().all(|c| c.is_ascii_digit()) {
                continue;
            }
            match tail[1].parse::<u64>() {
                Ok(v) => v,
                Err(_) => continue,
            }
        };

        total += size;

        let mut found = false;
        for e in statuses.iter_mut() {
            if e.0 == status {
                e.1 += 1;
                found = true;
                break;
            }
        }
        if !found {
            statuses.push((status, 1));
        }

        let mut found = false;
        for e in paths.iter_mut() {
            if e.0 == path {
                e.1 += 1;
                found = true;
                break;
            }
        }
        if !found {
            paths.push((path.to_string(), 1));
        }

        if status >= 500 && status <= 599 {
            let mut found = false;
            for e in errors.iter_mut() {
                if e.0 == ip {
                    e.1 += 1;
                    found = true;
                    break;
                }
            }
            if !found {
                errors.push((ip.to_string(), 1));
            }
        }
    }

    statuses.sort_by(|a, b| a.0.cmp(&b.0));
    errors.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));

    let mut out = String::new();
    for (s, c) in statuses.iter() {
        out.push_str(&format!("{} {}\n", s, c));
    }
    out.push_str(&format!("bytes {}\n", total));

    let mut best: Option<(String, u64)> = None;
    for (p, c) in paths.iter() {
        let better = match &best {
            None => true,
            Some((bp, bc)) => *c > *bc || (*c == *bc && p < bp),
        };
        if better {
            best = Some((p.clone(), *c));
        }
    }
    if let Some((p, c)) = best {
        out.push_str(&format!("top {} {}\n", p, c));
    }

    for (ip, c) in errors.iter() {
        out.push_str(&format!("errors {} {}\n", ip, c));
    }

    Ok(out)
}

