        let size: u64 = if sz == "-" {
            0
        } else {
            if sz.len() == 0 || !sz.chars().all(|c| c.is_ascii_digit()) {
                continue;
            }
            match sz.parse::<u64>() {
                Ok(v) => v,
                Err(_) => continue,
            }
        };

        total += size;

        let mut found = false;
        let mut i: usize = 0;
        while i < statuses.len() {
            if statuses[i].0 == status {
                statuses[i].1 += 1;
                found = true;
                break;
            }
            i += 1;
        }
        if !found {
            statuses.push((status, 1));
        }

        let mut found = false;
        let mut i: usize = 0;
        while i < paths.len() {
            if paths[i].0 == path {
