            }
            i += 1;
        }
        out = format!("{}top {} {}\n", out, best_p, best_c);
    }

    let mut i: usize = 0;
    while i < errors.len() {
        out = format!("{}errors {} {}\n", out, errors[i].0, errors[i].1);
        i += 1;
    }

    Ok(out)
}

