        let qp: Vec<Str> = req[1].split("?").collect();
        if qp.len() == 0 {
            continue;
        }
        let path: Str = qp[0].clone();

        let tail: Vec<Str> = parts[2].split_whitespace().collect();
        if tail.len() != 2 {
            continue;
        }

        let st: Str = tail[0].clone();
        if st.len() != 3 || st.starts_with("+") || st.starts_with("-") {
            continue;
        }
        let status_r: Result<u32, Error> = st.parse();
        let status: u32 = match status_r {
            Ok(v) => v,
            Err(_) => continue,
        };

        let sz: Str = tail[1].clone();
        let mut size: u64 = 0;
        if sz != "-" {
            if sz.len() == 0 || sz.starts_with("+") || sz.starts_with("-") {
                continue;
            }
            let size_r: Result<u64, Error> = sz.parse();
            size = match size_r {
                Ok(v) => v,
                Err(_) => continue,
            };
        }

        total += size;

        let mut found = false;
        let mut i: usize = 0;
        while i < statuses.len() {
            if statuses[i].code == status {
                statuses[i].count += 1;
                found = true;
                break;
            }
            i += 1;
        }
        if !found {
            statuses.push(StatusCount { code: status, count: 1 });
        }

        let mut found = false;
        let mut i: usize = 0;
        while i < paths.len() {
            if paths[i].name == path {
                paths[i].count += 1;
                found = true;
                break;
            }
            i += 1;
        }
        if !found {
            paths.push(NameCount { name: path.clone(), count: 1 });
        }

        if status >= 500 && status <= 599 {
            let mut found = false;
            let mut i: usize = 0;
            while i < errors.len() {
                if errors[i].name == ip {
                    errors[i].count += 1;
                    found = true;
                    break;
                }
                i += 1;
            }
            if !found {
                errors.push(NameCount { name: ip.clone(), count: 1 });
            }
        }
    }

    let mut i: usize = 1;
    while i < statuses.len() {
        let mut j: usize = i;
        while j > 0 && statuses[j - 1].code > statuses[j].code {
            statuses.swap(j - 1, j);
            j -= 1;
        }
        i += 1;
    }

    let mut i: usize = 1;
    while i < errors.len() {
        let mut j: usize = i;
        while j > 0 {
            let a_c: u64 = errors[j - 1].count;
            let b_c: u64 = errors[j].count;
            let a_ip: Str = errors[j - 1].name.clone();
            let b_ip: Str = errors[j].name.clone();
            let out_of_order = a_c < b_c || (a_c == b_c && a_ip > b_ip);
            if !out_of_order {
                break;
            }
            errors.swap(j - 1, j);
            j -= 1;
        }
        i += 1;
    }

    let mut out: Str = Str::new();
    let mut i: usize = 0;
    while i < statuses.len() {
        out = format!("{}{} {}\n", out, statuses[i].code, statuses[i].count);
        i += 1;
    }
    out = format!("{}bytes {}\n", out, total);

    if paths.len() > 0 {
        let mut best_p: Str = paths[0].name.clone();
        let mut best_c: u64 = paths[0].count;
        let mut i: usize = 1;
        while i < paths.len() {
            let p: Str = paths[i].name.clone();
            let c: u64 = paths[i].count;
            if c > best_c || (c == best_c && p < best_p) {
                best_p = p;
                best_c = c;
            }
            i += 1;
        }
        out = format!("{}top {} {}\n", out, best_p, best_c);
    }

    let mut i: usize = 0;
    while i < errors.len() {
        out = format!("{}errors {} {}\n", out, errors[i].name, errors[i].count);
        i += 1;
    }

    Ok(out)
}

enum Json {
    Null,
    Bool(bool),
    Num(i64),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

fn skip_ws(b: &Vec<u8>, i: &mut usize) {
    while *i < b.len() {
        let c = b[*i];
        if c == b' ' || c == b'\n' || c == b'\r' || c == b'\t' {
            *i += 1;
        } else {
            break;
        }
    }
}

fn hex_val(c: u8) -> u32 {
    if c >= b'0' && c <= b'9' {
        (c - b'0') as u32
    } else if c >= b'a' && c <= b'f' {
        (c - b'a' + 10) as u32
    } else if c >= b'A' && c <= b'F' {
        (c - b'A' + 10) as u32
    } else {
        0
    }
}

fn parse_string(text: &Str, b: &Vec<u8>, i: &mut usize) -> Str {
    // assumes b[*i] == '"'
    *i += 1;
    let mut out = Str::new();
    let mut seg = *i;
    while *i < b.len() {
        let c = b[*i];
        if c == b'"' {
            out.push_str(&text[seg..*i]);
            *i += 1;
            return out;
        } else if c == b'\\' {
            out.push_str(&text[seg..*i]);
            *i += 1;
            if *i >= b.len() {
                break;
            }
            let e = b[*i];
            *i += 1;
            if e == b'n' {
                out.push('\n');
            } else if e == b't' {
                out.push('\t');
            } else if e == b'r' {
                out.push('\r');
            } else if e == b'b' {
                out.push('\u{8}');
            } else if e == b'f' {
                out.push('\u{c}');
            } else if e == b'u' {
                let mut code: u32 = 0;
                let mut k = 0;
                while k < 4 && *i < b.len() {
                    code = code * 16 + hex_val(b[*i]);
                    *i += 1;
                    k += 1;
                }
                match char::from_u32(code) {
                    Some(ch) => out.push(ch),
                    None => out.push('?'),
                }
            } else {
                out.push(e as char);
            }
            seg = *i;
        } else {
            *i += 1;
        }
    }
    out
}

fn parse_value(text: &Str, b: &Vec<u8>, i: &mut usize) -> Json {
    skip_ws(b, i);
    if *i >= b.len() {
        return Json::Null;
    }
    let c = b[*i];
    if c == b'"' {
        let s = parse_string(text, b, i);
        return Json::Text(s);
    }
    if c == b'[' {
        *i += 1;
        let mut items: Vec<Json> = Vec::new();
        skip_ws(b, i);
        if *i < b.len() && b[*i] == b']' {
            *i += 1;
            return Json::Arr(items);
        }
        while *i < b.len() {
            let v = parse_value(text, b, i);
            items.push(v);
            skip_ws(b, i);
            if *i < b.len() && b[*i] == b',' {
                *i += 1;
            } else {
                if *i < b.len() && b[*i] == b']' {
                    *i += 1;
                }
                break;
            }
        }
        return Json::Arr(items);
    }
    if c == b'{' {
        *i += 1;
        let mut fields: Vec<(Str, Json)> = Vec::new();
        skip_ws(b, i);
        if *i < b.len() && b[*i] == b'}' {
            *i += 1;
            return Json::Obj(fields);
        }
        while *i < b.len() {
            skip_ws(b, i);
            let key = parse_string(text, b, i);
            skip_ws(b, i);
            if *i < b.len() && b[*i] == b':' {
                *i += 1;
            }
            let v = parse_value(text, b, i);
            fields.push((key, v));
            skip_ws(b, i);
            if *i < b.len() && b[*i] == b',' {
                *i += 1;
            } else {
                if *i < b.len() && b[*i] == b'}' {
                    *i += 1;
                }
                break;
            }
        }
        return Json::Obj(fields);
    }
    if c == b't' {
        *i += 4;
        return Json::Bool(true);
    }
    if c == b'f' {
        *i += 5;
        return Json::Bool(false);
    }
    if c == b'n' {
        *i += 4;
        return Json::Null;
    }
    // number
    let mut neg = false;
    if c == b'-' {
        neg = true;
        *i += 1;
    }
    let mut n: i64 = 0;
    while *i < b.len() && b[*i] >= b'0' && b[*i] <= b'9' {
        n = n * 10 + (b[*i] - b'0') as i64;
        *i += 1;
    }
    // skip fraction / exponent
    while *i < b.len() {
        let d = b[*i];
        if d == b'.' || d == b'e' || d == b'E' || d == b'+' || d == b'-' || (d >= b'0' && d <= b'9') {
            *i += 1;
        } else {
            break;
        }
    }
    if neg {
        n = -n;
    }
    Json::Num(n)
}

fn get<'a>(obj: &'a Json, key: &str) -> Option<&'a Json> {
    match obj {
        Json::Obj(fields) => {
            for (k, v) in fields.iter() {
                if k == key {
                    return Some(v);
                }
            }
            None
        }
        _ => None,
    }
}

fn as_num(v: Option<&Json>) -> i64 {
    match v {
        Some(Json::Num(n)) => *n,
        _ => 0,
    }
}

fn as_text(v: Option<&Json>) -> Str {
    match v {
        Some(Json::Text(s)) => s.clone(),
        _ => Str::new(),
    }
}

fn main(input: Dir) -> Result<Str, Error> {
    let text = input.read("orders.json")?;
    let b: Vec<u8> = text.as_bytes().to_vec();
    let mut pos: usize = 0;
    let root = parse_value(&text, &b, &mut pos);

    let mut names: Vec<Str> = Vec::new();
    let mut counts: Vec<i64> = Vec::new();
    let mut totals: Vec<i64> = Vec::new();
    let mut refunded_n: i64 = 0;
    let mut refunded_t: i64 = 0;
    let mut pending_n: i64 = 0;

    if let Json::Arr(orders) = &root {
        for order in orders.iter() {
            let status = as_text(get(order, "status"));
            let mut total: i64 = 0;
            if let Some(Json::Arr(items)) = get(order, "items") {
                for item in items.iter() {
                    total += as_num(get(item, "qty")) * as_num(get(item, "price_cents"));
                }
            }
            if status == "paid" {
                let customer = as_text(get(order, "customer"));
                let mut found = false;
                let mut k = 0;
                while k < names.len() {
                    if names[k] == customer {
                        counts[k] += 1;
                        totals[k] += total;
                        found = true;
                        break;
                    }
                    k += 1;
                }
                if !found {
                    names.push(customer);
                    counts.push(1);
                    totals.push(total);
                }
            } else if status == "refunded" {
                refunded_n += 1;
                refunded_t += total;
            } else if status == "pending" {
                pending_n += 1;
            }
        }
    }

    // insertion sort of indices by name (byte order)
    let mut idx: Vec<usize> = Vec::new();
    let mut k = 0;
    while k < names.len() {
        idx.push(k);
        k += 1;
    }
    let mut a = 1;
    while a < idx.len() {
        let mut j = a;
        while j > 0 && names[idx[j]].as_bytes() < names[idx[j - 1]].as_bytes() {
            let tmp = idx[j];
            idx[j] = idx[j - 1];
            idx[j - 1] = tmp;
            j -= 1;
        }
        a += 1;
    }

    let mut out = Str::new();
    for &n in idx.iter() {
        out.push_str(&format!("{} {} {}\n", names[n], counts[n], totals[n]));
    }
    out.push_str(&format!("refunded {} {}\n", refunded_n, refunded_t));
    out.push_str(&format!("pending {}\n", pending_n));
    Ok(out)
}

