}

fn parse_value(b: Vec<u8>, start: usize) -> (Json, usize) {
    let mut i = skip_ws(b.clone(), start);
    if i >= b.len() {
        return (Json::Null, i);
    }
    let c = b[i];
    if c == b'"' {
        let (s, ni) = parse_string(b.clone(), i);
        return (Json::Text(s), ni);
    }
    if c == b'[' {
        i += 1;
        let mut items: Vec<Json> = Vec::new();
        i = skip_ws(b.clone(), i);
        if i < b.len() && b[i] == b']' {
            return (Json::Arr(items), i + 1);
        }
        while i < b.len() {
            let (v, ni) = parse_value(b.clone(), i);
            items.push(v);
            i = skip_ws(b.clone(), ni);
            if i < b.len() && b[i] == b',' {
                i += 1;
            } else {
                if i < b.len() && b[i] == b']' {
                    i += 1;
                }
                break;
            }
        }
        return (Json::Arr(items), i);
    }
    if c == b'{' {
        i += 1;
        let mut fields: Vec<(Str, Json)> = Vec::new();
        i = skip_ws(b.clone(), i);
        if i < b.len() && b[i] == b'}' {
            return (Json::Obj(fields), i + 1);
        }
        while i < b.len() {
            i = skip_ws(b.clone(), i);
            let (key, ki) = parse_string(b.clone(), i);
            i = skip_ws(b.clone(), ki);
            if i < b.len() && b[i] == b':' {
                i += 1;
            }
            let (v, vi) = parse_value(b.clone(), i);
            fields.push((key, v));
            i = skip_ws(b.clone(), vi);
            if i < b.len() && b[i] == b',' {
                i += 1;
            } else {
                if i < b.len() && b[i] == b'}' {
                    i += 1;
                }
                break;
            }
        }
        return (Json::Obj(fields), i);
    }
    if c == b't' {
        return (Json::Bool(true), i + 4);
    }
    if c == b'f' {
        return (Json::Bool(false), i + 5);
    }
    if c == b'n' {
        return (Json::Null, i + 4);
    }
    let mut neg = false;
    if c == b'-' {
        neg = true;
        i += 1;
    }
    let mut n: i64 = 0;
    while i < b.len() && b[i] >= b'0' && b[i] <= b'9' {
        n = n * 10 + (b[i] - b'0') as i64;
        i += 1;
    }
    while i < b.len() {
        let d = b[i];
        if d == b'.' || d == b'e' || d == b'E' || d == b'+' || d == b'-' || (d >= b'0' && d <= b'9') {
            i += 1;
        } else {
            break;
        }
    }
    if neg {
        n = -n;
    }
    (Json::Num(n), i)
}

