}

fn skip_ws(b: Vec<u8>, start: usize) -> usize {
    let mut i = start;
    while i < b.len() {
        let c = b[i];
        if c == 32 || c == 10 || c == 13 || c == 9 {
            i += 1;
        } else {
            break;
        }
    }
    i
}

fn hex_val(c: u8) -> u32 {
    if c >= 48 && c <= 57 {
        (c - 48) as u32
    } else if c >= 97 && c <= 102 {
        (c - 97 + 10) as u32
    } else if c >= 65 && c <= 70 {
        (c - 65 + 10) as u32
    } else {
        0
    }
}

fn push_utf8(out: &mut Vec<u8>, code: u32) {
    if code < 128 {
        out.push(code as u8);
    } else if code < 2048 {
        out.push((192 | (code >> 6)) as u8);
        out.push((128 | (code & 63)) as u8);
    } else if code < 65536 {
        out.push((224 | (code >> 12)) as u8);
        out.push((128 | ((code >> 6) & 63)) as u8);
        out.push((128 | (code & 63)) as u8);
    } else {
        out.push((240 | (code >> 18)) as u8);
        out.push((128 | ((code >> 12) & 63)) as u8);
        out.push((128 | ((code >> 6) & 63)) as u8);
        out.push((128 | (code & 63)) as u8);
    }
}

fn parse_string(b: Vec<u8>, start: usize) -> (Vec<u8>, usize) {
    let mut i = start + 1;
    let mut out: Vec<u8> = Vec::new();
    while i < b.len() {
        let c = b[i];
        if c == 34 {
            i += 1;
            return (out, i);
        } else if c == 92 {
            i += 1;
            if i >= b.len() {
                break;
            }
            let e = b[i];
            i += 1;
            if e == 110 {
                out.push(10);
            } else if e == 116 {
                out.push(9);
            } else if e == 114 {
                out.push(13);
            } else if e == 98 {
                out.push(8);
            } else if e == 102 {
                out.push(12);
            } else if e == 117 {
                let mut code: u32 = 0;
                let mut k = 0;
                while k < 4 && i < b.len() {
                    code = code * 16 + hex_val(b[i]);
                    i += 1;
                    k += 1;
                }
                if code >= 55296 && code <= 57343 {
                    out.push(63);
                } else {
                    push_utf8(&mut out, code);
                }
            } else {
                out.push(e);
            }
        } else {
            out.push(c);
            i += 1;
        }
    }
    (out, i)
}

fn parse_value(b: Vec<u8>, start: usize) -> (Json, usize) {
    let mut i = skip_ws(b.clone(), start);
    if i >= b.len() {
