    if d == 7 { return "7"; }
    if d == 8 { return "8"; }
    "9"
}

fn int_to_str(n: Int) -> Str {
    if n == 0 {
        return "0";
    }
    let mut out: Str = "";
    let mut rest = n;
    while rest > 0 {
        out = digit_char(rest % 10) + out;
        rest = rest / 10;
    }
    out
}

fn roman_digit(c: Str) -> Int {
    if c == "I" { return 1; }
    if c == "V" { return 5; }
    if c == "X" { return 10; }
    if c == "L" { return 50; }
    if c == "C" { return 100; }
    if c == "D" { return 500; }
    if c == "M" { return 1000; }
    0
}

fn digit_value(c: Str) -> Int {
    if c == "0" { return 0; }
    if c == "1" { return 1; }
    if c == "2" { return 2; }
    if c == "3" { return 3; }
    if c == "4" { return 4; }
    if c == "5" { return 5; }
    if c == "6" { return 6; }
    if c == "7" { return 7; }
    if c == "8" { return 8; }
    if c == "9" { return 9; }
    -1
}

fn is_all_digits(s: Str) -> Bool {
    if s.len() == 0 {
        return false;
    }
    for c in s.chars() {
        if digit_value(c) < 0 {
            return false;
        }
    }
    true
}

fn is_all_roman(s: Str) -> Bool {
    if s.len() == 0 {
        return false;
    }
    for c in s.chars() {
        if roman_digit(c) == 0 {
            return false;
        }
    }
    true
}

fn convert(s: Str) -> Str {
    if is_all_digits(s) {
        let mut v: Int = 0;
        for c in s.chars() {
            v = v * 10 + digit_value(c);
            if v > 100000 {
                return "invalid";
            }
        }
        if v >= 1 && v <= 3999 {
            return to_roman(v);
        }
        return "invalid";
    }
    if is_all_roman(s) {
        let mut total: Int = 0;
        let mut prev: Int = 0;
        for c in s.chars() {
            let d = roman_digit(c);
            total = total + d;
            if prev > 0 && prev < d {
                total = total - 2 * prev;
            }
            prev = d;
        }
        if total >= 1 && total <= 3999 && to_roman(total) == s {
            return int_to_str(total);
        }
        return "invalid";
    }
    "invalid"
}

