fn closer_for(c: char) -> char {
    match c {
        '(' => ')',
        '[' => ']',
        '{' => '}',
        _ => ' ',
    }
}

fn check(line: &str) -> Str {
    let mut stack: Vec<char> = Vec::new();
    let mut col = 0;
    for c in line.chars() {
        col += 1;
        if c == '(' || c == '[' || c == '{' {
            stack.push(closer_for(c));
        } else if c == ')' || c == ']' || c == '}' {
            match stack.pop() {
                None => {
                    return format!("col {}: unexpected {}", col, c);
                }
                Some(expected) => {
                    if expected != c {
                        return format!("col {}: expected {}, found {}", col, expected, c);
                    }
                }
            }
        }
    }
    match stack.last() {
        Some(x) => format!("unclosed {}", x),
        None => format!("ok"),
    }
}

