fn find(names: &Vec<Str>, s: &Str) -> i64 {
    let mut i: usize = 0;
    while i < names.len() {
        if names[i] == *s {
            return i as i64;
        }
        i += 1;
    }
    -1
}

fn intern(names: &mut Vec<Str>, adj_to: &mut Vec<Vec<usize>>, adj_w: &mut Vec<Vec<i64>>, s: &Str) -> usize {
    let f = find(names, s);
    if f >= 0 {
        return f as usize;
    }
    names.push(s.clone());
    adj_to.push(Vec::new());
    adj_w.push(Vec::new());
    names.len() - 1
}

fn path_less(a: &Vec<usize>, b: &Vec<usize>, names: &Vec<Str>) -> bool {
    let mut i: usize = 0;
    while i < a.len() && i < b.len() {
        let x = &names[a[i]];
        let y = &names[b[i]];
        if x < y {
            return true;
        }
        if y < x {
            return false;
        }
        i += 1;
    }
    a.len() < b.len()
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = input.read("routes.txt")?;
    let mut names: Vec<Str> = Vec::new();
    let mut adj_to: Vec<Vec<usize>> = Vec::new();
    let mut adj_w: Vec<Vec<i64>> = Vec::new();
    let mut trip_a: Vec<Str> = Vec::new();
    let mut trip_b: Vec<Str> = Vec::new();

    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with("#") {
            continue;
        }
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() == 4 && parts[0] == "road" {
            let a = parts[1].to_string();
            let b = parts[2].to_string();
            let w: i64 = match parts[3].parse::<i64>() {
                Ok(v) => v,
                Err(_) => continue,
            };
            let ia = intern(&mut names, &mut adj_to, &mut adj_w, &a);
            let ib = intern(&mut names, &mut adj_to, &mut adj_w, &b);
            adj_to[ia].push(ib);
            adj_w[ia].push(w);
            adj_to[ib].push(ia);
            adj_w[ib].push(w);
        } else if parts.len() == 3 && parts[0] == "trip" {
            trip_a.push(parts[1].to_string());
            trip_b.push(parts[2].to_string());
        }
    }

    let n = names.len();
    let mut out = String::new();
    let mut t: usize = 0;
    while t < trip_a.len() {
        let xa = trip_a[t].clone();
        let yb = trip_b[t].clone();
        t += 1;
        if xa == yb {
            out.push_str(&format!("{} 0\n", xa));
            continue;
        }
        let sx = find(&names, &xa);
        let sy = find(&names, &yb);
        if sx < 0 || sy < 0 {
            out.push_str(&format!("{} {} unreachable\n", xa, yb));
            continue;
        }
        let s = sx as usize;
        let target = sy as usize;
        let mut dist: Vec<i64> = Vec::new();
        let mut paths: Vec<Vec<usize>> = Vec::new();
        let mut done: Vec<bool> = Vec::new();
        let mut i: usize = 0;
        while i < n {
            dist.push(-1);
            paths.push(Vec::new());
            done.push(false);
            i += 1;
        }
        dist[s] = 0;
        let mut p0: Vec<usize> = Vec::new();
        p0.push(s);
        paths[s] = p0;
        loop {
            let mut best: i64 = -1;
            let mut j: usize = 0;
            while j < n {
                if !done[j] && dist[j] >= 0 {
                    if best < 0 {
                        best = j as i64;
                    } else {
                        let b = best as usize;
                        if dist[j] < dist[b] || (dist[j] == dist[b] && path_less(&paths[j], &paths[b], &names)) {
                            best = j as i64;
                        }
                    }
                }
                j += 1;
            }
            if best < 0 {
                break;
            }
            let u = best as usize;
            done[u] = true;
            if u == target {
                break;
            }
            let mut k: usize = 0;
            while k < adj_to[u].len() {
                let v = adj_to[u][k];
                let w = adj_w[u][k];
                k += 1;
                if done[v] {
                    continue;
                }
                let nd = dist[u] + w;
                let mut np = paths[u].clone();
                np.push(v);
                if dist[v] < 0 || nd < dist[v] || (nd == dist[v] && path_less(&np, &paths[v], &names)) {
                    dist[v] = nd;
                    paths[v] = np;
                }
            }
        }
        if dist[target] < 0 {
            out.push_str(&format!("{} {} unreachable\n", xa, yb));
        } else {
            let mut line = String::new();
            let mut q: usize = 0;
            while q < paths[target].len() {
                if q > 0 {
                    line.push_str(" -> ");
                }
                line.push_str(&names[paths[target][q]]);
                q += 1;
            }
            out.push_str(&format!("{} {}\n", line, dist[target]));
        }
    }
    Ok(out)
}

fn find(names: Vec<Str>, s: Str) -> i64 {
    let mut i: usize = 0;
    while i < names.len() {
        if names[i] == s {
            return i as i64;
        }
        i += 1;
    }
    -1
}

fn path_less(a: Vec<usize>, b: Vec<usize>, names: Vec<Str>) -> bool {
    let mut i: usize = 0;
    while i < a.len() && i < b.len() {
        let x = names[a[i]].clone();
        let y = names[b[i]].clone();
        if x < y {
            return true;
        }
        if y < x {
            return false;
        }
        i += 1;
    }
    a.len() < b.len()
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = input.read("routes.txt")?;
    let mut names: Vec<Str> = Vec::new();
    let mut adj_to: Vec<Vec<usize>> = Vec::new();
    let mut adj_w: Vec<Vec<i64>> = Vec::new();
