enum Json {
    Null,
    Bool(bool),
    Num(i64),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(text: Str) -> Parser {
        Parser { chars: text.chars().collect(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.chars.len() {
            let c = self.chars[self.pos];
            if c == ' ' || c == '\n' || c == '\t' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn peek(&self) -> char {
        if self.pos < self.chars.len() {
            self.chars[self.pos]
        } else {
            '\0'
        }
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        let c = self.peek();
        if c == '{' {
            self.pos += 1;
            let mut items: Vec<(Str, Json)> = Vec::new();
            self.skip_ws();
            if self.peek() == '}' {
                self.pos += 1;
                return Json::Obj(items);
            }
            loop {
                self.skip_ws();
                let key = self.parse_string();
                self.skip_ws();
                if self.peek() == ':' {
                    self.pos += 1;
                }
                let v = self.parse_value();
                items.push((key, v));
                self.skip_ws();
                let d = self.peek();
                self.pos += 1;
                if d != ',' {
                    break;
                }
            }
            Json::Obj(items)
        } else if c == '[' {
            self.pos += 1;
            let mut items: Vec<Json> = Vec::new();
            self.skip_ws();
            if self.peek() == ']' {
                self.pos += 1;
                return Json::Arr(items);
            }
            loop {
                let v = self.parse_value();
                items.push(v);
                self.skip_ws();
                let d = self.peek();
                self.pos += 1;
                if d != ',' {
                    break;
                }
            }
            Json::Arr(items)
        } else if c == '"' {
            Json::Text(self.parse_string())
        } else if c == 't' {
            self.pos += 4;
            Json::Bool(true)
        } else if c == 'f' {
            self.pos += 5;
            Json::Bool(false)
        } else if c == 'n' {
            self.pos += 4;
            Json::Null
        } else {
            let mut neg = false;
            if c == '-' {
                neg = true;
                self.pos += 1;
            }
            let mut n: i64 = 0;
            while self.pos < self.chars.len() {
                let d = self.chars[self.pos];
                if d >= '0' && d <= '9' {
                    n = n * 10 + ((d as i64) - ('0' as i64));
                    self.pos += 1;
                } else {
                    break;
                }
            }
            if neg {
                n = -n;
            }
            Json::Num(n)
        }
    }

    fn hex_val(c: char) -> u32 {
        if c >= '0' && c <= '9' {
            (c as u32) - ('0' as u32)
        } else if c >= 'a' && c <= 'f' {
            (c as u32) - ('a' as u32) + 10
        } else if c >= 'A' && c <= 'F' {
            (c as u32) - ('A' as u32) + 10
        } else {
            0
        }
    }

    fn parse_hex4(&mut self) -> u32 {
        let mut code: u32 = 0;
        let mut i = 0;
        while i < 4 && self.pos < self.chars.len() {
            code = code * 16 + Parser::hex_val(self.chars[self.pos]);
            self.pos += 1;
            i += 1;
        }
        code
    }

    fn parse_string(&mut self) -> Str {
        let mut out = Str::new();
        if self.peek() == '"' {
            self.pos += 1;
        }
        while self.pos < self.chars.len() {
            let c = self.chars[self.pos];
            self.pos += 1;
            if c == '"' {
                break;
            }
            if c == '\\' {
                let e = self.peek();
                self.pos += 1;
                if e == 'n' {
                    out.push('\n');
                } else if e == 't' {
                    out.push('\t');
                } else if e == 'r' {
                    out.push('\r');
                } else if e == 'b' {
                    out.push('\u{8}');
                } else if e == 'f' {
                    out.push('\u{c}');
                } else if e == 'u' {
                    let mut code = self.parse_hex4();
                    if code >= 0xD800 && code < 0xDC00 {
                        if self.peek() == '\\' && self.pos + 1 < self.chars.len() && self.chars[self.pos + 1] == 'u' {
                            self.pos += 2;
                            let low = self.parse_hex4();
                            code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                        }
                    }
                    match char::from_u32(code) {
                        Some(ch) => out.push(ch),
                        None => out.push('?'),
                    }
                } else {
                    out.push(e);
                }
            } else {
                out.push(c);
            }
        }
        out
    }
}

fn merge(base: Json, patch: Json) -> Json {
    match patch {
        Json::Obj(pitems) => {
            let mut items: Vec<(Str, Json)> = match base {
                Json::Obj(b) => b,
                _ => Vec::new(),
            };
            for (k, v) in pitems {
                let mut idx: i64 = -1;
                let mut i = 0;
                while i < items.len() {
                    if items[i].0 == k {
                        idx = i as i64;
                    }
                    i += 1;
                }
                let is_null = match v {
                    Json::Null => true,
                    _ => false,
                };
                if is_null {
                    if idx >= 0 {
                        items.remove(idx as usize);
                    }
                } else if idx >= 0 {
                    let (key, old) = items.remove(idx as usize);
                    let merged = merge(old, v);
                    items.insert(idx as usize, (key, merged));
                } else {
                    let merged = merge(Json::Null, v);
                    items.push((k, merged));
                }
            }
            Json::Obj(items)
        }
        other => other,
    }
}

fn quote(s: &Str) -> Str {
    let mut out = Str::new();
    out.push('"');
    for c in s.chars() {
        if c == '"' {
            out.push_str("\\\"");
        } else if c == '\\' {
            out.push_str("\\\\");
        } else if c == '\n' {
            out.push_str("\\n");
        } else if c == '\t' {
            out.push_str("\\t");
        } else if c == '\r' {
            out.push_str("\\r");
        } else {
            out.push(c);
        }
    }
    out.push('"');
    out
}

fn join(prefix: &Str, key: &Str) -> Str {
    let mut p = Str::new();
    if prefix.len() > 0 {
        p.push_str(prefix);
        p.push('.');
    }
    p.push_str(key);
    p
}

fn flatten(v: &Json, path: Str, out: &mut Vec<(Str, Str)>) {
    match v {
        Json::Null => out.push((path, Str::from("null"))),
        Json::Bool(b) => {
            if *b {
                out.push((path, Str::from("true")));
            } else {
                out.push((path, Str::from("false")));
            }
        }
        Json::Num(n) => out.push((path, n.to_string())),
        Json::Text(s) => out.push((path, quote(s))),
        Json::Arr(items) => {
            if items.len() == 0 {
                out.push((path, Str::from("[]")));
            } else {
                let mut i = 0;
                while i < items.len() {
                    let key = i.to_string();
                    flatten(&items[i], join(&path, &key), out);
                    i += 1;
                }
            }
        }
        Json::Obj(items) => {
            if items.len() == 0 {
                out.push((path, Str::from("{}")));
            } else {
                for (k, child) in items.iter() {
                    flatten(child, join(&path, k), out);
                }
            }
        }
    }
}

fn main(input: Dir) -> Str {
    let base_text = match input.read("base.json") {
