    let mut leaves: Vec<(Str, Str)> = Vec::new();
    flatten(&merged, Str::new(), &mut leaves);
    leaves.sort_by(|a, b| a.0.as_bytes().cmp(b.0.as_bytes()));

    let mut out = Str::new();
    for (p, v) in leaves.iter() {
        out.push_str(p);
        out.push('=');
        out.push_str(v);
        out.push('\n');
    }
    out
}

enum Json {
    Null,
    Bool(bool),
    Num(i64),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct P {
    chars: Vec<char>,
    pos: usize,
}

fn cur(p: P) -> (P, char) {
    let c = if p.pos < p.chars.len() { p.chars[p.pos] } else { '\0' };
    (p, c)
}

fn skip_ws(p: P) -> P {
    let mut p = p;
    loop {
        let (q, c) = cur(p);
        p = q;
        if c == ' ' || c == '\n' || c == '\t' || c == '\r' {
            p.pos += 1;
        } else {
            break;
        }
    }
    p
}

fn hex_val(c: char) -> u32 {
    if c >= '0' && c <= '9' {
        (c as u32) - ('0' as u32)
    } else if c >= 'a' && c <= 'f' {
        (c as u32) - ('a' as u32) + 10
    } else if c >= 'A' && c <= 'F' {
        (c as u32) - ('A' as u32) + 10
    } else {
        0
    }
}

fn parse_hex4(p: P) -> (P, u32) {
    let mut p = p;
    let mut code: u32 = 0;
    let mut i = 0;
    while i < 4 && p.pos < p.chars.len() {
        code = code * 16 + hex_val(p.chars[p.pos]);
        p.pos += 1;
        i += 1;
    }
    (p, code)
}

fn parse_string(p: P) -> (P, Str) {
    let mut p = p;
    let mut out = Str::new();
    let (q, c0) = cur(p);
    p = q;
    if c0 == '"' {
        p.pos += 1;
    }
    while p.pos < p.chars.len() {
        let c = p.chars[p.pos];
        p.pos += 1;
        if c == '"' {
            break;
        }
        if c == '\\' {
            let (q, e) = cur(p);
            p = q;
            p.pos += 1;
            if e == 'n' {
                out.push('\n');
            } else if e == 't' {
                out.push('\t');
            } else if e == 'r' {
                out.push('\r');
            } else if e == 'b' {
                out.push('\u{8}');
            } else if e == 'f' {
                out.push('\u{c}');
            } else if e == 'u' {
                let (q, c1) = parse_hex4(p);
                p = q;
                let mut code = c1;
                if code >= 0xD800 && code < 0xDC00 {
                    if p.pos + 1 < p.chars.len() && p.chars[p.pos] == '\\' && p.chars[p.pos + 1] == 'u' {
                        p.pos += 2;
                        let (q, low) = parse_hex4(p);
                        p = q;
                        if low >= 0xDC00 {
                            code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                        }
                    }
                }
                match char::from_u32(code) {
                    Some(ch) => out.push(ch),
                    None => out.push('?'),
                }
            } else {
                out.push(e);
            }
        } else {
            out.push(c);
        }
    }
    (p, out)
}

fn parse_value(p: P) -> (P, Json) {
    let mut p = skip_ws(p);
    let (q, c) = cur(p);
    p = q;
    if c == '{' {
        p.pos += 1;
        let mut items: Vec<(Str, Json)> = Vec::new();
        p = skip_ws(p);
        let (q, c2) = cur(p);
        p = q;
        if c2 == '}' {
            p.pos += 1;
            return (p, Json::Obj(items));
        }
        loop {
            p = skip_ws(p);
            let (q, key) = parse_string(p);
            p = skip_ws(q);
            let (q, c3) = cur(p);
            p = q;
            if c3 == ':' {
                p.pos += 1;
            }
            let (q, v) = parse_value(p);
            p = q;
            items.push((key, v));
            p = skip_ws(p);
            let (q, d) = cur(p);
            p = q;
            p.pos += 1;
            if d != ',' {
                break;
            }
        }
        (p, Json::Obj(items))
    } else if c == '[' {
        p.pos += 1;
        let mut items: Vec<Json> = Vec::new();
        p = skip_ws(p);
        let (q, c2) = cur(p);
        p = q;
        if c2 == ']' {
            p.pos += 1;
            return (p, Json::Arr(items));
        }
        loop {
            let (q, v) = parse_value(p);
            p = q;
            items.push(v);
            p = skip_ws(p);
            let (q, d) = cur(p);
            p = q;
            p.pos += 1;
            if d != ',' {
                break;
            }
        }
        (p, Json::Arr(items))
    } else if c == '"' {
        let (q, s) = parse_string(p);
        (q, Json::Text(s))
    } else if c == 't' {
        p.pos += 4;
        (p, Json::Bool(true))
    } else if c == 'f' {
        p.pos += 5;
        (p, Json::Bool(false))
    } else if c == 'n' {
        p.pos += 4;
        (p, Json::Null)
    } else {
        let mut neg = false;
        if c == '-' {
            neg = true;
            p.pos += 1;
        }
        let mut n: i64 = 0;
        while p.pos < p.chars.len() {
            let d = p.chars[p.pos];
            if d >= '0' && d <= '9' {
                n = n * 10 + ((d as i64) - ('0' as i64));
                p.pos += 1;
            } else {
                break;
            }
        }
        if neg {
            n = -n;
        }
        (p, Json::Num(n))
    }
}

fn merge(base: Json, patch: Json) -> Json {
    match patch {
        Json::Obj(pitems) => {
            let mut items: Vec<(Str, Json)> = match base {
