}

fn parse_string(p: P) -> PS {
    let mut p = p;
    let mut out = Str::new();
    let r = cur(p);
    p = r.p;
    if r.c == "\"" {
        p.pos += 1;
    }
    while p.pos < p.chars.len() {
        let c = p.chars[p.pos].clone();
        p.pos += 1;
        if c == "\"" {
            break;
        }
        if c == "\\" {
            out.push_str(c);
            if p.pos < p.chars.len() {
                let e = p.chars[p.pos].clone();
                p.pos += 1;
                out.push_str(e);
            }
        } else {
