}

fn parse_value(p: P) -> PV {
    let mut p = skip_ws(p);
    let r = cur(p);
    p = r.p;
    let c = r.c;
    if c == "{" {
        p.pos += 1;
        let mut items: Vec<Entry> = Vec::new();
        p = skip_ws(p);
        let r2 = cur(p);
        p = r2.p;
        if r2.c == "}" {
            p.pos += 1;
            return PV { p: p, v: Json::Obj(items) };
        }
        loop {
            p = skip_ws(p);
            let ks = parse_string(p);
            p = skip_ws(ks.p);
            let key = ks.s;
            let r3 = cur(p);
            p = r3.p;
            if r3.c == ":" {
                p.pos += 1;
            }
            let pv = parse_value(p);
            p = pv.p;
            items.push(Entry { key: key, val: pv.v });
            p = skip_ws(p);
            let r4 = cur(p);
            p = r4.p;
            p.pos += 1;
            if r4.c != "," {
                break;
            }
        }
        PV { p: p, v: Json::Obj(items) }
    } else if c == "[" {
        p.pos += 1;
        let mut items: Vec<Json> = Vec::new();
        p = skip_ws(p);
        let r2 = cur(p);
        p = r2.p;
        if r2.c == "]" {
            p.pos += 1;
            return PV { p: p, v: Json::Arr(items) };
        }
        loop {
            let pv = parse_value(p);
            p = pv.p;
            items.push(pv.v);
            p = skip_ws(p);
            let r4 = cur(p);
            p = r4.p;
            p.pos += 1;
            if r4.c != "," {
                break;
            }
        }
        PV { p: p, v: Json::Arr(items) }
    } else if c == "\"" {
        let ps = parse_string(p);
        PV { p: ps.p, v: Json::Text(ps.s) }
    } else if c == "t" {
        p.pos += 4;
        PV { p: p, v: Json::Bool(true) }
    } else if c == "f" {
