        if c == "-" {
            neg = true;
            p.pos += 1;
        }
        let mut n: i64 = 0;
        while p.pos < p.chars.len() {
            let d = digit_val(p.chars[p.pos].clone());
            if d >= 0 {
                n = n * 10 + d;
                p.pos += 1;
            } else {
