fn merge(base: Json, patch: Json) -> Json {
    match patch {
        Json::Obj(pitems) => {
            let mut items: Vec<Entry> = match base {
                Json::Obj(b) => b,
                _ => Vec::new(),
            };
            for e in pitems {
                let k = e.key;
                let v = e.val;
                let mut idx: i64 = -1;
                let mut i: usize = 0;
                while i < items.len() {
                    if items[i].key == k {
                        idx = i as i64;
                    }
                    i += 1;
                }
                let is_null = match v {
                    Json::Null => true,
                    _ => false,
                };
                if is_null {
                    if idx >= 0 {
                        items.remove(idx as usize);
                    }
                } else if idx >= 0 {
                    let old = items.remove(idx as usize);
                    let merged = merge(old.val, v);
                    items.insert(idx as usize, Entry { key: old.key, val: merged });
                } else {
                    let merged = merge(Json::Null, v);
                    items.push(Entry { key: k, val: merged });
                }
            }
            Json::Obj(items)
        }
        other => other,
    }
}

