    p.push_str(key);
    p
}

fn flatten(v: Json, path: Str, out: Vec<Leaf>) -> Vec<Leaf> {
    let mut out = out;
    match v {
        Json::Null => out.push(Leaf { path: path, val: Str::from("null") }),
        Json::Bool(b) => {
            if b {
                out.push(Leaf { path: path, val: Str::from("true") });
            } else {
                out.push(Leaf { path: path, val: Str::from("false") });
            }
        }
        Json::Num(n) => out.push(Leaf { path: path, val: n.to_string() }),
        Json::Text(s) => out.push(Leaf { path: path, val: quote(s) }),
        Json::Arr(items) => {
            if items.len() == 0 {
                out.push(Leaf { path: path, val: Str::from("[]") });
            } else {
                let mut i: usize = 0;
                for item in items {
                    let key = i.to_string();
                    out = flatten(item, join(path.clone(), key), out);
                    i += 1;
                }
            }
        }
        Json::Obj(items) => {
            if items.len() == 0 {
                out.push(Leaf { path: path, val: Str::from("{}") });
            } else {
                for e in items {
                    out = flatten(e.val, join(path.clone(), e.key), out);
                }
            }
        }
    }
    out
}

