fn level_of(line: &str) -> Option<usize> {
    let fields: Vec<&str> = line.split(' ').filter(|f| !f.is_empty()).collect();
    if fields.len() < 3 {
        return None;
    }
    let lvl = fields[1].to_uppercase();
    if lvl == "ERROR" {
        Some(0)
    } else if lvl == "WARN" || lvl == "WARNING" {
        Some(1)
    } else if lvl == "INFO" {
        Some(2)
    } else {
        None
    }
}

fn main(input: Dir, out: Dir) -> Result<Str, Error> {
    let text = input.read("app.log")?;

    let mut error_buf = String::new();
    let mut warn_buf = String::new();
    let mut info_buf = String::new();

    let mut error_n = 0;
    let mut warn_n = 0;
    let mut info_n = 0;
    let mut other_n = 0;

    for line in text.lines() {
        if line.trim().is_empty() {
            continue;
        }
        match level_of(line) {
            Some(0) => {
                error_buf.push_str(line);
                error_buf.push_str("\n");
                error_n += 1;
            }
            Some(1) => {
                warn_buf.push_str(line);
                warn_buf.push_str("\n");
                warn_n += 1;
            }
            Some(2) => {
                info_buf.push_str(line);
                info_buf.push_str("\n");
                info_n += 1;
            }
            _ => {
                other_n += 1;
            }
        }
    }

    out.write("error.log", &error_buf)?;
    out.write("warn.log", &warn_buf)?;
    out.write("info.log", &info_buf)?;

    Ok(format!(
        "error {}\nwarn {}\ninfo {}\nother {}\n",
        error_n, warn_n, info_n, other_n
    ))
}

