}

fn level_of(line: Str) -> Option<Int> {
    let fields: List<Str> = line.split(" ").filter(|f| !f.is_empty()).collect();
    if fields.len() < 3 {
        return None;
    }
    let lvl = fields[1].to_uppercase();
    if lvl == "ERROR" {
        Some(0)
    } else if lvl == "WARN" || lvl == "WARNING" {
        Some(1)
    } else if lvl == "INFO" {
        Some(2)
    } else {
        None
    }
}

fn main(input: Dir, out: Dir) -> Result<Str, Str> {
    let text = input.read("app.log")?;

    let mut error_buf = Str::new();
    let mut warn_buf = Str::new();
    let mut info_buf = Str::new();

    let mut error_n: Int = 0;
    let mut warn_n: Int = 0;
    let mut info_n: Int = 0;
    let mut other_n: Int = 0;

    for line in text.lines() {
        if line.trim().is_empty() {
            continue;
        }
        match level_of(line) {
            Some(0) => {
                error_buf.push_str(line);
                error_buf.push_str("\n");
                error_n += 1;
            }
            Some(1) => {
                warn_buf.push_str(line);
                warn_buf.push_str("\n");
                warn_n += 1;
            }
            Some(2) => {
                info_buf.push_str(line);
                info_buf.push_str("\n");
                info_n += 1;
            }
            _ => {
                other_n += 1;
            }
        }
    }

    out.write("error.log", error_buf)?;
    out.write("warn.log", warn_buf)?;
    out.write("info.log", info_buf)?;

    let result = "error " + error_n.to_str()
        + "\nwarn " + warn_n.to_str()
        + "\ninfo " + info_n.to_str()
        + "\nother " + other_n.to_str()
        + "\n";
    Ok(result)
}

fn walk(dir: &Dir, prefix: &Str, rows: &mut Vec<(Str, u64, u64)>) -> Result<(), Error> {
    let entries = dir.list()?;
    for entry in entries {
        let name = entry.name();
        let rel = if prefix.is_empty() {
            name.clone()
        } else {
            format!("{}/{}", prefix, name)
        };
        if entry.is_dir() {
            let sub = dir.open_dir(&name)?;
            walk(&sub, &rel, rows)?;
        } else {
            let data = dir.read_bytes(&name)?;
            let size = data.len() as u64;
            let mut lines: u64 = 0;
            for b in data.iter() {
                if *b == b'\n' {
                    lines += 1;
                }
            }
            if size > 0 && data[data.len() - 1] != b'\n' {
                lines += 1;
            }
            rows.push((rel, size, lines));
        }
    }
    Ok(())
}

