fn parse_csv_line(line: &Str) -> Vec<Str> {
    let mut fields: Vec<Str> = Vec::new();
    let mut cur = Str::new();
    let chars: Vec<char> = line.chars().collect();
    let mut i: usize = 0;
    let n = chars.len();
    let mut in_quotes = false;
    while i < n {
        let c = chars[i];
        if in_quotes {
            if c == '"' {
                if i + 1 < n && chars[i + 1] == '"' {
                    cur.push('"');
                    i += 1;
                } else {
                    in_quotes = false;
                }
            } else {
                cur.push(c);
            }
        } else {
            if c == '"' {
                in_quotes = true;
            } else if c == ',' {
                fields.push(cur);
                cur = Str::new();
            } else {
                cur.push(c);
            }
        }
        i += 1;
    }
    fields.push(cur);
    fields
}

fn json_escape(s: &Str) -> Str {
    let mut o = Str::new();
    o.push('"');
    for c in s.chars() {
        if c == '"' {
            o.push_str("\\\"");
        } else if c == '\\' {
            o.push_str("\\\\");
        } else if c == '\n' {
            o.push_str("\\n");
        } else if c == '\r' {
            o.push_str("\\r");
        } else if c == '\t' {
            o.push_str("\\t");
        } else if (c as u32) < 0x20 {
            o.push_str(&format!("\\u{:04x}", c as u32));
        } else {
            o.push(c);
        }
    }
    o.push('"');
    o
}

fn parse_active(s: &Str) -> bool {
    let v = s.trim().to_lowercase();
    v == "yes" || v == "true" || v == "1"
}

fn main(input: Dir, out: Dir) -> Result<Str, Str> {
    let text = match input.read_to_string("users.csv") {
        Ok(t) => t,
        Err(e) => return Err(format!("cannot read users.csv: {}", e)),
    };

    let mut rows: i64 = 0;
    let mut skipped: i64 = 0;
    let mut seen_header = false;
    let mut objs: Vec<Str> = Vec::new();

    for raw in text.split('\n') {
        let line = raw.trim_end_matches('\r');
        if line.trim().is_empty() {
            continue;
        }
        if !seen_header {
            seen_header = true;
            continue;
        }
        let line_s: Str = line.to_string();
        let f = parse_csv_line(&line_s);
        if f.len() != 5 {
            skipped += 1;
            continue;
        }
        let id: i64 = match f[0].trim().parse::<i64>() {
            Ok(v) => v,
            Err(_) => {
                skipped += 1;
                continue;
            }
