            if active { "true" } else { "false" },
            tags.join(", ")
        );
        objs.push(obj);
        rows += 1;
    }

    let mut json = Str::new();
    json.push_str("[\n");
    let mut first = true;
    for o in objs.iter() {
        if !first {
            json.push_str(",\n");
        }
        first = false;
        json.push_str("  ");
        json.push_str(o);
    }
    if !first {
        json.push('\n');
    }
    json.push_str("]\n");

    match out.write("users.json", &json) {
        Ok(_) => {}
        Err(e) => return Err(format!("cannot write users.json: {}", e)),
    }

    Ok(format!("rows {} skipped {}", rows, skipped))
}

