fn count_quotes(s: Str) -> i64 {
    let mut n: i64 = 0;
    for _p in s.split("\"") {
        n += 1;
    }
    n - 1
}

fn unquote(field: Str) -> Str {
    let mut segs: Vec<Str> = Vec::new();
    for p in field.split("\"") {
        segs.push(p.to_string());
    }
    let mut result = Str::new();
    let mut in_q = false;
    let mut skip = false;
    let n = segs.len();
    let mut i: usize = 0;
    while i < n {
        if i > 0 {
            if skip {
                skip = false;
            } else if in_q {
                if segs[i].is_empty() && i + 1 < n {
                    result.push_str("\"");
                    skip = true;
                } else {
                    in_q = false;
                }
            } else {
                in_q = true;
            }
        }
        result.push_str(segs[i].clone());
        i += 1;
    }
    result
}

