fn normalize(name: &Str) -> Str {
    let mut s = String::new();
    let mut in_dash = false;
    for c in name.chars() {
        let c = c.to_ascii_lowercase();
        if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' {
            s.push(c);
            in_dash = false;
        } else if !in_dash {
            s.push('-');
            in_dash = true;
        }
    }
    s.trim_matches('-').to_string()
}

fn main(input: Dir, out: Dir) -> Result<Str, Error> {
    let mut names: Vec<Str> = input.list()?;
    names.sort();

    let mut taken: Vec<Str> = Vec::new();
    let mut report = String::new();

    for name in names.iter() {
        let new_name = normalize(name);
        if new_name.is_empty() || taken.contains(&new_name) {
            report.push_str(&format!("{} skipped\n", name));
            continue;
        }
        let data = input.read(name)?;
        out.write(&new_name, &data)?;
        report.push_str(&format!("{} -> {}\n", name, new_name));
        taken.push(new_name);
    }

    Ok(report)
}

fn normalize(name: Str) -> Str {
    let mut s = Str::new();
    let mut in_dash = false;
    for c in name.chars() {
        let c = c.to_ascii_lowercase();
        if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' {
            s.push(c);
            in_dash = false;
        } else if !in_dash {
            s.push('-');
            in_dash = true;
        }
    }
    let chars: Vec<char> = s.chars().collect();
    let mut start = 0;
    let mut end = chars.len();
    while start < end && chars[start] == '-' {
        start += 1;
    }
    while end > start && chars[end - 1] == '-' {
        end -= 1;
    }
    let mut r = Str::new();
    let mut i = start;
    while i < end {
        r.push(chars[i]);
        i += 1;
    }
    r
}

