fn digit_value(c: Str) -> Option<i64> {
    if c == "0" { return Some(0); }
    if c == "1" { return Some(1); }
    if c == "2" { return Some(2); }
    if c == "3" { return Some(3); }
    if c == "4" { return Some(4); }
    if c == "5" { return Some(5); }
    if c == "6" { return Some(6); }
    if c == "7" { return Some(7); }
    if c == "8" { return Some(8); }
    if c == "9" { return Some(9); }
    None
}

fn is_part_name(name: Str) -> bool {
    if !name.starts_with("part-") || !name.ends_with(".txt") {
        return false;
    }
    if name.len() != 13 {
        return false;
    }
    let mut i = 0;
    for c in name.chars() {
        if i >= 5 && i < 9 {
            if digit_value(c).is_none() {
                return false;
            }
        }
        i += 1;
    }
    true
}

fn parse_int(t: Str) -> Option<i64> {
    let mut neg = false;
    let mut first = true;
    let mut digits = 0;
    let mut v: i64 = 0;
    for c in t.chars() {
        if first {
            first = false;
            if c == "-" {
                neg = true;
                continue;
            }
            if c == "+" {
                continue;
            }
        }
        match digit_value(c) {
            Some(d) => {
                v = v * 10 + d;
                digits += 1;
            }
            None => {
                return None;
            }
        }
    }
    if digits == 0 {
        return None;
    }
    if neg {
        Some(0 - v)
    } else {
        Some(v)
    }
}

fn parse_part(text: Str) -> Option<Vec<i64>> {
    let mut vals: Vec<i64> = Vec::new();
    for line in text.lines() {
        let t = line.trim();
        if t.is_empty() {
            continue;
        }
        let parsed = parse_int(t);
        match parsed {
            Some(v) => {
                vals.push(v);
            }
            None => {
                return None;
            }
        }
    }
    Some(vals)
}

