fn main(input: Dir, counts: Kv) -> Result<Str, Error> {
    let text = input.read_to_string("visits.txt")?;

    // Tally this run's visits first.
    let mut run: Vec<(Str, i64)> = Vec::new();
    for line in text.lines() {
        let page = line.trim();
        if page.is_empty() {
            continue;
        }
        let mut found = false;
        for entry in run.iter_mut() {
            if entry.0 == page {
                entry.1 += 1;
                found = true;
                break;
            }
        }
        if !found {
            run.push((page.to_string(), 1));
        }
    }

    // Add this run's tallies to the persistent totals.
    for (page, n) in run.iter() {
        let prev: i64 = match counts.get(page)? {
            Some(v) => v.trim().parse::<i64>().unwrap_or(0),
            None => 0,
        };
        let total = prev + *n;
        counts.set(page, &total.to_string())?;
    }

    // Collect every page seen in any run.
    let mut all: Vec<(Str, i64)> = Vec::new();
    for key in counts.keys()? {
        let total: i64 = match counts.get(&key)? {
            Some(v) => v.trim().parse::<i64>().unwrap_or(0),
            None => 0,
        };
        all.push((key, total));
    }

    // Highest total first, then page in byte order.
    all.sort_by(|a, b| {
        if a.1 != b.1 {
            b.1.cmp(&a.1)
        } else {
            a.0.as_bytes().cmp(b.0.as_bytes())
        }
    });

    let mut out = String::new();
    for (page, total) in all.iter() {
        out.push_str(page);
        out.push_str(" ");
        out.push_str(&total.to_string());
        out.push_str("\n");
    }
    Ok(out)
}

