fn main(input: Dir, state: Kv) -> Result<Str, Error> {
    let text = input.read("events.jsonl")?;
    let mut applied: Int = 0;
    let mut dup: Int = 0;
    let mut rej: Int = 0;
    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        let v = match Json::parse(line) {
            Ok(v) => v,
            Err(_) => {
                rej += 1;
                continue;
            }
        };
        let id = match v.get("id").and_then(|x| x.as_str()) {
            Some(s) => s,
            None => {
                rej += 1;
                continue;
            }
        };
        let account = match v.get("account").and_then(|x| x.as_str()) {
            Some(s) => s,
            None => {
                rej += 1;
                continue;
            }
        };
        let cents = match v.get("cents").and_then(|x| x.as_int()) {
            Some(n) => n,
            None => {
                rej += 1;
                continue;
            }
        };
        let seen_key = "seen/" + id;
        if state.get(seen_key.clone())?.is_some() {
            dup += 1;
            continue;
        }
        let bal_key = "bal/" + account;
        let cur = match state.get(bal_key.clone())? {
            Some(s) => s.parse_int()?,
            None => 0,
        };
        state.set(bal_key, (cur + cents).to_str())?;
        state.set(seen_key, "1")?;
        applied += 1;
    }
    let mut out = "applied " + applied.to_str() + " duplicate " + dup.to_str() + " rejected " + rej.to_str();
    let mut keys = state.keys("bal/")?;
    keys.sort();
    for k in keys {
        let bal = state.get(k.clone())?.unwrap_or("0");
        out = out + "\n" + k.strip_prefix("bal/").unwrap_or(k.clone()) + " " + bal;
    }
    Ok(out)
}

