fn main(input: Dir, limits: Kv) -> Result<Str, Error> {
    let text = input.read("requests.txt")?;
    let mut out = Str::new();

    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }

        let fields: Vec<&str> = line.split_whitespace().collect();
        if fields.len() != 2 {
            continue;
        }

        let ts: i64 = match fields[0].parse::<i64>() {
            Ok(v) => v,
            Err(_) => continue,
        };
        let client = fields[1];
        let window = ts.div_euclid(60);

        // Count of allowed requests for this client in this window.
        let key = format!("{}|{}", window, client);
        let count: i64 = match limits.get(&key)? {
            Some(v) => match v.trim().parse::<i64>() {
                Ok(n) => n,
                Err(_) => 0,
            },
            None => 0,
        };

        let verdict = if count < 3 {
            limits.set(&key, &format!("{}", count + 1))?;
            "allow"
        } else {
            "deny"
        };

        out.push_str(&format!("{} {} {}\n", fields[0], client, verdict));
    }

    Ok(out)
}

