struct Rec {
    name: Str,
    points: i64,
    played: i64,
}

fn find(recs: &Vec<Rec>, name: &Str) -> Option<usize> {
    let mut i = 0;
    while i < recs.len() {
        if recs[i].name == *name {
            return Some(i);
        }
        i += 1;
    }
    None
}

fn add(recs: &mut Vec<Rec>, name: &Str, pts: i64) {
    match find(recs, name) {
        Some(i) => {
            recs[i].points += pts;
            recs[i].played += 1;
        }
        None => {
            recs.push(Rec { name: name.clone(), points: pts, played: 1 });
        }
    }
}

fn main(input: Dir, board: Kv) -> Result<Str, Error> {
    let mut recs: Vec<Rec> = Vec::new();

    // Load previous totals: one "NAME POINTS PLAYED" per line.
    match board.get("season")? {
        Some(saved) => {
            for line in saved.lines() {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() == 3 {
                    let p: i64 = match parts[1].parse() { Ok(v) => v, Err(_) => continue };
                    let g: i64 = match parts[2].parse() { Ok(v) => v, Err(_) => continue };
                    recs.push(Rec { name: parts[0].to_string(), points: p, played: g });
                }
            }
        }
        None => {}
    }

    let text = input.read("games.txt")?;
    for line in text.lines() {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() == 2 {
            add(&mut recs, &parts[0].to_string(), 3);
            add(&mut recs, &parts[1].to_string(), 0);
        } else if parts.len() == 3 && parts[2] == "draw" {
            add(&mut recs, &parts[0].to_string(), 1);
            add(&mut recs, &parts[1].to_string(), 1);
        }
    }

    // Save totals.
    let mut data = String::new();
    for r in recs.iter() {
        data.push_str(&format!("{} {} {}\n", r.name, r.points, r.played));
    }
    board.set("season", &data)?;

    recs.sort_by(|a, b| {
        b.points
            .cmp(&a.points)
            .then(a.played.cmp(&b.played))
            .then(a.name.as_bytes().cmp(b.name.as_bytes()))
    });

    let mut out = String::new();
    let mut i = 0;
    while i < recs.len() && i < 3 {
        let r = &recs[i];
        out.push_str(&format!("{}. {} {} {}\n", i + 1, r.name, r.points, r.played));
        i += 1;
    }
    Ok(out)
}

