        let line = recs[k].name.clone() + " " + recs[k].points.to_str() + " " + recs[k].played.to_str() + "\n";
        data = data + line;
        k += 1;
    }
    board.set("season", data)?;

    // Insertion sort: points desc, played asc, name asc (byte order).
    let mut i: usize = 1;
    while i < recs.len() {
        let mut j = i;
        while j > 0 {
            let better = if recs[j].points != recs[j - 1].points {
                recs[j].points > recs[j - 1].points
            } else if recs[j].played != recs[j - 1].played {
                recs[j].played < recs[j - 1].played
            } else {
                recs[j].name < recs[j - 1].name
            };
            if better {
                recs.swap(j, j - 1);
                j -= 1;
            } else {
                break;
            }
        }
        i += 1;
    }

    let mut out = Str::new();
    let mut i: usize = 0;
    let mut rank: i64 = 1;
    while i < recs.len() && i < 3 {
        let line = rank.to_str() + ". " + recs[i].name.clone() + " " + recs[i].points.to_str() + " " + recs[i].played.to_str() + "\n";
        out = out + line;
        i += 1;
        rank += 1;
    }
    Ok(out)
}

