fn parse_int(s: Str) -> Option<i64> {
    let t = s.trim();
    if t.is_empty() {
        return None;
    }
    let mut neg = false;
    let mut value: i64 = 0;
    let mut digits: i64 = 0;
    let mut idx: i64 = 0;
    for c in t.chars() {
        if idx == 0 && (c == '-' || c == '+') {
            if c == '-' {
                neg = true;
            }
            idx += 1;
            continue;
        }
        idx += 1;
        if c < '0' || c > '9' {
            return None;
        }
        let d: i64 = (c as i64) - ('0' as i64);
        value = value * 10 + d;
        digits += 1;
    }
    if digits == 0 {
        return None;
    }
    if neg {
        value = 0 - value;
    }
    Some(value)
}

