fn main(shop: Db) -> Result<Str, DbError> {
    let sql = "
        WITH p AS (
            SELECT o.customer_id AS customer_id,
                   o.total_cents AS total_cents,
                   c.country AS country,
                   c.name AS name
            FROM orders o
            JOIN customers c ON c.id = o.customer_id
            WHERE o.status = 'paid'
              AND substr(o.placed, 1, 4) = '2026'
        ),
        cust AS (
            SELECT country, customer_id, name, SUM(total_cents) AS rev
            FROM p
            GROUP BY country, customer_id, name
        ),
        ranked AS (
            SELECT country, name,
                   ROW_NUMBER() OVER (PARTITION BY country ORDER BY rev DESC, customer_id ASC) AS rn
            FROM cust
        ),
        agg AS (
            SELECT country,
                   COUNT(DISTINCT customer_id) AS nc,
                   COUNT(*) AS n,
                   SUM(total_cents) AS r
            FROM p
            GROUP BY country
        )
        SELECT a.country, a.nc, a.n, a.r, k.name
        FROM agg a
        JOIN ranked k ON k.country = a.country AND k.rn = 1
        ORDER BY a.r DESC, a.country ASC
    ";

    let rows = shop.query(sql, [])?;

    let mut out = Str::new();
    let mut total_orders: i64 = 0;
    let mut total_revenue: i64 = 0;

    for row in rows {
        let country: Str = row.get(0)?;
        let customers: i64 = row.get(1)?;
        let orders: i64 = row.get(2)?;
        let revenue: i64 = row.get(3)?;
        let top: Str = row.get(4)?;

        total_orders += orders;
        total_revenue += revenue;

        out.push_str(&format!(
            "{} customers={} orders={} revenue={} top={}\n",
            country, customers, orders, revenue, top
        ));
    }

    out.push_str(&format!("total orders={} revenue={}\n", total_orders, total_revenue));

    Ok(out)
}

