fn parse_move(line: &str) -> Option<(String, i64)> {
    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() != 2 {
        return None;
    }
    let sku = parts[0];
    let amt = parts[1];
    if amt.len() < 2 {
        return None;
    }
    let sign = &amt[0..1];
    let digits = &amt[1..];
    if !digits.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let n: i64 = match digits.parse::<i64>() {
        Ok(v) => v,
        Err(_) => return None,
    };
    if n <= 0 {
        return None;
    }
    if sign == "+" {
        Some((sku.to_string(), n))
    } else if sign == "-" {
        Some((sku.to_string(), -n))
    } else {
        None
    }
}

fn main(input: Dir, stock: Db) -> Result<Str, Str> {
    stock.exec("CREATE TABLE IF NOT EXISTS inventory (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)", [])?;
    stock.exec("CREATE TABLE IF NOT EXISTS batches (name TEXT PRIMARY KEY)", [])?;

    let mut qty: BTreeMap<String, i64> = BTreeMap::new();
    for row in stock.query("SELECT sku, qty FROM inventory", [])? {
        qty.insert(row.get_str(0)?, row.get_int(1)?);
    }
    let mut done: BTreeSet<String> = BTreeSet::new();
    for row in stock.query("SELECT name FROM batches", [])? {
        done.insert(row.get_str(0)?);
    }

    let text = input.read("moves.txt")?;

    // Group lines into batches: (name, move lines)
    let mut batches: Vec<(String, Vec<String>)> = Vec::new();
    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        if line == "batch" || line.starts_with("batch ") || line.starts_with("batch\t") {
            let name = line[5..].trim().to_string();
            batches.push((name, Vec::new()));
        } else if let Some(last) = batches.last_mut() {
            last.1.push(line.to_string());
        }
    }

    let mut out = String::new();
    let mut new_batches: Vec<String> = Vec::new();
