fn main(input: Dir, crm: Db) -> Result<Str, Error> {
    crm.execute(
        "CREATE TABLE IF NOT EXISTS contacts (email TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL)",
        &[],
    )?;

    let text = input.read_to_string("contacts.csv")?;

    let mut inserted: i64 = 0;
    let mut updated: i64 = 0;
    let mut unchanged: i64 = 0;
    let mut rejected: i64 = 0;

    let mut first = true;
    for raw in text.lines() {
        if first {
            first = false;
            continue;
        }
        let line = raw.trim_end_matches('\r');
        if line.trim().is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() != 3 {
            rejected += 1;
            continue;
        }
        let email = fields[0].trim().to_lowercase();
        if !email.contains('@') {
            rejected += 1;
            continue;
        }
        let name = fields[1].trim().to_string();
        let phone = fields[2].trim().to_string();

        let rows = crm.query(
            "SELECT name, phone FROM contacts WHERE email = ?1",
            &[email.clone()],
        )?;
        if rows.is_empty() {
            crm.execute(
                "INSERT INTO contacts (email, name, phone) VALUES (?1, ?2, ?3)",
                &[email.clone(), name.clone(), phone.clone()],
            )?;
            inserted += 1;
        } else {
            let old_name: Str = rows[0].get(0)?;
            let old_phone: Str = rows[0].get(1)?;
            if old_name != name || old_phone != phone {
                crm.execute(
                    "UPDATE contacts SET name = ?2, phone = ?3 WHERE email = ?1",
                    &[email.clone(), name.clone(), phone.clone()],
                )?;
                updated += 1;
            } else {
                unchanged += 1;
            }
        }
    }

    let mut out = format!(
        "inserted {} updated {} unchanged {} rejected {}\n",
        inserted, updated, unchanged, rejected
    );

    let count_rows = crm.query("SELECT COUNT(*) FROM contacts", &[])?;
    let total: i64 = count_rows[0].get(0)?;
    out.push_str(&format!("contacts {}\n", total));

    let missing = crm.query(
        "SELECT email FROM contacts WHERE phone = '' ORDER BY email",
        &[],
    )?;
    for row in missing.iter() {
        let email: Str = row.get(0)?;
        out.push_str(&format!("missing phone: {}\n", email));
    }

    Ok(out)
}

