fn valid_name(name: &Str) -> bool {
    let n = name.len();
    if n < 1 || n > 32 {
        return false;
    }
    for c in name.chars() {
        let ok = (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-';
        if !ok {
            return false;
        }
    }
    true
}

fn get_count(counts: &Kv, name: &Str) -> i64 {
    match counts.get(name) {
        Some(v) => match v.parse::<i64>() {
            Ok(n) => n,
            Err(_) => 0,
        },
        None => 0,
    }
}

fn entry_json(name: &Str, count: i64) -> Str {
    format!("{{\"name\": \"{}\", \"count\": {}}}", name, count)
}

fn send(res: &Outgoing, status: i64, body: Str) {
    res.status(status);
    res.header("content-type", "application/json");
    res.write(body);
}

// Returns true if (an, ac) should come before (bn, bc).
fn before(an: &Str, ac: i64, bn: &Str, bc: i64) -> bool {
    if ac != bc {
        return ac > bc;
    }
    an.as_bytes() < bn.as_bytes()
}

fn main(req: Incoming, res: Outgoing, counts: Kv) -> Result<Str, Str> {
    let method = req.method();
    let path = req.path();

    if method == "GET" && path == "/top" {
        let mut items: Vec<(Str, i64)> = Vec::new();
        for key in counts.keys() {
            let c = get_count(&counts, &key);
            items.push((key, c));
        }
        // insertion sort
        let mut i = 1;
        while i < items.len() {
            let mut j = i;
            while j > 0 {
                let swap = before(&items[j].0, items[j].1, &items[j - 1].0, items[j - 1].1);
                if swap {
                    items.swap(j, j - 1);
                    j = j - 1;
                } else {
                    break;
                }
            }
            i = i + 1;
        }
        let mut body = Str::from("[");
        let mut k = 0;
        while k < items.len() && k < 3 {
            if k > 0 {
                body.push_str(", ");
            }
            body.push_str(&entry_json(&items[k].0, items[k].1));
            k = k + 1;
        }
        body.push_str("]");
        send(&res, 200, body);
        return Ok(Str::from(""));
    }

    if method == "POST" && path.starts_with("/hit/") {
        let name: Str = path["/hit/".len()..].to_string();
        if !valid_name(&name) {
            send(&res, 400, Str::from("{\"error\": \"bad name\"}"));
            return Ok(Str::from(""));
        }
        let n = get_count(&counts, &name) + 1;
        counts.set(&name, &format!("{}", n));
        send(&res, 200, entry_json(&name, n));
        return Ok(Str::from(""));
    }

    if method == "GET" && path.starts_with("/count/") {
        let name: Str = path["/count/".len()..].to_string();
        if !valid_name(&name) {
            send(&res, 400, Str::from("{\"error\": \"bad name\"}"));
            return Ok(Str::from(""));
        }
        let n = get_count(&counts, &name);
        send(&res, 200, entry_json(&name, n));
        return Ok(Str::from(""));
    }

    send(&res, 404, Str::from("{\"error\": \"not found\"}"));
    Ok(Str::from(""))
}

