    while i < s.len() {
        let c: Str = s[i..i + 1].to_string();
        let mut val: i64 = 0;
        let mut found: i64 = -1;
        for dg in digits {
            if c == dg {
                found = val;
            }
            val = val + 1;
        }
        if found < 0 {
            return 0;
        }
        n = n * 10 + found;
        i = i + 1;
    }
    n
}

