        if method == "GET" {
            let filter = query_done(query);
            let mut list = ids_from(store.get("ids"));
            list.sort();
            let mut o = Str::new();
            o.push_str("[");
            let mut first = true;
            for id in list {
                match store.get(todo_key(id)) {
                    Some(raw) => match decode(raw) {
                        Some(td) => {
                            let keep = match filter {
                                Some(want) => want == td.done,
                                None => true,
                            };
                            if keep {
                                if !first {
                                    o.push_str(",");
                                }
                                first = false;
                                o.push_str(todo_json(id, td.title, td.done));
                            }
                        }
                        None => {}
                    },
                    None => {}
                }
            }
            o.push_str("]");
            return reply(res, 200, o);
        }
        return reply(res, 404, err_json("not found"));
    }

    if path.starts_with("/todos/") {
        let mut rest = Str::new();
        let mut n = 0;
        for ch in path.chars() {
            if n >= 7 {
                rest.push_str(ch);
            }
            n += 1;
        }
        let id = match parse_id(rest) {
            Some(n) => n,
            None => return reply(res, 404, err_json("not found")),
        };
        if method != "GET" && method != "PATCH" && method != "DELETE" {
            return reply(res, 404, err_json("not found"));
        }
        let loaded = match store.get(todo_key(id)) {
            Some(raw) => decode(raw),
            None => None,
        };
        let td = match loaded {
            Some(x) => x,
            None => return reply(res, 404, err_json("not found")),
        };
        if method == "GET" {
            return reply(res, 200, todo_json(id, td.title, td.done));
        }
        if method == "DELETE" {
            store.delete(todo_key(id));
            let list = ids_from(store.get("ids"));
            let mut kept: Vec<u64> = Vec::new();
            for m in list {
                if m != id {
                    kept.push(m);
                }
            }
            store.set("ids", ids_str(kept));
            res.status(204);
            res.body("");
            return Str::new();
        }
        let body = req.body();
        let mut new_title = td.title;
        let mut new_done = td.done;
        match parse(body) {
            Some(J::Obj(items)) => {
                for f in items {
                    if f.k == "title" {
                        match f.v {
                            J::S(t) => {
                                let tt = trim_units(t);
                                if tt.len() == 0 {
                                    return reply(res, 400, err_json("bad update"));
                                }
                                new_title = tt;
                            }
                            _ => return reply(res, 400, err_json("bad update")),
                        }
                    } else if f.k == "done" {
                        match f.v {
                            J::Bool(b) => new_done = b,
                            _ => return reply(res, 400, err_json("bad update")),
                        }
                    }
                }
            }
            _ => return reply(res, 400, err_json("bad update")),
        }
        store.set(todo_key(id), todo_json(id, new_title.clone(), new_done));
        return reply(res, 200, todo_json(id, new_title, new_done));
    }

    reply(res, 404, err_json("not found"))
}

enum J {
    Null,
    Bool(bool),
    Num(Str),
    S(Vec<Str>),
    Arr(Vec<J>),
    Obj(Vec<Field>),
}

struct Field {
    k: Str,
    v: J,
}

struct P {
    c: Vec<Str>,
    i: usize,
}

struct LitR {
    p: P,
    ok: bool,
}

struct StrR {
    p: P,
    v: Option<Vec<Str>>,
}

struct NumR {
    p: P,
    v: Option<Str>,
}

struct ValR {
    p: P,
    v: Option<J>,
}

struct Todo {
    title: Str,
    done: bool,
}

fn is_digit(ch: Str) -> bool {
    ch == "0" || ch == "1" || ch == "2" || ch == "3" || ch == "4" || ch == "5" || ch == "6"
        || ch == "7" || ch == "8" || ch == "9"
}

fn dval(ch: Str) -> u64 {
    if ch == "1" {
        return 1;
    }
    if ch == "2" {
        return 2;
    }
    if ch == "3" {
        return 3;
    }
    if ch == "4" {
        return 4;
    }
    if ch == "5" {
        return 5;
    }
    if ch == "6" {
        return 6;
    }
    if ch == "7" {
        return 7;
    }
    if ch == "8" {
        return 8;
    }
    if ch == "9" {
        return 9;
    }
    0
}

fn to_u64(s: Str) -> Option<u64> {
    let cs: Vec<Str> = s.chars().collect();
    if cs.len() == 0 || cs.len() > 18 {
        return None;
    }
    let mut n: u64 = 0;
    for ch in cs {
        if !is_digit(ch.clone()) {
            return None;
        }
        n = n * 10 + dval(ch);
    }
    Some(n)
}

fn is_hex(ch: Str) -> bool {
    if is_digit(ch.clone()) {
        return true;
    }
    ch == "a" || ch == "b" || ch == "c" || ch == "d" || ch == "e" || ch == "f" || ch == "A"
        || ch == "B" || ch == "C" || ch == "D" || ch == "E" || ch == "F"
}

fn ws(p: P) -> P {
    let mut p = p;
    while p.i < p.c.len() {
        let ch = p.c[p.i].clone();
        if ch == " " || ch == "\n" || ch == "\r" || ch == "\t" {
            p.i += 1;
        } else {
            break;
        }
    }
    p
}

fn lit(p: P, w: Str) -> LitR {
    let mut p = p;
    let wc: Vec<Str> = w.chars().collect();
    if p.i + wc.len() > p.c.len() {
        return LitR { p: p, ok: false };
    }
    let mut k = 0;
    while k < wc.len() {
        if p.c[p.i + k] != wc[k] {
            return LitR { p: p, ok: false };
        }
        k += 1;
    }
    p.i += wc.len();
    LitR { p: p, ok: true }
}

fn pstr(p: P) -> StrR {
    let mut p = p;
    if p.i >= p.c.len() || p.c[p.i] != "\"" {
        return StrR { p: p, v: None };
    }
    p.i += 1;
    let mut units: Vec<Str> = Vec::new();
    loop {
        if p.i >= p.c.len() {
            return StrR { p: p, v: None };
        }
        let ch = p.c[p.i].clone();
        p.i += 1;
        if ch == "\"" {
            return StrR { p: p, v: Some(units) };
        }
        if ch == "\n" || ch == "\r" || ch == "\t" {
            return StrR { p: p, v: None };
        }
        if ch == "\\" {
            if p.i >= p.c.len() {
                return StrR { p: p, v: None };
            }
            let e = p.c[p.i].clone();
            p.i += 1;
            if e == "\"" || e == "\\" || e == "/" || e == "b" || e == "f" || e == "n" || e == "r"
                || e == "t"
            {
                let mut u = Str::new();
                u.push_str("\\");
                u.push_str(e);
                units.push(u);
            } else if e == "u" {
                if p.i + 4 > p.c.len() {
                    return StrR { p: p, v: None };
                }
                let mut u = Str::new();
                u.push_str("\\u");
                let mut k = 0;
                while k < 4 {
                    let h = p.c[p.i + k].clone();
                    if !is_hex(h.clone()) {
                        return StrR { p: p, v: None };
                    }
                    u.push_str(h);
                    k += 1;
                }
                p.i += 4;
                units.push(u);
            } else {
                return StrR { p: p, v: None };
            }
        } else {
            units.push(ch);
        }
    }
}

fn pnum(p: P) -> NumR {
    let mut p = p;
    let start = p.i;
    if p.i < p.c.len() && p.c[p.i] == "-" {
        p.i += 1;
    }
    let mut digits = 0;
    while p.i < p.c.len() && is_digit(p.c[p.i].clone()) {
        p.i += 1;
        digits += 1;
    }
    if digits == 0 {
        return NumR { p: p, v: None };
    }
    if p.i < p.c.len() && p.c[p.i] == "." {
        p.i += 1;
        let mut fd = 0;
        while p.i < p.c.len() && is_digit(p.c[p.i].clone()) {
            p.i += 1;
            fd += 1;
        }
        if fd == 0 {
            return NumR { p: p, v: None };
        }
    }
    if p.i < p.c.len() && (p.c[p.i] == "e" || p.c[p.i] == "E") {
        p.i += 1;
        if p.i < p.c.len() && (p.c[p.i] == "+" || p.c[p.i] == "-") {
            p.i += 1;
        }
        let mut ed = 0;
        while p.i < p.c.len() && is_digit(p.c[p.i].clone()) {
            p.i += 1;
            ed += 1;
        }
        if ed == 0 {
            return NumR { p: p, v: None };
        }
    }
    let mut s = Str::new();
    let mut k = start;
    while k < p.i {
        s.push_str(p.c[k].clone());
        k += 1;
    }
    NumR { p: p, v: Some(s) }
}

fn join(u: Vec<Str>) -> Str {
    let mut s = Str::new();
    for x in u {
        s.push_str(x);
    }
    s
}

fn is_ws_unit(u: Str) -> bool {
    u == " " || u == "\\n" || u == "\\t" || u == "\\r" || u == "\\u0020" || u == "\\u0009"
        || u == "\\u000a" || u == "\\u000A" || u == "\\u000d" || u == "\\u000D"
}

fn trim_units(u: Vec<Str>) -> Str {
    let mut start = 0;
    let mut end = u.len();
    while start < end && is_ws_unit(u[start].clone()) {
        start += 1;
    }
    while end > start && is_ws_unit(u[end - 1].clone()) {
        end -= 1;
    }
    let mut s = Str::new();
    let mut k = start;
    while k < end {
        s.push_str(u[k].clone());
        k += 1;
    }
    s
}

fn pval(p: P, depth: usize) -> ValR {
    let mut p = p;
    if depth > 200 {
        return ValR { p: p, v: None };
    }
    p = ws(p);
    if p.i >= p.c.len() {
        return ValR { p: p, v: None };
    }
    let ch = p.c[p.i].clone();
    if ch == "\"" {
        let r = pstr(p);
        let q = r.p;
        return match r.v {
            Some(s) => ValR { p: q, v: Some(J::S(s)) },
            None => ValR { p: q, v: None },
        };
    }
    if ch == "{" {
        p.i += 1;
        let mut items: Vec<Field> = Vec::new();
        p = ws(p);
        if p.i < p.c.len() && p.c[p.i] == "}" {
            p.i += 1;
            return ValR { p: p, v: Some(J::Obj(items)) };
        }
        loop {
            p = ws(p);
            let r = pstr(p);
            p = r.p;
            let k = match r.v {
                Some(k) => join(k),
                None => return ValR { p: p, v: None },
            };
            p = ws(p);
            if p.i >= p.c.len() || p.c[p.i] != ":" {
                return ValR { p: p, v: None };
            }
            p.i += 1;
            let r2 = pval(p, depth + 1);
            p = r2.p;
            let v = match r2.v {
                Some(v) => v,
                None => return ValR { p: p, v: None },
            };
            items.push(Field { k: k, v: v });
            p = ws(p);
            if p.i >= p.c.len() {
                return ValR { p: p, v: None };
            }
            if p.c[p.i] == "," {
                p.i += 1;
            } else if p.c[p.i] == "}" {
                p.i += 1;
                return ValR { p: p, v: Some(J::Obj(items)) };
            } else {
                return ValR { p: p, v: None };
            }
        }
    }
    if ch == "[" {
        p.i += 1;
        let mut items: Vec<J> = Vec::new();
        p = ws(p);
        if p.i < p.c.len() && p.c[p.i] == "]" {
            p.i += 1;
            return ValR { p: p, v: Some(J::Arr(items)) };
        }
        loop {
            let r = pval(p, depth + 1);
            p = r.p;
            let v = match r.v {
                Some(v) => v,
                None => return ValR { p: p, v: None },
            };
            items.push(v);
            p = ws(p);
            if p.i >= p.c.len() {
                return ValR { p: p, v: None };
            }
            if p.c[p.i] == "," {
                p.i += 1;
            } else if p.c[p.i] == "]" {
                p.i += 1;
                return ValR { p: p, v: Some(J::Arr(items)) };
            } else {
                return ValR { p: p, v: None };
            }
        }
    }
    let l1 = lit(p, "true");
    p = l1.p;
    if l1.ok {
        return ValR { p: p, v: Some(J::Bool(true)) };
    }
    let l2 = lit(p, "false");
    p = l2.p;
    if l2.ok {
        return ValR { p: p, v: Some(J::Bool(false)) };
    }
    let l3 = lit(p, "null");
    p = l3.p;
    if l3.ok {
        return ValR { p: p, v: Some(J::Null) };
    }
    let n = pnum(p);
    let q = n.p;
    match n.v {
        Some(s) => ValR { p: q, v: Some(J::Num(s)) },
        None => ValR { p: q, v: None },
    }
}

fn parse(s: Str) -> Option<J> {
    let p = P { c: s.chars().collect(), i: 0 };
    let r = pval(p, 0);
    let q = ws(r.p);
    if q.i != q.c.len() {
        return None;
    }
    r.v
}

fn todo_json(id: u64, title: Str, done: bool) -> Str {
    let mut o = Str::new();
    o.push_str("{\"id\":");
    o.push_str(id.to_string());
    o.push_str(",\"title\":\"");
    o.push_str(title);
    o.push_str("\",\"done\":");
    if done {
        o.push_str("true");
    } else {
        o.push_str("false");
    }
    o.push_str("}");
    o
}

fn err_json(msg: Str) -> Str {
    let mut o = Str::new();
    o.push_str("{\"error\":\"");
    o.push_str(msg);
    o.push_str("\"}");
    o
}

fn todo_key(id: u64) -> Str {
    let mut k = Str::new();
    k.push_str("todo:");
    k.push_str(id.to_string());
    k
}

fn decode(raw: Str) -> Option<Todo> {
    let v = match parse(raw) {
        Some(v) => v,
        None => return None,
    };
    let mut title: Option<Str> = None;
    let mut done = false;
    match v {
        J::Obj(items) => {
            for f in items {
                if f.k == "title" {
                    match f.v {
                        J::S(t) => title = Some(join(t)),
                        _ => {}
                    }
                } else if f.k == "done" {
                    match f.v {
                        J::Bool(b) => done = b,
                        _ => {}
                    }
                }
            }
        }
        _ => {}
    }
    match title {
        Some(t) => Some(Todo { title: t, done: done }),
        None => None,
    }
}

fn ids_from(raw: Option<Str>) -> Vec<u64> {
    let mut out: Vec<u64> = Vec::new();
    match raw {
        Some(s) => {
            let mut cur = Str::new();
            for ch in s.chars() {
                if ch == "," {
                    match to_u64(cur.clone()) {
                        Some(n) => out.push(n),
                        None => {}
                    }
                    cur = Str::new();
                } else {
                    cur.push_str(ch);
                }
            }
            match to_u64(cur) {
                Some(n) => out.push(n),
                None => {}
            }
        }
        None => {}
    }
    out
}

fn ids_str(list: Vec<u64>) -> Str {
    let mut s = Str::new();
    let mut first = true;
    for n in list {
        if !first {
            s.push_str(",");
        }
        first = false;
        s.push_str(n.to_string());
    }
    s
}

fn reply(res: Outgoing, status: u16, body: Str) -> Str {
    res.status(status);
    if body.len() > 0 {
        res.header("content-type", "application/json");
    }
    res.body(body);
    Str::new()
}

fn check_pair(k: Str, v: Str, cur: Option<bool>) -> Option<bool> {
    if k == "done" {
        if v == "true" {
            return Some(true);
        }
        if v == "false" {
            return Some(false);
        }
    }
    cur
}

fn query_done(q: Str) -> Option<bool> {
    let mut result: Option<bool> = None;
    let mut k = Str::new();
    let mut v = Str::new();
    let mut seen_eq = false;
    for ch in q.chars() {
        if ch == "&" {
            result = check_pair(k.clone(), v.clone(), result);
            k = Str::new();
            v = Str::new();
            seen_eq = false;
        } else if !seen_eq && ch == "=" {
            seen_eq = true;
        } else if seen_eq {
            v.push_str(ch);
        } else {
            k.push_str(ch);
        }
    }
    result = check_pair(k, v, result);
    result
}

fn main(req: Incoming, res: Outgoing, store: Kv) -> Str {
    let method = req.method();
    let full = req.path();
    let mut path = Str::new();
    let mut query = Str::new();
    let mut in_q = false;
    for ch in full.chars() {
        if !in_q && ch == "?" {
            in_q = true;
        } else if in_q {
            query.push_str(ch);
        } else {
            path.push_str(ch);
        }
    }
    if !in_q {
        query = req.query();
    }

    if path == "/todos" || path == "/todos/" {
        if method == "POST" {
            let body = req.body();
            let mut title: Option<Str> = None;
            match parse(body) {
                Some(J::Obj(items)) => {
                    for f in items {
                        if f.k == "title" {
                            match f.v {
                                J::S(t) => {
                                    let tt = trim_units(t);
                                    if tt.len() > 0 {
                                        title = Some(tt);
                                    } else {
                                        title = None;
                                    }
                                }
                                _ => title = None,
                            }
                        }
                    }
                }
                _ => {}
            }
            let t = match title {
                Some(t) => t,
                None => return reply(res, 400, err_json("title required")),
            };
            let next: u64 = match store.get("next") {
                Some(s) => match to_u64(s) {
                    Some(n) => n,
                    None => 1,
                },
                None => 1,
            };
            store.set("next", (next + 1).to_string());
            store.set(todo_key(next), todo_json(next, t.clone(), false));
            let mut list = ids_from(store.get("ids"));
            list.push(next);
            store.set("ids", ids_str(list));
            return reply(res, 201, todo_json(next, t, false));
        }
        if method == "GET" {
            let filter = query_done(query);
            let list = ids_from(store.get("ids"));
            let mut o = Str::new();
            o.push_str("[");
            let mut first = true;
            for id in list {
                match store.get(todo_key(id)) {
                    Some(raw) => match decode(raw) {
                        Some(td) => {
                            let keep = match filter {
                                Some(want) => want == td.done,
                                None => true,
                            };
                            if keep {
                                if !first {
                                    o.push_str(",");
                                }
                                first = false;
                                o.push_str(todo_json(id, td.title, td.done));
                            }
                        }
                        None => {}
                    },
                    None => {}
                }
            }
            o.push_str("]");
            return reply(res, 200, o);
        }
        return reply(res, 404, err_json("not found"));
    }

    if path.starts_with("/todos/") {
        let mut rest = Str::new();
        let mut n = 0;
        for ch in path.chars() {
            if n >= 7 {
                rest.push_str(ch);
            }
            n += 1;
        }
        let id = match to_u64(rest) {
            Some(n) => n,
            None => return reply(res, 404, err_json("not found")),
        };
        if method != "GET" && method != "PATCH" && method != "DELETE" {
            return reply(res, 404, err_json("not found"));
        }
        let loaded = match store.get(todo_key(id)) {
            Some(raw) => decode(raw),
            None => None,
        };
        let td = match loaded {
            Some(x) => x,
            None => return reply(res, 404, err_json("not found")),
        };
        if method == "GET" {
            return reply(res, 200, todo_json(id, td.title, td.done));
        }
        if method == "DELETE" {
            store.delete(todo_key(id));
            let list = ids_from(store.get("ids"));
            let mut kept: Vec<u64> = Vec::new();
            for m in list {
                if m != id {
                    kept.push(m);
                }
            }
            store.set("ids", ids_str(kept));
            res.status(204);
            res.body("");
            return Str::new();
        }
        let body = req.body();
        let mut new_title = td.title;
        let mut new_done = td.done;
        match parse(body) {
            Some(J::Obj(items)) => {
                for f in items {
                    if f.k == "title" {
                        match f.v {
                            J::S(t) => {
                                let tt = trim_units(t);
                                if tt.len() == 0 {
                                    return reply(res, 400, err_json("bad update"));
                                }
                                new_title = tt;
                            }
                            _ => return reply(res, 400, err_json("bad update")),
                        }
                    } else if f.k == "done" {
                        match f.v {
                            J::Bool(b) => new_done = b,
                            _ => return reply(res, 400, err_json("bad update")),
                        }
                    }
                }
            }
            _ => return reply(res, 400, err_json("bad update")),
        }
        store.set(todo_key(id), todo_json(id, new_title.clone(), new_done));
        return reply(res, 200, todo_json(id, new_title, new_done));
    }

    reply(res, 404, err_json("not found"))
}

enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct Parser {
    cs: Vec<char>,
    i: usize,
}

impl Parser {
    fn ws(&mut self) {
        while self.i < self.cs.len() {
            let c = self.cs[self.i];
            if c == ' ' || c == '\n' || c == '\r' || c == '\t' {
                self.i += 1;
            } else {
                break;
            }
        }
    }

    fn peek(&self) -> Option<char> {
        if self.i < self.cs.len() { Some(self.cs[self.i]) } else { None }
    }

    fn lit(&mut self, w: &str) -> bool {
        let ws: Vec<char> = w.chars().collect();
        if self.i + ws.len() > self.cs.len() {
            return false;
        }
        for k in 0..ws.len() {
            if self.cs[self.i + k] != ws[k] {
                return false;
            }
        }
        self.i += ws.len();
        true
    }

    fn hex4(&mut self) -> Option<u32> {
        if self.i + 4 > self.cs.len() {
            return None;
        }
        let mut v: u32 = 0;
        for _ in 0..4 {
            let d = self.cs[self.i].to_digit(16)?;
            v = v * 16 + d;
            self.i += 1;
        }
        Some(v)
    }

    fn string(&mut self) -> Option<Str> {
        if self.peek() != Some('"') {
            return None;
        }
        self.i += 1;
        let mut out = Str::new();
        loop {
            let c = self.peek()?;
            self.i += 1;
            if c == '"' {
                return Some(out);
            }
            if (c as u32) < 0x20 {
                return None;
            }
            if c != '\\' {
                out.push(c);
                continue;
            }
            let e = self.peek()?;
            self.i += 1;
            match e {
                '"' => out.push('"'),
                '\\' => out.push('\\'),
                '/' => out.push('/'),
                'b' => out.push('\u{8}'),
                'f' => out.push('\u{c}'),
                'n' => out.push('\n'),
                'r' => out.push('\r'),
                't' => out.push('\t'),
                'u' => {
                    let h = self.hex4()?;
                    if h >= 0xD800 && h < 0xDC00 {
                        if !self.lit("\\u") {
                            return None;
                        }
                        let l = self.hex4()?;
                        if l < 0xDC00 || l >= 0xE000 {
                            return None;
                        }
                        let cp = 0x10000 + ((h - 0xD800) << 10) + (l - 0xDC00);
                        out.push(char::from_u32(cp)?);
                    } else if h >= 0xDC00 && h < 0xE000 {
                        return None;
                    } else {
                        out.push(char::from_u32(h)?);
                    }
                }
                _ => return None,
            }
        }
    }

    fn number(&mut self) -> Option<Json> {
        let start = self.i;
        if self.peek() == Some('-') {
            self.i += 1;
        }
        let mut digits = 0;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() { self.i += 1; digits += 1; } else { break; }
        }
        if digits == 0 {
            return None;
        }
        if self.peek() == Some('.') {
            self.i += 1;
            let mut d = 0;
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() { self.i += 1; d += 1; } else { break; }
            }
            if d == 0 { return None; }
        }
        if self.peek() == Some('e') || self.peek() == Some('E') {
            self.i += 1;
            if self.peek() == Some('+') || self.peek() == Some('-') {
                self.i += 1;
            }
            let mut d = 0;
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() { self.i += 1; d += 1; } else { break; }
            }
            if d == 0 { return None; }
        }
        let s: Str = self.cs[start..self.i].iter().collect();
        let v: f64 = s.parse().ok()?;
        Some(Json::Num(v))
    }

    fn value(&mut self, depth: usize) -> Option<Json> {
        if depth > 200 {
            return None;
        }
        self.ws();
        let c = self.peek()?;
        if c == '{' {
            self.i += 1;
            let mut items: Vec<(Str, Json)> = Vec::new();
            self.ws();
            if self.peek() == Some('}') {
                self.i += 1;
                return Some(Json::Obj(items));
            }
            loop {
                self.ws();
                let k = self.string()?;
                self.ws();
                if self.peek() != Some(':') {
                    return None;
                }
                self.i += 1;
                let v = self.value(depth + 1)?;
                items.push((k, v));
                self.ws();
                match self.peek()? {
                    ',' => { self.i += 1; }
                    '}' => { self.i += 1; return Some(Json::Obj(items)); }
                    _ => return None,
                }
            }
        } else if c == '[' {
            self.i += 1;
            let mut items: Vec<Json> = Vec::new();
            self.ws();
            if self.peek() == Some(']') {
                self.i += 1;
                return Some(Json::Arr(items));
            }
            loop {
                let v = self.value(depth + 1)?;
                items.push(v);
                self.ws();
                match self.peek()? {
                    ',' => { self.i += 1; }
                    ']' => { self.i += 1; return Some(Json::Arr(items)); }
                    _ => return None,
                }
            }
        } else if c == '"' {
            Some(Json::Text(self.string()?))
        } else if self.lit("true") {
            Some(Json::Bool(true))
        } else if self.lit("false") {
            Some(Json::Bool(false))
        } else if self.lit("null") {
            Some(Json::Null)
        } else {
            self.number()
        }
    }
}

fn parse_json(s: &str) -> Option<Json> {
    let mut p = Parser { cs: s.chars().collect(), i: 0 };
    let v = p.value(0)?;
    p.ws();
    if p.i != p.cs.len() {
        return None;
    }
    Some(v)
}

fn quote(s: &str) -> Str {
    let mut o = Str::from("\"");
    for c in s.chars() {
        match c {
            '"' => o.push_str("\\\""),
            '\\' => o.push_str("\\\\"),
            '\n' => o.push_str("\\n"),
            '\r' => o.push_str("\\r"),
            '\t' => o.push_str("\\t"),
            c if (c as u32) < 0x20 => o.push_str(&format!("\\u{:04x}", c as u32)),
            c => o.push(c),
        }
    }
    o.push('"');
    o
}

fn sql_str(s: &str) -> Str {
    format!("'{}'", s.replace("'", "''"))
}

fn tags_json(tags: &Vec<Str>) -> Str {
    let parts: Vec<Str> = tags.iter().map(|t| quote(t)).collect();
    format!("[{}]", parts.join(","))
}

fn parse_tags(s: &str) -> Vec<Str> {
    let mut out: Vec<Str> = Vec::new();
    if let Some(Json::Arr(items)) = parse_json(s) {
        for it in items {
            if let Json::Text(t) = it {
                out.push(t);
            }
        }
    }
    out
}

fn not_found() -> (u16, Str) {
    (404, Str::from("{\"error\": \"not found\"}"))
}

fn invalid() -> (u16, Str) {
    (400, Str::from("{\"error\": \"invalid note\"}"))
}

fn parse_id(s: &str) -> Option<i64> {
    if s.is_empty() || s.len() > 18 {
        return None;
    }
    for c in s.chars() {
        if !c.is_ascii_digit() {
            return None;
        }
    }
    s.parse().ok()
}

fn validate(body: &str) -> Option<(Str, Str, Vec<Str>)> {
    let v = parse_json(body)?;
    let items = match v {
        Json::Obj(items) => items,
        _ => return None,
    };
    let mut title: Option<Str> = None;
    let mut text: Option<Str> = None;
    let mut tags: Vec<Str> = Vec::new();
    let mut seen_tags = false;
    for (k, v) in items {
        if k == "title" {
            match v {
                Json::Text(t) => title = Some(t),
                _ => return None,
            }
        } else if k == "body" {
            match v {
                Json::Text(t) => text = Some(t),
                _ => return None,
            }
        } else if k == "tags" {
            seen_tags = true;
            tags = Vec::new();
            match v {
                Json::Arr(arr) => {
                    for t in arr {
                        match t {
                            Json::Text(s) => {
                                let l = s.to_lowercase();
                                if !tags.contains(&l) {
                                    tags.push(l);
                                }
                            }
                            _ => return None,
                        }
                    }
                }
                _ => return None,
            }
        }
    }
    let _ = seen_tags;
    let title = title?;
    if title.is_empty() {
        return None;
    }
    let text = text?;
    Some((title, text, tags))
}

fn route(method: &str, target: &str, body: &str, db: &Db) -> Result<(u16, Str), Str> {
    let (path, query) = match target.find('?') {
        Some(p) => (&target[..p], &target[p + 1..]),
        None => (target, ""),
    };

    if path == "/notes" {
        if method == "POST" {
            let (title, text, tags) = match validate(body) {
                Some(x) => x,
                None => return Ok(invalid()),
            };
            let sql = format!(
                "INSERT INTO notes (title, body, tags) VALUES ({}, {}, {}) RETURNING id",
                sql_str(&title),
                sql_str(&text),
                sql_str(&tags_json(&tags))
            );
            let rows = db.query(&sql)?;
            let id = rows[0].int(0);
            return Ok((201, format!("{{\"id\": {}}}", id)));
        }
        if method == "GET" {
            let mut tag: Option<Str> = None;
            let mut q: Option<Str> = None;
            for part in query.split('&') {
                if part.is_empty() {
                    continue;
                }
                let (k, v) = match part.find('=') {
                    Some(p) => (&part[..p], &part[p + 1..]),
                    None => (part, ""),
                };
                if k == "tag" {
                    tag = Some(v.to_lowercase());
                } else if k == "q" {
                    q = Some(Str::from(v));
                }
            }
            let rows = db.query("SELECT id, title, body, tags FROM notes ORDER BY id DESC")?;
            let mut parts: Vec<Str> = Vec::new();
            for r in rows.iter() {
                let id = r.int(0);
                let title = r.text(1);
                let text = r.text(2);
                if let Some(t) = &tag {
                    let tags = parse_tags(&r.text(3));
                    if !tags.contains(t) {
                        continue;
                    }
                }
                if let Some(w) = &q {
                    if !title.contains(w.as_str()) && !text.contains(w.as_str()) {
                        continue;
                    }
                }
                parts.push(format!("{{\"id\": {}, \"title\": {}}}", id, quote(&title)));
            }
            return Ok((200, format!("[{}]", parts.join(", "))));
        }
        return Ok(not_found());
    }

    if path.starts_with("/notes/") {
        let id = match parse_id(&path[7..]) {
            Some(i) => i,
            None => return Ok(not_found()),
        };
        if method == "GET" {
            let rows = db.query(&format!(
                "SELECT id, title, body, tags FROM notes WHERE id = {}",
                id
            ))?;
            if rows.is_empty() {
                return Ok(not_found());
            }
            let r = &rows[0];
            let tags = parse_tags(&r.text(3));
            return Ok((
                200,
                format!(
                    "{{\"id\": {}, \"title\": {}, \"body\": {}, \"tags\": {}}}",
                    r.int(0),
                    quote(&r.text(1)),
                    quote(&r.text(2)),
                    tags_json(&tags)
                ),
            ));
        }
        if method == "DELETE" {
            let rows = db.query(&format!("DELETE FROM notes WHERE id = {} RETURNING id", id))?;
            if rows.is_empty() {
                return Ok(not_found());
            }
            return Ok((200, format!("{{\"deleted\": {}}}", id)));
        }
        return Ok(not_found());
    }

    Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, Str> {
    db.exec("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)")?;
    let method = req.method();
    let target = req.path();
    let body = req.body();
    let (status, out) = route(&method, &target, &body, &db)?;
    res.status(status);
    res.header("content-type", "application/json");
    Ok(out)
}

enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct Parser {
    cs: Vec<char>,
    i: usize,
}

fn ws(mut p: Parser) -> Parser {
    while p.i < p.cs.len() {
        let c = p.cs[p.i];
        if c == ' ' || c == '\n' || c == '\r' || c == '\t' {
            p.i += 1;
        } else {
            break;
        }
    }
    p
}

fn cur(p: Parser) -> (Parser, char) {
    if p.i < p.cs.len() {
        let c = p.cs[p.i];
        (p, c)
    } else {
        (p, '\0')
    }
}

fn lit(mut p: Parser, w: Str) -> (Parser, bool) {
    let wc: Vec<char> = w.chars().collect();
    if p.i + wc.len() > p.cs.len() {
        return (p, false);
    }
    for k in 0..wc.len() {
        if p.cs[p.i + k] != wc[k] {
            return (p, false);
        }
    }
    p.i += wc.len();
    (p, true)
}

fn hex4(mut p: Parser) -> (Parser, Option<u32>) {
    if p.i + 4 > p.cs.len() {
        return (p, None);
    }
    let mut v: u32 = 0;
    for _ in 0..4 {
        match p.cs[p.i].to_digit(16) {
            Some(d) => v = v * 16 + d,
            None => return (p, None),
        }
        p.i += 1;
    }
    (p, Some(v))
}

fn pstring(mut p: Parser) -> (Parser, Option<Str>) {
    if p.i >= p.cs.len() || p.cs[p.i] != '"' {
        return (p, None);
    }
    p.i += 1;
    let mut out = Str::new();
    loop {
        if p.i >= p.cs.len() {
            return (p, None);
        }
        let c = p.cs[p.i];
        p.i += 1;
        if c == '"' {
            return (p, Some(out));
        }
        if (c as u32) < 0x20 {
            return (p, None);
        }
        if c != '\\' {
            out.push(c);
            continue;
        }
        if p.i >= p.cs.len() {
            return (p, None);
        }
        let e = p.cs[p.i];
        p.i += 1;
        if e == '"' {
            out.push('"');
        } else if e == '\\' {
            out.push('\\');
        } else if e == '/' {
            out.push('/');
        } else if e == 'b' {
            out.push('\u{8}');
        } else if e == 'f' {
            out.push('\u{c}');
        } else if e == 'n' {
            out.push('\n');
        } else if e == 'r' {
            out.push('\r');
        } else if e == 't' {
            out.push('\t');
        } else if e == 'u' {
            let (p2, ho) = hex4(p);
            p = p2;
            let h = match ho {
                Some(h) => h,
                None => return (p, None),
            };
            if h >= 0xD800 && h < 0xDC00 {
                let (p3, ok) = lit(p, Str::from("\\u"));
                p = p3;
                if !ok {
                    return (p, None);
                }
                let (p4, lo) = hex4(p);
                p = p4;
                let l = match lo {
                    Some(l) => l,
                    None => return (p, None),
                };
                if l < 0xDC00 || l >= 0xE000 {
                    return (p, None);
                }
                let cp = 0x10000 + ((h - 0xD800) << 10) + (l - 0xDC00);
                match char::from_u32(cp) {
                    Some(ch) => out.push(ch),
                    None => return (p, None),
                }
            } else if h >= 0xDC00 && h < 0xE000 {
                return (p, None);
            } else {
                match char::from_u32(h) {
                    Some(ch) => out.push(ch),
                    None => return (p, None),
                }
            }
        } else {
            return (p, None);
        }
    }
}

fn is_digit_at(p: Parser) -> (Parser, bool) {
    let (p, c) = cur(p);
    (p, c >= '0' && c <= '9')
}

fn number(mut p: Parser) -> (Parser, Option<Json>) {
    let (p0, c0) = cur(p);
    p = p0;
    if c0 == '-' {
        p.i += 1;
    }
    let mut digits = 0;
    loop {
        let (p1, d) = is_digit_at(p);
        p = p1;
        if d { p.i += 1; digits += 1; } else { break; }
    }
    if digits == 0 {
        return (p, None);
    }
    let (p2, c2) = cur(p);
    p = p2;
    if c2 == '.' {
        p.i += 1;
        let mut d = 0;
        loop {
            let (p3, isd) = is_digit_at(p);
            p = p3;
            if isd { p.i += 1; d += 1; } else { break; }
        }
        if d == 0 {
            return (p, None);
        }
    }
    let (p4, c4) = cur(p);
    p = p4;
    if c4 == 'e' || c4 == 'E' {
        p.i += 1;
        let (p5, c5) = cur(p);
        p = p5;
        if c5 == '+' || c5 == '-' {
            p.i += 1;
        }
        let mut d = 0;
        loop {
            let (p6, isd) = is_digit_at(p);
            p = p6;
            if isd { p.i += 1; d += 1; } else { break; }
        }
        if d == 0 {
            return (p, None);
        }
    }
    (p, Some(Json::Num(0.0)))
}

fn value(mut p: Parser, depth: usize) -> (Parser, Option<Json>) {
    if depth > 200 {
        return (p, None);
    }
    p = ws(p);
    let (p0, c) = cur(p);
    p = p0;
    if c == '{' {
        p.i += 1;
        let mut items: Vec<(Str, Json)> = Vec::new();
        p = ws(p);
        let (p1, c1) = cur(p);
        p = p1;
        if c1 == '}' {
            p.i += 1;
            return (p, Some(Json::Obj(items)));
        }
        loop {
            p = ws(p);
            let (p2, ko) = pstring(p);
            p = p2;
            let k = match ko {
                Some(k) => k,
                None => return (p, None),
            };
            p = ws(p);
            let (p3, c3) = cur(p);
            p = p3;
            if c3 != ':' {
                return (p, None);
            }
            p.i += 1;
            let (p4, vo) = value(p, depth + 1);
            p = p4;
            let v = match vo {
                Some(v) => v,
                None => return (p, None),
            };
            items.push((k, v));
            p = ws(p);
            let (p5, c5) = cur(p);
            p = p5;
            if c5 == ',' {
                p.i += 1;
            } else if c5 == '}' {
                p.i += 1;
                return (p, Some(Json::Obj(items)));
            } else {
                return (p, None);
            }
        }
    } else if c == '[' {
        p.i += 1;
        let mut items: Vec<Json> = Vec::new();
        p = ws(p);
        let (p1, c1) = cur(p);
        p = p1;
        if c1 == ']' {
            p.i += 1;
            return (p, Some(Json::Arr(items)));
        }
        loop {
            let (p2, vo) = value(p, depth + 1);
            p = p2;
            let v = match vo {
                Some(v) => v,
                None => return (p, None),
            };
            items.push(v);
            p = ws(p);
            let (p3, c3) = cur(p);
            p = p3;
            if c3 == ',' {
                p.i += 1;
            } else if c3 == ']' {
                p.i += 1;
                return (p, Some(Json::Arr(items)));
            } else {
                return (p, None);
            }
        }
    } else if c == '"' {
        let (p1, so) = pstring(p);
        p = p1;
        match so {
            Some(s) => (p, Some(Json::Text(s))),
            None => (p, None),
        }
    } else {
        let (p1, t) = lit(p, Str::from("true"));
        p = p1;
        if t {
            return (p, Some(Json::Bool(true)));
        }
        let (p2, f) = lit(p, Str::from("false"));
        p = p2;
        if f {
            return (p, Some(Json::Bool(false)));
        }
        let (p3, n) = lit(p, Str::from("null"));
        p = p3;
        if n {
            return (p, Some(Json::Null));
        }
        number(p)
    }
}

fn parse_json(s: Str) -> Option<Json> {
    let p = Parser { cs: s.chars().collect(), i: 0 };
    let (p, vo) = value(p, 0);
    let v = match vo {
        Some(v) => v,
        None => return None,
    };
    let p = ws(p);
    if p.i != p.cs.len() {
        return None;
    }
    Some(v)
}

fn quote(s: Str) -> Str {
    let mut o = Str::from("\"");
    for c in s.chars() {
        if c == '"' {
            o.push_str("\\\"");
        } else if c == '\\' {
            o.push_str("\\\\");
        } else if c == '\n' {
            o.push_str("\\n");
        } else if c == '\r' {
            o.push_str("\\r");
        } else if c == '\t' {
            o.push_str("\\t");
        } else if (c as u32) < 0x20 {
            o.push_str("\\u00");
            let v = c as u32;
            let hx: Vec<char> = "0123456789abcdef".chars().collect();
            o.push(hx[(v / 16) as usize]);
            o.push(hx[(v % 16) as usize]);
        } else {
            o.push(c);
        }
    }
    o.push('"');
    o
}

fn sql_str(s: Str) -> Str {
    let mut o = Str::from("'");
    for c in s.chars() {
        if c == '\'' {
            o.push('\'');
        }
        o.push(c);
    }
    o.push('\'');
    o
}

fn tags_json(tags: Vec<Str>) -> Str {
    let mut o = Str::from("[");
    for k in 0..tags.len() {
        if k > 0 {
            o.push_str(",");
        }
        o.push_str(&quote(tags[k].clone()));
    }
    o.push(']');
    o
}

fn parse_tags(s: Str) -> Vec<Str> {
    let mut out: Vec<Str> = Vec::new();
    match parse_json(s) {
        Some(Json::Arr(items)) => {
            for it in items {
                match it {
                    Json::Text(t) => out.push(t),
                    _ => {}
                }
            }
        }
        _ => {}
    }
    out
}

fn vec_has(v: Vec<Str>, s: Str) -> bool {
    for k in 0..v.len() {
        if v[k] == s {
            return true;
        }
    }
    false
}

fn substr(s: Str, a: usize, b: usize) -> Str {
    let mut o = Str::new();
    let mut k: usize = 0;
    for c in s.chars() {
        if k >= a && k < b {
            o.push(c);
        }
        k += 1;
    }
    o
}

fn char_len(s: Str) -> usize {
    let mut n: usize = 0;
    for _c in s.chars() {
        n += 1;
    }
    n
}

fn find_char(s: Str, ch: char) -> Option<usize> {
    let mut k: usize = 0;
    for c in s.chars() {
        if c == ch {
            return Some(k);
        }
        k += 1;
    }
    None
}

fn split_on(s: Str, ch: char) -> Vec<Str> {
    let mut out: Vec<Str> = Vec::new();
    let mut curs = Str::new();
    for c in s.chars() {
        if c == ch {
            out.push(curs);
            curs = Str::new();
        } else {
            curs.push(c);
        }
    }
    out.push(curs);
    out
}

fn contains_str(hay: Str, needle: Str) -> bool {
    let h: Vec<char> = hay.chars().collect();
    let n: Vec<char> = needle.chars().collect();
    if n.len() == 0 {
        return true;
    }
    if n.len() > h.len() {
        return false;
    }
    for a in 0..(h.len() - n.len() + 1) {
        let mut ok = true;
        for b in 0..n.len() {
            if h[a + b] != n[b] {
                ok = false;
                break;
            }
        }
        if ok {
            return true;
        }
    }
    false
}

fn not_found() -> (u16, Str) {
    (404, Str::from("{\"error\": \"not found\"}"))
}

fn invalid() -> (u16, Str) {
    (400, Str::from("{\"error\": \"invalid note\"}"))
}

fn parse_id(s: Str) -> Option<i64> {
    let n = char_len(s.clone());
    if n == 0 || n > 18 {
        return None;
    }
    let mut v: i64 = 0;
    for c in s.chars() {
        if c < '0' || c > '9' {
            return None;
        }
        v = v * 10 + ((c as u32) - ('0' as u32)) as i64;
    }
    Some(v)
}

fn validate(body: Str) -> Option<(Str, Str, Vec<Str>)> {
    let v = match parse_json(body) {
        Some(v) => v,
        None => return None,
    };
    let items = match v {
        Json::Obj(items) => items,
        _ => return None,
    };
    let mut title: Option<Str> = None;
    let mut text: Option<Str> = None;
    let mut tags: Vec<Str> = Vec::new();
    for (k, v) in items {
        if k == "title" {
            match v {
                Json::Text(t) => title = Some(t),
                _ => return None,
            }
        } else if k == "body" {
            match v {
                Json::Text(t) => text = Some(t),
                _ => return None,
            }
        } else if k == "tags" {
            tags = Vec::new();
            match v {
                Json::Arr(arr) => {
                    for t in arr {
                        match t {
                            Json::Text(s) => {
                                let l = s.to_lowercase();
                                if !vec_has(tags.clone(), l.clone()) {
                                    tags.push(l);
                                }
                            }
                            _ => return None,
                        }
                    }
                }
                _ => return None,
            }
        }
    }
    let title = match title {
        Some(t) => t,
        None => return None,
    };
    if char_len(title.clone()) == 0 {
        return None;
    }
    let text = match text {
        Some(t) => t,
        None => return None,
    };
    Some((title, text, tags))
}

fn route(method: Str, target: Str, body: Str, db: Db) -> Result<(u16, Str), Str> {
    let tlen = char_len(target.clone());
    let (path, query) = match find_char(target.clone(), '?') {
        Some(p) => (substr(target.clone(), 0, p), substr(target.clone(), p + 1, tlen)),
        None => (target.clone(), Str::new()),
    };

    if path == "/notes" {
        if method == "POST" {
            let (title, text, tags) = match validate(body) {
                Some(x) => x,
                None => return Ok(invalid()),
            };
            let sql = format!(
                "INSERT INTO notes (title, body, tags) VALUES ({}, {}, {}) RETURNING id",
                sql_str(title),
                sql_str(text),
                sql_str(tags_json(tags))
            );
            let rows = db.query(sql)?;
            let id = rows[0].int(0);
            return Ok((201, format!("{{\"id\": {}}}", id)));
        }
        if method == "GET" {
            let mut tag: Option<Str> = None;
            let mut q: Option<Str> = None;
            let parts_q = split_on(query, '&');
            for k in 0..parts_q.len() {
                let part = parts_q[k].clone();
                let plen = char_len(part.clone());
                if plen == 0 {
                    continue;
                }
                let (key, val) = match find_char(part.clone(), '=') {
                    Some(p) => (substr(part.clone(), 0, p), substr(part.clone(), p + 1, plen)),
                    None => (part.clone(), Str::new()),
                };
                if key == "tag" {
                    tag = Some(val.to_lowercase());
                } else if key == "q" {
                    q = Some(val);
                }
            }
            let rows = db.query(Str::from("SELECT id, title, body, tags FROM notes ORDER BY id DESC"))?;
            let mut out = Str::from("[");
            let mut first = true;
            for k in 0..rows.len() {
                let id = rows[k].int(0);
                let title = rows[k].text(1);
                let text = rows[k].text(2);
                match tag.clone() {
                    Some(t) => {
                        let tags = parse_tags(rows[k].text(3));
                        if !vec_has(tags, t) {
                            continue;
                        }
                    }
                    None => {}
                }
                match q.clone() {
                    Some(w) => {
                        if !contains_str(title.clone(), w.clone()) && !contains_str(text.clone(), w) {
                            continue;
                        }
                    }
                    None => {}
                }
                if !first {
                    out.push_str(", ");
                }
                first = false;
                out.push_str(&format!("{{\"id\": {}, \"title\": {}}}", id, quote(title)));
            }
            out.push(']');
            return Ok((200, out));
        }
        return Ok(not_found());
    }

    let plen = char_len(path.clone());
    if plen > 7 && substr(path.clone(), 0, 7) == "/notes/" {
        let id = match parse_id(substr(path.clone(), 7, plen)) {
            Some(i) => i,
            None => return Ok(not_found()),
        };
        if method == "GET" {
            let rows = db.query(format!(
                "SELECT id, title, body, tags FROM notes WHERE id = {}",
                id
            ))?;
            if rows.len() == 0 {
                return Ok(not_found());
            }
            let tags = parse_tags(rows[0].text(3));
            return Ok((
                200,
                format!(
                    "{{\"id\": {}, \"title\": {}, \"body\": {}, \"tags\": {}}}",
                    rows[0].int(0),
                    quote(rows[0].text(1)),
                    quote(rows[0].text(2)),
                    tags_json(tags)
                ),
            ));
        }
        if method == "DELETE" {
            let rows = db.query(format!("DELETE FROM notes WHERE id = {} RETURNING id", id))?;
            if rows.len() == 0 {
                return Ok(not_found());
            }
            return Ok((200, format!("{{\"deleted\": {}}}", id)));
        }
        return Ok(not_found());
    }

    Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, Str> {
    db.exec(Str::from("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)"))?;
    let method = req.method();
    let target = req.path();
    let body = req.body();
    let (status, out) = route(method, target, body, db)?;
    res.status(status);
    res.header("content-type", "application/json");
    Ok(out)
}

fn esc(s: Str) -> Str {
    format!("'{}'", s.replace("'", "''"))
}

fn not_found() -> (u16, Str) {
    (404, Str::from("{\"error\": \"not found\"}"))
}

fn invalid() -> (u16, Str) {
    (400, Str::from("{\"error\": \"invalid note\"}"))
}

fn route(method: Str, target: Str, body: Str, db: Db) -> Result<(u16, Str), Str> {
    let t = esc(target);
    let parse_sql = format!(
        "WITH x AS (SELECT {} AS t), \
         y AS (SELECT CASE WHEN instr(t,'?')>0 THEN substr(t,1,instr(t,'?')-1) ELSE t END AS p, \
                      CASE WHEN instr(t,'?')>0 THEN '&'||substr(t,instr(t,'?')+1)||'&' ELSE '&' END AS q FROM x) \
         SELECT p, \
           CASE WHEN p = '/notes' THEN 1 ELSE 0 END, \
           CASE WHEN instr(q,'&tag=')>0 THEN 1 ELSE 0 END, \
           CASE WHEN instr(q,'&tag=')>0 THEN lower(substr(q, instr(q,'&tag=')+5, instr(substr(q,instr(q,'&tag=')+5),'&')-1)) ELSE '' END, \
           CASE WHEN instr(q,'&q=')>0 THEN 1 ELSE 0 END, \
           CASE WHEN instr(q,'&q=')>0 THEN substr(q, instr(q,'&q=')+3, instr(substr(q,instr(q,'&q=')+3),'&')-1) ELSE '' END, \
           CASE WHEN substr(p,1,7)='/notes/' AND length(p)>7 AND length(p)<=25 AND substr(p,8) NOT GLOB '*[^0-9]*' THEN CAST(substr(p,8) AS INTEGER) ELSE -1 END \
         FROM y",
        t
    );
    let pr = db.query(parse_sql)?;
    let is_list = pr[0].int(1);
    let has_tag = pr[0].int(2);
    let tag = pr[0].text(3);
    let has_q = pr[0].int(4);
    let q = pr[0].text(5);
    let id = pr[0].int(6);

    if is_list == 1 {
        if method == "POST" {
            let b = esc(body);
            let check = format!(
                "SELECT CASE WHEN json_valid({b}) THEN \
                   (CASE WHEN json_type({b})='object' \
                      AND json_type({b},'$.title')='text' \
                      AND length(json_extract({b},'$.title'))>0 \
                      AND json_type({b},'$.body')='text' \
                      AND (json_type({b},'$.tags') IS NULL OR (json_type({b},'$.tags')='array' \
                           AND NOT EXISTS (SELECT 1 FROM json_each({b},'$.tags') WHERE type != 'text'))) \
                    THEN 1 ELSE 0 END) \
                 ELSE 0 END",
                b = b
            );
            let cr = db.query(check)?;
            if cr[0].int(0) != 1 {
                return Ok(invalid());
            }
            let ins = format!(
                "INSERT INTO notes (title, body, tags) SELECT \
                   json_extract({b},'$.title'), json_extract({b},'$.body'), \
                   coalesce((SELECT json_group_array(tg) FROM (SELECT lower(value) AS tg, min(key) AS k FROM json_each({b},'$.tags') GROUP BY lower(value) ORDER BY k)), '[]') \
                 RETURNING id",
                b = b
            );
            let rows = db.query(ins)?;
            let nid = rows[0].int(0);
            return Ok((201, format!("{{\"id\": {}}}", nid)));
        }
        if method == "GET" {
            let mut cond = Str::from("1");
            if has_tag == 1 {
                cond = format!(
                    "{} AND EXISTS (SELECT 1 FROM json_each(notes.tags) WHERE value = {})",
                    cond,
                    esc(tag)
                );
            }
            if has_q == 1 {
                let w = esc(q);
                cond = format!(
                    "{} AND (instr(title, {}) > 0 OR instr(body, {}) > 0)",
                    cond, w, w
                );
            }
            let sql = format!(
                "SELECT coalesce((SELECT json_group_array(json_object('id', id, 'title', title)) FROM (SELECT id, title FROM notes WHERE {} ORDER BY id DESC)), '[]')",
                cond
            );
            let rows = db.query(sql)?;
            return Ok((200, rows[0].text(0)));
        }
        return Ok(not_found());
    }

    if id >= 0 {
        if method == "GET" {
            let rows = db.query(format!(
                "SELECT json_object('id', id, 'title', title, 'body', body, 'tags', json(tags)) FROM notes WHERE id = {}",
                id
            ))?;
            if rows.len() == 0 {
                return Ok(not_found());
            }
            return Ok((200, rows[0].text(0)));
        }
        if method == "DELETE" {
            let rows = db.query(format!("DELETE FROM notes WHERE id = {} RETURNING id", id))?;
            if rows.len() == 0 {
                return Ok(not_found());
            }
            return Ok((200, format!("{{\"deleted\": {}}}", id)));
        }
        return Ok(not_found());
    }

    Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, Str> {
    db.exec(Str::from("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)"))?;
    let method = req.method();
    let target = req.path();
