fn route(method: Str, target: Str, body: Str, db: Db) -> Result<(u16, Str), Str> {
    let t = esc(target);
    let parse_tpl = Str::from("WITH x AS (SELECT @@T@@ AS t), y AS (SELECT CASE WHEN instr(t,'?')>0 THEN substr(t,1,instr(t,'?')-1) ELSE t END AS p, CASE WHEN instr(t,'?')>0 THEN '&'||substr(t,instr(t,'?')+1)||'&' ELSE '&' END AS q FROM x) SELECT p, CASE WHEN p = '/notes' THEN 1 ELSE 0 END, CASE WHEN instr(q,'&tag=')>0 THEN 1 ELSE 0 END, CASE WHEN instr(q,'&tag=')>0 THEN lower(substr(q, instr(q,'&tag=')+5, instr(substr(q,instr(q,'&tag=')+5),'&')-1)) ELSE '' END, CASE WHEN instr(q,'&q=')>0 THEN 1 ELSE 0 END, CASE WHEN instr(q,'&q=')>0 THEN substr(q, instr(q,'&q=')+3, instr(substr(q,instr(q,'&q=')+3),'&')-1) ELSE '' END, CASE WHEN substr(p,1,7)='/notes/' AND length(p)>7 AND length(p)<=18 AND substr(p,8) NOT GLOB '*[^0-9]*' THEN CAST(substr(p,8) AS INTEGER) ELSE -1 END FROM y");
    let parse_sql = parse_tpl.replace("@@T@@", t);
    let pr = db.query(parse_sql)?;
    let is_list = pr[0].int(1);
    let has_tag = pr[0].int(2);
    let tag = pr[0].text(3);
    let has_q = pr[0].int(4);
    let q = pr[0].text(5);
    let id = pr[0].int(6);

    if is_list == 1 {
        if method == "POST" {
            let check_tpl = Str::from("SELECT CASE WHEN json_valid(@@B@@) THEN (CASE WHEN json_type(@@B@@)='object' AND json_type(@@B@@,'$.title')='text' AND length(json_extract(@@B@@,'$.title'))>0 AND json_type(@@B@@,'$.body')='text' AND (json_type(@@B@@,'$.tags') IS NULL OR (json_type(@@B@@,'$.tags')='array' AND NOT EXISTS (SELECT 1 FROM json_each(@@B@@,'$.tags') WHERE type != 'text'))) THEN 1 ELSE 0 END) ELSE 0 END");
            let check = check_tpl.replace("@@B@@", esc(body.clone()));
            let cr = db.query(check)?;
            if cr[0].int(0) != 1 {
                return Ok(invalid());
            }
            let ins_tpl = Str::from("INSERT INTO notes (title, body, tags) SELECT json_extract(@@B@@,'$.title'), json_extract(@@B@@,'$.body'), coalesce((SELECT json_group_array(tg) FROM (SELECT lower(value) AS tg, min(key) AS k FROM json_each(@@B@@,'$.tags') GROUP BY lower(value) ORDER BY k)), '[]') RETURNING id");
            let ins = ins_tpl.replace("@@B@@", esc(body));
            let rows = db.query(ins)?;
            let nid = rows[0].int(0);
            return Ok((201, Str::from("{\"id\": ") + nid.to_str() + "}"));
        }
        if method == "GET" {
            let mut cond = Str::from("1");
            if has_tag == 1 {
                cond = cond + " AND EXISTS (SELECT 1 FROM json_each(notes.tags) WHERE value = " + esc(tag) + ")";
            }
            if has_q == 1 {
                let w = esc(q);
                cond = cond + " AND (instr(title, " + w.clone() + ") > 0 OR instr(body, " + w + ") > 0)";
            }
            let sql = Str::from("SELECT coalesce((SELECT json_group_array(json_object('id', id, 'title', title)) FROM (SELECT id, title FROM notes WHERE ") + cond + " ORDER BY id DESC)), '[]')";
            let rows = db.query(sql)?;
            return Ok((200, rows[0].text(0)));
        }
        return Ok(not_found());
    }

    if id >= 0 {
        if method == "GET" {
            let sql = Str::from("SELECT json_object('id', id, 'title', title, 'body', body, 'tags', json(tags)) FROM notes WHERE id = ") + id.to_str();
            let rows = db.query(sql)?;
            if rows.len() == 0 {
                return Ok(not_found());
            }
            return Ok((200, rows[0].text(0)));
        }
        if method == "DELETE" {
            let sql = Str::from("DELETE FROM notes WHERE id = ") + id.to_str() + " RETURNING id";
            let rows = db.query(sql)?;
            if rows.len() == 0 {
                return Ok(not_found());
            }
            return Ok((200, Str::from("{\"deleted\": ") + id.to_str() + "}"));
        }
        return Ok(not_found());
    }

    Ok(not_found())
}

