fn fmt_tenths(v: i64) -> Str {
    let neg = v < 0;
    let a = if neg { -v } else { v };
    let sign = if neg { "-" } else { "" };
    format!("{}{}.{}", sign, a / 10, a % 10)
}

fn station_line(api: &Http, id: &Str, name: &Str) -> Str {
    let path = format!("/stations/{}/readings", id);
    let resp = match api.get(&path) {
        Ok(r) => r,
        Err(_) => return format!("{} unavailable", name),
    };
    if resp.status < 200 || resp.status > 299 {
        return format!("{} unavailable", name);
    }
    let doc = match json::parse(&resp.body) {
        Ok(d) => d,
        Err(_) => return format!("{} unavailable", name),
    };
    let readings = match doc.get("readings").and_then(|r| r.as_array()) {
        Some(rs) => rs,
        None => return format!("{} no data", name),
    };

    let mut count: i64 = 0;
    let mut sum: i64 = 0;
    let mut min: i64 = 0;
    let mut max: i64 = 0;
    for r in readings.iter() {
        let t = match r.get("temp").and_then(|t| t.as_i64()) {
            Some(t) => t,
            None => continue,
        };
        if count == 0 || t < min {
            min = t;
        }
        if count == 0 || t > max {
            max = t;
        }
        sum += t;
        count += 1;
    }

    if count == 0 {
        return format!("{} no data", name);
    }
    let avg = sum / count;
    format!(
