enum Json {
    Null,
    Bool(Bool),
    Num(Int),
    Text(Str),
    Arr(List<Json>),
    Obj(List<Field>),
}

struct Field {
    key: Str,
    val: Json,
}

struct Parsed {
    val: Json,
    pos: Int,
}

struct Station {
    id: Str,
    name: Str,
}

fn is_ws(c: Str) -> Bool {
    c == " " || c == "\n" || c == "\t" || c == "\r"
}

fn skip_ws(cs: &List<Str>, start: Int) -> Int {
    let mut i = start;
    while i < cs.len() && is_ws(cs[i]) {
        i += 1;
    }
    i
}

fn digit(c: Str) -> Int {
    if c == "0" { 0 }
    else if c == "1" { 1 }
    else if c == "2" { 2 }
    else if c == "3" { 3 }
    else if c == "4" { 4 }
    else if c == "5" { 5 }
    else if c == "6" { 6 }
    else if c == "7" { 7 }
    else if c == "8" { 8 }
    else if c == "9" { 9 }
    else { -1 }
}

fn parse_string(cs: &List<Str>, start: Int) -> Result<Parsed, Str> {
    // cs[start] == "\""
    let mut i = start + 1;
    let mut s = "";
    while i < cs.len() {
        let c = cs[i];
        if c == "\"" {
            return Ok(Parsed { val: Json::Text(s), pos: i + 1 });
        }
        if c == "\\" {
            if i + 1 >= cs.len() {
                return Err("bad escape");
            }
            let e = cs[i + 1];
            if e == "n" {
                s = s + "\n";
                i += 2;
            } else if e == "t" {
                s = s + "\t";
                i += 2;
            } else if e == "r" {
                s = s + "\r";
                i += 2;
            } else if e == "b" || e == "f" {
                i += 2;
            } else if e == "u" {
                s = s + "?";
                i += 6;
            } else {
                s = s + e;
                i += 2;
            }
        } else {
            s = s + c;
            i += 1;
        }
    }
    Err("unterminated string")
}

fn parse_number(cs: &List<Str>, start: Int) -> Result<Parsed, Str> {
    let mut i = start;
    let mut neg = false;
    if i < cs.len() && cs[i] == "-" {
        neg = true;
        i += 1;
    }
    let mut n: Int = 0;
    let mut any = false;
    while i < cs.len() && digit(cs[i]) >= 0 {
        n = n * 10 + digit(cs[i]);
        any = true;
        i += 1;
    }
    if !any {
        return Err("bad number");
    }
    // skip any fraction / exponent part
    while i < cs.len() && (cs[i] == "." || cs[i] == "e" || cs[i] == "E" || cs[i] == "+" || cs[i] == "-" || digit(cs[i]) >= 0) {
        i += 1;
    }
    let v = if neg { 0 - n } else { n };
    Ok(Parsed { val: Json::Num(v), pos: i })
}

fn expect_word(cs: &List<Str>, start: Int, w: Str) -> Bool {
    let mut k = 0;
    for c in w.chars() {
        if start + k >= cs.len() || cs[start + k] != c {
            return false;
        }
        k += 1;
    }
    true
}

fn parse_value(cs: &List<Str>, start: Int) -> Result<Parsed, Str> {
    let i = skip_ws(cs, start);
    if i >= cs.len() {
        return Err("unexpected end");
    }
    let c = cs[i];
    if c == "{" {
        let mut fields: List<Field> = List::new();
        let mut j = skip_ws(cs, i + 1);
        if j < cs.len() && cs[j] == "}" {
            return Ok(Parsed { val: Json::Obj(fields), pos: j + 1 });
        }
        while j < cs.len() {
            j = skip_ws(cs, j);
            if j >= cs.len() || cs[j] != "\"" {
                return Err("expected key");
            }
            let kp = parse_string(cs, j)?;
            let key = match kp.val {
                Json::Text(k) => k,
                _ => return Err("bad key"),
            };
            j = skip_ws(cs, kp.pos);
            if j >= cs.len() || cs[j] != ":" {
                return Err("expected colon");
            }
            let vp = parse_value(cs, j + 1)?;
            fields.push(Field { key: key, val: vp.val });
            j = skip_ws(cs, vp.pos);
            if j < cs.len() && cs[j] == "," {
                j += 1;
            } else if j < cs.len() && cs[j] == "}" {
                return Ok(Parsed { val: Json::Obj(fields), pos: j + 1 });
            } else {
                return Err("bad object");
            }
        }
        return Err("unterminated object");
    }
    if c == "[" {
        let mut items: List<Json> = List::new();
        let mut j = skip_ws(cs, i + 1);
        if j < cs.len() && cs[j] == "]" {
            return Ok(Parsed { val: Json::Arr(items), pos: j + 1 });
        }
        while j < cs.len() {
            let vp = parse_value(cs, j)?;
            items.push(vp.val);
            j = skip_ws(cs, vp.pos);
            if j < cs.len() && cs[j] == "," {
                j += 1;
            } else if j < cs.len() && cs[j] == "]" {
                return Ok(Parsed { val: Json::Arr(items), pos: j + 1 });
            } else {
                return Err("bad array");
            }
        }
        return Err("unterminated array");
    }
    if c == "\"" {
        return parse_string(cs, i);
    }
    if c == "t" && expect_word(cs, i, "true") {
        return Ok(Parsed { val: Json::Bool(true), pos: i + 4 });
    }
    if c == "f" && expect_word(cs, i, "false") {
        return Ok(Parsed { val: Json::Bool(false), pos: i + 5 });
    }
    if c == "n" && expect_word(cs, i, "null") {
        return Ok(Parsed { val: Json::Null, pos: i + 4 });
    }
    parse_number(cs, i)
}

fn parse_json(text: Str) -> Result<Json, Str> {
    let mut cs: List<Str> = List::new();
    for c in text.chars() {
        cs.push(c);
    }
    let p = parse_value(&cs, 0)?;
    Ok(p.val)
}

fn obj_get(v: Json, key: Str) -> Option<Json> {
    match v {
        Json::Obj(fs) => {
            for f in fs {
                if f.key == key {
                    return Some(f.val);
                }
            }
            None
        }
        _ => None,
    }
}

