fn main(api: Http) -> Result<Str, Str> {
    let mut count: i64 = 0;
    let mut refunded: i64 = 0;
    let mut totals: Vec<(Str, i64)> = Vec::new();
    let mut have_largest = false;
    let mut largest_id: i64 = 0;
    let mut largest_cents: i64 = 0;

    let mut page: i64 = 1;
    loop {
        let path = format!("/orders?page={}", page);
        let resp = api.get(&path).map_err(|e| format!("GET {} failed: {}", path, e))?;
        if resp.status() != 200 {
            return Err(format!("GET {} returned status {}", path, resp.status()));
        }
        let doc = resp.json().map_err(|e| format!("bad JSON from {}: {}", path, e))?;

        let orders = doc
            .get("orders")
            .and_then(|o| o.as_array())
            .ok_or(format!("missing orders array on page {}", page))?;

        for order in orders.iter() {
            count += 1;
            let id = order.get("id").and_then(|v| v.as_i64()).ok_or("order without id")?;
            let status = order.get("status").and_then(|v| v.as_str()).ok_or("order without status")?;
            if status == "paid" {
                let cents = order.get("cents").and_then(|v| v.as_i64()).ok_or("order without cents")?;
                let currency = order.get("currency").and_then(|v| v.as_str()).ok_or("order without currency")?;

                let mut found = false;
                for entry in totals.iter_mut() {
                    if entry.0 == currency {
                        entry.1 += cents;
                        found = true;
                    }
                }
                if !found {
                    totals.push((currency.to_string(), cents));
                }

                if !have_largest || cents > largest_cents || (cents == largest_cents && id < largest_id) {
                    have_largest = true;
                    largest_cents = cents;
                    largest_id = id;
                }
            } else if status == "refunded" {
                refunded += 1;
            }
        }

        match doc.get("next").and_then(|v| v.as_i64()) {
            Some(n) => page = n,
            None => break,
        }
    }

    totals.sort_by(|a, b| a.0.cmp(&b.0));
    let mut paid = Str::new();
    paid.push_str("{");
    let mut first = true;
    for entry in totals.iter() {
        if !first {
            paid.push_str(",");
        }
        first = false;
        paid.push_str(&format!("{}:{}", json_string(&entry.0), entry.1));
    }
    paid.push_str("}");

    let largest = if have_largest { format!("{}", largest_id) } else { "null".to_string() };

    let body = format!(
        "{{\"orders\":{},\"paid_cents\":{},\"refunded\":{},\"largest\":{}}}",
        count, paid, refunded, largest
    );

    let resp = api
        .post("/summaries", &body, &[("content-type", "application/json")])
        .map_err(|e| format!("POST /summaries failed: {}", e))?;
    if resp.status() != 201 {
