fn json_string(s: &Str) -> Str {
    let mut out = Str::new();
    out.push_str("\"");
    for c in s.chars() {
        if c == '"' {
            out.push_str("\\\"");
        } else if c == '\\' {
            out.push_str("\\\\");
        } else {
            out.push(c);
        }
    }
    out.push_str("\"");
    out
}

