fn load_num(cache: &Kv, name: &str) -> i64 {
    match cache.get(name) {
        Some(s) => match s.trim().parse::<i64>() {
            Ok(n) => n,
            Err(_) => 0,
        },
        None => 0,
    }
}

fn split_lines(s: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for part in s.split('\n') {
        let p = part.trim_end_matches('\r');
        out.push(p.to_string());
    }
    out
}

fn find_key(keys: &Vec<String>, k: &str) -> i64 {
    let mut i: usize = 0;
    while i < keys.len() {
        if keys[i] == k {
            return i as i64;
        }
        i += 1;
    }
    -1
}

fn main(input: Dir, cache: Kv) -> Str {
    let text = match input.read("ops.txt") {
        Ok(t) => t,
        Err(_) => return "".to_string(),
    };

    // Load persisted state: keys and values, most recently used first.
    let mut keys: Vec<String> = Vec::new();
    let mut vals: Vec<String> = Vec::new();
    let stored_keys = match cache.get("lru_keys") {
        Some(s) => s,
        None => "".to_string(),
    };
    let stored_vals = match cache.get("lru_vals") {
        Some(s) => s,
        None => "".to_string(),
    };
    if stored_keys.len() > 0 {
        for k in stored_keys.split('\n') {
            keys.push(k.to_string());
        }
        for v in stored_vals.split('\n') {
            vals.push(v.to_string());
        }
    }
    while vals.len() < keys.len() {
        vals.push("".to_string());
    }
    let mut hits = load_num(&cache, "lru_hits");
    let mut misses = load_num(&cache, "lru_misses");
    let mut evictions = load_num(&cache, "lru_evictions");

    let lines = split_lines(&text);
    let mut out: Vec<String> = Vec::new();

    let first = if lines.len() > 0 { lines[0].clone() } else { "".to_string() };
    let mut cap: usize = 1;
    if first.starts_with("capacity ") {
        let n = &first["capacity ".len()..];
        match n.trim().parse::<i64>() {
            Ok(v) => {
                if v >= 1 {
                    cap = v as usize;
                }
            }
            Err(_) => {}
        }
    }

    while keys.len() > cap {
        let k = keys.pop().unwrap();
        vals.pop();
        out.push(format!("evict {}", k));
        evictions += 1;
    }

    let mut i: usize = 1;
    while i < lines.len() {
        let line = lines[i].clone();
        let lineno = i + 1;
        i += 1;
        if line.len() == 0 {
            continue;
        }
        if line.starts_with("put ") {
            let rest = &line[4..];
            let mut ok = false;
            match rest.find(' ') {
                Some(p) => {
                    let k = rest[..p].to_string();
                    let v = rest[p + 1..].to_string();
                    if k.len() > 0 && v.len() > 0 {
                        ok = true;
                        let idx = find_key(&keys, &k);
                        if idx >= 0 {
                            keys.remove(idx as usize);
                            vals.remove(idx as usize);
                        } else if keys.len() >= cap {
                            let ek = keys.pop().unwrap();
                            vals.pop();
                            out.push(format!("evict {}", ek));
                            evictions += 1;
                        }
                        keys.insert(0, k);
                        vals.insert(0, v);
                    }
                }
                None => {}
            }
            if !ok {
                out.push(format!("bad line {}", lineno));
            }
            continue;
        }
        let mut words: Vec<String> = Vec::new();
        for w in line.split(' ') {
            words.push(w.to_string());
        }
        if words.len() == 2 && words[1].len() > 0 && words[0] == "get" {
            let k = words[1].clone();
            let idx = find_key(&keys, &k);
            if idx >= 0 {
                let kk = keys.remove(idx as usize);
                let vv = vals.remove(idx as usize);
                out.push(format!("{}={}", kk, vv));
                keys.insert(0, kk);
                vals.insert(0, vv);
                hits += 1;
            } else {
                out.push(format!("{} miss", k));
                misses += 1;
            }
        } else if words.len() == 2 && words[1].len() > 0 && words[0] == "del" {
            let idx = find_key(&keys, &words[1]);
            if idx >= 0 {
                keys.remove(idx as usize);
                vals.remove(idx as usize);
            }
        } else {
            out.push(format!("bad line {}", lineno));
        }
    }

    // Persist state.
    cache.set("lru_keys", &keys.join("\n"));
    cache.set("lru_vals", &vals.join("\n"));
    cache.set("lru_hits", &hits.to_string());
    cache.set("lru_misses", &misses.to_string());
    cache.set("lru_evictions", &evictions.to_string());

    if keys.len() == 0 {
        out.push("cache:".to_string());
    } else {
        out.push(format!("cache: {}", keys.join(",")));
    }
    out.push(format!("stats hits {} misses {} evictions {}", hits, misses, evictions));

    let mut result = out.join("\n");
    result.push('\n');
    result
}

fn parse_num(v: Option<Str>) -> i64 {
    match v {
        Some(s) => match s.trim().parse::<i64>() {
            Ok(n) => n,
            Err(_) => 0,
        },
        None => 0,
    }
}

fn main(input: Dir, cache: Kv) -> Str {
    let text: Str = match input.read("ops.txt") {
        Ok(t) => t,
        Err(_) => return "".to_string(),
    };

    let mut keys: Vec<Str> = Vec::new();
    let mut vals: Vec<Str> = Vec::new();
    let stored_keys: Str = match cache.get("lru_keys") {
        Some(s) => s,
        None => "".to_string(),
    };
    let stored_vals: Str = match cache.get("lru_vals") {
        Some(s) => s,
        None => "".to_string(),
    };
    if stored_keys.len() > 0 {
        for k in stored_keys.split('\n') {
            keys.push(k.to_string());
        }
        for v in stored_vals.split('\n') {
            vals.push(v.to_string());
        }
    }
    while vals.len() < keys.len() {
        vals.push("".to_string());
    }
    while vals.len() > keys.len() {
        vals.pop();
    }
    let mut hits: i64 = parse_num(cache.get("lru_hits"));
    let mut misses: i64 = parse_num(cache.get("lru_misses"));
    let mut evictions: i64 = parse_num(cache.get("lru_evictions"));

    let mut lines: Vec<Str> = Vec::new();
    for part in text.split('\n') {
        lines.push(part.trim_end_matches('\r').to_string());
    }

    let mut out: Vec<Str> = Vec::new();

    let mut cap: usize = 1;
    if lines.len() > 0 {
        let mut fw: Vec<Str> = Vec::new();
        for w in lines[0].split(' ') {
            fw.push(w.to_string());
        }
        if fw.len() >= 2 && fw[0] == "capacity" {
            match fw[fw.len() - 1].trim().parse::<i64>() {
                Ok(v) => {
                    if v >= 1 {
                        cap = v as usize;
                    }
                }
                Err(_) => {}
            }
        }
    }

    while keys.len() > cap {
        let k = keys.pop().unwrap();
        vals.pop();
        out.push(format!("evict {}", k));
        evictions += 1;
    }

    let mut i: usize = 1;
    while i < lines.len() {
        let line: Str = lines[i].clone();
        let lineno = i + 1;
        i += 1;
        if line.len() == 0 {
            continue;
        }
        let mut parts: Vec<Str> = Vec::new();
        for p in line.splitn(3, ' ') {
            parts.push(p.to_string());
        }
        if parts[0] == "put" {
            if parts.len() == 3 && parts[1].len() > 0 && parts[2].len() > 0 {
                let k = parts[1].clone();
                let v = parts[2].clone();
                let mut idx: i64 = -1;
                let mut j: usize = 0;
                while j < keys.len() {
                    if keys[j] == k {
                        idx = j as i64;
                        break;
                    }
                    j += 1;
                }
                if idx >= 0 {
                    keys.remove(idx as usize);
                    vals.remove(idx as usize);
                } else if keys.len() >= cap {
                    let ek = keys.pop().unwrap();
                    vals.pop();
                    out.push(format!("evict {}", ek));
                    evictions += 1;
                }
                keys.insert(0, k);
                vals.insert(0, v);
            } else {
                out.push(format!("bad line {}", lineno));
            }
            continue;
        }
        let mut words: Vec<Str> = Vec::new();
        for w in line.split(' ') {
            words.push(w.to_string());
        }
        let is_get = words.len() == 2 && words[1].len() > 0 && words[0] == "get";
        let is_del = words.len() == 2 && words[1].len() > 0 && words[0] == "del";
        if is_get || is_del {
            let k = words[1].clone();
            let mut idx: i64 = -1;
            let mut j: usize = 0;
            while j < keys.len() {
                if keys[j] == k {
                    idx = j as i64;
                    break;
                }
