enum Json {
    Null,
    Bool(bool),
    Num,
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

fn skip_ws(s: &Vec<char>, i: &mut usize) {
    while *i < s.len() && (s[*i] == ' ' || s[*i] == '\n' || s[*i] == '\r' || s[*i] == '\t') {
        *i += 1;
    }
}

fn hex4(s: &Vec<char>, i: &mut usize) -> Option<u32> {
    if *i + 4 > s.len() {
        return None;
    }
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        let c = s[*i];
        let d = match c.to_digit(16) {
            Some(d) => d,
            None => return None,
        };
        v = v * 16 + d;
        *i += 1;
        k += 1;
    }
    Some(v)
}

fn parse_string(s: &Vec<char>, i: &mut usize) -> Option<Str> {
    if *i >= s.len() || s[*i] != '"' {
        return None;
    }
    *i += 1;
    let mut out: Str = "".to_string();
    loop {
        if *i >= s.len() {
            return None;
        }
        let c = s[*i];
        *i += 1;
        if c == '"' {
            return Some(out);
        }
        if c == '\\' {
            if *i >= s.len() {
                return None;
            }
            let e = s[*i];
            *i += 1;
            if e == '"' {
                out.push('"');
            } else if e == '\\' {
                out.push('\\');
            } else if e == '/' {
                out.push('/');
            } else if e == 'b' {
                out.push('\u{8}');
            } else if e == 'f' {
                out.push('\u{c}');
            } else if e == 'n' {
                out.push('\n');
            } else if e == 'r' {
                out.push('\r');
            } else if e == 't' {
                out.push('\t');
            } else if e == 'u' {
                let mut code = match hex4(s, i) {
                    Some(v) => v,
                    None => return None,
                };
                if code >= 0xD800 && code < 0xDC00 {
                    if *i + 1 < s.len() && s[*i] == '\\' && s[*i + 1] == 'u' {
                        let save = *i;
                        *i += 2;
                        match hex4(s, i) {
                            Some(lo) => {
                                if lo >= 0xDC00 && lo < 0xE000 {
                                    code = 0x10000 + ((code - 0xD800) << 10) + (lo - 0xDC00);
                                } else {
                                    *i = save;
                                }
                            }
                            None => return None,
                        }
                    }
                }
                match char::from_u32(code) {
                    Some(ch) => out.push(ch),
                    None => out.push('\u{FFFD}'),
                }
            } else {
                return None;
            }
        } else {
            out.push(c);
        }
    }
}

fn parse_value(s: &Vec<char>, i: &mut usize) -> Option<Json> {
    skip_ws(s, i);
    if *i >= s.len() {
        return None;
    }
    let c = s[*i];
    if c == '{' {
        *i += 1;
        let mut items: Vec<(Str, Json)> = Vec::new();
        skip_ws(s, i);
        if *i < s.len() && s[*i] == '}' {
            *i += 1;
            return Some(Json::Obj(items));
        }
        loop {
            skip_ws(s, i);
            let k = match parse_string(s, i) {
                Some(k) => k,
                None => return None,
            };
            skip_ws(s, i);
            if *i >= s.len() || s[*i] != ':' {
                return None;
            }
            *i += 1;
            let v = match parse_value(s, i) {
                Some(v) => v,
                None => return None,
            };
            let mut found = false;
            let mut j = 0;
            while j < items.len() {
                if items[j].0 == k {
                    items[j].1 = v;
                    found = true;
                    break;
                }
                j += 1;
            }
            if !found {
                items.push((k, v));
            }
            skip_ws(s, i);
            if *i >= s.len() {
                return None;
            }
            if s[*i] == ',' {
                *i += 1;
            } else if s[*i] == '}' {
                *i += 1;
                return Some(Json::Obj(items));
            } else {
                return None;
            }
        }
    } else if c == '[' {
        *i += 1;
        let mut items: Vec<Json> = Vec::new();
        skip_ws(s, i);
        if *i < s.len() && s[*i] == ']' {
            *i += 1;
            return Some(Json::Arr(items));
        }
        loop {
            let v = match parse_value(s, i) {
                Some(v) => v,
                None => return None,
            };
            items.push(v);
            skip_ws(s, i);
            if *i >= s.len() {
                return None;
            }
            if s[*i] == ',' {
                *i += 1;
            } else if s[*i] == ']' {
                *i += 1;
                return Some(Json::Arr(items));
            } else {
                return None;
            }
        }
    } else if c == '"' {
        match parse_string(s, i) {
            Some(t) => Some(Json::Text(t)),
            None => None,
        }
    } else if c == 't' {
        if lit(s, i, "true") { Some(Json::Bool(true)) } else { None }
    } else if c == 'f' {
        if lit(s, i, "false") { Some(Json::Bool(false)) } else { None }
    } else if c == 'n' {
        if lit(s, i, "null") { Some(Json::Null) } else { None }
    } else if c == '-' || (c >= '0' && c <= '9') {
        if c == '-' {
            *i += 1;
        }
        let mut digits = 0;
        while *i < s.len() && s[*i] >= '0' && s[*i] <= '9' {
            *i += 1;
            digits += 1;
        }
        if digits == 0 {
            return None;
        }
        if *i < s.len() && s[*i] == '.' {
            *i += 1;
            let mut d = 0;
            while *i < s.len() && s[*i] >= '0' && s[*i] <= '9' {
                *i += 1;
                d += 1;
            }
            if d == 0 {
                return None;
            }
        }
        if *i < s.len() && (s[*i] == 'e' || s[*i] == 'E') {
            *i += 1;
            if *i < s.len() && (s[*i] == '+' || s[*i] == '-') {
                *i += 1;
            }
            let mut d = 0;
            while *i < s.len() && s[*i] >= '0' && s[*i] <= '9' {
                *i += 1;
                d += 1;
            }
            if d == 0 {
                return None;
            }
        }
        Some(Json::Num)
    } else {
        None
    }
}

fn lit(s: &Vec<char>, i: &mut usize, w: &str) -> bool {
    let cs: Vec<char> = w.chars().collect();
    if *i + cs.len() > s.len() {
        return false;
    }
    let mut k = 0;
    while k < cs.len() {
        if s[*i + k] != cs[k] {
            return false;
        }
        k += 1;
    }
    *i += cs.len();
    true
}

fn join(v: &Vec<Str>) -> Str {
    let mut out: Str = "".to_string();
    let mut k = 0;
    while k < v.len() {
        if k > 0 {
            out.push_str(", ");
        }
        out.push_str(&v[k]);
        k += 1;
    }
    out
}

fn find(names: &Vec<Str>, n: &Str) -> Option<usize> {
    let mut k = 0;
    while k < names.len() {
        if names[k] == *n {
            return Some(k);
        }
        k += 1;
    }
    None
}

fn tarjan(
    v: usize,
    adj: &Vec<Vec<usize>>,
    idx: &mut Vec<i64>,
    low: &mut Vec<i64>,
    on: &mut Vec<bool>,
    stack: &mut Vec<usize>,
    counter: &mut i64,
    comps: &mut Vec<Vec<usize>>,
) {
    idx[v] = *counter;
    low[v] = *counter;
    *counter += 1;
    stack.push(v);
    on[v] = true;
    let mut k = 0;
    while k < adj[v].len() {
        let w = adj[v][k];
        if idx[w] < 0 {
            tarjan(w, adj, idx, low, on, stack, counter, comps);
            if low[w] < low[v] {
                low[v] = low[w];
            }
        } else if on[w] {
            if idx[w] < low[v] {
                low[v] = idx[w];
            }
        }
        k += 1;
    }
    if low[v] == idx[v] {
        let mut comp: Vec<usize> = Vec::new();
        loop {
            let w = stack.pop().unwrap();
            on[w] = false;
            comp.push(w);
            if w == v {
                break;
            }
        }
        comps.push(comp);
    }
}

fn main(input: Dir) -> Str {
    let text: Str = match input.read_to_string("packages.json") {
        Ok(t) => t,
        Err(_) => return "error: not an object".to_string(),
    };
    let chars: Vec<char> = text.chars().collect();
    let mut pos: usize = 0;
    let root = match parse_value(&chars, &mut pos) {
        Some(v) => v,
        None => return "error: not an object".to_string(),
    };
    skip_ws(&chars, &mut pos);
    if pos != chars.len() {
        return "error: not an object".to_string();
    }
    let entries = match root {
        Json::Obj(e) => e,
        _ => return "error: not an object".to_string(),
    };

    let mut pkgs: Vec<(Str, Vec<Str>)> = Vec::new();
    let mut invalid: Vec<Str> = Vec::new();
    for (name, val) in entries.iter() {
        let mut ok = true;
        let mut deps: Vec<Str> = Vec::new();
        match val {
            Json::Arr(items) => {
                for it in items.iter() {
                    match it {
                        Json::Text(t) => {
                            if find(&deps, t).is_none() {
                                deps.push(t.clone());
                            }
                        }
                        _ => {
                            ok = false;
                        }
                    }
                }
            }
            _ => {
                ok = false;
            }
        }
        if ok {
            pkgs.push((name.clone(), deps));
        } else {
            invalid.push(name.clone());
        }
    }
    pkgs.sort_by(|a, b| a.0.cmp(&b.0));
    invalid.sort();

    let n = pkgs.len();
    let mut names: Vec<Str> = Vec::new();
    for p in pkgs.iter() {
        names.push(p.0.clone());
    }

    let mut adj: Vec<Vec<usize>> = Vec::new();
    let mut has_missing: Vec<bool> = Vec::new();
    let mut missing: Vec<(Str, Vec<Str>)> = Vec::new();
    let mut a = 0;
    while a < n {
        let mut out: Vec<usize> = Vec::new();
        let mut miss = false;
        for d in pkgs[a].1.iter() {
            match find(&names, d) {
                Some(j) => out.push(j),
                None => {
                    miss = true;
                    let mut found = false;
                    let mut k = 0;
                    while k < missing.len() {
                        if missing[k].0 == *d {
                            missing[k].1.push(names[a].clone());
                            found = true;
                            break;
                        }
                        k += 1;
                    }
                    if !found {
                        let mut v: Vec<Str> = Vec::new();
                        v.push(names[a].clone());
                        missing.push((d.clone(), v));
                    }
                }
            }
        }
        adj.push(out);
        has_missing.push(miss);
        a += 1;
    }
    missing.sort_by(|x, y| x.0.cmp(&y.0));
    let mut k = 0;
    while k < missing.len() {
        missing[k].1.sort();
        k += 1;
    }

    // SCCs
    let mut idx: Vec<i64> = vec![-1; n];
    let mut low: Vec<i64> = vec![0; n];
    let mut on: Vec<bool> = vec![false; n];
    let mut stack: Vec<usize> = Vec::new();
    let mut counter: i64 = 0;
    let mut comps: Vec<Vec<usize>> = Vec::new();
    let mut v = 0;
    while v < n {
        if idx[v] < 0 {
            tarjan(v, &adj, &mut idx, &mut low, &mut on, &mut stack, &mut counter, &mut comps);
        }
        v += 1;
    }
    let mut in_cycle: Vec<bool> = vec![false; n];
    let mut cycles: Vec<Vec<Str>> = Vec::new();
    for c in comps.iter() {
        let is_cycle = if c.len() >= 2 {
            true
        } else {
            let x = c[0];
            let mut self_loop = false;
            for w in adj[x].iter() {
                if *w == x {
                    self_loop = true;
                }
            }
            self_loop
        };
        if is_cycle {
            let mut g: Vec<Str> = Vec::new();
            for x in c.iter() {
                in_cycle[*x] = true;
                g.push(names[*x].clone());
            }
            g.sort();
            cycles.push(g);
        }
    }
    cycles.sort_by(|x, y| x[0].cmp(&y[0]));

    // stages
    let mut stage: Vec<usize> = vec![0; n];
    let mut changed = true;
    while changed {
        changed = false;
        let mut x = 0;
        while x < n {
            if stage[x] == 0 && !has_missing[x] && !in_cycle[x] {
                let mut all = true;
                let mut best = 0;
                for w in adj[x].iter() {
                    if stage[*w] == 0 {
                        all = false;
                    } else if stage[*w] > best {
                        best = stage[*w];
                    }
                }
                if all {
                    stage[x] = best + 1;
                    changed = true;
                }
            }
            x += 1;
        }
    }

    let mut lines: Vec<Str> = Vec::new();
    let mut maxs = 0;
    let mut built = 0;
    let mut x = 0;
    while x < n {
        if stage[x] > 0 {
            built += 1;
            if stage[x] > maxs {
                maxs = stage[x];
            }
        }
        x += 1;
    }
    let mut st = 1;
    while st <= maxs {
        let mut g: Vec<Str> = Vec::new();
        let mut x = 0;
        while x < n {
            if stage[x] == st {
                g.push(names[x].clone());
            }
            x += 1;
        }
        if g.len() > 0 {
            lines.push(format!("stage {}: {}", st, join(&g)));
        }
        st += 1;
    }
    for g in cycles.iter() {
        lines.push(format!("cycle: {}", join(g)));
    }
    for m in missing.iter() {
        lines.push(format!("missing: {} (needed by {})", m.0, join(&m.1)));
    }
    if invalid.len() > 0 {
        lines.push(format!("invalid: {}", join(&invalid)));
    }
    let mut blocked: Vec<Str> = Vec::new();
    let mut x = 0;
    while x < n {
        if stage[x] == 0 && !in_cycle[x] {
            blocked.push(names[x].clone());
        }
        x += 1;
    }
    if blocked.len() > 0 {
        lines.push(format!("blocked: {}", join(&blocked)));
    }
    lines.push(format!("built {} of {}", built, n));

    let mut out: Str = "".to_string();
    let mut k = 0;
    while k < lines.len() {
        if k > 0 {
            out.push('\n');
        }
        out.push_str(&lines[k]);
        k += 1;
    }
    out
}

enum Json {
    Null,
    Bool(bool),
    Num,
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

fn skip_ws(s: Vec<char>, i: usize) -> usize {
    let mut i = i;
    while i < s.len() && (s[i] == ' ' || s[i] == '\n' || s[i] == '\r' || s[i] == '\t') {
        i += 1;
    }
    i
}

fn hex4(s: Vec<char>, i: usize) -> Option<(u32, usize)> {
    let mut i = i;
    if i + 4 > s.len() {
        return None;
    }
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        let c = s[i];
        let d = match c.to_digit(16) {
            Some(d) => d,
            None => return None,
        };
        v = v * 16 + d;
        i += 1;
        k += 1;
    }
    Some((v, i))
}

fn parse_string(s: Vec<char>, i: usize) -> Option<(Str, usize)> {
    let mut i = i;
    if i >= s.len() || s[i] != '"' {
        return None;
    }
    i += 1;
    let mut out: Str = "".to_string();
    loop {
        if i >= s.len() {
            return None;
        }
        let c = s[i];
        i += 1;
        if c == '"' {
            return Some((out, i));
        }
        if c == '\\' {
            if i >= s.len() {
                return None;
            }
            let e = s[i];
            i += 1;
            if e == '"' {
                out.push('"');
            } else if e == '\\' {
                out.push('\\');
            } else if e == '/' {
                out.push('/');
            } else if e == 'b' {
                out.push('\u{8}');
            } else if e == 'f' {
                out.push('\u{c}');
            } else if e == 'n' {
                out.push('\n');
            } else if e == 'r' {
                out.push('\r');
            } else if e == 't' {
                out.push('\t');
            } else if e == 'u' {
                let (c0, ni) = match hex4(s.clone(), i) {
                    Some(r) => r,
                    None => return None,
                };
                let mut code = c0;
                i = ni;
                if code >= 0xD800 && code < 0xDC00 {
                    if i + 1 < s.len() && s[i] == '\\' && s[i + 1] == 'u' {
                        match hex4(s.clone(), i + 2) {
                            Some((lo, ni2)) => {
                                if lo >= 0xDC00 && lo < 0xE000 {
                                    code = 0x10000 + ((code - 0xD800) << 10) + (lo - 0xDC00);
                                    i = ni2;
                                }
                            }
                            None => return None,
                        }
                    }
                }
                match char::from_u32(code) {
                    Some(ch) => out.push(ch),
                    None => out.push('\u{FFFD}'),
                }
            } else {
                return None;
            }
        } else {
            out.push(c);
        }
    }
}

fn lit(s: Vec<char>, i: usize, w: Str) -> bool {
    let cs: Vec<char> = w.chars().collect();
    if i + cs.len() > s.len() {
        return false;
    }
    let mut k = 0;
    while k < cs.len() {
        if s[i + k] != cs[k] {
            return false;
        }
        k += 1;
    }
    true
}

fn parse_value(s: Vec<char>, i: usize) -> Option<(Json, usize)> {
    let mut i = skip_ws(s.clone(), i);
    if i >= s.len() {
        return None;
    }
    let c = s[i];
    if c == '{' {
        i += 1;
        let mut items: Vec<(Str, Json)> = Vec::new();
        i = skip_ws(s.clone(), i);
        if i < s.len() && s[i] == '}' {
            return Some((Json::Obj(items), i + 1));
        }
        loop {
            i = skip_ws(s.clone(), i);
            let (k, ni) = match parse_string(s.clone(), i) {
                Some(r) => r,
                None => return None,
            };
            i = skip_ws(s.clone(), ni);
            if i >= s.len() || s[i] != ':' {
                return None;
            }
            i += 1;
            let (v, ni2) = match parse_value(s.clone(), i) {
                Some(r) => r,
                None => return None,
            };
            i = ni2;
            let mut j = 0;
            while j < items.len() {
                if items[j].0 == k {
                    items.remove(j);
                    break;
                }
                j += 1;
            }
            items.push((k, v));
            i = skip_ws(s.clone(), i);
            if i >= s.len() {
                return None;
            }
            if s[i] == ',' {
                i += 1;
            } else if s[i] == '}' {
                return Some((Json::Obj(items), i + 1));
            } else {
                return None;
            }
        }
    } else if c == '[' {
        i += 1;
        let mut items: Vec<Json> = Vec::new();
        i = skip_ws(s.clone(), i);
        if i < s.len() && s[i] == ']' {
            return Some((Json::Arr(items), i + 1));
        }
        loop {
            let (v, ni) = match parse_value(s.clone(), i) {
                Some(r) => r,
                None => return None,
            };
            items.push(v);
            i = skip_ws(s.clone(), ni);
            if i >= s.len() {
                return None;
            }
            if s[i] == ',' {
                i += 1;
            } else if s[i] == ']' {
                return Some((Json::Arr(items), i + 1));
            } else {
                return None;
            }
        }
    } else if c == '"' {
        match parse_string(s.clone(), i) {
            Some((t, ni)) => Some((Json::Text(t), ni)),
            None => None,
        }
    } else if c == 't' {
        if lit(s.clone(), i, "true".to_string()) { Some((Json::Bool(true), i + 4)) } else { None }
    } else if c == 'f' {
        if lit(s.clone(), i, "false".to_string()) { Some((Json::Bool(false), i + 5)) } else { None }
    } else if c == 'n' {
        if lit(s.clone(), i, "null".to_string()) { Some((Json::Null, i + 4)) } else { None }
    } else if c == '-' || (c >= '0' && c <= '9') {
        if c == '-' {
            i += 1;
        }
        let mut digits = 0;
        while i < s.len() && s[i] >= '0' && s[i] <= '9' {
            i += 1;
            digits += 1;
        }
        if digits == 0 {
            return None;
        }
        if i < s.len() && s[i] == '.' {
            i += 1;
            let mut d = 0;
            while i < s.len() && s[i] >= '0' && s[i] <= '9' {
                i += 1;
                d += 1;
            }
            if d == 0 {
                return None;
            }
        }
        if i < s.len() && (s[i] == 'e' || s[i] == 'E') {
            i += 1;
            if i < s.len() && (s[i] == '+' || s[i] == '-') {
                i += 1;
            }
            let mut d = 0;
            while i < s.len() && s[i] >= '0' && s[i] <= '9' {
                i += 1;
                d += 1;
            }
            if d == 0 {
                return None;
            }
        }
        Some((Json::Num, i))
    } else {
        None
    }
}

fn join(v: Vec<Str>) -> Str {
    let mut out: Str = "".to_string();
    let mut k = 0;
    while k < v.len() {
        if k > 0 {
            out = format!("{}, ", out);
        }
        out = format!("{}{}", out, v[k]);
        k += 1;
    }
    out
}

fn find(names: Vec<Str>, n: Str) -> Option<usize> {
    let mut k = 0;
    while k < names.len() {
        if names[k] == n {
            return Some(k);
        }
        k += 1;
    }
    None
}

fn sort_strs(v: Vec<Str>) -> Vec<Str> {
    let mut v = v;
    let mut a = 1;
    while a < v.len() {
        let mut j = a;
        while j > 0 && v[j] < v[j - 1] {
            let t = v[j].clone();
            v[j] = v[j - 1].clone();
            v[j - 1] = t;
            j -= 1;
        }
        a += 1;
    }
    v
}

fn main(input: Dir) -> Str {
    let text: Str = match input.read_to_string("packages.json") {
        Ok(t) => t,
        Err(_) => return "error: not an object".to_string(),
    };
    let chars: Vec<char> = text.chars().collect();
    let (root, pos0) = match parse_value(chars.clone(), 0) {
        Some(r) => r,
        None => return "error: not an object".to_string(),
    };
    let pos = skip_ws(chars.clone(), pos0);
    if pos != chars.len() {
        return "error: not an object".to_string();
    }
    let entries = match root {
        Json::Obj(e) => e,
        _ => return "error: not an object".to_string(),
    };

    let mut raw_names: Vec<Str> = Vec::new();
    let mut raw_deps: Vec<Vec<Str>> = Vec::new();
    let mut invalid: Vec<Str> = Vec::new();
    for (name, val) in entries {
        let mut ok = true;
        let mut deps: Vec<Str> = Vec::new();
        match val {
            Json::Arr(items) => {
                for it in items {
                    match it {
                        Json::Text(t) => {
                            if find(deps.clone(), t.clone()).is_none() {
                                deps.push(t);
                            }
                        }
                        _ => {
                            ok = false;
                        }
                    }
                }
            }
            _ => {
                ok = false;
            }
        }
        if ok {
            raw_names.push(name);
            raw_deps.push(deps);
        } else {
            invalid.push(name);
        }
    }
    let invalid = sort_strs(invalid);
    let names = sort_strs(raw_names.clone());
    let n = names.len();
    let mut deps_of: Vec<Vec<Str>> = Vec::new();
    let mut a = 0;
    while a < n {
        let r = find(raw_names.clone(), names[a].clone()).unwrap();
        deps_of.push(raw_deps[r].clone());
        a += 1;
    }

    let mut adj: Vec<Vec<usize>> = Vec::new();
    let mut has_missing: Vec<bool> = Vec::new();
    let mut missing_names: Vec<Str> = Vec::new();
    let mut a = 0;
    while a < n {
        let mut out: Vec<usize> = Vec::new();
        let mut miss = false;
        let mut k = 0;
        while k < deps_of[a].len() {
            let d = deps_of[a][k].clone();
            match find(names.clone(), d.clone()) {
                Some(j) => out.push(j),
                None => {
                    miss = true;
                    if find(missing_names.clone(), d.clone()).is_none() {
                        missing_names.push(d);
                    }
                }
            }
            k += 1;
        }
        adj.push(out);
        has_missing.push(miss);
        a += 1;
    }
    let missing_names = sort_strs(missing_names);

    // reachability
    let mut reach: Vec<Vec<bool>> = Vec::new();
    let mut v = 0;
    while v < n {
        let mut seen: Vec<bool> = vec![false; n];
        let mut queue: Vec<usize> = Vec::new();
        let mut k = 0;
        while k < adj[v].len() {
            let w = adj[v][k];
            if !seen[w] {
                seen[w] = true;
                queue.push(w);
            }
            k += 1;
        }
        let mut q = 0;
        while q < queue.len() {
            let u = queue[q];
            let mut k = 0;
            while k < adj[u].len() {
                let w = adj[u][k];
                if !seen[w] {
                    seen[w] = true;
                    queue.push(w);
                }
                k += 1;
            }
            q += 1;
        }
        reach.push(seen);
        v += 1;
    }
    let mut in_cycle: Vec<bool> = vec![false; n];
    let mut v = 0;
    while v < n {
        if reach[v][v] {
            in_cycle[v] = true;
        }
        v += 1;
    }
    let mut assigned: Vec<bool> = vec![false; n];
    let mut cycle_lines: Vec<Str> = Vec::new();
    let mut v = 0;
    while v < n {
        if in_cycle[v] && !assigned[v] {
            let mut g: Vec<Str> = Vec::new();
            let mut u = 0;
            while u < n {
                if u == v || (reach[v][u] && reach[u][v]) {
                    assigned[u] = true;
                    g.push(names[u].clone());
                }
                u += 1;
            }
            cycle_lines.push(format!("cycle: {}", join(g)));
        }
        v += 1;
    }

    // stages
    let mut stage: Vec<usize> = vec![0; n];
    let mut changed = true;
    while changed {
        changed = false;
        let mut x = 0;
        while x < n {
            if stage[x] == 0 && !has_missing[x] && !in_cycle[x] {
                let mut all = true;
                let mut best = 0;
                let mut k = 0;
                while k < adj[x].len() {
                    let w = adj[x][k];
                    if stage[w] == 0 {
                        all = false;
                    } else if stage[w] > best {
                        best = stage[w];
                    }
                    k += 1;
                }
                if all {
                    stage[x] = best + 1;
                    changed = true;
                }
            }
            x += 1;
        }
    }

    let mut lines: Vec<Str> = Vec::new();
    let mut maxs = 0;
    let mut built = 0;
    let mut x = 0;
    while x < n {
        if stage[x] > 0 {
            built += 1;
            if stage[x] > maxs {
                maxs = stage[x];
            }
        }
        x += 1;
    }
    let mut st = 1;
    while st <= maxs {
        let mut g: Vec<Str> = Vec::new();
        let mut x = 0;
        while x < n {
            if stage[x] == st {
                g.push(names[x].clone());
            }
            x += 1;
        }
        if g.len() > 0 {
            lines.push(format!("stage {}: {}", st, join(g)));
        }
        st += 1;
    }
    let mut k = 0;
    while k < cycle_lines.len() {
        lines.push(cycle_lines[k].clone());
        k += 1;
    }
    let mut m = 0;
    while m < missing_names.len() {
        let mn = missing_names[m].clone();
        let mut needers: Vec<Str> = Vec::new();
        let mut a = 0;
        while a < n {
            if find(deps_of[a].clone(), mn.clone()).is_some() {
                needers.push(names[a].clone());
            }
            a += 1;
        }
        lines.push(format!("missing: {} (needed by {})", mn, join(needers)));
        m += 1;
    }
    if invalid.len() > 0 {
        lines.push(format!("invalid: {}", join(invalid)));
    }
    let mut blocked: Vec<Str> = Vec::new();
    let mut x = 0;
    while x < n {
        if stage[x] == 0 && !in_cycle[x] {
            blocked.push(names[x].clone());
        }
        x += 1;
    }
    if blocked.len() > 0 {
        lines.push(format!("blocked: {}", join(blocked)));
    }
    lines.push(format!("built {} of {}", built, n));

    let mut out: Str = "".to_string();
    let mut k = 0;
    while k < lines.len() {
        if k > 0 {
            out = format!("{}\n", out);
        }
        out = format!("{}{}", out, lines[k]);
        k += 1;
    }
    out
}

enum Json {
    Null,
    Bool(bool),
    Num,
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

fn chars_of(t: Str) -> Vec<Str> {
    let mut v: Vec<Str> = Vec::new();
    for p in t.split("") {
        if p.len() > 0 {
            v.push(p.to_string());
        }
    }
    v
}

fn is_ws(c: Str) -> bool {
    c == " " || c == "\n" || c == "\r" || c == "\t"
}

fn is_digit(c: Str) -> bool {
    c.len() == 1 && c >= "0".to_string() && c <= "9".to_string()
}

fn skip_ws(s: Vec<Str>, i: usize) -> usize {
    let mut i = i;
    while i < s.len() && is_ws(s[i].clone()) {
        i += 1;
    }
    i
}

fn hexval(c: Str) -> Option<u32> {
    let lo = chars_of("0123456789abcdef".to_string());
    let up = chars_of("0123456789ABCDEF".to_string());
    let mut k = 0;
    while k < 16 {
        if lo[k] == c || up[k] == c {
            return Some(k as u32);
        }
        k += 1;
    }
    None
}

fn hex4(s: Vec<Str>, i: usize) -> Option<(u32, usize)> {
    let mut i = i;
    if i + 4 > s.len() {
        return None;
    }
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        let d = match hexval(s[i].clone()) {
            Some(d) => d,
            None => return None,
        };
        v = v * 16 + d;
        i += 1;
        k += 1;
    }
    Some((v, i))
}

fn ascii_of(code: u32) -> Option<Str> {
    if code >= 32 && code <= 126 {
        let table = chars_of(" !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~".to_string());
        let idx = (code - 32) as usize;
        if idx < table.len() {
            return Some(table[idx].clone());
        }
        return None;
    }
    if code == 10 {
        return Some("\n".to_string());
    }
    if code == 9 {
        return Some("\t".to_string());
    }
    if code == 13 {
        return Some("\r".to_string());
    }
    None
}

fn parse_string(s: Vec<Str>, i: usize) -> Option<(Str, usize)> {
    let mut i = i;
    if i >= s.len() || s[i] != "\"" {
        return None;
    }
    i += 1;
    let mut out: Str = "".to_string();
    loop {
        if i >= s.len() {
            return None;
        }
        let c = s[i].clone();
        i += 1;
        if c == "\"" {
            return Some((out, i));
        }
        if c == "\\" {
            if i >= s.len() {
                return None;
            }
            let e = s[i].clone();
            i += 1;
            if e == "\"" {
                out = format!("{}{}", out, "\"");
            } else if e == "\\" {
                out = format!("{}{}", out, "\\");
            } else if e == "/" {
                out = format!("{}{}", out, "/");
            } else if e == "b" {
                out = format!("{}{}", out, "\\b");
            } else if e == "f" {
                out = format!("{}{}", out, "\\f");
            } else if e == "n" {
                out = format!("{}{}", out, "\n");
            } else if e == "r" {
                out = format!("{}{}", out, "\r");
            } else if e == "t" {
                out = format!("{}{}", out, "\t");
            } else if e == "u" {
                let start = i;
                let (code, ni) = match hex4(s.clone(), i) {
                    Some(r) => r,
                    None => return None,
                };
                i = ni;
                match ascii_of(code) {
                    Some(t) => {
                        out = format!("{}{}", out, t);
                    }
                    None => {
                        out = format!("{}\\u", out);
                        let mut k = start;
                        while k < ni {
                            out = format!("{}{}", out, s[k]);
                            k += 1;
                        }
                    }
                }
            } else {
                return None;
            }
        } else {
            out = format!("{}{}", out, c);
        }
    }
}

fn lit(s: Vec<Str>, i: usize, w: Str) -> bool {
    let cs: Vec<Str> = chars_of(w);
    if i + cs.len() > s.len() {
        return false;
    }
    let mut k = 0;
    while k < cs.len() {
        if s[i + k] != cs[k] {
            return false;
        }
        k += 1;
    }
    true
}

fn parse_value(s: Vec<Str>, i: usize) -> Option<(Json, usize)> {
    let mut i = skip_ws(s.clone(), i);
    if i >= s.len() {
        return None;
    }
    let c = s[i].clone();
    if c == "{" {
        i += 1;
        let mut items: Vec<(Str, Json)> = Vec::new();
        i = skip_ws(s.clone(), i);
        if i < s.len() && s[i] == "}" {
            return Some((Json::Obj(items), i + 1));
        }
        loop {
            i = skip_ws(s.clone(), i);
            let (k, ni) = match parse_string(s.clone(), i) {
                Some(r) => r,
                None => return None,
            };
            i = skip_ws(s.clone(), ni);
            if i >= s.len() || s[i] != ":" {
                return None;
            }
            i += 1;
            let (v, ni2) = match parse_value(s.clone(), i) {
                Some(r) => r,
                None => return None,
            };
            i = ni2;
            let mut j = 0;
            while j < items.len() {
                if items[j].0 == k {
                    items.remove(j);
                    break;
                }
                j += 1;
            }
            items.push((k, v));
            i = skip_ws(s.clone(), i);
            if i >= s.len() {
                return None;
            }
            if s[i] == "," {
                i += 1;
            } else if s[i] == "}" {
                return Some((Json::Obj(items), i + 1));
            } else {
                return None;
            }
        }
    } else if c == "[" {
        i += 1;
        let mut items: Vec<Json> = Vec::new();
        i = skip_ws(s.clone(), i);
        if i < s.len() && s[i] == "]" {
            return Some((Json::Arr(items), i + 1));
        }
        loop {
            let (v, ni) = match parse_value(s.clone(), i) {
                Some(r) => r,
                None => return None,
            };
            items.push(v);
            i = skip_ws(s.clone(), ni);
            if i >= s.len() {
                return None;
            }
            if s[i] == "," {
                i += 1;
            } else if s[i] == "]" {
                return Some((Json::Arr(items), i + 1));
            } else {
                return None;
            }
        }
    } else if c == "\"" {
        match parse_string(s.clone(), i) {
            Some((t, ni)) => Some((Json::Text(t), ni)),
            None => None,
        }
    } else if c == "t" {
        if lit(s.clone(), i, "true".to_string()) { Some((Json::Bool(true), i + 4)) } else { None }
    } else if c == "f" {
        if lit(s.clone(), i, "false".to_string()) { Some((Json::Bool(false), i + 5)) } else { None }
    } else if c == "n" {
        if lit(s.clone(), i, "null".to_string()) { Some((Json::Null, i + 4)) } else { None }
    } else if c == "-" || is_digit(c.clone()) {
        if c == "-" {
            i += 1;
        }
        let mut digits = 0;
        while i < s.len() && is_digit(s[i].clone()) {
            i += 1;
            digits += 1;
        }
        if digits == 0 {
            return None;
        }
        if i < s.len() && s[i] == "." {
            i += 1;
            let mut d = 0;
            while i < s.len() && is_digit(s[i].clone()) {
                i += 1;
                d += 1;
            }
            if d == 0 {
                return None;
            }
        }
        if i < s.len() && (s[i] == "e" || s[i] == "E") {
            i += 1;
            if i < s.len() && (s[i] == "+" || s[i] == "-") {
                i += 1;
            }
            let mut d = 0;
            while i < s.len() && is_digit(s[i].clone()) {
                i += 1;
                d += 1;
            }
            if d == 0 {
                return None;
            }
        }
        Some((Json::Num, i))
    } else {
        None
    }
}

fn join(v: Vec<Str>) -> Str {
    let mut out: Str = "".to_string();
    let mut k = 0;
    while k < v.len() {
        if k > 0 {
            out = format!("{}, ", out);
        }
        out = format!("{}{}", out, v[k]);
        k += 1;
    }
    out
}

fn find(names: Vec<Str>, n: Str) -> Option<usize> {
    let mut k = 0;
    while k < names.len() {
        if names[k] == n {
            return Some(k);
        }
        k += 1;
    }
    None
}

fn sort_strs(v: Vec<Str>) -> Vec<Str> {
    let mut v = v;
    let mut a = 1;
    while a < v.len() {
        let mut j = a;
        while j > 0 && v[j] < v[j - 1] {
            let t = v[j].clone();
            v[j] = v[j - 1].clone();
            v[j - 1] = t;
            j -= 1;
        }
        a += 1;
    }
    v
}

fn main(input: Dir) -> Str {
    let text: Str = match input.read_to_string("packages.json") {
        Ok(t) => t,
        Err(_) => return "error: not an object".to_string(),
    };
    let chars: Vec<Str> = chars_of(text);
    let (root, pos0) = match parse_value(chars.clone(), 0) {
        Some(r) => r,
        None => return "error: not an object".to_string(),
    };
    let pos = skip_ws(chars.clone(), pos0);
    if pos != chars.len() {
        return "error: not an object".to_string();
    }
    let entries = match root {
        Json::Obj(e) => e,
        _ => return "error: not an object".to_string(),
    };

    let mut raw_names: Vec<Str> = Vec::new();
    let mut raw_deps: Vec<Vec<Str>> = Vec::new();
    let mut invalid: Vec<Str> = Vec::new();
    for (name, val) in entries {
        let mut ok = true;
        let mut deps: Vec<Str> = Vec::new();
        match val {
            Json::Arr(items) => {
                for it in items {
                    match it {
                        Json::Text(t) => {
                            if find(deps.clone(), t.clone()).is_none() {
                                deps.push(t);
                            }
                        }
                        _ => {
                            ok = false;
                        }
                    }
                }
            }
            _ => {
                ok = false;
            }
        }
        if ok {
            raw_names.push(name);
            raw_deps.push(deps);
        } else {
            invalid.push(name);
        }
    }
    let invalid = sort_strs(invalid);
    let names = sort_strs(raw_names.clone());
    let n = names.len();
    let mut deps_of: Vec<Vec<Str>> = Vec::new();
    let mut a = 0;
    while a < n {
        let r = find(raw_names.clone(), names[a].clone()).unwrap();
        deps_of.push(raw_deps[r].clone());
        a += 1;
    }

    let mut adj: Vec<Vec<usize>> = Vec::new();
    let mut has_missing: Vec<bool> = Vec::new();
    let mut missing_names: Vec<Str> = Vec::new();
    let mut a = 0;
    while a < n {
        let mut out: Vec<usize> = Vec::new();
        let mut miss = false;
        let mut k = 0;
        while k < deps_of[a].len() {
            let d = deps_of[a][k].clone();
            match find(names.clone(), d.clone()) {
                Some(j) => out.push(j),
                None => {
                    miss = true;
                    if find(missing_names.clone(), d.clone()).is_none() {
                        missing_names.push(d);
                    }
                }
            }
            k += 1;
        }
        adj.push(out);
        has_missing.push(miss);
        a += 1;
    }
    let missing_names = sort_strs(missing_names);

    let mut reach: Vec<Vec<bool>> = Vec::new();
    let mut v = 0;
    while v < n {
        let mut seen: Vec<bool> = vec![false; n];
        let mut queue: Vec<usize> = Vec::new();
        let mut k = 0;
        while k < adj[v].len() {
            let w = adj[v][k];
            if !seen[w] {
                seen[w] = true;
                queue.push(w);
            }
            k += 1;
        }
        let mut q = 0;
        while q < queue.len() {
            let u = queue[q];
            let mut k = 0;
            while k < adj[u].len() {
                let w = adj[u][k];
                if !seen[w] {
                    seen[w] = true;
                    queue.push(w);
                }
                k += 1;
            }
            q += 1;
        }
        reach.push(seen);
        v += 1;
    }
    let mut in_cycle: Vec<bool> = vec![false; n];
    let mut v = 0;
    while v < n {
        if reach[v][v] {
            in_cycle[v] = true;
        }
        v += 1;
    }
    let mut assigned: Vec<bool> = vec![false; n];
    let mut cycle_lines: Vec<Str> = Vec::new();
    let mut v = 0;
    while v < n {
        if in_cycle[v] && !assigned[v] {
            let mut g: Vec<Str> = Vec::new();
            let mut u = 0;
            while u < n {
                if u == v || (reach[v][u] && reach[u][v]) {
                    assigned[u] = true;
                    g.push(names[u].clone());
                }
                u += 1;
            }
            cycle_lines.push(format!("cycle: {}", join(g)));
        }
        v += 1;
    }

    let mut stage: Vec<usize> = vec![0; n];
    let mut changed = true;
    while changed {
        changed = false;
        let mut x = 0;
        while x < n {
            if stage[x] == 0 && !has_missing[x] && !in_cycle[x] {
                let mut all = true;
                let mut best = 0;
                let mut k = 0;
                while k < adj[x].len() {
                    let w = adj[x][k];
                    if stage[w] == 0 {
                        all = false;
                    } else if stage[w] > best {
                        best = stage[w];
                    }
                    k += 1;
                }
                if all {
                    stage[x] = best + 1;
                    changed = true;
                }
            }
            x += 1;
        }
    }

    let mut lines: Vec<Str> = Vec::new();
    let mut maxs = 0;
    let mut built = 0;
    let mut x = 0;
    while x < n {
        if stage[x] > 0 {
            built += 1;
            if stage[x] > maxs {
                maxs = stage[x];
            }
        }
        x += 1;
    }
    let mut st = 1;
    while st <= maxs {
        let mut g: Vec<Str> = Vec::new();
        let mut x = 0;
        while x < n {
            if stage[x] == st {
                g.push(names[x].clone());
            }
            x += 1;
        }
        if g.len() > 0 {
            lines.push(format!("stage {}: {}", st, join(g)));
        }
        st += 1;
    }
    let mut k = 0;
    while k < cycle_lines.len() {
        lines.push(cycle_lines[k].clone());
        k += 1;
    }
    let mut m = 0;
    while m < missing_names.len() {
        let mn = missing_names[m].clone();
        let mut needers: Vec<Str> = Vec::new();
        let mut a = 0;
        while a < n {
            if find(deps_of[a].clone(), mn.clone()).is_some() {
                needers.push(names[a].clone());
            }
            a += 1;
        }
        lines.push(format!("missing: {} (needed by {})", mn, join(needers)));
        m += 1;
    }
    if invalid.len() > 0 {
        lines.push(format!("invalid: {}", join(invalid)));
    }
    let mut blocked: Vec<Str> = Vec::new();
    let mut x = 0;
    while x < n {
        if stage[x] == 0 && !in_cycle[x] {
            blocked.push(names[x].clone());
        }
        x += 1;
    }
    if blocked.len() > 0 {
        lines.push(format!("blocked: {}", join(blocked)));
    }
    lines.push(format!("built {} of {}", built, n));

    let mut out: Str = "".to_string();
    let mut k = 0;
    while k < lines.len() {
        if k > 0 {
            out = format!("{}\n", out);
        }
        out = format!("{}{}", out, lines[k]);
        k += 1;
    }
    out
}

struct Entry {
    key: Str,
    val: Json,
}

enum Json {
    Null,
    Bool(bool),
    Num,
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<Entry>),
}

struct PStr {
    s: Str,
    i: usize,
}

struct PVal {
    v: Json,
    i: usize,
}

struct Hex {
    v: u32,
    i: usize,
}

fn chars_of(t: Str) -> Vec<Str> {
    let mut v: Vec<Str> = Vec::new();
    for p in t.split("") {
        if p.len() > 0 {
            v.push(p.to_string());
        }
    }
    v
}

fn is_ws(c: Str) -> bool {
    c == " " || c == "\n" || c == "\r" || c == "\t"
}

fn is_digit(c: Str) -> bool {
    c.len() == 1 && c >= "0".to_string() && c <= "9".to_string()
}

fn skip_ws(s: Vec<Str>, i: usize) -> usize {
    let mut i = i;
    while i < s.len() && is_ws(s[i].clone()) {
        i += 1;
    }
    i
}

fn hexval(c: Str) -> Option<u32> {
    let lo = chars_of("0123456789abcdef".to_string());
    let up = chars_of("0123456789ABCDEF".to_string());
    let mut k = 0;
    while k < 16 {
        if lo[k] == c || up[k] == c {
            return Some(k as u32);
        }
        k += 1;
    }
    None
}

fn hex4(s: Vec<Str>, i: usize) -> Option<Hex> {
    let mut i = i;
    if i + 4 > s.len() {
        return None;
    }
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        let d = match hexval(s[i].clone()) {
            Some(d) => d,
            None => return None,
        };
        v = v * 16 + d;
        i += 1;
        k += 1;
    }
    Some(Hex { v: v, i: i })
}

fn ascii_of(code: u32) -> Option<Str> {
    if code >= 32 && code <= 126 {
        let table = chars_of(" !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~".to_string());
        let idx = (code - 32) as usize;
        if idx < table.len() {
            return Some(table[idx].clone());
        }
        return None;
    }
    if code == 10 {
        return Some("\n".to_string());
    }
    if code == 9 {
        return Some("\t".to_string());
    }
    if code == 13 {
        return Some("\r".to_string());
    }
    None
}

fn parse_string(s: Vec<Str>, i: usize) -> Option<PStr> {
    let mut i = i;
    if i >= s.len() || s[i] != "\"" {
        return None;
    }
    i += 1;
    let mut out: Str = "".to_string();
    loop {
        if i >= s.len() {
            return None;
        }
        let c = s[i].clone();
        i += 1;
        if c == "\"" {
            return Some(PStr { s: out, i: i });
        }
        if c == "\\" {
            if i >= s.len() {
                return None;
            }
            let e = s[i].clone();
            i += 1;
            if e == "\"" {
                out = format!("{}{}", out, "\"");
            } else if e == "\\" {
                out = format!("{}{}", out, "\\");
            } else if e == "/" {
                out = format!("{}{}", out, "/");
            } else if e == "b" {
                out = format!("{}{}", out, "\\b");
            } else if e == "f" {
                out = format!("{}{}", out, "\\f");
            } else if e == "n" {
                out = format!("{}{}", out, "\n");
            } else if e == "r" {
                out = format!("{}{}", out, "\r");
            } else if e == "t" {
                out = format!("{}{}", out, "\t");
            } else if e == "u" {
                let start = i;
                let h = match hex4(s.clone(), i) {
                    Some(r) => r,
                    None => return None,
                };
                let code = h.v;
                let ni = h.i;
                i = ni;
                match ascii_of(code) {
                    Some(t) => {
                        out = format!("{}{}", out, t);
                    }
                    None => {
                        out = format!("{}\\u", out);
                        let mut k = start;
                        while k < ni {
                            out = format!("{}{}", out, s[k]);
                            k += 1;
                        }
                    }
                }
            } else {
                return None;
            }
        } else {
            out = format!("{}{}", out, c);
        }
    }
}

fn lit(s: Vec<Str>, i: usize, w: Str) -> bool {
    let cs: Vec<Str> = chars_of(w);
    if i + cs.len() > s.len() {
        return false;
    }
    let mut k = 0;
    while k < cs.len() {
        if s[i + k] != cs[k] {
            return false;
        }
        k += 1;
    }
    true
}

fn parse_value(s: Vec<Str>, i: usize) -> Option<PVal> {
    let mut i = skip_ws(s.clone(), i);
    if i >= s.len() {
        return None;
    }
    let c = s[i].clone();
    if c == "{" {
        i += 1;
        let mut items: Vec<Entry> = Vec::new();
        i = skip_ws(s.clone(), i);
        if i < s.len() && s[i] == "}" {
            return Some(PVal { v: Json::Obj(items), i: i + 1 });
        }
        loop {
            i = skip_ws(s.clone(), i);
            let ps = match parse_string(s.clone(), i) {
                Some(r) => r,
                None => return None,
            };
            let k = ps.s;
            i = skip_ws(s.clone(), ps.i);
            if i >= s.len() || s[i] != ":" {
                return None;
            }
            i += 1;
            let pv = match parse_value(s.clone(), i) {
                Some(r) => r,
                None => return None,
            };
            i = pv.i;
            let mut j = 0;
            while j < items.len() {
                if items[j].key == k {
                    items.remove(j);
                    break;
                }
                j += 1;
            }
            items.push(Entry { key: k, val: pv.v });
            i = skip_ws(s.clone(), i);
            if i >= s.len() {
                return None;
            }
            if s[i] == "," {
                i += 1;
            } else if s[i] == "}" {
                return Some(PVal { v: Json::Obj(items), i: i + 1 });
            } else {
                return None;
            }
        }
    } else if c == "[" {
        i += 1;
        let mut items: Vec<Json> = Vec::new();
        i = skip_ws(s.clone(), i);
        if i < s.len() && s[i] == "]" {
            return Some(PVal { v: Json::Arr(items), i: i + 1 });
        }
        loop {
            let pv = match parse_value(s.clone(), i) {
                Some(r) => r,
                None => return None,
            };
            items.push(pv.v);
            i = skip_ws(s.clone(), pv.i);
            if i >= s.len() {
                return None;
            }
            if s[i] == "," {
                i += 1;
            } else if s[i] == "]" {
                return Some(PVal { v: Json::Arr(items), i: i + 1 });
            } else {
                return None;
            }
        }
    } else if c == "\"" {
        match parse_string(s.clone(), i) {
            Some(ps) => Some(PVal { v: Json::Text(ps.s), i: ps.i }),
            None => None,
        }
    } else if c == "t" {
        if lit(s.clone(), i, "true".to_string()) { Some(PVal { v: Json::Bool(true), i: i + 4 }) } else { None }
    } else if c == "f" {
        if lit(s.clone(), i, "false".to_string()) { Some(PVal { v: Json::Bool(false), i: i + 5 }) } else { None }
    } else if c == "n" {
        if lit(s.clone(), i, "null".to_string()) { Some(PVal { v: Json::Null, i: i + 4 }) } else { None }
    } else if c == "-" || is_digit(c.clone()) {
        if c == "-" {
            i += 1;
        }
        let mut digits = 0;
        while i < s.len() && is_digit(s[i].clone()) {
            i += 1;
            digits += 1;
        }
        if digits == 0 {
            return None;
        }
        if i < s.len() && s[i] == "." {
            i += 1;
            let mut d = 0;
            while i < s.len() && is_digit(s[i].clone()) {
                i += 1;
                d += 1;
            }
            if d == 0 {
                return None;
            }
        }
        if i < s.len() && (s[i] == "e" || s[i] == "E") {
            i += 1;
            if i < s.len() && (s[i] == "+" || s[i] == "-") {
                i += 1;
            }
            let mut d = 0;
            while i < s.len() && is_digit(s[i].clone()) {
                i += 1;
                d += 1;
            }
            if d == 0 {
                return None;
            }
        }
        Some(PVal { v: Json::Num, i: i })
    } else {
        None
    }
}

fn join(v: Vec<Str>) -> Str {
    let mut out: Str = "".to_string();
    let mut k = 0;
    while k < v.len() {
        if k > 0 {
            out = format!("{}, ", out);
        }
        out = format!("{}{}", out, v[k]);
        k += 1;
    }
    out
}

fn find(names: Vec<Str>, n: Str) -> Option<usize> {
    let mut k = 0;
    while k < names.len() {
        if names[k] == n {
            return Some(k);
        }
        k += 1;
    }
    None
}

fn sort_strs(v: Vec<Str>) -> Vec<Str> {
    let mut v = v;
    let mut a = 1;
    while a < v.len() {
        let mut j = a;
        while j > 0 && v[j] < v[j - 1] {
            let t = v[j].clone();
            v[j] = v[j - 1].clone();
            v[j - 1] = t;
            j -= 1;
        }
        a += 1;
    }
    v
}

fn main(input: Dir) -> Str {
    let text: Str = match input.read_to_string("packages.json") {
        Ok(t) => t,
        Err(_) => return "error: not an object".to_string(),
    };
    let chars: Vec<Str> = chars_of(text);
    let parsed = match parse_value(chars.clone(), 0) {
        Some(r) => r,
        None => return "error: not an object".to_string(),
    };
    let pos = skip_ws(chars.clone(), parsed.i);
    if pos != chars.len() {
        return "error: not an object".to_string();
    }
    let entries = match parsed.v {
        Json::Obj(e) => e,
        _ => return "error: not an object".to_string(),
    };

    let mut raw_names: Vec<Str> = Vec::new();
    let mut raw_deps: Vec<Vec<Str>> = Vec::new();
    let mut invalid: Vec<Str> = Vec::new();
    for ent in entries {
        let name = ent.key;
        let val = ent.val;
        let mut ok = true;
        let mut deps: Vec<Str> = Vec::new();
        match val {
            Json::Arr(items) => {
                for it in items {
                    match it {
                        Json::Text(t) => {
                            if find(deps.clone(), t.clone()).is_none() {
                                deps.push(t);
                            }
                        }
                        _ => {
                            ok = false;
                        }
                    }
                }
            }
            _ => {
                ok = false;
            }
        }
        if ok {
            raw_names.push(name);
            raw_deps.push(deps);
        } else {
            invalid.push(name);
        }
    }
    let invalid = sort_strs(invalid);
    let names = sort_strs(raw_names.clone());
    let n = names.len();
    let mut deps_of: Vec<Vec<Str>> = Vec::new();
    let mut a = 0;
    while a < n {
        let r = find(raw_names.clone(), names[a].clone()).unwrap();
        deps_of.push(raw_deps[r].clone());
        a += 1;
    }

    let mut adj: Vec<Vec<usize>> = Vec::new();
    let mut has_missing: Vec<bool> = Vec::new();
    let mut missing_names: Vec<Str> = Vec::new();
    let mut a = 0;
    while a < n {
        let mut out: Vec<usize> = Vec::new();
        let mut miss = false;
        let mut k = 0;
        while k < deps_of[a].len() {
            let d = deps_of[a][k].clone();
            match find(names.clone(), d.clone()) {
                Some(j) => out.push(j),
                None => {
                    miss = true;
                    if find(missing_names.clone(), d.clone()).is_none() {
                        missing_names.push(d);
                    }
                }
            }
            k += 1;
        }
        adj.push(out);
        has_missing.push(miss);
        a += 1;
    }
    let missing_names = sort_strs(missing_names);

    let mut reach: Vec<Vec<bool>> = Vec::new();
    let mut v = 0;
    while v < n {
        let mut seen: Vec<bool> = vec![false; n];
        let mut queue: Vec<usize> = Vec::new();
        let mut k = 0;
        while k < adj[v].len() {
            let w = adj[v][k];
            if !seen[w] {
                seen[w] = true;
                queue.push(w);
            }
            k += 1;
        }
        let mut q = 0;
        while q < queue.len() {
            let u = queue[q];
            let mut k = 0;
            while k < adj[u].len() {
                let w = adj[u][k];
                if !seen[w] {
                    seen[w] = true;
                    queue.push(w);
                }
                k += 1;
            }
            q += 1;
        }
        reach.push(seen);
        v += 1;
    }
    let mut in_cycle: Vec<bool> = vec![false; n];
    let mut v = 0;
    while v < n {
        if reach[v][v] {
            in_cycle[v] = true;
        }
        v += 1;
    }
    let mut assigned: Vec<bool> = vec![false; n];
    let mut cycle_lines: Vec<Str> = Vec::new();
    let mut v = 0;
    while v < n {
        if in_cycle[v] && !assigned[v] {
            let mut g: Vec<Str> = Vec::new();
            let mut u = 0;
            while u < n {
                if u == v || (reach[v][u] && reach[u][v]) {
                    assigned[u] = true;
                    g.push(names[u].clone());
                }
                u += 1;
            }
            cycle_lines.push(format!("cycle: {}", join(g)));
        }
        v += 1;
    }

    let mut stage: Vec<usize> = vec![0; n];
    let mut changed = true;
    while changed {
        changed = false;
        let mut x = 0;
        while x < n {
            if stage[x] == 0 && !has_missing[x] && !in_cycle[x] {
                let mut all = true;
                let mut best = 0;
                let mut k = 0;
                while k < adj[x].len() {
                    let w = adj[x][k];
                    if stage[w] == 0 {
                        all = false;
                    } else if stage[w] > best {
                        best = stage[w];
                    }
                    k += 1;
                }
                if all {
                    stage[x] = best + 1;
                    changed = true;
                }
            }
            x += 1;
        }
    }

    let mut lines: Vec<Str> = Vec::new();
    let mut maxs = 0;
    let mut built = 0;
    let mut x = 0;
    while x < n {
        if stage[x] > 0 {
            built += 1;
            if stage[x] > maxs {
                maxs = stage[x];
            }
        }
        x += 1;
    }
    let mut st = 1;
    while st <= maxs {
        let mut g: Vec<Str> = Vec::new();
        let mut x = 0;
        while x < n {
            if stage[x] == st {
                g.push(names[x].clone());
            }
            x += 1;
        }
        if g.len() > 0 {
            lines.push(format!("stage {}: {}", st, join(g)));
        }
        st += 1;
    }
    let mut k = 0;
    while k < cycle_lines.len() {
        lines.push(cycle_lines[k].clone());
        k += 1;
    }
    let mut m = 0;
    while m < missing_names.len() {
        let mn = missing_names[m].clone();
        let mut needers: Vec<Str> = Vec::new();
        let mut a = 0;
        while a < n {
            if find(deps_of[a].clone(), mn.clone()).is_some() {
                needers.push(names[a].clone());
            }
            a += 1;
        }
        lines.push(format!("missing: {} (needed by {})", mn, join(needers)));
        m += 1;
    }
    if invalid.len() > 0 {
        lines.push(format!("invalid: {}", join(invalid)));
    }
    let mut blocked: Vec<Str> = Vec::new();
    let mut x = 0;
    while x < n {
        if stage[x] == 0 && !in_cycle[x] {
            blocked.push(names[x].clone());
        }
        x += 1;
    }
    if blocked.len() > 0 {
        lines.push(format!("blocked: {}", join(blocked)));
    }
    lines.push(format!("built {} of {}", built, n));

    let mut out: Str = "".to_string();
    let mut k = 0;
    while k < lines.len() {
        if k > 0 {
            out = format!("{}\n", out);
        }
        out = format!("{}{}", out, lines[k]);
        k += 1;
    }
    out
}

struct Entry {
    key: Str,
    val: Json,
}

enum Json {
    Null,
    Bool(bool),
    Num,
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<Entry>),
}

struct PStr {
    s: Str,
    i: usize,
}

struct PVal {
    v: Json,
    i: usize,
}

struct Hex {
    v: u32,
    i: usize,
}

fn chars_of(t: Str) -> Vec<Str> {
    let mut v: Vec<Str> = Vec::new();
    for p in t.split("") {
        if p.len() > 0 {
            v.push(p.to_string());
        }
    }
    v
}

fn is_ws(c: Str) -> bool {
    c == " " || c == "\n" || c == "\r" || c == "\t"
}

fn is_digit(c: Str) -> bool {
    c.len() == 1 && c >= "0".to_string() && c <= "9".to_string()
}

fn skip_ws(s: Vec<Str>, i: usize) -> usize {
    let mut i = i;
    while i < s.len() && is_ws(s[i].clone()) {
        i += 1;
    }
    i
}

fn hexval(c: Str) -> Option<u32> {
    let lo = chars_of("0123456789abcdef".to_string());
    let up = chars_of("0123456789ABCDEF".to_string());
    let mut k: usize = 0;
    let mut kv: u32 = 0;
    while k < 16 {
        if lo[k] == c || up[k] == c {
            return Some(kv);
        }
        k += 1;
        kv += 1;
    }
    None
}

fn hex4(s: Vec<Str>, i: usize) -> Option<Hex> {
    let mut i = i;
    if i + 4 > s.len() {
        return None;
    }
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        let d = match hexval(s[i].clone()) {
            Some(d) => d,
            None => return None,
        };
        v = v * 16 + d;
        i += 1;
        k += 1;
    }
    Some(Hex { v: v, i: i })
}

fn ascii_of(code: u32) -> Option<Str> {
    if code >= 32 && code <= 126 {
        let table = chars_of(" !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~".to_string());
        let mut idx: usize = 0;
        let mut cv: u32 = 32;
        while idx < table.len() {
            if cv == code {
                return Some(table[idx].clone());
            }
            idx += 1;
            cv += 1;
        }
        return None;
    }
    if code == 10 {
        return Some("\n".to_string());
    }
    if code == 9 {
        return Some("\t".to_string());
    }
    if code == 13 {
        return Some("\r".to_string());
    }
    None
}

fn parse_string(s: Vec<Str>, i: usize) -> Option<PStr> {
    let mut i = i;
    if i >= s.len() || s[i] != "\"" {
        return None;
    }
    i += 1;
    let mut out: Str = "".to_string();
    loop {
        if i >= s.len() {
            return None;
        }
        let c = s[i].clone();
        i += 1;
        if c == "\"" {
            return Some(PStr { s: out, i: i });
        }
        if c == "\\" {
            if i >= s.len() {
                return None;
            }
            let e = s[i].clone();
            i += 1;
            if e == "\"" {
                out = format!("{}{}", out, "\"");
            } else if e == "\\" {
                out = format!("{}{}", out, "\\");
            } else if e == "/" {
                out = format!("{}{}", out, "/");
            } else if e == "b" {
                out = format!("{}{}", out, "\\b");
            } else if e == "f" {
                out = format!("{}{}", out, "\\f");
            } else if e == "n" {
                out = format!("{}{}", out, "\n");
            } else if e == "r" {
                out = format!("{}{}", out, "\r");
            } else if e == "t" {
                out = format!("{}{}", out, "\t");
            } else if e == "u" {
                let start = i;
                let h = match hex4(s.clone(), i) {
                    Some(r) => r,
                    None => return None,
                };
                let code = h.v;
                let ni = h.i;
                i = ni;
                match ascii_of(code) {
                    Some(t) => {
                        out = format!("{}{}", out, t);
                    }
                    None => {
                        out = format!("{}\\u", out);
                        let mut k = start;
                        while k < ni {
                            out = format!("{}{}", out, s[k]);
                            k += 1;
                        }
                    }
                }
            } else {
                return None;
            }
        } else {
            out = format!("{}{}", out, c);
        }
    }
}

fn lit(s: Vec<Str>, i: usize, w: Str) -> bool {
    let cs: Vec<Str> = chars_of(w);
    if i + cs.len() > s.len() {
        return false;
    }
    let mut k = 0;
    while k < cs.len() {
        if s[i + k] != cs[k] {
            return false;
        }
        k += 1;
    }
    true
}

fn parse_value(s: Vec<Str>, i: usize) -> Option<PVal> {
    let mut i = skip_ws(s.clone(), i);
    if i >= s.len() {
        return None;
    }
    let c = s[i].clone();
    if c == "{" {
        i += 1;
        let mut items: Vec<Entry> = Vec::new();
        i = skip_ws(s.clone(), i);
        if i < s.len() && s[i] == "}" {
            return Some(PVal { v: Json::Obj(items), i: i + 1 });
        }
        loop {
            i = skip_ws(s.clone(), i);
            let ps = match parse_string(s.clone(), i) {
                Some(r) => r,
                None => return None,
            };
            let k = ps.s;
            i = skip_ws(s.clone(), ps.i);
            if i >= s.len() || s[i] != ":" {
                return None;
            }
            i += 1;
            let pv = match parse_value(s.clone(), i) {
                Some(r) => r,
                None => return None,
            };
            i = pv.i;
            let mut j = 0;
            while j < items.len() {
                if items[j].key == k {
                    items.remove(j);
                    break;
                }
                j += 1;
            }
            items.push(Entry { key: k, val: pv.v });
            i = skip_ws(s.clone(), i);
            if i >= s.len() {
                return None;
            }
            if s[i] == "," {
                i += 1;
            } else if s[i] == "}" {
                return Some(PVal { v: Json::Obj(items), i: i + 1 });
            } else {
                return None;
            }
        }
    } else if c == "[" {
        i += 1;
        let mut items: Vec<Json> = Vec::new();
        i = skip_ws(s.clone(), i);
        if i < s.len() && s[i] == "]" {
            return Some(PVal { v: Json::Arr(items), i: i + 1 });
        }
        loop {
            let pv = match parse_value(s.clone(), i) {
                Some(r) => r,
                None => return None,
            };
            items.push(pv.v);
            i = skip_ws(s.clone(), pv.i);
            if i >= s.len() {
                return None;
            }
            if s[i] == "," {
                i += 1;
            } else if s[i] == "]" {
                return Some(PVal { v: Json::Arr(items), i: i + 1 });
            } else {
                return None;
            }
        }
    } else if c == "\"" {
        match parse_string(s.clone(), i) {
            Some(ps) => Some(PVal { v: Json::Text(ps.s), i: ps.i }),
            None => None,
        }
    } else if c == "t" {
        if lit(s.clone(), i, "true".to_string()) { Some(PVal { v: Json::Bool(true), i: i + 4 }) } else { None }
    } else if c == "f" {
        if lit(s.clone(), i, "false".to_string()) { Some(PVal { v: Json::Bool(false), i: i + 5 }) } else { None }
    } else if c == "n" {
        if lit(s.clone(), i, "null".to_string()) { Some(PVal { v: Json::Null, i: i + 4 }) } else { None }
    } else if c == "-" || is_digit(c.clone()) {
        if c == "-" {
            i += 1;
        }
        let mut digits = 0;
        while i < s.len() && is_digit(s[i].clone()) {
            i += 1;
            digits += 1;
        }
        if digits == 0 {
            return None;
        }
        if i < s.len() && s[i] == "." {
            i += 1;
            let mut d = 0;
            while i < s.len() && is_digit(s[i].clone()) {
                i += 1;
                d += 1;
            }
            if d == 0 {
                return None;
            }
        }
        if i < s.len() && (s[i] == "e" || s[i] == "E") {
            i += 1;
            if i < s.len() && (s[i] == "+" || s[i] == "-") {
                i += 1;
            }
            let mut d = 0;
            while i < s.len() && is_digit(s[i].clone()) {
                i += 1;
                d += 1;
            }
            if d == 0 {
                return None;
            }
        }
        Some(PVal { v: Json::Num, i: i })
    } else {
        None
    }
}

fn join(v: Vec<Str>) -> Str {
    let mut out: Str = "".to_string();
    let mut k = 0;
    while k < v.len() {
        if k > 0 {
