    let names = sort_strs(raw_names.clone());
    let n = names.len();
    let mut deps_of: Vec<Vec<Str>> = Vec::new();
    let mut a = 0;
    while a < n {
        let r = find(raw_names.clone(), names[a].clone()).unwrap();
        deps_of.push(raw_deps[r].clone());
        a += 1;
    }

    let mut adj: Vec<Vec<usize>> = Vec::new();
    let mut has_missing: Vec<bool> = Vec::new();
    let mut missing_names: Vec<Str> = Vec::new();
    let mut a = 0;
    while a < n {
        let mut out: Vec<usize> = Vec::new();
        let mut miss = false;
        let mut k = 0;
        while k < deps_of[a].len() {
            let d = deps_of[a][k].clone();
            match find(names.clone(), d.clone()) {
                Some(j) => out.push(j),
                None => {
                    miss = true;
                    if find(missing_names.clone(), d.clone()).is_none() {
                        missing_names.push(d);
                    }
                }
            }
            k += 1;
        }
        adj.push(out);
        has_missing.push(miss);
        a += 1;
    }
    let missing_names = sort_strs(missing_names);

    let mut reach: Vec<Vec<bool>> = Vec::new();
    let mut v = 0;
    while v < n {
        let mut seen: Vec<bool> = vec![false; n];
        let mut queue: Vec<usize> = Vec::new();
        let mut k = 0;
        while k < adj[v].len() {
            let w = adj[v][k];
            if !seen[w] {
                seen[w] = true;
                queue.push(w);
            }
            k += 1;
        }
        let mut q = 0;
        while q < queue.len() {
            let u = queue[q];
            let mut k = 0;
            while k < adj[u].len() {
                let w = adj[u][k];
                if !seen[w] {
                    seen[w] = true;
                    queue.push(w);
                }
                k += 1;
            }
            q += 1;
        }
        reach.push(seen);
        v += 1;
    }
    let mut in_cycle: Vec<bool> = vec![false; n];
    let mut v = 0;
    while v < n {
        if reach[v][v] {
            in_cycle[v] = true;
        }
        v += 1;
    }
    let mut assigned: Vec<bool> = vec![false; n];
    let mut cycle_lines: Vec<Str> = Vec::new();
    let mut v = 0;
    while v < n {
        if in_cycle[v] && !assigned[v] {
            let mut g: Vec<Str> = Vec::new();
            let mut u = 0;
            while u < n {
                if u == v || (reach[v][u] && reach[u][v]) {
                    assigned[u] = true;
                    g.push(names[u].clone());
                }
                u += 1;
            }
            cycle_lines.push(format!("cycle: {}", join(g)));
        }
        v += 1;
    }

    let mut stage: Vec<usize> = vec![0; n];
    let mut changed = true;
    while changed {
        changed = false;
        let mut x = 0;
        while x < n {
            if stage[x] == 0 && !has_missing[x] && !in_cycle[x] {
                let mut all = true;
                let mut best = 0;
                let mut k = 0;
                while k < adj[x].len() {
                    let w = adj[x][k];
                    if stage[w] == 0 {
                        all = false;
                    } else if stage[w] > best {
                        best = stage[w];
                    }
                    k += 1;
                }
                if all {
                    stage[x] = best + 1;
                    changed = true;
                }
            }
            x += 1;
        }
    }

    let mut lines: Vec<Str> = Vec::new();
    let mut maxs = 0;
    let mut built = 0;
    let mut x = 0;
    while x < n {
        if stage[x] > 0 {
            built += 1;
            if stage[x] > maxs {
                maxs = stage[x];
            }
        }
        x += 1;
    }
    let mut st = 1;
    while st <= maxs {
        let mut g: Vec<Str> = Vec::new();
        let mut x = 0;
        while x < n {
            if stage[x] == st {
                g.push(names[x].clone());
            }
            x += 1;
        }
        if g.len() > 0 {
            lines.push(format!("stage {}: {}", st, join(g)));
        }
        st += 1;
    }
    let mut k = 0;
    while k < cycle_lines.len() {
        lines.push(cycle_lines[k].clone());
        k += 1;
    }
    let mut m = 0;
    while m < missing_names.len() {
        let mn = missing_names[m].clone();
        let mut needers: Vec<Str> = Vec::new();
        let mut a = 0;
        while a < n {
            if find(deps_of[a].clone(), mn.clone()).is_some() {
                needers.push(names[a].clone());
            }
            a += 1;
        }
        lines.push(format!("missing: {} (needed by {})", mn, join(needers)));
        m += 1;
    }
    if invalid.len() > 0 {
        lines.push(format!("invalid: {}", join(invalid)));
    }
    let mut blocked: Vec<Str> = Vec::new();
    let mut x = 0;
    while x < n {
        if stage[x] == 0 && !in_cycle[x] {
            blocked.push(names[x].clone());
        }
        x += 1;
    }
    if blocked.len() > 0 {
        lines.push(format!("blocked: {}", join(blocked)));
    }
    lines.push(format!("built {} of {}", built, n));

    let mut out: Str = "".to_string();
    let mut k = 0;
    while k < lines.len() {
        if k > 0 {
            out = format!("{}\n", out);
        }
        out = format!("{}{}", out, lines[k]);
        k += 1;
    }
    out
}

fn parse_time(s: &str, allow_24: bool) -> Option<i64> {
    let b = s.as_bytes();
    if b.len() != 5 {
        return None;
    }
    if b[2] != b':' {
        return None;
    }
    let digits = [b[0], b[1], b[3], b[4]];
    for d in digits.iter() {
        if *d < b'0' || *d > b'9' {
            return None;
        }
    }
    let h = ((b[0] - b'0') as i64) * 10 + ((b[1] - b'0') as i64);
    let m = ((b[3] - b'0') as i64) * 10 + ((b[4] - b'0') as i64);
    if h == 24 && m == 0 && allow_24 {
        return Some(1440);
    }
    if h > 23 || m > 59 {
        return None;
    }
    Some(h * 60 + m)
}

fn fmt_time(t: i64) -> Str {
    let h = t / 60;
    let m = t % 60;
    format!("{:02}:{:02}", h, m)
}

fn fmt_iv(a: i64, b: i64) -> Str {
    format!("{}-{}", fmt_time(a), fmt_time(b))
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = match input.read("bookings.csv") {
        Ok(t) => t,
        Err(_) => return Err("cannot read bookings.csv".to_string()),
    };

    // (room, day, start, end, who)
    let mut bookings: Vec<(Str, Str, i64, i64, Str)> = Vec::new();
    let mut seen: Vec<Str> = Vec::new();
    let mut skipped: Vec<i64> = Vec::new();

    let mut lineno: i64 = 0;
    for raw in text.split('\n') {
        lineno += 1;
        if lineno == 1 {
            continue;
        }
        let line = raw.trim_end_matches('\r');
        if line.trim().is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() != 5 {
            skipped.push(lineno);
            continue;
        }
        let s = parse_time(fields[2], false);
        let e = parse_time(fields[3], true);
        let (s, e) = match (s, e) {
            (Some(s), Some(e)) => (s, e),
            _ => {
                skipped.push(lineno);
                continue;
            }
        };
        if e <= s {
            skipped.push(lineno);
            continue;
        }
        let key = line.to_string();
        let mut dup = false;
        for k in seen.iter() {
            if *k == key {
                dup = true;
                break;
            }
        }
        if dup {
            continue;
        }
        seen.push(key);
        bookings.push((
            fields[0].to_string(),
            fields[1].to_string(),
            s,
            e,
            fields[4].to_string(),
        ));
    }

    // collect distinct (room, day) groups
    let mut groups: Vec<(Str, Str)> = Vec::new();
    for b in bookings.iter() {
        let g = (b.0.clone(), b.1.clone());
        let mut found = false;
        for x in groups.iter() {
            if *x == g {
                found = true;
                break;
            }
        }
        if !found {
            groups.push(g);
        }
    }
    groups.sort();

    let mut out = String::new();
    for g in groups.iter() {
        let mut ivs: Vec<(i64, i64)> = Vec::new();
        let mut items: Vec<(i64, i64, Str)> = Vec::new();
        for b in bookings.iter() {
            if b.0 == g.0 && b.1 == g.1 {
                ivs.push((b.2, b.3));
                items.push((b.2, b.3, b.4.clone()));
            }
        }
        ivs.sort();
        let mut merged: Vec<(i64, i64)> = Vec::new();
        for iv in ivs.iter() {
            let n = merged.len();
            if n > 0 && iv.0 <= merged[n - 1].1 {
                if iv.1 > merged[n - 1].1 {
                    merged[n - 1].1 = iv.1;
                }
            } else {
                merged.push((iv.0, iv.1));
            }
        }

        out.push_str(&format!("{} {}\n", g.0, g.1));

        let mut busy: Vec<Str> = Vec::new();
        for m in merged.iter() {
            busy.push(fmt_iv(m.0, m.1));
        }
        out.push_str(&format!("  busy {}\n", busy.join(", ")));

        let mut free: Vec<Str> = Vec::new();
        let mut cur: i64 = 540;
        for m in merged.iter() {
            if m.0 > cur {
                let gap_end = if m.0 < 1080 { m.0 } else { 1080 };
                if gap_end - cur >= 30 {
                    free.push(fmt_iv(cur, gap_end));
                }
            }
            if m.1 > cur {
                cur = m.1;
            }
            if cur >= 1080 {
                break;
            }
        }
        if cur < 1080 && 1080 - cur >= 30 {
            free.push(fmt_iv(cur, 1080));
        }
        if free.is_empty() {
            out.push_str("  free none\n");
        } else {
            out.push_str(&format!("  free {}\n", free.join(", ")));
        }

        let mut conflicts: Vec<(i64, Str)> = Vec::new();
        let n = items.len();
        let mut i = 0;
        while i < n {
            let mut j = i + 1;
            while j < n {
                let a = &items[i];
                let b = &items[j];
                let s = if a.0 > b.0 { a.0 } else { b.0 };
                let e = if a.1 < b.1 { a.1 } else { b.1 };
                if e - s >= 1 {
                    let (n1, n2) = if a.2 <= b.2 {
                        (a.2.clone(), b.2.clone())
                    } else {
                        (b.2.clone(), a.2.clone())
                    };
                    let t = format!("  conflict {}/{} {}", n1, n2, fmt_iv(s, e));
                    conflicts.push((s, t));
                }
                j += 1;
            }
            i += 1;
        }
        conflicts.sort();
        for c in conflicts.iter() {
            out.push_str(&c.1);
            out.push_str("\n");
        }
    }

    if skipped.is_empty() {
        out.push_str("skipped: none\n");
    } else {
        let mut parts: Vec<Str> = Vec::new();
        for s in skipped.iter() {
            parts.push(format!("{}", s));
        }
        out.push_str(&format!("skipped: {}\n", parts.join(", ")));
    }

    Ok(out)
}

fn parse_time(s: Str, allow_24: bool) -> Option<i64> {
    let b: Vec<char> = s.chars().collect();
    if b.len() != 5 {
        return None;
    }
    if b[2] != ':' {
        return None;
    }
    let idx = [0, 1, 3, 4];
    for k in 0..4 {
        let d = b[idx[k]];
        if d < '0' || d > '9' {
            return None;
        }
    }
    let h = ((b[0] as i64) - ('0' as i64)) * 10 + ((b[1] as i64) - ('0' as i64));
    let m = ((b[3] as i64) - ('0' as i64)) * 10 + ((b[4] as i64) - ('0' as i64));
    if h == 24 && m == 0 && allow_24 {
        return Some(1440);
    }
    if h > 23 || m > 59 {
        return None;
    }
    Some(h * 60 + m)
}

fn fmt_time(t: i64) -> Str {
    let h = t / 60;
    let m = t % 60;
    format!("{:02}:{:02}", h, m)
}

fn fmt_iv(a: i64, b: i64) -> Str {
    format!("{}-{}", fmt_time(a), fmt_time(b))
}

fn join(parts: Vec<Str>, sep: Str) -> Str {
    let mut out = String::new();
    let n = parts.len();
    let mut i = 0;
    while i < n {
        if i > 0 {
            out = format!("{}{}", out, sep.clone());
        }
        out = format!("{}{}", out, parts[i].clone());
        i += 1;
    }
    out
}

