fn parse_two(p: Str, limit: i64) -> Option<i64> {
    let mut v: i64 = 0;
    while v < limit {
        if format!("{:02}", v) == p {
            return Some(v);
        }
        v += 1;
    }
    None
}

fn parse_time(s: Str, allow_24: bool) -> Option<i64> {
    if allow_24 && s == "24:00".to_string() {
        return Some(1440);
    }
    let mut parts: Vec<Str> = Vec::new();
    for p in s.split(":") {
        parts.push(p.to_string());
    }
    if parts.len() != 2 {
        return None;
    }
    let h = match parse_two(parts[0].clone(), 24) {
        Some(h) => h,
        None => return None,
    };
    let m = match parse_two(parts[1].clone(), 60) {
        Some(m) => m,
        None => return None,
    };
    Some(h * 60 + m)
}

fn fmt_time(t: i64) -> Str {
    let h = t / 60;
    let m = t % 60;
    format!("{:02}:{:02}", h, m)
}

fn fmt_iv(a: i64, b: i64) -> Str {
    format!("{}-{}", fmt_time(a), fmt_time(b))
}

fn join(parts: Vec<Str>, sep: Str) -> Str {
    let mut out = String::new();
    let n = parts.len();
    let mut i = 0;
    while i < n {
        if i > 0 {
            out = format!("{}{}", out, sep.clone());
        }
        out = format!("{}{}", out, parts[i].clone());
        i += 1;
    }
    out
}

