        let mut merged: Vec<(i64, i64)> = Vec::new();
        let mut k = 0;
        while k < ivs.len() {
            let a = ivs[k].0;
            let b = ivs[k].1;
            let n = merged.len();
            if n > 0 && a <= merged[n - 1].1 {
                if b > merged[n - 1].1 {
                    merged[n - 1].1 = b;
                }
            } else {
                merged.push((a, b));
            }
            k += 1;
        }

        out = format!("{}{} {}\n", out, groom, gday);

        let mut busy: Vec<Str> = Vec::new();
        let mut k = 0;
        while k < merged.len() {
            busy.push(fmt_iv(merged[k].0, merged[k].1));
            k += 1;
        }
        out = format!("{}  busy {}\n", out, join(busy, ", ".to_string()));

        let mut free: Vec<Str> = Vec::new();
        let mut cur: i64 = 540;
        let mut k = 0;
        while k < merged.len() {
            let ms = merged[k].0;
            let me = merged[k].1;
            if ms > cur {
                let gap_end = if ms < 1080 { ms } else { 1080 };
                if gap_end - cur >= 30 {
                    free.push(fmt_iv(cur, gap_end));
                }
            }
            if me > cur {
                cur = me;
            }
            if cur >= 1080 {
                break;
            }
            k += 1;
        }
        if cur < 1080 && 1080 - cur >= 30 {
            free.push(fmt_iv(cur, 1080));
        }
        if free.is_empty() {
            out = format!("{}  free none\n", out);
        } else {
            out = format!("{}  free {}\n", out, join(free, ", ".to_string()));
        }

        let mut conflicts: Vec<(i64, Str)> = Vec::new();
        let n = items.len();
        let mut i = 0;
        while i < n {
            let mut j = i + 1;
            while j < n {
                let a0 = items[i].0;
                let a1 = items[i].1;
                let b0 = items[j].0;
                let b1 = items[j].1;
                let s = if a0 > b0 { a0 } else { b0 };
                let e = if a1 < b1 { a1 } else { b1 };
                if e - s >= 1 {
                    let an = items[i].2.clone();
                    let bn = items[j].2.clone();
                    let (n1, n2) = if an <= bn { (an, bn) } else { (bn, an) };
                    let t = format!("  conflict {}/{} {}", n1, n2, fmt_iv(s, e));
                    conflicts.push((s, t));
                }
                j += 1;
            }
            i += 1;
        }
        conflicts.sort();
        let mut k = 0;
        while k < conflicts.len() {
            out = format!("{}{}\n", out, conflicts[k].1.clone());
            k += 1;
        }
        gi += 1;
    }

    if skipped.is_empty() {
        out = format!("{}skipped: none\n", out);
    } else {
        let mut parts: Vec<Str> = Vec::new();
        let mut k = 0;
        while k < skipped.len() {
            parts.push(format!("{}", skipped[k]));
            k += 1;
        }
        out = format!("{}skipped: {}\n", out, join(parts, ", ".to_string()));
    }

    Ok(out)
}

fn pad2(v: i64) -> Str {
    if v < 10 {
        "0" + v.to_str()
    } else {
        v.to_str()
    }
}

fn parse_two(p: Str, limit: i64) -> Option<i64> {
    let mut v: i64 = 0;
    while v < limit {
        if pad2(v) == p {
            return Some(v);
        }
        v += 1;
    }
    None
}

fn parse_time(s: Str, allow_24: bool) -> Option<i64> {
    if allow_24 && s == "24:00" {
        return Some(1440);
    }
    let mut parts: Vec<Str> = Vec::new();
    for p in s.split(":") {
        parts.push(p.to_str());
    }
    if parts.len() != 2 {
        return None;
    }
    let h = match parse_two(parts[0].clone(), 24) {
        Some(h) => h,
        None => return None,
    };
    let m = match parse_two(parts[1].clone(), 60) {
        Some(m) => m,
        None => return None,
    };
    Some(h * 60 + m)
}

fn fmt_time(t: i64) -> Str {
    let h = t / 60;
    let m = t % 60;
    pad2(h) + ":" + pad2(m)
}

fn fmt_iv(a: i64, b: i64) -> Str {
    fmt_time(a) + "-" + fmt_time(b)
}

fn join(parts: Vec<Str>, sep: Str) -> Str {
    let mut out: Str = "";
    let n = parts.len();
    let mut i = 0;
    while i < n {
        if i > 0 {
            out = out + sep.clone();
        }
        out = out + parts[i].clone();
        i += 1;
    }
    out
}

