        broom.push(fields[0].clone());
        bday.push(fields[1].clone());
        bs.push(s);
        be.push(e);
        bwho.push(fields[4].clone());
    }

    let mut gr: Vec<Str> = Vec::new();
    let mut gd: Vec<Str> = Vec::new();
