        } else {
            out = out + "  free " + join(free, ", ") + "\n";
        }

        let mut cs: Vec<i64> = Vec::new();
        let mut ct: Vec<Str> = Vec::new();
        let n = ia.len();
        let mut i = 0;
        while i < n {
            let mut j = i + 1;
            while j < n {
                let s = if ia[i] > ia[j] { ia[i] } else { ia[j] };
                let e = if ib[i] < ib[j] { ib[i] } else { ib[j] };
                if e - s >= 1 {
                    let an = iw[i].clone();
                    let bn = iw[j].clone();
                    let mut n1 = an.clone();
                    let mut n2 = bn.clone();
                    if bn < an {
                        n1 = bn.clone();
                        n2 = an.clone();
                    }
                    let t = "  conflict " + n1 + "/" + n2 + " " + fmt_iv(s, e);
                    cs.push(s);
                    ct.push(t);
                }
                j += 1;
            }
            i += 1;
        }
        let mut i = 1;
        while i < cs.len() {
            let mut j = i;
