enum Json {
    Null,
    Bool(bool),
    Num(f64, bool),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

fn peek(p: &Parser) -> Option<char> {
    if p.pos < p.chars.len() {
        Some(p.chars[p.pos])
    } else {
        None
    }
}

fn skip_ws(p: &mut Parser) {
    while p.pos < p.chars.len() {
        let c = p.chars[p.pos];
        if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
            p.pos += 1;
        } else {
            break;
        }
    }
}

fn expect_word(p: &mut Parser, w: Str) -> bool {
    let wc: Vec<char> = w.chars().collect();
    let mut i = 0;
    while i < wc.len() {
        if p.pos + i >= p.chars.len() || p.chars[p.pos + i] != wc[i] {
            return false;
        }
        i += 1;
    }
    p.pos += wc.len();
    true
}

fn is_digit(c: char) -> bool {
    c >= '0' && c <= '9'
}

fn hex_val(c: char) -> Option<u32> {
    if c >= '0' && c <= '9' {
        Some((c as u32) - ('0' as u32))
    } else if c >= 'a' && c <= 'f' {
        Some((c as u32) - ('a' as u32) + 10)
    } else if c >= 'A' && c <= 'F' {
        Some((c as u32) - ('A' as u32) + 10)
    } else {
        None
    }
}

fn read_hex4(p: &mut Parser) -> Option<u32> {
    if p.pos + 4 > p.chars.len() {
        return None;
    }
    let mut v: u32 = 0;
    let mut i = 0;
    while i < 4 {
        match hex_val(p.chars[p.pos + i]) {
            Some(h) => {
                v = v * 16 + h;
            }
            None => {
                return None;
            }
        }
        i += 1;
    }
    p.pos += 4;
    Some(v)
}

fn parse_string(p: &mut Parser) -> Option<Str> {
    // assumes current char is '"'
    p.pos += 1;
    let mut out = Str::new();
    loop {
        if p.pos >= p.chars.len() {
            return None;
        }
        let c = p.chars[p.pos];
        p.pos += 1;
        if c == '"' {
            return Some(out);
        }
        if (c as u32) < 0x20 {
            return None;
        }
        if c == '\\' {
            if p.pos >= p.chars.len() {
                return None;
            }
            let e = p.chars[p.pos];
            p.pos += 1;
            if e == '"' {
                out.push('"');
            } else if e == '\\' {
                out.push('\\');
            } else if e == '/' {
                out.push('/');
            } else if e == 'b' {
                out.push('\u{8}');
            } else if e == 'f' {
                out.push('\u{c}');
            } else if e == 'n' {
                out.push('\n');
            } else if e == 'r' {
                out.push('\r');
            } else if e == 't' {
                out.push('\t');
            } else if e == 'u' {
                let v = match read_hex4(p) {
                    Some(v) => v,
                    None => {
                        return None;
                    }
                };
                if v >= 0xD800 && v < 0xDC00 {
                    let save = p.pos;
                    let mut done = false;
                    if p.pos + 1 < p.chars.len() && p.chars[p.pos] == '\\' && p.chars[p.pos + 1] == 'u' {
                        p.pos += 2;
                        match read_hex4(p) {
                            Some(lo) => {
                                if lo >= 0xDC00 && lo < 0xE000 {
                                    let cp = 0x10000 + ((v - 0xD800) << 10) + (lo - 0xDC00);
                                    match char::from_u32(cp) {
                                        Some(ch) => out.push(ch),
                                        None => out.push('\u{FFFD}'),
                                    }
                                    done = true;
                                }
                            }
                            None => {}
                        }
                    }
                    if !done {
                        p.pos = save;
                        out.push('\u{FFFD}');
                    }
                } else {
                    match char::from_u32(v) {
                        Some(ch) => out.push(ch),
                        None => out.push('\u{FFFD}'),
                    }
                }
            } else {
                return None;
            }
        } else {
            out.push(c);
        }
    }
}

fn parse_number(p: &mut Parser) -> Option<Json> {
    let start = p.pos;
    let mut is_int = true;
    if peek(p) == Some('-') {
        p.pos += 1;
    }
    match peek(p) {
        Some(c) => {
            if c == '0' {
                p.pos += 1;
            } else if is_digit(c) {
                while p.pos < p.chars.len() && is_digit(p.chars[p.pos]) {
                    p.pos += 1;
                }
            } else {
                return None;
            }
        }
        None => {
            return None;
        }
    }
    if peek(p) == Some('.') {
        is_int = false;
        p.pos += 1;
        let ds = p.pos;
        while p.pos < p.chars.len() && is_digit(p.chars[p.pos]) {
            p.pos += 1;
        }
        if p.pos == ds {
            return None;
        }
    }
    if peek(p) == Some('e') || peek(p) == Some('E') {
        is_int = false;
        p.pos += 1;
        if peek(p) == Some('+') || peek(p) == Some('-') {
            p.pos += 1;
        }
        let ds = p.pos;
        while p.pos < p.chars.len() && is_digit(p.chars[p.pos]) {
            p.pos += 1;
        }
        if p.pos == ds {
            return None;
        }
    }
    let mut text = Str::new();
    let mut i = start;
    while i < p.pos {
        text.push(p.chars[i]);
        i += 1;
    }
    match text.parse::<f64>() {
        Ok(v) => Some(Json::Num(v, is_int)),
        Err(_) => None,
    }
}

fn parse_value(p: &mut Parser, depth: usize) -> Option<Json> {
    if depth > 500 {
        return None;
    }
    skip_ws(p);
    let c = match peek(p) {
        Some(c) => c,
        None => {
            return None;
        }
    };
    if c == '{' {
        p.pos += 1;
        let mut fields: Vec<(Str, Json)> = Vec::new();
        skip_ws(p);
        if peek(p) == Some('}') {
            p.pos += 1;
            return Some(Json::Obj(fields));
        }
        loop {
            skip_ws(p);
            if peek(p) != Some('"') {
                return None;
            }
            let key = match parse_string(p) {
                Some(k) => k,
                None => {
                    return None;
                }
            };
            skip_ws(p);
            if peek(p) != Some(':') {
                return None;
            }
            p.pos += 1;
            let v = match parse_value(p, depth + 1) {
                Some(v) => v,
                None => {
                    return None;
                }
            };
            // duplicate keys: last wins
            let mut idx = 0;
            let mut found = false;
            while idx < fields.len() {
                if fields[idx].0 == key {
                    found = true;
                    break;
                }
                idx += 1;
            }
            if found {
                fields.remove(idx);
            }
            fields.push((key, v));
            skip_ws(p);
            match peek(p) {
                Some(',') => {
                    p.pos += 1;
                }
                Some('}') => {
                    p.pos += 1;
                    return Some(Json::Obj(fields));
                }
                _ => {
                    return None;
                }
            }
        }
    } else if c == '[' {
        p.pos += 1;
        let mut items: Vec<Json> = Vec::new();
        skip_ws(p);
        if peek(p) == Some(']') {
            p.pos += 1;
            return Some(Json::Arr(items));
        }
        loop {
            let v = match parse_value(p, depth + 1) {
                Some(v) => v,
                None => {
                    return None;
                }
            };
            items.push(v);
            skip_ws(p);
            match peek(p) {
                Some(',') => {
                    p.pos += 1;
                }
                Some(']') => {
                    p.pos += 1;
                    return Some(Json::Arr(items));
                }
                _ => {
                    return None;
                }
            }
        }
    } else if c == '"' {
        match parse_string(p) {
            Some(s) => Some(Json::Text(s)),
            None => None,
        }
    } else if c == 't' {
        if expect_word(p, "true".to_string()) {
            Some(Json::Bool(true))
        } else {
            None
        }
    } else if c == 'f' {
        if expect_word(p, "false".to_string()) {
            Some(Json::Bool(false))
        } else {
            None
        }
    } else if c == 'n' {
        if expect_word(p, "null".to_string()) {
            Some(Json::Null)
        } else {
            None
        }
    } else if c == '-' || is_digit(c) {
        parse_number(p)
    } else {
        None
    }
}

fn parse_json(text: Str) -> Option<Json> {
    let mut p = Parser { chars: text.chars().collect(), pos: 0 };
    let v = match parse_value(&mut p, 0) {
        Some(v) => v,
        None => {
            return None;
        }
    };
    skip_ws(&mut p);
    if p.pos != p.chars.len() {
        return None;
    }
    Some(v)
}

fn get(obj: &Json, key: Str) -> Option<&Json> {
    match obj {
        Json::Obj(fields) => {
            let mut i = 0;
            while i < fields.len() {
                if fields[i].0 == key {
                    return Some(&fields[i].1);
                }
                i += 1;
            }
            None
        }
        _ => None,
    }
}

fn get_str(obj: &Json, key: Str) -> Option<Str> {
    match get(obj, key) {
        Some(Json::Text(s)) => Some(s.clone()),
        _ => None,
    }
}

fn get_int(obj: &Json, key: Str) -> Option<i64> {
    match get(obj, key) {
        Some(Json::Num(v, _)) => Some(*v as i64),
        _ => None,
    }
}

fn add_err(errs: &mut Vec<(Str, Str)>, path: &Str, msg: Str) {
    errs.push((path.clone(), msg));
}

fn check_bounds(schema: &Json, v: f64, path: &Str, errs: &mut Vec<(Str, Str)>) {
    match get_int(schema, "minimum".to_string()) {
        Some(n) => {
            if v < (n as f64) {
                add_err(errs, path, format!("less than {}", n));
                return;
            }
        }
        None => {}
    }
    match get_int(schema, "maximum".to_string()) {
        Some(n) => {
            if v > (n as f64) {
                add_err(errs, path, format!("greater than {}", n));
            }
        }
        None => {}
    }
}

fn validate(schema: &Json, value: &Json, path: Str, errs: &mut Vec<(Str, Str)>) {
    let ty = match get_str(schema, "type".to_string()) {
        Some(t) => t,
        None => {
            return;
        }
    };
    if ty == "object" {
        match value {
            Json::Obj(fields) => {
                let props = get(schema, "properties".to_string());
                match get(schema, "required".to_string()) {
                    Some(Json::Arr(req)) => {
                        let mut i = 0;
                        while i < req.len() {
                            match &req[i] {
                                Json::Text(name) => {
                                    if get(value, name.clone()).is_none() {
                                        let mut fp = path.clone();
                                        fp.push('.');
                                        fp.push_str(name);
                                        add_err(errs, &fp, "missing required field".to_string());
                                    }
                                }
                                _ => {}
                            }
                            i += 1;
                        }
                    }
                    _ => {}
                }
                let mut no_additional = false;
                match get(schema, "additional".to_string()) {
                    Some(Json::Bool(false)) => {
                        no_additional = true;
                    }
                    _ => {}
                }
                let mut i = 0;
                while i < fields.len() {
                    let name = fields[i].0.clone();
                    let mut fp = path.clone();
                    fp.push('.');
                    fp.push_str(&name);
                    let sub = match props {
                        Some(pr) => get(pr, name.clone()),
                        None => None,
                    };
                    match sub {
                        Some(s) => {
                            validate(s, &fields[i].1, fp, errs);
                        }
                        None => {
                            if no_additional {
                                add_err(errs, &fp, "unexpected field".to_string());
                            }
                        }
                    }
                    i += 1;
                }
            }
            _ => {
                add_err(errs, &path, "expected object".to_string());
            }
        }
    } else if ty == "array" {
        match value {
            Json::Arr(items) => {
                match get_int(schema, "min_items".to_string()) {
                    Some(n) => {
                        if (items.len() as i64) < n {
                            add_err(errs, &path, format!("fewer than {} items", n));
                        }
                    }
                    None => {}
                }
                match get(schema, "items".to_string()) {
                    Some(sub) => {
                        let mut i = 0;
                        while i < items.len() {
                            let ip = format!("{}[{}]", path, i);
                            validate(sub, &items[i], ip, errs);
                            i += 1;
                        }
                    }
                    None => {}
                }
            }
            _ => {
                add_err(errs, &path, "expected array".to_string());
            }
        }
    } else if ty == "string" {
        match value {
            Json::Text(s) => {
                let len = s.chars().count() as i64;
                match get_int(schema, "min_length".to_string()) {
                    Some(n) => {
                        if len < n {
                            add_err(errs, &path, format!("shorter than {}", n));
                            return;
                        }
                    }
                    None => {}
                }
                match get_int(schema, "max_length".to_string()) {
                    Some(n) => {
                        if len > n {
                            add_err(errs, &path, format!("longer than {}", n));
                            return;
                        }
                    }
                    None => {}
                }
                match get(schema, "enum".to_string()) {
                    Some(Json::Arr(opts)) => {
                        let mut ok = false;
                        let mut i = 0;
                        while i < opts.len() {
                            match &opts[i] {
                                Json::Text(o) => {
                                    if o == s {
                                        ok = true;
                                    }
                                }
                                _ => {}
                            }
                            i += 1;
                        }
                        if !ok {
                            add_err(errs, &path, "not in enum".to_string());
                        }
                    }
                    _ => {}
                }
            }
            _ => {
                add_err(errs, &path, "expected string".to_string());
            }
        }
    } else if ty == "integer" {
        match value {
            Json::Num(v, true) => {
                check_bounds(schema, *v, &path, errs);
            }
            _ => {
                add_err(errs, &path, "expected integer".to_string());
            }
        }
    } else if ty == "number" {
        match value {
            Json::Num(v, _) => {
                check_bounds(schema, *v, &path, errs);
            }
            _ => {
                add_err(errs, &path, "expected number".to_string());
            }
        }
    } else if ty == "boolean" {
        match value {
            Json::Bool(_) => {}
            _ => {
                add_err(errs, &path, "expected boolean".to_string());
            }
        }
    } else if ty == "null" {
        match value {
            Json::Null => {}
            _ => {
                add_err(errs, &path, "expected null".to_string());
            }
        }
    }
}

fn less(a: &(Str, Str), b: &(Str, Str)) -> bool {
    if a.0 < b.0 {
        true
    } else if a.0 == b.0 {
        a.1 < b.1
    } else {
        false
    }
}

fn sort_errs(errs: &mut Vec<(Str, Str)>) {
    let mut i = 1;
    while i < errs.len() {
        let mut j = i;
        while j > 0 && less(&errs[j], &errs[j - 1]) {
            errs.swap(j, j - 1);
            j -= 1;
        }
        i += 1;
    }
}

fn main(input: Dir) -> Result<Str, Str> {
    let schema_text = match input.read("schema.json") {
        Ok(t) => t,
        Err(_) => {
            return Err("cannot read schema.json".to_string());
        }
    };
    let records_text = match input.read("records.jsonl") {
        Ok(t) => t,
        Err(_) => {
            return Err("cannot read records.jsonl".to_string());
        }
    };
    let schema = match parse_json(schema_text) {
        Some(s) => s,
        None => {
            return Err("invalid schema".to_string());
        }
    };
    let mut out = Str::new();
    let mut valid = 0;
    let mut total = 0;
    let mut line_no = 0;
    for raw in records_text.split('\n') {
        line_no += 1;
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        total += 1;
        match parse_json(line.to_string()) {
            None => {
                out.push_str(&format!("line {}: invalid JSON\n", line_no));
            }
            Some(v) => {
                let mut errs: Vec<(Str, Str)> = Vec::new();
                validate(&schema, &v, "$".to_string(), &mut errs);
                if errs.is_empty() {
                    valid += 1;
                    out.push_str(&format!("line {}: ok\n", line_no));
                } else {
                    sort_errs(&mut errs);
                    let mut i = 0;
                    while i < errs.len() {
                        out.push_str(&format!("line {}: {}: {}\n", line_no, errs[i].0, errs[i].1));
                        i += 1;
                    }
                }
            }
        }
    }
    out.push_str(&format!("valid {} of {}", valid, total));
    Ok(out)
}

enum Json {
    Null,
    Bool(bool),
    Num(f64, bool),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

fn skip_ws(p: Parser) -> Parser {
    let mut p = p;
    while p.pos < p.chars.len() {
        let c = p.chars[p.pos];
        if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
            p.pos += 1;
        } else {
            break;
        }
    }
    p
}

fn expect_word(p: Parser, w: Str) -> (Parser, bool) {
    let mut p = p;
    let wc: Vec<char> = w.chars().collect();
    let mut i = 0;
    while i < wc.len() {
        if p.pos + i >= p.chars.len() || p.chars[p.pos + i] != wc[i] {
            return (p, false);
        }
        i += 1;
    }
    p.pos += wc.len();
    (p, true)
}

fn is_digit(c: char) -> bool {
    c >= '0' && c <= '9'
}

fn hex_val(c: char) -> Option<u32> {
    if c >= '0' && c <= '9' {
        Some((c as u32) - ('0' as u32))
    } else if c >= 'a' && c <= 'f' {
        Some((c as u32) - ('a' as u32) + 10)
    } else if c >= 'A' && c <= 'F' {
        Some((c as u32) - ('A' as u32) + 10)
    } else {
        None
    }
}

fn read_hex4(p: Parser) -> (Parser, Option<u32>) {
    let mut p = p;
    if p.pos + 4 > p.chars.len() {
        return (p, None);
    }
    let mut v: u32 = 0;
    let mut i = 0;
    while i < 4 {
        match hex_val(p.chars[p.pos + i]) {
            Some(h) => {
                v = v * 16 + h;
            }
            None => {
                return (p, None);
            }
        }
        i += 1;
    }
    p.pos += 4;
    (p, Some(v))
}

fn parse_string(p: Parser) -> (Parser, Option<Str>) {
    let mut p = p;
    p.pos += 1;
    let mut out = Str::new();
    loop {
        if p.pos >= p.chars.len() {
            return (p, None);
        }
        let c = p.chars[p.pos];
        p.pos += 1;
        if c == '"' {
            return (p, Some(out));
        }
        if (c as u32) < 0x20 {
            return (p, None);
        }
        if c == '\\' {
            if p.pos >= p.chars.len() {
                return (p, None);
            }
            let e = p.chars[p.pos];
            p.pos += 1;
            if e == '"' {
                out.push('"');
            } else if e == '\\' {
                out.push('\\');
            } else if e == '/' {
                out.push('/');
            } else if e == 'b' {
                out.push('\u{8}');
            } else if e == 'f' {
                out.push('\u{c}');
            } else if e == 'n' {
                out.push('\n');
            } else if e == 'r' {
                out.push('\r');
            } else if e == 't' {
                out.push('\t');
            } else if e == 'u' {
                let (q, hv) = read_hex4(p);
                p = q;
                let v = match hv {
                    Some(v) => v,
                    None => {
                        return (p, None);
                    }
                };
                if v >= 0xD800 && v < 0xDC00 {
                    let save = p.pos;
                    let mut done = false;
                    if p.pos + 1 < p.chars.len() && p.chars[p.pos] == '\\' && p.chars[p.pos + 1] == 'u' {
                        p.pos += 2;
                        let (q2, lv) = read_hex4(p);
                        p = q2;
                        match lv {
                            Some(lo) => {
                                if lo >= 0xDC00 && lo < 0xE000 {
                                    let cp = 0x10000 + ((v - 0xD800) << 10) + (lo - 0xDC00);
                                    match char::from_u32(cp) {
                                        Some(ch) => out.push(ch),
                                        None => out.push('\u{FFFD}'),
                                    }
                                    done = true;
                                }
                            }
                            None => {}
                        }
                    }
                    if !done {
                        p.pos = save;
                        out.push('\u{FFFD}');
                    }
                } else {
                    match char::from_u32(v) {
                        Some(ch) => out.push(ch),
                        None => out.push('\u{FFFD}'),
                    }
                }
            } else {
                return (p, None);
            }
        } else {
            out.push(c);
        }
    }
}

fn parse_number(p: Parser) -> (Parser, Option<Json>) {
    let mut p = p;
    let start = p.pos;
    let mut is_int = true;
    if p.pos < p.chars.len() && p.chars[p.pos] == '-' {
        p.pos += 1;
    }
    if p.pos >= p.chars.len() {
        return (p, None);
    }
    let c = p.chars[p.pos];
    if c == '0' {
        p.pos += 1;
    } else if is_digit(c) {
        while p.pos < p.chars.len() && is_digit(p.chars[p.pos]) {
            p.pos += 1;
        }
    } else {
        return (p, None);
    }
    if p.pos < p.chars.len() && p.chars[p.pos] == '.' {
        is_int = false;
        p.pos += 1;
        let ds = p.pos;
        while p.pos < p.chars.len() && is_digit(p.chars[p.pos]) {
            p.pos += 1;
        }
        if p.pos == ds {
            return (p, None);
        }
    }
    if p.pos < p.chars.len() && (p.chars[p.pos] == 'e' || p.chars[p.pos] == 'E') {
        is_int = false;
        p.pos += 1;
        if p.pos < p.chars.len() && (p.chars[p.pos] == '+' || p.chars[p.pos] == '-') {
            p.pos += 1;
        }
        let ds = p.pos;
        while p.pos < p.chars.len() && is_digit(p.chars[p.pos]) {
            p.pos += 1;
        }
        if p.pos == ds {
            return (p, None);
        }
    }
    let mut text = Str::new();
    let mut i = start;
    while i < p.pos {
        text.push(p.chars[i]);
        i += 1;
    }
    match text.parse::<f64>() {
        Ok(v) => (p, Some(Json::Num(v, is_int))),
        Err(_) => (p, None),
    }
}

fn parse_value(p: Parser, depth: usize) -> (Parser, Option<Json>) {
    let mut p = p;
    if depth > 500 {
        return (p, None);
    }
    p = skip_ws(p);
    if p.pos >= p.chars.len() {
        return (p, None);
    }
    let c = p.chars[p.pos];
    if c == '{' {
        p.pos += 1;
        let mut fields: Vec<(Str, Json)> = Vec::new();
        p = skip_ws(p);
        if p.pos < p.chars.len() && p.chars[p.pos] == '}' {
            p.pos += 1;
            return (p, Some(Json::Obj(fields)));
        }
        loop {
            p = skip_ws(p);
            if !(p.pos < p.chars.len() && p.chars[p.pos] == '"') {
                return (p, None);
            }
            let (q, kr) = parse_string(p);
            p = q;
            let key = match kr {
                Some(k) => k,
                None => {
                    return (p, None);
                }
            };
            p = skip_ws(p);
            if !(p.pos < p.chars.len() && p.chars[p.pos] == ':') {
                return (p, None);
            }
            p.pos += 1;
            let (q2, vr) = parse_value(p, depth + 1);
            p = q2;
            let v = match vr {
                Some(v) => v,
                None => {
                    return (p, None);
                }
            };
            let mut idx = 0;
            let mut found = false;
            while idx < fields.len() {
                if fields[idx].0 == key {
                    found = true;
                    break;
                }
                idx += 1;
            }
            if found {
                fields.remove(idx);
            }
            fields.push((key, v));
            p = skip_ws(p);
            if p.pos >= p.chars.len() {
                return (p, None);
            }
            let d = p.chars[p.pos];
            if d == ',' {
                p.pos += 1;
            } else if d == '}' {
                p.pos += 1;
                return (p, Some(Json::Obj(fields)));
            } else {
                return (p, None);
            }
        }
    } else if c == '[' {
        p.pos += 1;
        let mut items: Vec<Json> = Vec::new();
        p = skip_ws(p);
        if p.pos < p.chars.len() && p.chars[p.pos] == ']' {
            p.pos += 1;
            return (p, Some(Json::Arr(items)));
        }
        loop {
            let (q, vr) = parse_value(p, depth + 1);
            p = q;
            let v = match vr {
                Some(v) => v,
                None => {
                    return (p, None);
                }
            };
            items.push(v);
            p = skip_ws(p);
            if p.pos >= p.chars.len() {
                return (p, None);
            }
            let d = p.chars[p.pos];
            if d == ',' {
                p.pos += 1;
            } else if d == ']' {
                p.pos += 1;
                return (p, Some(Json::Arr(items)));
            } else {
                return (p, None);
            }
        }
    } else if c == '"' {
        let (q, sr) = parse_string(p);
        match sr {
            Some(s) => (q, Some(Json::Text(s))),
            None => (q, None),
        }
    } else if c == 't' {
        let (q, ok) = expect_word(p, "true".to_string());
        if ok {
            (q, Some(Json::Bool(true)))
        } else {
            (q, None)
        }
    } else if c == 'f' {
        let (q, ok) = expect_word(p, "false".to_string());
        if ok {
            (q, Some(Json::Bool(false)))
        } else {
            (q, None)
        }
    } else if c == 'n' {
        let (q, ok) = expect_word(p, "null".to_string());
        if ok {
            (q, Some(Json::Null))
        } else {
            (q, None)
        }
    } else if c == '-' || is_digit(c) {
        parse_number(p)
    } else {
        (p, None)
    }
}

fn parse_json(text: Str) -> Option<Json> {
    let p = Parser { chars: text.chars().collect(), pos: 0 };
    let (q, vr) = parse_value(p, 0);
    let v = match vr {
        Some(v) => v,
        None => {
            return None;
        }
    };
    let q = skip_ws(q);
    if q.pos != q.chars.len() {
        return None;
    }
    Some(v)
}

fn get(obj: Json, key: Str) -> Option<Json> {
    match obj {
        Json::Obj(fields) => {
            let mut i = 0;
            while i < fields.len() {
                if fields[i].0 == key {
                    return Some(fields[i].1.clone());
                }
                i += 1;
            }
            None
        }
        _ => None,
    }
}

fn has_key(fields: Vec<(Str, Json)>, key: Str) -> bool {
    let mut i = 0;
    while i < fields.len() {
        if fields[i].0 == key {
            return true;
        }
        i += 1;
    }
    false
}

fn get_str(obj: Json, key: Str) -> Option<Str> {
    match get(obj, key) {
        Some(Json::Text(s)) => Some(s),
        _ => None,
    }
}

fn get_int(obj: Json, key: Str) -> Option<i64> {
    match get(obj, key) {
        Some(Json::Num(v, _)) => Some(v as i64),
        _ => None,
    }
}

fn check_bounds(schema: Json, v: f64, path: Str, errs: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut errs = errs;
    match get_int(schema.clone(), "minimum".to_string()) {
        Some(n) => {
            if v < (n as f64) {
                errs.push((path.clone(), format!("less than {}", n)));
                return errs;
            }
        }
        None => {}
    }
    match get_int(schema.clone(), "maximum".to_string()) {
        Some(n) => {
            if v > (n as f64) {
                errs.push((path.clone(), format!("greater than {}", n)));
            }
        }
        None => {}
    }
    errs
}

fn validate(schema: Json, value: Json, path: Str, errs: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut errs = errs;
    let ty = match get_str(schema.clone(), "type".to_string()) {
        Some(t) => t,
        None => {
            return errs;
        }
    };
    if ty == "object".to_string() {
        match value {
            Json::Obj(fields) => {
                let props = get(schema.clone(), "properties".to_string());
                match get(schema.clone(), "required".to_string()) {
                    Some(Json::Arr(req)) => {
                        let mut i = 0;
                        while i < req.len() {
                            match req[i].clone() {
                                Json::Text(name) => {
                                    if !has_key(fields.clone(), name.clone()) {
                                        let mut fp = path.clone();
                                        fp.push('.');
                                        fp.push_str(name.clone());
                                        errs.push((fp, "missing required field".to_string()));
                                    }
                                }
                                _ => {}
                            }
                            i += 1;
                        }
                    }
                    _ => {}
                }
                let mut no_additional = false;
                match get(schema.clone(), "additional".to_string()) {
                    Some(Json::Bool(false)) => {
                        no_additional = true;
                    }
                    _ => {}
                }
                let mut i = 0;
                while i < fields.len() {
                    let name = fields[i].0.clone();
                    let mut fp = path.clone();
                    fp.push('.');
                    fp.push_str(name.clone());
                    let sub = match props.clone() {
                        Some(pr) => get(pr, name.clone()),
                        None => None,
                    };
                    match sub {
                        Some(s) => {
                            errs = validate(s, fields[i].1.clone(), fp, errs);
                        }
                        None => {
                            if no_additional {
                                errs.push((fp, "unexpected field".to_string()));
                            }
                        }
                    }
                    i += 1;
                }
            }
            _ => {
                errs.push((path.clone(), "expected object".to_string()));
            }
        }
    } else if ty == "array".to_string() {
        match value {
            Json::Arr(items) => {
                match get_int(schema.clone(), "min_items".to_string()) {
                    Some(n) => {
                        if (items.len() as i64) < n {
                            errs.push((path.clone(), format!("fewer than {} items", n)));
                        }
                    }
                    None => {}
                }
                match get(schema.clone(), "items".to_string()) {
                    Some(sub) => {
                        let mut i = 0;
                        while i < items.len() {
                            let ip = format!("{}[{}]", path, i);
                            errs = validate(sub.clone(), items[i].clone(), ip, errs);
                            i += 1;
                        }
                    }
                    None => {}
                }
            }
            _ => {
                errs.push((path.clone(), "expected array".to_string()));
            }
        }
    } else if ty == "string".to_string() {
        match value {
            Json::Text(s) => {
                let len = s.chars().count() as i64;
                match get_int(schema.clone(), "min_length".to_string()) {
                    Some(n) => {
                        if len < n {
                            errs.push((path.clone(), format!("shorter than {}", n)));
                            return errs;
                        }
                    }
                    None => {}
                }
                match get_int(schema.clone(), "max_length".to_string()) {
                    Some(n) => {
                        if len > n {
                            errs.push((path.clone(), format!("longer than {}", n)));
                            return errs;
                        }
                    }
                    None => {}
                }
                match get(schema.clone(), "enum".to_string()) {
                    Some(Json::Arr(opts)) => {
                        let mut ok = false;
                        let mut i = 0;
                        while i < opts.len() {
                            match opts[i].clone() {
                                Json::Text(o) => {
                                    if o == s {
                                        ok = true;
                                    }
                                }
                                _ => {}
                            }
                            i += 1;
                        }
                        if !ok {
                            errs.push((path.clone(), "not in enum".to_string()));
                        }
                    }
                    _ => {}
                }
            }
            _ => {
                errs.push((path.clone(), "expected string".to_string()));
            }
        }
    } else if ty == "integer".to_string() {
        match value {
            Json::Num(v, true) => {
                errs = check_bounds(schema.clone(), v, path.clone(), errs);
            }
            _ => {
                errs.push((path.clone(), "expected integer".to_string()));
            }
        }
    } else if ty == "number".to_string() {
        match value {
            Json::Num(v, _) => {
                errs = check_bounds(schema.clone(), v, path.clone(), errs);
            }
            _ => {
                errs.push((path.clone(), "expected number".to_string()));
            }
        }
    } else if ty == "boolean".to_string() {
        match value {
            Json::Bool(_) => {}
            _ => {
                errs.push((path.clone(), "expected boolean".to_string()));
            }
        }
    } else if ty == "null".to_string() {
        match value {
            Json::Null => {}
            _ => {
                errs.push((path.clone(), "expected null".to_string()));
            }
        }
    }
    errs
}

fn less(a: (Str, Str), b: (Str, Str)) -> bool {
    if a.0 < b.0 {
        true
    } else if a.0 == b.0 {
        a.1 < b.1
    } else {
        false
    }
}

fn sort_errs(errs: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut errs = errs;
    let mut i = 1;
    while i < errs.len() {
        let mut j = i;
        while j > 0 && less(errs[j].clone(), errs[j - 1].clone()) {
            errs.swap(j, j - 1);
            j -= 1;
        }
        i += 1;
    }
    errs
}

fn main(input: Dir) -> Result<Str, Str> {
    let schema_text = match input.read("schema.json") {
        Ok(t) => t,
        Err(_) => {
            return Err("cannot read schema.json".to_string());
        }
    };
    let records_text = match input.read("records.jsonl") {
        Ok(t) => t,
        Err(_) => {
            return Err("cannot read records.jsonl".to_string());
        }
    };
    let schema = match parse_json(schema_text) {
        Some(s) => s,
        None => {
            return Err("invalid schema".to_string());
        }
    };
    let mut out = Str::new();
    let mut valid = 0;
    let mut total = 0;
    let mut line_no = 0;
    for raw in records_text.split('\n') {
        line_no += 1;
        let line = raw.trim().to_string();
        if line.is_empty() {
            continue;
        }
        total += 1;
        match parse_json(line) {
            None => {
                out.push_str(format!("line {}: invalid JSON\n", line_no));
            }
            Some(v) => {
                let errs0: Vec<(Str, Str)> = Vec::new();
                let errs = validate(schema.clone(), v, "$".to_string(), errs0);
                if errs.is_empty() {
                    valid += 1;
                    out.push_str(format!("line {}: ok\n", line_no));
                } else {
                    let errs = sort_errs(errs);
                    let mut i = 0;
                    while i < errs.len() {
                        out.push_str(format!("line {}: {}: {}\n", line_no, errs[i].0, errs[i].1));
                        i += 1;
                    }
                }
            }
        }
    }
    out.push_str(format!("valid {} of {}", valid, total));
    Ok(out)
}

enum Json {
    Null,
    Bool(bool),
    Num(f64, bool),
    Text(Str, i64),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct Parser {
    chars: Vec<Str>,
    pos: usize,
}

fn s(x: Str) -> Str {
    x.to_string()
}

fn at(p: Parser, i: usize) -> Str {
    if i < p.chars.len() {
        p.chars[i].clone()
    } else {
        "".to_string()
    }
}

fn skip_ws(p: Parser) -> Parser {
    let mut p = p;
    while p.pos < p.chars.len() {
        let c = p.chars[p.pos].clone();
        if c == s(" ") || c == s("\t") || c == s("\n") || c == s("\r") {
            p.pos += 1;
        } else {
            break;
        }
    }
    p
}

fn expect_word(p: Parser, w: Str) -> (Parser, bool) {
    let mut p = p;
    let wc: Vec<Str> = w.chars().collect();
    let mut i = 0;
    while i < wc.len() {
        if p.pos + i >= p.chars.len() || p.chars[p.pos + i].clone() != wc[i].clone() {
            return (p, false);
        }
        i += 1;
    }
    p.pos += wc.len();
    (p, true)
}

fn is_digit(c: Str) -> bool {
    c.len() == 1 && c >= s("0") && c <= s("9")
}

fn hex_val(c: Str) -> Option<u32> {
    let lower: Vec<Str> = s("0123456789abcdef").chars().collect();
    let upper: Vec<Str> = s("0123456789ABCDEF").chars().collect();
    let mut i = 0;
    while i < 16 {
        if lower[i].clone() == c || upper[i].clone() == c {
            return Some(i as u32);
        }
        i += 1;
    }
    None
}

fn read_hex4(p: Parser) -> (Parser, Option<u32>, Str) {
    let mut p = p;
    let mut raw = Str::new();
    if p.pos + 4 > p.chars.len() {
        return (p, None, raw);
    }
    let mut v: u32 = 0;
    let mut i = 0;
    while i < 4 {
        let c = p.chars[p.pos + i].clone();
        match hex_val(c.clone()) {
            Some(h) => {
                v = v * 16 + h;
                raw.push_str(c);
            }
            None => {
                return (p, None, raw);
            }
        }
        i += 1;
    }
    p.pos += 4;
    (p, Some(v), raw)
}

fn ascii_of(v: u32) -> Option<Str> {
    if v == 8 {
        return Some(s("\u{8}"));
    }
    if v == 9 {
        return Some(s("\t"));
    }
    if v == 10 {
        return Some(s("\n"));
    }
    if v == 12 {
        return Some(s("\u{c}"));
    }
    if v == 13 {
        return Some(s("\r"));
    }
    if v >= 32 && v < 127 {
        let table: Vec<Str> = s(" !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~").chars().collect();
        let idx = (v - 32) as usize;
        if idx < table.len() {
            return Some(table[idx].clone());
        }
    }
    None
}

fn parse_string(p: Parser) -> (Parser, Option<(Str, i64)>) {
    let mut p = p;
    p.pos += 1;
    let mut out = Str::new();
    let mut count: i64 = 0;
    loop {
        if p.pos >= p.chars.len() {
            return (p, None);
        }
        let c = p.chars[p.pos].clone();
        p.pos += 1;
        if c == s("\"") {
            return (p, Some((out, count)));
        }
        if c < s(" ") {
            return (p, None);
        }
        if c == s("\\") {
            if p.pos >= p.chars.len() {
                return (p, None);
            }
            let e = p.chars[p.pos].clone();
            p.pos += 1;
            if e == s("\"") {
                out.push_str(s("\""));
            } else if e == s("\\") {
                out.push_str(s("\\"));
            } else if e == s("/") {
                out.push_str(s("/"));
            } else if e == s("b") {
                out.push_str(s("\u{8}"));
            } else if e == s("f") {
                out.push_str(s("\u{c}"));
            } else if e == s("n") {
                out.push_str(s("\n"));
            } else if e == s("r") {
                out.push_str(s("\r"));
            } else if e == s("t") {
                out.push_str(s("\t"));
            } else if e == s("u") {
                let (q, hv, raw) = read_hex4(p);
                p = q;
                let v = match hv {
                    Some(v) => v,
                    None => {
                        return (p, None);
                    }
                };
                if v >= 0xD800 && v < 0xDC00 {
                    let mut token = s("\\u");
                    token.push_str(raw);
                    if at(p.clone(), p.pos) == s("\\") && at(p.clone(), p.pos + 1) == s("u") {
                        let save = p.pos;
                        p.pos += 2;
                        let (q2, lv, raw2) = read_hex4(p);
                        p = q2;
                        let mut ok = false;
                        match lv {
                            Some(lo) => {
                                if lo >= 0xDC00 && lo < 0xE000 {
                                    ok = true;
                                }
                            }
                            None => {}
                        }
                        if ok {
                            token.push_str(s("\\u"));
                            token.push_str(raw2);
                        } else {
                            p.pos = save;
                        }
                    }
                    out.push_str(token);
                } else {
                    match ascii_of(v) {
                        Some(ch) => out.push_str(ch),
                        None => {
                            let mut token = s("\\u");
                            token.push_str(raw);
                            out.push_str(token);
                        }
                    }
                }
            } else {
                return (p, None);
            }
        } else {
            out.push_str(c);
        }
        count += 1;
    }
}

fn parse_number(p: Parser) -> (Parser, Option<Json>) {
    let mut p = p;
    let start = p.pos;
    let mut is_int = true;
    if at(p.clone(), p.pos) == s("-") {
        p.pos += 1;
    }
    if p.pos >= p.chars.len() {
        return (p, None);
    }
    let c = p.chars[p.pos].clone();
    if c == s("0") {
        p.pos += 1;
    } else if is_digit(c) {
        while p.pos < p.chars.len() && is_digit(p.chars[p.pos].clone()) {
            p.pos += 1;
        }
    } else {
        return (p, None);
    }
    if at(p.clone(), p.pos) == s(".") {
        is_int = false;
        p.pos += 1;
        let ds = p.pos;
        while p.pos < p.chars.len() && is_digit(p.chars[p.pos].clone()) {
            p.pos += 1;
        }
        if p.pos == ds {
            return (p, None);
        }
    }
    let ec = at(p.clone(), p.pos);
    if ec == s("e") || ec == s("E") {
        is_int = false;
        p.pos += 1;
        let sc = at(p.clone(), p.pos);
        if sc == s("+") || sc == s("-") {
            p.pos += 1;
        }
        let ds = p.pos;
        while p.pos < p.chars.len() && is_digit(p.chars[p.pos].clone()) {
            p.pos += 1;
        }
        if p.pos == ds {
            return (p, None);
        }
    }
    let mut text = Str::new();
    let mut i = start;
    while i < p.pos {
        text.push_str(p.chars[i].clone());
        i += 1;
    }
    match text.parse::<f64>() {
        Ok(v) => (p, Some(Json::Num(v, is_int))),
        Err(_) => (p, None),
    }
}

fn parse_value(p: Parser, depth: usize) -> (Parser, Option<Json>) {
    let mut p = p;
    if depth > 500 {
        return (p, None);
    }
    p = skip_ws(p);
    if p.pos >= p.chars.len() {
        return (p, None);
    }
    let c = p.chars[p.pos].clone();
    if c == s("{") {
        p.pos += 1;
        let mut fields: Vec<(Str, Json)> = Vec::new();
        p = skip_ws(p);
        if at(p.clone(), p.pos) == s("}") {
            p.pos += 1;
            return (p, Some(Json::Obj(fields)));
        }
        loop {
            p = skip_ws(p);
            if at(p.clone(), p.pos) != s("\"") {
                return (p, None);
            }
            let (q, kr) = parse_string(p);
            p = q;
            let key = match kr {
                Some(k) => k.0,
                None => {
                    return (p, None);
                }
            };
            p = skip_ws(p);
            if at(p.clone(), p.pos) != s(":") {
                return (p, None);
            }
            p.pos += 1;
            let (q2, vr) = parse_value(p, depth + 1);
            p = q2;
            let v = match vr {
                Some(v) => v,
                None => {
                    return (p, None);
                }
            };
            let mut idx = 0;
            let mut found = false;
            while idx < fields.len() {
                if fields[idx].0 == key {
                    found = true;
                    break;
                }
                idx += 1;
            }
            if found {
                fields.remove(idx);
            }
            fields.push((key, v));
            p = skip_ws(p);
            if p.pos >= p.chars.len() {
                return (p, None);
            }
            let d = p.chars[p.pos].clone();
            if d == s(",") {
                p.pos += 1;
            } else if d == s("}") {
                p.pos += 1;
                return (p, Some(Json::Obj(fields)));
            } else {
                return (p, None);
            }
        }
    } else if c == s("[") {
        p.pos += 1;
        let mut items: Vec<Json> = Vec::new();
        p = skip_ws(p);
        if at(p.clone(), p.pos) == s("]") {
            p.pos += 1;
            return (p, Some(Json::Arr(items)));
        }
        loop {
            let (q, vr) = parse_value(p, depth + 1);
            p = q;
            let v = match vr {
                Some(v) => v,
                None => {
                    return (p, None);
                }
            };
            items.push(v);
            p = skip_ws(p);
            if p.pos >= p.chars.len() {
                return (p, None);
            }
            let d = p.chars[p.pos].clone();
            if d == s(",") {
                p.pos += 1;
            } else if d == s("]") {
                p.pos += 1;
                return (p, Some(Json::Arr(items)));
            } else {
                return (p, None);
            }
        }
    } else if c == s("\"") {
        let (q, sr) = parse_string(p);
        match sr {
            Some(t) => (q, Some(Json::Text(t.0, t.1))),
            None => (q, None),
        }
    } else if c == s("t") {
        let (q, ok) = expect_word(p, s("true"));
        if ok {
            (q, Some(Json::Bool(true)))
        } else {
            (q, None)
        }
    } else if c == s("f") {
        let (q, ok) = expect_word(p, s("false"));
        if ok {
            (q, Some(Json::Bool(false)))
        } else {
            (q, None)
        }
    } else if c == s("n") {
        let (q, ok) = expect_word(p, s("null"));
        if ok {
            (q, Some(Json::Null))
        } else {
            (q, None)
        }
    } else if c == s("-") || is_digit(c) {
        parse_number(p)
    } else {
        (p, None)
    }
}

fn parse_json(text: Str) -> Option<Json> {
    let p = Parser { chars: text.chars().collect(), pos: 0 };
    let (q, vr) = parse_value(p, 0);
    let v = match vr {
        Some(v) => v,
        None => {
            return None;
        }
    };
    let q = skip_ws(q);
    if q.pos != q.chars.len() {
        return None;
    }
    Some(v)
}

fn get(obj: Json, key: Str) -> Option<Json> {
    match obj {
        Json::Obj(fields) => {
            let mut i = 0;
            while i < fields.len() {
                if fields[i].0 == key {
                    return Some(fields[i].1.clone());
                }
                i += 1;
            }
            None
        }
        _ => None,
    }
}

fn has_key(fields: Vec<(Str, Json)>, key: Str) -> bool {
    let mut i = 0;
    while i < fields.len() {
        if fields[i].0 == key {
            return true;
        }
        i += 1;
    }
    false
}

fn get_str(obj: Json, key: Str) -> Option<Str> {
    match get(obj, key) {
        Some(Json::Text(t, _)) => Some(t),
        _ => None,
    }
}

fn get_int(obj: Json, key: Str) -> Option<i64> {
    match get(obj, key) {
        Some(Json::Num(v, _)) => Some(v as i64),
        _ => None,
    }
}

fn check_bounds(schema: Json, v: f64, path: Str, errs: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut errs = errs;
    match get_int(schema.clone(), s("minimum")) {
        Some(n) => {
            if v < (n as f64) {
                errs.push((path.clone(), format!("less than {}", n)));
                return errs;
            }
        }
        None => {}
    }
    match get_int(schema.clone(), s("maximum")) {
        Some(n) => {
            if v > (n as f64) {
                errs.push((path.clone(), format!("greater than {}", n)));
            }
        }
        None => {}
    }
    errs
}

fn field_path(path: Str, name: Str) -> Str {
    let mut fp = path;
    fp.push_str(s("."));
    fp.push_str(name);
    fp
}

fn validate(schema: Json, value: Json, path: Str, errs: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut errs = errs;
    let ty = match get_str(schema.clone(), s("type")) {
        Some(t) => t,
        None => {
            return errs;
        }
    };
    if ty == s("object") {
        match value {
            Json::Obj(fields) => {
                let props = get(schema.clone(), s("properties"));
                match get(schema.clone(), s("required")) {
                    Some(Json::Arr(req)) => {
                        let mut i = 0;
                        while i < req.len() {
                            match req[i].clone() {
                                Json::Text(name, _) => {
                                    if !has_key(fields.clone(), name.clone()) {
                                        errs.push((field_path(path.clone(), name.clone()), s("missing required field")));
                                    }
                                }
                                _ => {}
                            }
                            i += 1;
                        }
                    }
                    _ => {}
                }
                let mut no_additional = false;
                match get(schema.clone(), s("additional")) {
                    Some(Json::Bool(false)) => {
                        no_additional = true;
                    }
                    _ => {}
                }
                let mut i = 0;
                while i < fields.len() {
                    let name = fields[i].0.clone();
                    let fp = field_path(path.clone(), name.clone());
                    let sub = match props.clone() {
                        Some(pr) => get(pr, name.clone()),
                        None => None,
                    };
                    match sub {
                        Some(sc) => {
                            errs = validate(sc, fields[i].1.clone(), fp, errs);
                        }
                        None => {
                            if no_additional {
                                errs.push((fp, s("unexpected field")));
                            }
                        }
                    }
                    i += 1;
                }
            }
            _ => {
                errs.push((path.clone(), s("expected object")));
            }
        }
    } else if ty == s("array") {
        match value {
            Json::Arr(items) => {
                match get_int(schema.clone(), s("min_items")) {
                    Some(n) => {
                        if (items.len() as i64) < n {
                            errs.push((path.clone(), format!("fewer than {} items", n)));
                        }
                    }
                    None => {}
                }
                match get(schema.clone(), s("items")) {
                    Some(sub) => {
                        let mut i = 0;
                        while i < items.len() {
                            let ip = format!("{}[{}]", path, i);
                            errs = validate(sub.clone(), items[i].clone(), ip, errs);
                            i += 1;
                        }
                    }
                    None => {}
                }
            }
            _ => {
                errs.push((path.clone(), s("expected array")));
            }
        }
    } else if ty == s("string") {
        match value {
            Json::Text(t, len) => {
                match get_int(schema.clone(), s("min_length")) {
                    Some(n) => {
                        if len < n {
                            errs.push((path.clone(), format!("shorter than {}", n)));
                            return errs;
                        }
                    }
                    None => {}
                }
                match get_int(schema.clone(), s("max_length")) {
                    Some(n) => {
                        if len > n {
                            errs.push((path.clone(), format!("longer than {}", n)));
                            return errs;
                        }
                    }
                    None => {}
                }
                match get(schema.clone(), s("enum")) {
                    Some(Json::Arr(opts)) => {
                        let mut ok = false;
                        let mut i = 0;
                        while i < opts.len() {
                            match opts[i].clone() {
                                Json::Text(o, _) => {
                                    if o == t {
                                        ok = true;
                                    }
                                }
                                _ => {}
                            }
                            i += 1;
                        }
                        if !ok {
                            errs.push((path.clone(), s("not in enum")));
                        }
                    }
                    _ => {}
                }
            }
            _ => {
                errs.push((path.clone(), s("expected string")));
            }
        }
    } else if ty == s("integer") {
        match value {
            Json::Num(v, true) => {
                errs = check_bounds(schema.clone(), v, path.clone(), errs);
            }
            _ => {
                errs.push((path.clone(), s("expected integer")));
            }
        }
    } else if ty == s("number") {
        match value {
            Json::Num(v, _) => {
                errs = check_bounds(schema.clone(), v, path.clone(), errs);
            }
            _ => {
                errs.push((path.clone(), s("expected number")));
            }
        }
    } else if ty == s("boolean") {
        match value {
            Json::Bool(_) => {}
            _ => {
                errs.push((path.clone(), s("expected boolean")));
            }
        }
    } else if ty == s("null") {
        match value {
            Json::Null => {}
            _ => {
                errs.push((path.clone(), s("expected null")));
            }
        }
    }
    errs
}

fn less(a: (Str, Str), b: (Str, Str)) -> bool {
    if a.0 < b.0 {
        true
    } else if a.0 == b.0 {
        a.1 < b.1
    } else {
        false
    }
}

fn sort_errs(errs: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut errs = errs;
    let mut i = 1;
    while i < errs.len() {
        let mut j = i;
        while j > 0 && less(errs[j].clone(), errs[j - 1].clone()) {
            errs.swap(j, j - 1);
            j -= 1;
        }
        i += 1;
    }
    errs
}

fn main(input: Dir) -> Result<Str, Str> {
    let schema_text = match input.read("schema.json") {
        Ok(t) => t,
        Err(_) => {
            return Err(s("cannot read schema.json"));
        }
    };
    let records_text = match input.read("records.jsonl") {
        Ok(t) => t,
        Err(_) => {
            return Err(s("cannot read records.jsonl"));
        }
    };
    let schema = match parse_json(schema_text) {
        Some(sc) => sc,
        None => {
            return Err(s("invalid schema"));
        }
    };
    let mut out = Str::new();
    let mut valid = 0;
    let mut total = 0;
    let mut line_no = 0;
    for raw in records_text.split("\n") {
        line_no += 1;
        let line = raw.trim().to_string();
        if line.is_empty() {
            continue;
        }
        total += 1;
        match parse_json(line) {
            None => {
                out.push_str(format!("line {}: invalid JSON\n", line_no));
            }
            Some(v) => {
                let errs0: Vec<(Str, Str)> = Vec::new();
                let errs = validate(schema.clone(), v, s("$"), errs0);
                if errs.is_empty() {
                    valid += 1;
                    out.push_str(format!("line {}: ok\n", line_no));
                } else {
                    let errs = sort_errs(errs);
                    let mut i = 0;
                    while i < errs.len() {
                        out.push_str(format!("line {}: {}: {}\n", line_no, errs[i].0, errs[i].1));
                        i += 1;
                    }
                }
            }
        }
    }
    out.push_str(format!("valid {} of {}", valid, total));
    Ok(out)
}

enum Json {
    Null,
    Bool(bool),
    Num(f64, bool),
    Text(Str, i64),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct Parser {
    chars: Vec<Str>,
    pos: usize,
}

fn s(x: Str) -> Str {
    x.to_string()
}

fn at(p: Parser, i: usize) -> Str {
    if i < p.chars.len() {
        p.chars[i].clone()
    } else {
        "".to_string()
    }
}

fn skip_ws(p: Parser) -> Parser {
    let mut p = p;
    while p.pos < p.chars.len() {
        let c = p.chars[p.pos].clone();
        if c == s(" ") || c == s("\t") || c == s("\n") || c == s("\r") {
            p.pos += 1;
        } else {
            break;
        }
    }
    p
}

fn expect_word(p: Parser, w: Str) -> (Parser, bool) {
    let mut p = p;
    let wc: Vec<Str> = w.chars().collect();
    let mut i = 0;
    while i < wc.len() {
        if p.pos + i >= p.chars.len() || p.chars[p.pos + i].clone() != wc[i].clone() {
            return (p, false);
        }
        i += 1;
    }
    p.pos += wc.len();
    (p, true)
}

fn is_digit(c: Str) -> bool {
    c.len() == 1 && c >= s("0") && c <= s("9")
}

fn hex_val(c: Str) -> Option<u32> {
    let lower: Vec<Str> = s("0123456789abcdef").chars().collect();
    let upper: Vec<Str> = s("0123456789ABCDEF").chars().collect();
    let mut i = 0;
    while i < 16 {
        if lower[i].clone() == c || upper[i].clone() == c {
            return Some(i as u32);
        }
        i += 1;
    }
    None
}

fn read_hex4(p: Parser) -> (Parser, Option<u32>, Str) {
    let mut p = p;
    let mut raw = Str::new();
    if p.pos + 4 > p.chars.len() {
        return (p, None, raw);
    }
    let lower: Vec<Str> = s("0123456789abcdef").chars().collect();
    let mut v: u32 = 0;
    let mut i = 0;
    while i < 4 {
        let c = p.chars[p.pos + i].clone();
        match hex_val(c.clone()) {
            Some(h) => {
                v = v * 16 + h;
                raw.push_str(lower[h as usize].clone());
            }
            None => {
                return (p, None, raw);
            }
        }
        i += 1;
    }
    p.pos += 4;
    (p, Some(v), raw)
}

fn ascii_of(v: u32) -> Option<Str> {
    if v == 8 {
        return Some(s("\\b"));
    }
    if v == 9 {
        return Some(s("\t"));
    }
    if v == 10 {
        return Some(s("\n"));
    }
    if v == 12 {
        return Some(s("\\f"));
    }
    if v == 13 {
        return Some(s("\r"));
    }
    if v == 92 {
        return Some(s("\\\\"));
    }
    if v >= 32 && v < 127 {
        let table: Vec<Str> = s(" !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~").chars().collect();
        let idx = (v - 32) as usize;
        if idx < table.len() {
            return Some(table[idx].clone());
        }
    }
    None
}

fn parse_string(p: Parser) -> (Parser, Option<(Str, i64)>) {
    let mut p = p;
    p.pos += 1;
    let mut out = Str::new();
    let mut count: i64 = 0;
    loop {
        if p.pos >= p.chars.len() {
            return (p, None);
        }
        let c = p.chars[p.pos].clone();
        p.pos += 1;
        if c == s("\"") {
            return (p, Some((out, count)));
        }
        if c < s(" ") {
            return (p, None);
        }
        if c == s("\\") {
            if p.pos >= p.chars.len() {
                return (p, None);
            }
            let e = p.chars[p.pos].clone();
            p.pos += 1;
            if e == s("\"") {
                out.push_str(s("\""));
            } else if e == s("\\") {
                out.push_str(s("\\\\"));
            } else if e == s("/") {
                out.push_str(s("/"));
            } else if e == s("b") {
                out.push_str(s("\\b"));
            } else if e == s("f") {
                out.push_str(s("\\f"));
            } else if e == s("n") {
                out.push_str(s("\n"));
            } else if e == s("r") {
                out.push_str(s("\r"));
            } else if e == s("t") {
                out.push_str(s("\t"));
            } else if e == s("u") {
                let (q, hv, raw) = read_hex4(p);
                p = q;
                let v = match hv {
                    Some(v) => v,
                    None => {
                        return (p, None);
                    }
                };
                if v >= 0xD800 && v < 0xDC00 {
                    let mut token = s("\\u");
                    token.push_str(raw);
                    if at(p.clone(), p.pos) == s("\\") && at(p.clone(), p.pos + 1) == s("u") {
                        let save = p.pos;
                        p.pos += 2;
                        let (q2, lv, raw2) = read_hex4(p);
                        p = q2;
                        let mut ok = false;
                        match lv {
                            Some(lo) => {
                                if lo >= 0xDC00 && lo < 0xE000 {
                                    ok = true;
                                }
                            }
                            None => {}
                        }
                        if ok {
                            token.push_str(s("\\u"));
                            token.push_str(raw2);
                        } else {
                            p.pos = save;
                        }
                    }
                    out.push_str(token);
                } else {
                    match ascii_of(v) {
                        Some(ch) => out.push_str(ch),
                        None => {
                            let mut token = s("\\u");
                            token.push_str(raw);
                            out.push_str(token);
                        }
                    }
                }
            } else {
                return (p, None);
            }
        } else {
            out.push_str(c);
        }
        count += 1;
    }
}

fn parse_number(p: Parser) -> (Parser, Option<Json>) {
    let mut p = p;
    let start = p.pos;
    let mut is_int = true;
    if at(p.clone(), p.pos) == s("-") {
        p.pos += 1;
    }
    if p.pos >= p.chars.len() {
        return (p, None);
    }
    let c = p.chars[p.pos].clone();
    if c == s("0") {
        p.pos += 1;
    } else if is_digit(c) {
        while p.pos < p.chars.len() && is_digit(p.chars[p.pos].clone()) {
            p.pos += 1;
        }
    } else {
        return (p, None);
    }
    if at(p.clone(), p.pos) == s(".") {
        is_int = false;
        p.pos += 1;
        let ds = p.pos;
        while p.pos < p.chars.len() && is_digit(p.chars[p.pos].clone()) {
            p.pos += 1;
        }
        if p.pos == ds {
            return (p, None);
        }
    }
    let ec = at(p.clone(), p.pos);
    if ec == s("e") || ec == s("E") {
        is_int = false;
        p.pos += 1;
        let sc = at(p.clone(), p.pos);
        if sc == s("+") || sc == s("-") {
            p.pos += 1;
        }
        let ds = p.pos;
        while p.pos < p.chars.len() && is_digit(p.chars[p.pos].clone()) {
            p.pos += 1;
        }
        if p.pos == ds {
            return (p, None);
        }
    }
    let mut text = Str::new();
    let mut i = start;
    while i < p.pos {
        text.push_str(p.chars[i].clone());
        i += 1;
    }
    match text.parse::<f64>() {
        Ok(v) => (p, Some(Json::Num(v, is_int))),
        Err(_) => (p, None),
    }
}

fn parse_value(p: Parser, depth: usize) -> (Parser, Option<Json>) {
    let mut p = p;
    if depth > 500 {
        return (p, None);
    }
    p = skip_ws(p);
    if p.pos >= p.chars.len() {
        return (p, None);
    }
    let c = p.chars[p.pos].clone();
    if c == s("{") {
        p.pos += 1;
        let mut fields: Vec<(Str, Json)> = Vec::new();
        p = skip_ws(p);
        if at(p.clone(), p.pos) == s("}") {
            p.pos += 1;
            return (p, Some(Json::Obj(fields)));
        }
        loop {
            p = skip_ws(p);
            if at(p.clone(), p.pos) != s("\"") {
                return (p, None);
            }
            let (q, kr) = parse_string(p);
            p = q;
            let key = match kr {
                Some(k) => k.0,
                None => {
                    return (p, None);
                }
            };
            p = skip_ws(p);
            if at(p.clone(), p.pos) != s(":") {
                return (p, None);
            }
            p.pos += 1;
            let (q2, vr) = parse_value(p, depth + 1);
            p = q2;
            let v = match vr {
                Some(v) => v,
                None => {
                    return (p, None);
                }
            };
            let mut idx = 0;
            let mut found = false;
            while idx < fields.len() {
                if fields[idx].0 == key {
                    found = true;
                    break;
                }
                idx += 1;
            }
            if found {
                fields.remove(idx);
            }
            fields.push((key, v));
            p = skip_ws(p);
            if p.pos >= p.chars.len() {
                return (p, None);
            }
            let d = p.chars[p.pos].clone();
            if d == s(",") {
                p.pos += 1;
            } else if d == s("}") {
                p.pos += 1;
                return (p, Some(Json::Obj(fields)));
            } else {
                return (p, None);
            }
        }
    } else if c == s("[") {
        p.pos += 1;
        let mut items: Vec<Json> = Vec::new();
        p = skip_ws(p);
        if at(p.clone(), p.pos) == s("]") {
            p.pos += 1;
            return (p, Some(Json::Arr(items)));
        }
        loop {
            let (q, vr) = parse_value(p, depth + 1);
            p = q;
            let v = match vr {
                Some(v) => v,
                None => {
                    return (p, None);
                }
            };
            items.push(v);
            p = skip_ws(p);
            if p.pos >= p.chars.len() {
                return (p, None);
            }
            let d = p.chars[p.pos].clone();
            if d == s(",") {
                p.pos += 1;
            } else if d == s("]") {
                p.pos += 1;
                return (p, Some(Json::Arr(items)));
            } else {
                return (p, None);
            }
        }
    } else if c == s("\"") {
        let (q, sr) = parse_string(p);
        match sr {
            Some(t) => (q, Some(Json::Text(t.0, t.1))),
            None => (q, None),
        }
    } else if c == s("t") {
        let (q, ok) = expect_word(p, s("true"));
        if ok {
            (q, Some(Json::Bool(true)))
        } else {
            (q, None)
        }
    } else if c == s("f") {
        let (q, ok) = expect_word(p, s("false"));
        if ok {
            (q, Some(Json::Bool(false)))
        } else {
            (q, None)
        }
    } else if c == s("n") {
        let (q, ok) = expect_word(p, s("null"));
        if ok {
            (q, Some(Json::Null))
        } else {
            (q, None)
        }
    } else if c == s("-") || is_digit(c) {
        parse_number(p)
    } else {
        (p, None)
    }
}

fn parse_json(text: Str) -> Option<Json> {
    let p = Parser { chars: text.chars().collect(), pos: 0 };
    let (q, vr) = parse_value(p, 0);
    let v = match vr {
        Some(v) => v,
        None => {
            return None;
        }
    };
    let q = skip_ws(q);
    if q.pos != q.chars.len() {
        return None;
    }
    Some(v)
}

fn get(obj: Json, key: Str) -> Option<Json> {
    match obj {
        Json::Obj(fields) => {
            let mut i = 0;
            while i < fields.len() {
                if fields[i].0 == key {
                    return Some(fields[i].1.clone());
                }
                i += 1;
            }
            None
        }
        _ => None,
    }
}

fn has_key(fields: Vec<(Str, Json)>, key: Str) -> bool {
    let mut i = 0;
    while i < fields.len() {
        if fields[i].0 == key {
            return true;
        }
        i += 1;
    }
    false
}

fn get_str(obj: Json, key: Str) -> Option<Str> {
    match get(obj, key) {
        Some(Json::Text(t, _)) => Some(t),
        _ => None,
    }
}

fn get_int(obj: Json, key: Str) -> Option<i64> {
    match get(obj, key) {
        Some(Json::Num(v, _)) => Some(v as i64),
        _ => None,
    }
}

fn check_bounds(schema: Json, v: f64, path: Str, errs: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut errs = errs;
    match get_int(schema.clone(), s("minimum")) {
        Some(n) => {
            if v < (n as f64) {
                errs.push((path.clone(), format!("less than {}", n)));
                return errs;
            }
        }
        None => {}
    }
    match get_int(schema.clone(), s("maximum")) {
        Some(n) => {
            if v > (n as f64) {
                errs.push((path.clone(), format!("greater than {}", n)));
            }
        }
        None => {}
    }
    errs
}

fn field_path(path: Str, name: Str) -> Str {
    let mut fp = path;
    fp.push_str(s("."));
    fp.push_str(name);
    fp
}

fn validate(schema: Json, value: Json, path: Str, errs: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut errs = errs;
    let ty = match get_str(schema.clone(), s("type")) {
        Some(t) => t,
        None => {
            return errs;
        }
    };
    if ty == s("object") {
        match value {
            Json::Obj(fields) => {
                let props = get(schema.clone(), s("properties"));
                match get(schema.clone(), s("required")) {
                    Some(Json::Arr(req)) => {
                        let mut i = 0;
                        while i < req.len() {
                            match req[i].clone() {
                                Json::Text(name, _) => {
                                    if !has_key(fields.clone(), name.clone()) {
                                        errs.push((field_path(path.clone(), name.clone()), s("missing required field")));
                                    }
                                }
                                _ => {}
                            }
                            i += 1;
                        }
                    }
                    _ => {}
                }
                let mut no_additional = false;
                match get(schema.clone(), s("additional")) {
                    Some(Json::Bool(false)) => {
                        no_additional = true;
                    }
                    _ => {}
                }
                let mut i = 0;
                while i < fields.len() {
                    let name = fields[i].0.clone();
                    let fp = field_path(path.clone(), name.clone());
                    let sub = match props.clone() {
                        Some(pr) => get(pr, name.clone()),
                        None => None,
                    };
                    match sub {
                        Some(sc) => {
                            errs = validate(sc, fields[i].1.clone(), fp, errs);
                        }
                        None => {
                            if no_additional {
                                errs.push((fp, s("unexpected field")));
                            }
                        }
                    }
                    i += 1;
                }
            }
            _ => {
                errs.push((path.clone(), s("expected object")));
            }
        }
    } else if ty == s("array") {
        match value {
            Json::Arr(items) => {
                match get_int(schema.clone(), s("min_items")) {
                    Some(n) => {
                        if (items.len() as i64) < n {
                            errs.push((path.clone(), format!("fewer than {} items", n)));
                        }
                    }
                    None => {}
                }
                match get(schema.clone(), s("items")) {
                    Some(sub) => {
                        let mut i = 0;
                        while i < items.len() {
                            let ip = format!("{}[{}]", path, i);
                            errs = validate(sub.clone(), items[i].clone(), ip, errs);
                            i += 1;
                        }
                    }
                    None => {}
                }
            }
            _ => {
                errs.push((path.clone(), s("expected array")));
            }
        }
    } else if ty == s("string") {
        match value {
            Json::Text(t, len) => {
                match get_int(schema.clone(), s("min_length")) {
                    Some(n) => {
                        if len < n {
                            errs.push((path.clone(), format!("shorter than {}", n)));
                            return errs;
                        }
                    }
                    None => {}
                }
                match get_int(schema.clone(), s("max_length")) {
                    Some(n) => {
                        if len > n {
                            errs.push((path.clone(), format!("longer than {}", n)));
                            return errs;
                        }
                    }
                    None => {}
                }
                match get(schema.clone(), s("enum")) {
                    Some(Json::Arr(opts)) => {
                        let mut ok = false;
                        let mut i = 0;
                        while i < opts.len() {
                            match opts[i].clone() {
                                Json::Text(o, _) => {
                                    if o == t {
                                        ok = true;
                                    }
                                }
                                _ => {}
                            }
                            i += 1;
                        }
                        if !ok {
                            errs.push((path.clone(), s("not in enum")));
                        }
                    }
                    _ => {}
                }
            }
            _ => {
                errs.push((path.clone(), s("expected string")));
            }
        }
    } else if ty == s("integer") {
        match value {
            Json::Num(v, true) => {
                errs = check_bounds(schema.clone(), v, path.clone(), errs);
            }
            _ => {
                errs.push((path.clone(), s("expected integer")));
            }
        }
    } else if ty == s("number") {
        match value {
            Json::Num(v, _) => {
                errs = check_bounds(schema.clone(), v, path.clone(), errs);
            }
            _ => {
                errs.push((path.clone(), s("expected number")));
            }
        }
    } else if ty == s("boolean") {
        match value {
            Json::Bool(_) => {}
            _ => {
                errs.push((path.clone(), s("expected boolean")));
            }
        }
    } else if ty == s("null") {
        match value {
            Json::Null => {}
            _ => {
                errs.push((path.clone(), s("expected null")));
            }
        }
    }
    errs
}

fn less(a: (Str, Str), b: (Str, Str)) -> bool {
    if a.0 < b.0 {
        true
    } else if a.0 == b.0 {
        a.1 < b.1
    } else {
        false
    }
}

fn sort_errs(errs: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut errs = errs;
    let mut i = 1;
    while i < errs.len() {
        let mut j = i;
        while j > 0 && less(errs[j].clone(), errs[j - 1].clone()) {
            errs.swap(j, j - 1);
            j -= 1;
        }
        i += 1;
    }
    errs
}

fn main(input: Dir) -> Result<Str, Str> {
    let schema_text = match input.read("schema.json") {
        Ok(t) => t,
        Err(_) => {
            return Err(s("cannot read schema.json"));
        }
    };
    let records_text = match input.read("records.jsonl") {
        Ok(t) => t,
        Err(_) => {
            return Err(s("cannot read records.jsonl"));
        }
    };
    let schema = match parse_json(schema_text) {
        Some(sc) => sc,
        None => {
            return Err(s("invalid schema"));
        }
    };
    let mut out = Str::new();
    let mut valid = 0;
    let mut total = 0;
    let mut line_no = 0;
    for raw in records_text.split("\n") {
        line_no += 1;
        let line = raw.trim().to_string();
        if line.is_empty() {
            continue;
        }
        total += 1;
        match parse_json(line) {
            None => {
                out.push_str(format!("line {}: invalid JSON\n", line_no));
            }
            Some(v) => {
                let errs0: Vec<(Str, Str)> = Vec::new();
                let errs = validate(schema.clone(), v, s("$"), errs0);
                if errs.is_empty() {
                    valid += 1;
                    out.push_str(format!("line {}: ok\n", line_no));
                } else {
                    let errs = sort_errs(errs);
                    let mut i = 0;
                    while i < errs.len() {
                        out.push_str(format!("line {}: {}: {}\n", line_no, errs[i].0, errs[i].1));
                        i += 1;
                    }
                }
            }
        }
    }
    out.push_str(format!("valid {} of {}", valid, total));
    Ok(out)
}

enum Json {
    Null,
    Bool(bool),
    Int(f64),
    Float(f64),
    Text(JStr),
    Arr(Vec<Json>),
    Obj(Vec<Field>),
}

struct JStr {
    text: Str,
    len: i64,
}

struct Field {
    name: Str,
    value: Json,
}

struct VErr {
    path: Str,
    msg: Str,
}

struct Parser {
    chars: Vec<Str>,
    pos: usize,
}

struct PB {
    p: Parser,
    ok: bool,
}

struct PH {
    p: Parser,
    v: Option<u32>,
    raw: Str,
}

struct PS {
    p: Parser,
    s: Option<JStr>,
}

struct PV {
    p: Parser,
    v: Option<Json>,
}

fn s(x: Str) -> Str {
    x.to_string()
}

fn at(p: Parser, i: usize) -> Str {
    if i < p.chars.len() {
        p.chars[i].clone()
    } else {
        "".to_string()
    }
}

fn skip_ws(p: Parser) -> Parser {
    let mut p = p;
    while p.pos < p.chars.len() {
        let c = p.chars[p.pos].clone();
        if c == s(" ") || c == s("\t") || c == s("\n") || c == s("\r") {
            p.pos += 1;
        } else {
            break;
        }
    }
    p
}

fn expect_word(p: Parser, w: Str) -> PB {
    let mut p = p;
    let wc: Vec<Str> = w.chars().collect();
    let mut i = 0;
    while i < wc.len() {
        if p.pos + i >= p.chars.len() || p.chars[p.pos + i].clone() != wc[i].clone() {
            return PB { p: p, ok: false };
        }
        i += 1;
    }
    p.pos += wc.len();
    PB { p: p, ok: true }
}

fn is_digit(c: Str) -> bool {
    c.len() == 1 && c >= s("0") && c <= s("9")
}

fn hex_val(c: Str) -> Option<u32> {
    let lower: Vec<Str> = s("0123456789abcdef").chars().collect();
    let upper: Vec<Str> = s("0123456789ABCDEF").chars().collect();
    let mut i = 0;
    while i < 16 {
        if lower[i].clone() == c || upper[i].clone() == c {
            return Some(i as u32);
        }
        i += 1;
    }
    None
}

fn read_hex4(p: Parser) -> PH {
    let mut p = p;
    let mut raw = Str::new();
    if p.pos + 4 > p.chars.len() {
        return PH { p: p, v: None, raw: raw };
    }
    let lower: Vec<Str> = s("0123456789abcdef").chars().collect();
    let mut v: u32 = 0;
    let mut i = 0;
    while i < 4 {
        let c = p.chars[p.pos + i].clone();
        match hex_val(c.clone()) {
            Some(h) => {
                v = v * 16 + h;
                raw.push_str(lower[h as usize].clone());
            }
            None => {
                return PH { p: p, v: None, raw: raw };
            }
        }
        i += 1;
    }
    p.pos += 4;
    PH { p: p, v: Some(v), raw: raw }
}

fn ascii_of(v: u32) -> Option<Str> {
    if v == 8 {
        return Some(s("\\b"));
    }
    if v == 9 {
        return Some(s("\t"));
    }
    if v == 10 {
        return Some(s("\n"));
    }
    if v == 12 {
        return Some(s("\\f"));
    }
    if v == 13 {
        return Some(s("\r"));
    }
    if v == 92 {
        return Some(s("\\\\"));
    }
    if v >= 32 && v < 127 {
        let table: Vec<Str> = s(" !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~").chars().collect();
        let idx = (v - 32) as usize;
        if idx < table.len() {
            return Some(table[idx].clone());
        }
    }
    None
}

fn parse_string(p: Parser) -> PS {
    let mut p = p;
    p.pos += 1;
    let mut out = Str::new();
    let mut count: i64 = 0;
    loop {
        if p.pos >= p.chars.len() {
            return PS { p: p, s: None };
        }
        let c = p.chars[p.pos].clone();
        p.pos += 1;
        if c == s("\"") {
            return PS { p: p, s: Some(JStr { text: out, len: count }) };
        }
        if c < s(" ") {
            return PS { p: p, s: None };
        }
        if c == s("\\") {
            if p.pos >= p.chars.len() {
                return PS { p: p, s: None };
            }
            let e = p.chars[p.pos].clone();
            p.pos += 1;
            if e == s("\"") {
                out.push_str(s("\""));
            } else if e == s("\\") {
                out.push_str(s("\\\\"));
            } else if e == s("/") {
                out.push_str(s("/"));
            } else if e == s("b") {
                out.push_str(s("\\b"));
            } else if e == s("f") {
                out.push_str(s("\\f"));
            } else if e == s("n") {
                out.push_str(s("\n"));
            } else if e == s("r") {
                out.push_str(s("\r"));
            } else if e == s("t") {
                out.push_str(s("\t"));
            } else if e == s("u") {
                let r = read_hex4(p);
                let hv = r.v;
                let raw = r.raw.clone();
                p = r.p;
                let v = match hv {
                    Some(v) => v,
                    None => {
                        return PS { p: p, s: None };
                    }
                };
                if v >= 0xD800 && v < 0xDC00 {
                    let mut token = s("\\u");
                    token.push_str(raw);
                    if at(p.clone(), p.pos) == s("\\") && at(p.clone(), p.pos + 1) == s("u") {
                        let save = p.pos;
                        p.pos += 2;
                        let r2 = read_hex4(p);
                        let lv = r2.v;
                        let raw2 = r2.raw.clone();
                        p = r2.p;
                        let mut ok = false;
                        match lv {
                            Some(lo) => {
                                if lo >= 0xDC00 && lo < 0xE000 {
                                    ok = true;
                                }
                            }
                            None => {}
                        }
                        if ok {
                            token.push_str(s("\\u"));
                            token.push_str(raw2);
                        } else {
                            p.pos = save;
                        }
                    }
                    out.push_str(token);
                } else {
                    match ascii_of(v) {
                        Some(ch) => out.push_str(ch),
                        None => {
                            let mut token = s("\\u");
                            token.push_str(raw);
                            out.push_str(token);
                        }
                    }
                }
            } else {
                return PS { p: p, s: None };
            }
        } else {
            out.push_str(c);
        }
        count += 1;
    }
}

fn parse_number(p: Parser) -> PV {
    let mut p = p;
    let start = p.pos;
    let mut is_int = true;
    if at(p.clone(), p.pos) == s("-") {
        p.pos += 1;
    }
    if p.pos >= p.chars.len() {
        return PV { p: p, v: None };
    }
    let c = p.chars[p.pos].clone();
    if c == s("0") {
        p.pos += 1;
    } else if is_digit(c) {
        while p.pos < p.chars.len() && is_digit(p.chars[p.pos].clone()) {
            p.pos += 1;
        }
    } else {
        return PV { p: p, v: None };
    }
    if at(p.clone(), p.pos) == s(".") {
        is_int = false;
        p.pos += 1;
        let ds = p.pos;
        while p.pos < p.chars.len() && is_digit(p.chars[p.pos].clone()) {
            p.pos += 1;
        }
        if p.pos == ds {
            return PV { p: p, v: None };
        }
    }
    let ec = at(p.clone(), p.pos);
    if ec == s("e") || ec == s("E") {
        is_int = false;
        p.pos += 1;
        let sc = at(p.clone(), p.pos);
        if sc == s("+") || sc == s("-") {
            p.pos += 1;
        }
        let ds = p.pos;
        while p.pos < p.chars.len() && is_digit(p.chars[p.pos].clone()) {
            p.pos += 1;
        }
        if p.pos == ds {
            return PV { p: p, v: None };
        }
    }
    let mut text = Str::new();
    let mut i = start;
    while i < p.pos {
        text.push_str(p.chars[i].clone());
        i += 1;
    }
    match text.parse::<f64>() {
        Ok(v) => {
            if is_int {
                PV { p: p, v: Some(Json::Int(v)) }
            } else {
                PV { p: p, v: Some(Json::Float(v)) }
            }
        }
        Err(_) => PV { p: p, v: None },
    }
}

fn parse_value(p: Parser, depth: usize) -> PV {
    let mut p = p;
    if depth > 500 {
        return PV { p: p, v: None };
    }
    p = skip_ws(p);
    if p.pos >= p.chars.len() {
        return PV { p: p, v: None };
    }
    let c = p.chars[p.pos].clone();
    if c == s("{") {
        p.pos += 1;
        let mut fields: Vec<Field> = Vec::new();
        p = skip_ws(p);
        if at(p.clone(), p.pos) == s("}") {
            p.pos += 1;
            return PV { p: p, v: Some(Json::Obj(fields)) };
        }
        loop {
            p = skip_ws(p);
            if at(p.clone(), p.pos) != s("\"") {
                return PV { p: p, v: None };
            }
            let kr = parse_string(p);
            let ks = kr.s.clone();
            p = kr.p;
            let key = match ks {
                Some(k) => k.text,
                None => {
                    return PV { p: p, v: None };
                }
            };
            p = skip_ws(p);
            if at(p.clone(), p.pos) != s(":") {
                return PV { p: p, v: None };
            }
            p.pos += 1;
            let vr = parse_value(p, depth + 1);
            let vo = vr.v.clone();
            p = vr.p;
            let v = match vo {
                Some(v) => v,
                None => {
                    return PV { p: p, v: None };
                }
            };
            let mut idx = 0;
            let mut found = false;
            while idx < fields.len() {
                if fields[idx].name == key {
                    found = true;
                    break;
                }
                idx += 1;
            }
            if found {
                fields.remove(idx);
            }
            fields.push(Field { name: key, value: v });
            p = skip_ws(p);
            if p.pos >= p.chars.len() {
                return PV { p: p, v: None };
            }
            let d = p.chars[p.pos].clone();
            if d == s(",") {
                p.pos += 1;
            } else if d == s("}") {
                p.pos += 1;
                return PV { p: p, v: Some(Json::Obj(fields)) };
            } else {
                return PV { p: p, v: None };
            }
        }
    } else if c == s("[") {
        p.pos += 1;
        let mut items: Vec<Json> = Vec::new();
        p = skip_ws(p);
        if at(p.clone(), p.pos) == s("]") {
            p.pos += 1;
            return PV { p: p, v: Some(Json::Arr(items)) };
        }
        loop {
            let vr = parse_value(p, depth + 1);
            let vo = vr.v.clone();
            p = vr.p;
            let v = match vo {
                Some(v) => v,
                None => {
                    return PV { p: p, v: None };
                }
            };
            items.push(v);
            p = skip_ws(p);
            if p.pos >= p.chars.len() {
                return PV { p: p, v: None };
            }
            let d = p.chars[p.pos].clone();
            if d == s(",") {
                p.pos += 1;
            } else if d == s("]") {
                p.pos += 1;
                return PV { p: p, v: Some(Json::Arr(items)) };
            } else {
                return PV { p: p, v: None };
            }
        }
    } else if c == s("\"") {
        let r = parse_string(p);
        let so = r.s.clone();
        let q = r.p;
        match so {
            Some(t) => PV { p: q, v: Some(Json::Text(t)) },
            None => PV { p: q, v: None },
        }
    } else if c == s("t") {
        let r = expect_word(p, s("true"));
        let ok = r.ok;
        if ok {
            PV { p: r.p, v: Some(Json::Bool(true)) }
        } else {
            PV { p: r.p, v: None }
        }
    } else if c == s("f") {
        let r = expect_word(p, s("false"));
        let ok = r.ok;
        if ok {
            PV { p: r.p, v: Some(Json::Bool(false)) }
        } else {
            PV { p: r.p, v: None }
        }
    } else if c == s("n") {
        let r = expect_word(p, s("null"));
        let ok = r.ok;
        if ok {
            PV { p: r.p, v: Some(Json::Null) }
        } else {
            PV { p: r.p, v: None }
        }
    } else if c == s("-") || is_digit(c) {
        parse_number(p)
    } else {
        PV { p: p, v: None }
    }
}

fn parse_json(text: Str) -> Option<Json> {
    let p = Parser { chars: text.chars().collect(), pos: 0 };
    let r = parse_value(p, 0);
    let vo = r.v.clone();
    let q = r.p;
    let v = match vo {
        Some(v) => v,
        None => {
            return None;
        }
    };
    let q = skip_ws(q);
    if q.pos != q.chars.len() {
        return None;
    }
    Some(v)
}

fn get(obj: Json, key: Str) -> Option<Json> {
    match obj {
        Json::Obj(fields) => {
            let mut i = 0;
            while i < fields.len() {
                if fields[i].name == key {
                    return Some(fields[i].value.clone());
                }
                i += 1;
            }
            None
        }
        _ => None,
    }
}

fn has_key(fields: Vec<Field>, key: Str) -> bool {
    let mut i = 0;
    while i < fields.len() {
        if fields[i].name == key {
            return true;
        }
        i += 1;
    }
    false
}

fn get_str(obj: Json, key: Str) -> Option<Str> {
    match get(obj, key) {
        Some(Json::Text(t)) => Some(t.text),
        _ => None,
    }
}

fn get_int(obj: Json, key: Str) -> Option<i64> {
    match get(obj, key) {
        Some(Json::Int(v)) => Some(v as i64),
        Some(Json::Float(v)) => Some(v as i64),
        _ => None,
    }
}

fn push_err(errs: Vec<VErr>, path: Str, msg: Str) -> Vec<VErr> {
    let mut errs = errs;
    errs.push(VErr { path: path, msg: msg });
    errs
}

fn check_bounds(schema: Json, v: f64, path: Str, errs: Vec<VErr>) -> Vec<VErr> {
    let mut errs = errs;
    match get_int(schema.clone(), s("minimum")) {
        Some(n) => {
            if v < (n as f64) {
                errs = push_err(errs, path.clone(), format!("less than {}", n));
                return errs;
            }
        }
        None => {}
    }
    match get_int(schema.clone(), s("maximum")) {
        Some(n) => {
            if v > (n as f64) {
                errs = push_err(errs, path.clone(), format!("greater than {}", n));
            }
        }
        None => {}
    }
    errs
}

fn field_path(path: Str, name: Str) -> Str {
    let mut fp = path;
    fp.push_str(s("."));
    fp.push_str(name);
    fp
}

fn validate(schema: Json, value: Json, path: Str, errs: Vec<VErr>) -> Vec<VErr> {
    let mut errs = errs;
    let ty = match get_str(schema.clone(), s("type")) {
        Some(t) => t,
        None => {
            return errs;
        }
    };
    if ty == s("object") {
        match value {
            Json::Obj(fields) => {
                let props = get(schema.clone(), s("properties"));
                match get(schema.clone(), s("required")) {
                    Some(Json::Arr(req)) => {
                        let mut i = 0;
                        while i < req.len() {
                            match req[i].clone() {
                                Json::Text(name) => {
                                    if !has_key(fields.clone(), name.text.clone()) {
                                        errs = push_err(errs, field_path(path.clone(), name.text.clone()), s("missing required field"));
                                    }
                                }
                                _ => {}
                            }
                            i += 1;
                        }
                    }
                    _ => {}
                }
                let mut no_additional = false;
                match get(schema.clone(), s("additional")) {
                    Some(Json::Bool(false)) => {
                        no_additional = true;
                    }
                    _ => {}
                }
                let mut i = 0;
                while i < fields.len() {
                    let name = fields[i].name.clone();
                    let fp = field_path(path.clone(), name.clone());
                    let sub = match props.clone() {
                        Some(pr) => get(pr, name.clone()),
                        None => None,
                    };
                    match sub {
                        Some(sc) => {
                            errs = validate(sc, fields[i].value.clone(), fp, errs);
                        }
                        None => {
                            if no_additional {
                                errs = push_err(errs, fp, s("unexpected field"));
                            }
                        }
                    }
                    i += 1;
                }
            }
            _ => {
                errs = push_err(errs, path.clone(), s("expected object"));
            }
        }
    } else if ty == s("array") {
        match value {
            Json::Arr(items) => {
                match get_int(schema.clone(), s("min_items")) {
                    Some(n) => {
                        if (items.len() as i64) < n {
                            errs = push_err(errs, path.clone(), format!("fewer than {} items", n));
                        }
                    }
                    None => {}
                }
                match get(schema.clone(), s("items")) {
                    Some(sub) => {
                        let mut i = 0;
                        while i < items.len() {
                            let ip = format!("{}[{}]", path, i);
                            errs = validate(sub.clone(), items[i].clone(), ip, errs);
                            i += 1;
                        }
                    }
                    None => {}
                }
            }
            _ => {
                errs = push_err(errs, path.clone(), s("expected array"));
            }
        }
    } else if ty == s("string") {
        match value {
            Json::Text(js) => {
                let t = js.text.clone();
                let len = js.len;
                match get_int(schema.clone(), s("min_length")) {
                    Some(n) => {
                        if len < n {
                            errs = push_err(errs, path.clone(), format!("shorter than {}", n));
                            return errs;
                        }
                    }
                    None => {}
                }
                match get_int(schema.clone(), s("max_length")) {
                    Some(n) => {
                        if len > n {
                            errs = push_err(errs, path.clone(), format!("longer than {}", n));
                            return errs;
                        }
                    }
                    None => {}
                }
                match get(schema.clone(), s("enum")) {
                    Some(Json::Arr(opts)) => {
                        let mut ok = false;
                        let mut i = 0;
                        while i < opts.len() {
                            match opts[i].clone() {
                                Json::Text(o) => {
                                    if o.text == t {
                                        ok = true;
                                    }
                                }
                                _ => {}
                            }
                            i += 1;
                        }
                        if !ok {
                            errs = push_err(errs, path.clone(), s("not in enum"));
                        }
                    }
                    _ => {}
                }
            }
            _ => {
                errs = push_err(errs, path.clone(), s("expected string"));
            }
        }
    } else if ty == s("integer") {
        match value {
            Json::Int(v) => {
                errs = check_bounds(schema.clone(), v, path.clone(), errs);
            }
            _ => {
                errs = push_err(errs, path.clone(), s("expected integer"));
            }
        }
    } else if ty == s("number") {
        match value {
            Json::Int(v) => {
                errs = check_bounds(schema.clone(), v, path.clone(), errs);
            }
            Json::Float(v) => {
                errs = check_bounds(schema.clone(), v, path.clone(), errs);
            }
            _ => {
                errs = push_err(errs, path.clone(), s("expected number"));
            }
        }
    } else if ty == s("boolean") {
        match value {
            Json::Bool(_) => {}
            _ => {
                errs = push_err(errs, path.clone(), s("expected boolean"));
            }
        }
    } else if ty == s("null") {
        match value {
            Json::Null => {}
            _ => {
                errs = push_err(errs, path.clone(), s("expected null"));
            }
        }
    }
    errs
}

fn less(a: VErr, b: VErr) -> bool {
    if a.path < b.path {
        true
    } else if a.path == b.path {
        a.msg < b.msg
    } else {
        false
    }
}

fn sort_errs(errs: Vec<VErr>) -> Vec<VErr> {
    let mut errs = errs;
    let mut i = 1;
    while i < errs.len() {
        let mut j = i;
        while j > 0 && less(errs[j].clone(), errs[j - 1].clone()) {
            errs.swap(j, j - 1);
            j -= 1;
        }
        i += 1;
    }
    errs
}

fn main(input: Dir) -> Result<Str, Str> {
    let schema_text = match input.read("schema.json") {
        Ok(t) => t,
        Err(_) => {
            return Err(s("cannot read schema.json"));
        }
    };
    let records_text = match input.read("records.jsonl") {
        Ok(t) => t,
        Err(_) => {
            return Err(s("cannot read records.jsonl"));
        }
    };
    let schema = match parse_json(schema_text) {
        Some(sc) => sc,
        None => {
            return Err(s("invalid schema"));
        }
    };
    let mut out = Str::new();
    let mut valid = 0;
    let mut total = 0;
    let mut line_no = 0;
    for raw in records_text.split("\n") {
        line_no += 1;
        let line = raw.trim().to_string();
        if line.is_empty() {
            continue;
        }
        total += 1;
        match parse_json(line) {
            None => {
                out.push_str(format!("line {}: invalid JSON\n", line_no));
            }
            Some(v) => {
                let errs0: Vec<VErr> = Vec::new();
                let errs = validate(schema.clone(), v, s("$"), errs0);
                if errs.is_empty() {
                    valid += 1;
                    out.push_str(format!("line {}: ok\n", line_no));
                } else {
                    let errs = sort_errs(errs);
                    let mut i = 0;
                    while i < errs.len() {
                        out.push_str(format!("line {}: {}: {}\n", line_no, errs[i].path, errs[i].msg));
                        i += 1;
                    }
                }
            }
        }
    }
    out.push_str(format!("valid {} of {}", valid, total));
    Ok(out)
}

use std::collections::BTreeMap;

fn main(input: Dir, state: Kv, api: Http) -> Result<Str, Error> {
    let text = input.read_text("records.jsonl")?;
    let mut out = String::new();

    // id -> (version, line) ; last line for an id wins
    let mut records: BTreeMap<String, (i64, String)> = BTreeMap::new();

    let mut n = 0;
    for raw in text.lines() {
        n += 1;
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        let mut ok = false;
        if let Ok(v) = json::parse(line) {
            if v.is_object() {
                let id = v.get("id").and_then(|x| x.as_str().map(|s| s.to_string()));
                let ver = v.get("version").and_then(|x| x.as_i64());
                if let (Some(id), Some(ver)) = (id, ver) {
                    records.insert(id, (ver, line.to_string()));
                    ok = true;
                }
            }
        }
        if !ok {
            out.push_str(&format!("line {} invalid\n", n));
        }
    }

    let mut synced = 0;
    let mut unchanged = 0;
    let mut rejected = 0;
    let mut failed = 0;

    for (id, (ver, line)) in records.iter() {
        let key = format!("pushed:{}", id);
        let last: Option<i64> = match state.get(&key)? {
            Some(s) => s.trim().parse::<i64>().ok(),
            None => None,
        };
        let need = match last {
            Some(l) => *ver > l,
            None => true,
        };
        if !need {
            unchanged += 1;
            out.push_str(&format!("{} unchanged\n", id));
            continue;
        }

        let path = format!("/records/{}", id);
        let mut result: Option<String> = None;
        let mut attempts = 0;
        while attempts < 3 {
            attempts += 1;
            let resp = api.put(&path, &[("content-type", "application/json")], line.as_str());
            match resp {
                Ok(r) => {
                    let st = r.status();
                    if st >= 200 && st < 300 {
                        state.set(&key, &ver.to_string())?;
                        synced += 1;
                        result = Some(format!("{} synced", id));
                        break;
                    } else if st >= 400 && st < 500 {
                        rejected += 1;
                        result = Some(format!("{} rejected {}", id, st));
                        break;
                    } else if st >= 500 && st < 600 {
                        continue;
                    } else {
                        continue;
                    }
                }
                Err(_) => {
                    continue;
                }
            }
        }
        match result {
            Some(s) => {
                out.push_str(&s);
                out.push_str("\n");
            }
            None => {
                failed += 1;
                out.push_str(&format!("{} failed\n", id));
            }
        }
    }

    out.push_str(&format!(
        "synced {} unchanged {} rejected {} failed {}",
        synced, unchanged, rejected, failed
    ));
    Ok(out)
}

