fn two(n: i64) -> Str {
    if n < 10 { format!("0{}", n) } else { format!("{}", n) }
}

fn fmt_time(ms: i64) -> Str {
    let secs = ms.div_euclid(1000);
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let hh = rem / 3600;
    let mi = (rem % 3600) / 60;
    let ss = rem % 60;
    let z = days + 719468;
    let era = z.div_euclid(146097);
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 { y = y + 1; }
    format!("{}-{}-{}T{}:{}:{}Z", y, two(m), two(d), two(hh), two(mi), two(ss))
}

fn parse_int(s: &Str) -> Option<i64> {
    match s.parse::<i64>() {
        Ok(v) => Some(v),
        Err(_) => None,
    }
}

// Returns Some((balance, closed)) if the account row exists.
fn get_account(db: &Db, name: &Str) -> Result<Option<(i64, i64)>, Error> {
    let rows = db.query(
        "SELECT balance, closed FROM accounts WHERE name = ?1",
        [Value::Text(name.clone())],
    )?;
    if rows.len() == 0 {
        return Ok(None);
    }
    let r = &rows[0];
    Ok(Some((r.get_int(0)?, r.get_int(1)?)))
}

fn is_open(acct: &Option<(i64, i64)>) -> bool {
    match acct {
        Some((_, closed)) => *closed == 0,
        None => false,
    }
}

fn balance_of(acct: &Option<(i64, i64)>) -> i64 {
    match acct {
        Some((b, _)) => *b,
        None => 0,
    }
}

// Ok(Ok(true)) = success, Ok(Ok(false)) = duplicate, Ok(Err(msg)) = failure
fn do_op(db: &Db, words: &Vec<Str>, now: &Str) -> Result<Result<bool, Str>, Error> {
    let op = words[0].clone();
    if op == "open" {
        if words.len() != 3 { return Ok(Err("malformed".to_string())); }
        let cents = match parse_int(&words[2]) {
            Some(v) => v,
            None => return Ok(Err("malformed".to_string())),
        };
        if cents < 0 { return Ok(Err("bad amount".to_string())); }
        let name = words[1].clone();
        let acct = get_account(db, &name)?;
        if acct.is_some() { return Ok(Err("account exists".to_string())); }
        db.exec(
            "INSERT INTO accounts (name, balance, last, closed) VALUES (?1, ?2, ?3, 0)",
            [Value::Text(name), Value::Int(cents), Value::Text(now.clone())],
        )?;
        return Ok(Ok(true));
    } else if op == "transfer" {
        if words.len() != 5 { return Ok(Err("malformed".to_string())); }
        let cents = match parse_int(&words[4]) {
            Some(v) => v,
            None => return Ok(Err("malformed".to_string())),
        };
        let id = words[1].clone();
        let from = words[2].clone();
        let to = words[3].clone();
        let prev = db.query(
            "SELECT src, dst, cents FROM transfers WHERE id = ?1",
            [Value::Text(id.clone())],
        )?;
        if prev.len() > 0 {
            let r = &prev[0];
            let ps = r.get_text(0)?;
            let pd = r.get_text(1)?;
            let pc = r.get_int(2)?;
            if ps == from && pd == to && pc == cents {
                return Ok(Ok(false));
            }
            return Ok(Err("id reused".to_string()));
        }
        if cents <= 0 { return Ok(Err("bad amount".to_string())); }
        if from == to { return Ok(Err("same account".to_string())); }
        let fa = get_account(db, &from)?;
        if !is_open(&fa) { return Ok(Err(format!("no account {}", from))); }
        let ta = get_account(db, &to)?;
        if !is_open(&ta) { return Ok(Err(format!("no account {}", to))); }
        let fb = balance_of(&fa);
        let tb = balance_of(&ta);
        if fb < cents { return Ok(Err("insufficient funds".to_string())); }
        if tb > 9223372036854775807 - cents { return Ok(Err("overflow".to_string())); }
        db.exec("BEGIN", [])?;
        db.exec(
