}

fn parse_int(s: Str) -> Option<i64> {
    let min: i64 = -9223372036854775807 - 1;
    let mut neg = false;
    let mut first = true;
    let mut count = 0;
    let mut v: i64 = 0;
    for c in s.chars() {
        if first && (c == '-' || c == '+') {
            neg = c == '-';
            first = false;
            continue;
        }
        first = false;
        let d = digit(c);
        if d < 0 {
            return None;
        }
        if v < (min + d) / 10 {
            return None;
        }
        v = v * 10 - d;
        count = count + 1;
    }
    if count == 0 {
        return None;
    }
    if neg {
        Some(v)
    } else if v == min {
        None
    } else {
        Some(0 - v)
    }
}

fn main(input: Dir, db: Db, log: Log, clock: Clock) -> Result<Str, Error> {
    db.exec(
        "CREATE TABLE IF NOT EXISTS accounts (name TEXT PRIMARY KEY, balance INTEGER NOT NULL, last TEXT NOT NULL, closed INTEGER NOT NULL)",
        [],
    )?;
    db.exec(
        "CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY, src TEXT NOT NULL, dst TEXT NOT NULL, cents INTEGER NOT NULL)",
        [],
    )?;
    let now = fmt_time(clock.now_millis());
    let text = input.read("ops.txt")?;
    let mut ok = 0;
    let mut failed = 0;
    let mut dup = 0;
    let mut n = 0;
    for raw in text.split("\n") {
        n = n + 1;
        let line = raw.trim_end_matches("\r");
        if line.trim().is_empty() {
            continue;
        }
        let words: Vec<Str> = line.split(" ").map(|w| w.to_str()).collect();
        // "" = success, "#dup" = duplicate, else failure message
        let outcome: Str = loop {
            let op = words[0].clone();
            if op == "open" {
                if words.len() != 3 { break "malformed".to_str(); }
                let cents = match parse_int(words[2].clone()) {
                    Some(v) => v,
                    None => { break "malformed".to_str(); }
                };
                if cents < 0 { break "bad amount".to_str(); }
                let name = words[1].clone();
                let rows = db.query(
                    "SELECT balance FROM accounts WHERE name = ?1",
                    [Value::Text(name.clone())],
                )?;
                if rows.len() > 0 { break "account exists".to_str(); }
                db.exec(
                    "INSERT INTO accounts (name, balance, last, closed) VALUES (?1, ?2, ?3, 0)",
                    [Value::Text(name), Value::Int(cents), Value::Text(now.clone())],
                )?;
                break "".to_str();
            } else if op == "transfer" {
                if words.len() != 5 { break "malformed".to_str(); }
                let cents = match parse_int(words[4].clone()) {
                    Some(v) => v,
                    None => { break "malformed".to_str(); }
                };
                let id = words[1].clone();
                let from = words[2].clone();
                let to = words[3].clone();
                let prev = db.query(
                    "SELECT src, dst, cents FROM transfers WHERE id = ?1",
                    [Value::Text(id.clone())],
                )?;
                if prev.len() > 0 {
                    let ps = prev[0].get_text(0)?;
                    let pd = prev[0].get_text(1)?;
                    let pc = prev[0].get_int(2)?;
                    if ps == from && pd == to && pc == cents {
                        break "#dup".to_str();
                    }
                    break "id reused".to_str();
                }
                if cents <= 0 { break "bad amount".to_str(); }
                if from == to { break "same account".to_str(); }
                let fr = db.query(
                    "SELECT balance FROM accounts WHERE name = ?1 AND closed = 0",
                    [Value::Text(from.clone())],
                )?;
                if fr.len() == 0 { break "no account ".to_str() + from; }
                let tr = db.query(
                    "SELECT balance FROM accounts WHERE name = ?1 AND closed = 0",
                    [Value::Text(to.clone())],
                )?;
                if tr.len() == 0 { break "no account ".to_str() + to; }
                let fb = fr[0].get_int(0)?;
                let tb = tr[0].get_int(0)?;
                if fb < cents { break "insufficient funds".to_str(); }
                if tb > 9223372036854775807 - cents { break "overflow".to_str(); }
                db.exec("BEGIN", [])?;
                db.exec(
                    "UPDATE accounts SET balance = ?1, last = ?2 WHERE name = ?3",
                    [Value::Int(fb - cents), Value::Text(now.clone()), Value::Text(from.clone())],
                )?;
                db.exec(
                    "UPDATE accounts SET balance = ?1, last = ?2 WHERE name = ?3",
                    [Value::Int(tb + cents), Value::Text(now.clone()), Value::Text(to.clone())],
                )?;
                db.exec(
                    "INSERT INTO transfers (id, src, dst, cents) VALUES (?1, ?2, ?3, ?4)",
                    [Value::Text(id), Value::Text(from), Value::Text(to), Value::Int(cents)],
                )?;
                db.exec("COMMIT", [])?;
                break "".to_str();
            } else if op == "close" {
                if words.len() != 2 { break "malformed".to_str(); }
                let name = words[1].clone();
                let rows = db.query(
                    "SELECT balance FROM accounts WHERE name = ?1 AND closed = 0",
                    [Value::Text(name.clone())],
                )?;
                if rows.len() == 0 { break "no account ".to_str() + name; }
                if rows[0].get_int(0)? != 0 { break "balance not zero".to_str(); }
                db.exec(
                    "UPDATE accounts SET closed = 1 WHERE name = ?1",
                    [Value::Text(name)],
                )?;
                break "".to_str();
            }
            break "malformed".to_str();
        };
        if outcome == "" {
            ok = ok + 1;
        } else if outcome == "#dup" {
            dup = dup + 1;
        } else {
            failed = failed + 1;
            log.append(now.clone() + " line " + n.to_str() + ": " + outcome)?;
        }
    }
    let mut out = "ok ".to_str() + ok.to_str() + " failed " + failed.to_str() + " duplicate " + dup.to_str() + "\n";
    let rows = db.query(
        "SELECT name, balance, last FROM accounts WHERE closed = 0 ORDER BY CAST(name AS BLOB)",
        [],
    )?;
    for r in rows {
        out = out + r.get_text(0)? + " " + r.get_int(1)?.to_str() + " last " + r.get_text(2)? + "\n";
    }
    Ok(out)
}

fn json_resp(res: &Outgoing, status: i64, body: String) -> Str {
    res.status(status);
    res.header("content-type", "application/json");
    res.body(body.clone());
    body
}

fn err(res: &Outgoing, status: i64, msg: &str) -> Str {
    let mut m = Map::new();
    m.insert("error".to_string(), Json::String(msg.to_string()));
    json_resp(res, status, Json::Object(m).to_string())
}

fn valid_name(name: &str) -> bool {
    let n = name.len();
    if n < 3 || n > 20 {
        return false;
    }
    for c in name.chars() {
        if !(c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_') {
            return false;
        }
    }
    true
}

fn parse_creds(body: &str) -> Option<(String, String)> {
    match Json::parse(body) {
        Ok(Json::Object(m)) => {
            let name = match m.get("name") {
                Some(Json::String(s)) => s.clone(),
                _ => return None,
            };
            let pw = match m.get("password") {
                Some(Json::String(s)) => s.clone(),
                _ => return None,
            };
            Some((name, pw))
        }
        _ => None,
    }
}

fn hash_pw(name: &str, pw: &str) -> String {
    hex(sha256(format!("{}:{}", name, pw)))
}

fn to_int(s: &str) -> i64 {
    match s.parse::<i64>() {
        Ok(x) => x,
        Err(_) => 0,
    }
}

// user record: hash|logins|fails|lock_until
fn load_user(store: &Kv, name: &str) -> Option<(String, i64, i64, i64)> {
    match store.get(format!("user:{}", name)) {
        Some(v) => {
            let mut parts: Vec<String> = Vec::new();
            for p in v.split("|") {
                parts.push(p.to_string());
            }
            if parts.len() < 4 {
                return None;
            }
            Some((parts[0].clone(), to_int(&parts[1]), to_int(&parts[2]), to_int(&parts[3])))
        }
        None => None,
    }
}

fn save_user(store: &Kv, name: &str, hash: &str, logins: i64, fails: i64, lock: i64) {
    store.set(format!("user:{}", name), format!("{}|{}|{}|{}", hash, logins, fails, lock));
}

fn get_token(req: &Incoming) -> Option<String> {
    match req.header("authorization") {
        Some(a) => {
            let a = a.trim().to_string();
            match a.strip_prefix("Bearer ") {
                Some(t) => {
                    let t = t.trim().to_string();
                    if t.len() == 0 { None } else { Some(t) }
                }
                None => None,
            }
        }
        None => None,
    }
}

// session: name|expiry
fn load_session(store: &Kv, token: &str, now: i64) -> Option<String> {
    match store.get(format!("sess:{}", token)) {
        Some(v) => {
            let mut parts: Vec<String> = Vec::new();
            for p in v.split("|") {
                parts.push(p.to_string());
            }
            if parts.len() < 2 {
                return None;
            }
            let exp = to_int(&parts[1]);
            if now < exp {
                Some(parts[0].clone())
            } else {
                store.delete(format!("sess:{}", token));
                None
            }
        }
        None => None,
    }
}

fn main(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Str {
    let method = req.method();
    let full_path = req.path();
    let path = match full_path.split_once("?") {
        Some((p, _)) => p.to_string(),
        None => full_path.clone(),
    };
    let now = clock.now_ms();
    let session_ms: i64 = 30 * 60 * 1000;
    let lock_ms: i64 = 15 * 60 * 1000;

    if method == "POST" && path == "/users" {
        let body = req.body();
        let (name, pw) = match parse_creds(&body) {
            Some(c) => c,
            None => return err(&res, 400, "invalid"),
        };
        if !valid_name(&name) || pw.len() < 8 {
            return err(&res, 400, "invalid");
        }
        if load_user(&store, &name).is_some() {
            return err(&res, 409, "name taken");
        }
        save_user(&store, &name, &hash_pw(&name, &pw), 0, 0, 0);
        let mut m = Map::new();
        m.insert("name".to_string(), Json::String(name.clone()));
        return json_resp(&res, 201, Json::Object(m).to_string());
    }

    if method == "POST" && path == "/login" {
        let body = req.body();
        let (name, pw) = match parse_creds(&body) {
            Some(c) => c,
            None => return err(&res, 401, "bad credentials"),
        };
        let (hash, logins, fails, lock) = match load_user(&store, &name) {
            Some(u) => u,
            None => return err(&res, 401, "bad credentials"),
        };
        if now < lock {
            return err(&res, 429, "locked");
        }
        if hash_pw(&name, &pw) != hash {
            let f = fails + 1;
            if f >= 3 {
                save_user(&store, &name, &hash, logins, 0, now + lock_ms);
            } else {
                save_user(&store, &name, &hash, logins, f, lock);
            }
            return err(&res, 401, "bad credentials");
        }
        save_user(&store, &name, &hash, logins + 1, 0, 0);
        let token = hex(rng.bytes(16)).to_lowercase();
        store.set(format!("sess:{}", token), format!("{}|{}", name, now + session_ms));
        let mut m = Map::new();
        m.insert("token".to_string(), Json::String(token.clone()));
        m.insert("expires_in".to_string(), Json::Int(1800));
        return json_resp(&res, 200, Json::Object(m).to_string());
    }

    if method == "GET" && path == "/me" {
        let token = match get_token(&req) {
            Some(t) => t,
            None => return err(&res, 401, "unauthorized"),
        };
        let name = match load_session(&store, &token, now) {
            Some(n) => n,
            None => return err(&res, 401, "unauthorized"),
        };
        let logins = match load_user(&store, &name) {
            Some((_, l, _, _)) => l,
            None => return err(&res, 401, "unauthorized"),
        };
        store.set(format!("sess:{}", token), format!("{}|{}", name, now + session_ms));
        let mut m = Map::new();
        m.insert("name".to_string(), Json::String(name.clone()));
        m.insert("logins".to_string(), Json::Int(logins));
        return json_resp(&res, 200, Json::Object(m).to_string());
    }

    if method == "POST" && path == "/logout" {
        let token = match get_token(&req) {
            Some(t) => t,
            None => return err(&res, 401, "unauthorized"),
        };
        match load_session(&store, &token, now) {
            Some(_) => {}
            None => return err(&res, 401, "unauthorized"),
        };
        store.delete(format!("sess:{}", token));
        res.status(204);
        res.body("".to_string());
        return "".to_string();
    }

    err(&res, 404, "not found")
}

