fn handle(req: Incoming, store: Kv, clock: Clock, rng: Rng) -> (i64, Str) {
    let method = req.method();
    let full_path = req.path();
    let path = match full_path.split_once("?") {
        Some((p, _)) => p.to_string(),
        None => full_path.clone(),
    };
    let now = clock.now_ms();
    let session_ms: i64 = 30 * 60 * 1000;
    let lock_ms: i64 = 15 * 60 * 1000;

    if method == "POST" && path == "/users" {
        let body = req.body();
        let (name, pw) = match parse_creds(body) {
            Some(c) => c,
            None => return (400, err_body("invalid".to_string())),
        };
        if !valid_name(name.clone()) || pw.len() < 8 {
            return (400, err_body("invalid".to_string()));
        }
        let key = format!("user:{}", name);
        if store.get(key.clone()).is_some() {
            return (409, err_body("name taken".to_string()));
        }
        store.set(key, user_rec(hash_pw(name.clone(), pw), 0, 0, 0));
        let mut m = Map::new();
        m.insert("name".to_string(), Json::String(name));
        return (201, Json::Object(m).to_string());
    }

    if method == "POST" && path == "/login" {
        let body = req.body();
        let (name, pw) = match parse_creds(body) {
            Some(c) => c,
            None => return (401, err_body("bad credentials".to_string())),
        };
        let key = format!("user:{}", name);
        let rec = match store.get(key.clone()) {
            Some(v) => parse_user(v),
            None => None,
        };
        let (hash, logins, fails, lock) = match rec {
            Some(u) => u,
            None => return (401, err_body("bad credentials".to_string())),
        };
        if now < lock {
            return (429, err_body("locked".to_string()));
        }
        if hash_pw(name.clone(), pw) != hash {
            let f = fails + 1;
            if f >= 3 {
                store.set(key, user_rec(hash, logins, 0, now + lock_ms));
            } else {
                store.set(key, user_rec(hash, logins, f, lock));
            }
            return (401, err_body("bad credentials".to_string()));
        }
        store.set(key, user_rec(hash, logins + 1, 0, 0));
        let token = hex(rng.bytes(16)).to_lowercase();
        store.set(format!("sess:{}", token), format!("{}|{}", name, now + session_ms));
        let mut m = Map::new();
        m.insert("token".to_string(), Json::String(token));
        m.insert("expires_in".to_string(), Json::Int(1800));
        return (200, Json::Object(m).to_string());
    }

    if (method == "GET" && path == "/me") || (method == "POST" && path == "/logout") {
        let token = match token_from(req.header("authorization")) {
            Some(t) => t,
            None => return (401, err_body("unauthorized".to_string())),
        };
        let skey = format!("sess:{}", token);
        let sess = match store.get(skey.clone()) {
            Some(v) => parse_session(v),
            None => None,
        };
        let (name, exp) = match sess {
            Some(s) => s,
            None => return (401, err_body("unauthorized".to_string())),
        };
        if !(now < exp) {
            store.delete(skey);
            return (401, err_body("unauthorized".to_string()));
        }
        if path == "/logout" {
            store.delete(skey);
            return (204, "".to_string());
        }
        let rec = match store.get(format!("user:{}", name)) {
            Some(v) => parse_user(v),
            None => None,
        };
        let logins = match rec {
            Some((_, l, _, _)) => l,
            None => return (401, err_body("unauthorized".to_string())),
        };
        store.set(skey, format!("{}|{}", name, now + session_ms));
        let mut m = Map::new();
        m.insert("name".to_string(), Json::String(name));
        m.insert("logins".to_string(), Json::Int(logins));
        return (200, Json::Object(m).to_string());
    }

    (404, err_body("not found".to_string()))
}

fn main(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Str {
    let (status, body) = handle(req, store, clock, rng);
    res.status(status);
    if status == 204 {
        res.body("".to_string());
        return "".to_string();
    }
    res.header("content-type", "application/json");
    res.body(body.clone());
    body
}

