enum Json {
    Null,
    Bool(bool),
    Num(Str),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct Parser {
    c: Vec<char>,
    i: usize,
}

fn skip_ws(p: &mut Parser) {
    while p.i < p.c.len() {
        let ch = p.c[p.i];
        if ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' {
            p.i += 1;
        } else {
            break;
        }
    }
}

fn hex4(p: &mut Parser) -> Option<u32> {
    if p.i + 4 > p.c.len() {
        return None;
    }
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        let d = p.c[p.i].to_digit(16)?;
        v = v * 16 + d;
        p.i += 1;
        k += 1;
    }
    Some(v)
}

fn parse_string(p: &mut Parser) -> Option<Str> {
    if p.i >= p.c.len() || p.c[p.i] != '"' {
        return None;
    }
    p.i += 1;
    let mut out = Str::new();
    loop {
        if p.i >= p.c.len() {
            return None;
        }
        let ch = p.c[p.i];
        p.i += 1;
        if ch == '"' {
            return Some(out);
        }
        if (ch as u32) < 0x20 {
            return None;
        }
        if ch == '\\' {
            if p.i >= p.c.len() {
                return None;
            }
            let e = p.c[p.i];
            p.i += 1;
            if e == '"' {
                out.push('"');
            } else if e == '\\' {
                out.push('\\');
            } else if e == '/' {
                out.push('/');
            } else if e == 'b' {
                out.push('\u{8}');
            } else if e == 'f' {
                out.push('\u{c}');
            } else if e == 'n' {
                out.push('\n');
            } else if e == 'r' {
                out.push('\r');
            } else if e == 't' {
                out.push('\t');
            } else if e == 'u' {
                let mut cp = hex4(p)?;
                if cp >= 0xD800 && cp < 0xDC00 {
                    if p.i + 1 < p.c.len() && p.c[p.i] == '\\' && p.c[p.i + 1] == 'u' {
                        p.i += 2;
                        let lo = hex4(p)?;
                        if lo >= 0xDC00 && lo < 0xE000 {
                            cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                        } else {
                            return None;
                        }
                    } else {
                        return None;
                    }
                }
                let c2 = char::from_u32(cp)?;
                out.push(c2);
            } else {
                return None;
            }
        } else {
            out.push(ch);
        }
    }
}

fn is_digit(ch: char) -> bool {
    ch >= '0' && ch <= '9'
}

fn parse_number(p: &mut Parser) -> Option<Str> {
    let start = p.i;
    if p.i < p.c.len() && p.c[p.i] == '-' {
        p.i += 1;
    }
    if p.i >= p.c.len() || !is_digit(p.c[p.i]) {
        return None;
    }
    if p.c[p.i] == '0' {
        p.i += 1;
    } else {
        while p.i < p.c.len() && is_digit(p.c[p.i]) {
            p.i += 1;
        }
    }
    if p.i < p.c.len() && p.c[p.i] == '.' {
        p.i += 1;
        if p.i >= p.c.len() || !is_digit(p.c[p.i]) {
            return None;
        }
        while p.i < p.c.len() && is_digit(p.c[p.i]) {
            p.i += 1;
        }
    }
    if p.i < p.c.len() && (p.c[p.i] == 'e' || p.c[p.i] == 'E') {
        p.i += 1;
        if p.i < p.c.len() && (p.c[p.i] == '+' || p.c[p.i] == '-') {
            p.i += 1;
        }
        if p.i >= p.c.len() || !is_digit(p.c[p.i]) {
            return None;
        }
        while p.i < p.c.len() && is_digit(p.c[p.i]) {
            p.i += 1;
        }
    }
    let mut s = Str::new();
    let mut k = start;
    while k < p.i {
        s.push(p.c[k]);
        k += 1;
    }
    Some(s)
}

fn lit(p: &mut Parser, w: &str) -> bool {
    let wc: Vec<char> = w.chars().collect();
    if p.i + wc.len() > p.c.len() {
        return false;
    }
    let mut k = 0;
    while k < wc.len() {
        if p.c[p.i + k] != wc[k] {
            return false;
        }
        k += 1;
    }
    p.i += wc.len();
    true
}

fn parse_value(p: &mut Parser) -> Option<Json> {
    skip_ws(p);
    if p.i >= p.c.len() {
        return None;
    }
    let ch = p.c[p.i];
    if ch == '{' {
        p.i += 1;
        let mut items: Vec<(Str, Json)> = Vec::new();
        skip_ws(p);
        if p.i < p.c.len() && p.c[p.i] == '}' {
            p.i += 1;
            return Some(Json::Obj(items));
        }
        loop {
            skip_ws(p);
            let k = parse_string(p)?;
            skip_ws(p);
            if p.i >= p.c.len() || p.c[p.i] != ':' {
                return None;
            }
            p.i += 1;
            let v = parse_value(p)?;
            items.push((k, v));
            skip_ws(p);
            if p.i >= p.c.len() {
                return None;
            }
            if p.c[p.i] == ',' {
                p.i += 1;
            } else if p.c[p.i] == '}' {
                p.i += 1;
                return Some(Json::Obj(items));
            } else {
                return None;
            }
        }
    } else if ch == '[' {
        p.i += 1;
        let mut items: Vec<Json> = Vec::new();
        skip_ws(p);
        if p.i < p.c.len() && p.c[p.i] == ']' {
            p.i += 1;
            return Some(Json::Arr(items));
        }
        loop {
            let v = parse_value(p)?;
            items.push(v);
            skip_ws(p);
            if p.i >= p.c.len() {
                return None;
            }
            if p.c[p.i] == ',' {
                p.i += 1;
            } else if p.c[p.i] == ']' {
                p.i += 1;
                return Some(Json::Arr(items));
            } else {
                return None;
            }
        }
    } else if ch == '"' {
        let s = parse_string(p)?;
        Some(Json::Text(s))
    } else if ch == 't' {
        if lit(p, "true") { Some(Json::Bool(true)) } else { None }
    } else if ch == 'f' {
        if lit(p, "false") { Some(Json::Bool(false)) } else { None }
    } else if ch == 'n' {
        if lit(p, "null") { Some(Json::Null) } else { None }
    } else {
        let n = parse_number(p)?;
        Some(Json::Num(n))
    }
}

fn parse_json(s: &str) -> Option<Json> {
    let mut p = Parser { c: s.chars().collect(), i: 0 };
    let v = parse_value(&mut p)?;
    skip_ws(&mut p);
    if p.i != p.c.len() {
        return None;
    }
    Some(v)
}

fn json_str(s: &str) -> Str {
    let mut out = Str::new();
    out.push('"');
    for ch in s.chars() {
        if ch == '"' {
            out.push_str("\\\"");
        } else if ch == '\\' {
            out.push_str("\\\\");
        } else if ch == '\n' {
            out.push_str("\\n");
        } else if ch == '\r' {
            out.push_str("\\r");
        } else if ch == '\t' {
            out.push_str("\\t");
        } else if (ch as u32) < 0x20 {
            out.push_str(&format!("\\u{:04x}", ch as u32));
        } else {
            out.push(ch);
        }
    }
    out.push('"');
    out
}

fn canon(v: &Json) -> Str {
    match v {
        Json::Null => Str::from("null"),
        Json::Bool(b) => {
            if *b { Str::from("true") } else { Str::from("false") }
        }
        Json::Num(n) => n.clone(),
        Json::Text(s) => json_str(s),
        Json::Arr(items) => {
            let mut out = Str::from("[");
            let mut first = true;
            for it in items.iter() {
                if !first {
                    out.push(',');
                }
                first = false;
                out.push_str(&canon(it));
            }
            out.push(']');
            out
        }
        Json::Obj(items) => {
            let mut parts: Vec<(Str, Str)> = Vec::new();
            for (k, val) in items.iter() {
                parts.push((k.clone(), canon(val)));
            }
            let n = parts.len();
            let mut i = 1;
            while i < n {
                let mut j = i;
                while j > 0 && parts[j - 1].0 > parts[j].0 {
                    parts.swap(j - 1, j);
                    j -= 1;
                }
                i += 1;
            }
            let mut out = Str::from("{");
            let mut first = true;
            for (k, cv) in parts.iter() {
                if !first {
                    out.push(',');
                }
                first = false;
                out.push_str(&json_str(k));
                out.push(':');
                out.push_str(cv);
            }
            out.push('}');
            out
        }
    }
}

fn pos_int(v: &Json) -> Option<i64> {
    match v {
        Json::Num(n) => {
            for ch in n.chars() {
                if !is_digit(ch) {
                    return None;
                }
            }
            match n.parse::<i64>() {
                Ok(x) => {
                    if x > 0 { Some(x) } else { None }
                }
                Err(_) => None,
            }
        }
        _ => None,
    }
}

fn sql_str(s: &str) -> Str {
    let mut out = Str::from("'");
    for ch in s.chars() {
        if ch == '\'' {
            out.push_str("''");
        } else {
            out.push(ch);
        }
    }
    out.push('\'');
    out
}

fn err(msg: &str) -> Str {
    format!("{{\"error\":{}}}", json_str(msg))
}

fn hexval(ch: char) -> Option<u8> {
    match ch.to_digit(16) {
        Some(d) => Some(d as u8),
        None => None,
    }
}

fn url_decode(s: &str) -> Str {
    let c: Vec<char> = s.chars().collect();
    let mut bytes: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < c.len() {
        if c[i] == '+' {
            bytes.push(b' ');
            i += 1;
        } else if c[i] == '%' && i + 2 < c.len() + 0 && i + 2 <= c.len() - 1 {
            match (hexval(c[i + 1]), hexval(c[i + 2])) {
                (Some(a), Some(b)) => {
                    bytes.push(a * 16 + b);
                    i += 3;
                }
                _ => {
                    bytes.push(b'%');
                    i += 1;
                }
            }
        } else {
            let mut buf = [0u8; 4];
            let enc = c[i].encode_utf8(&mut buf);
            for b in enc.bytes() {
                bytes.push(b);
            }
            i += 1;
        }
    }
    String::from_utf8_lossy(&bytes).to_string()
}

fn payment_json(id: i64, account: &str, cents: i64, currency: &str, status: &str, refunded: i64) -> Str {
    format!(
        "{{\"id\":\"pay_{}\",\"account\":{},\"cents\":{},\"currency\":{},\"status\":{},\"refunded\":{}}}",
        id,
        json_str(account),
        cents,
        json_str(currency),
        json_str(status),
        refunded
    )
}

struct Pay {
    id: i64,
    account: Str,
    cents: i64,
    currency: Str,
    status: Str,
    refunded: i64,
}

fn pay_to_json(p: &Pay) -> Str {
    payment_json(p.id, &p.account, p.cents, &p.currency, &p.status, p.refunded)
}

fn parse_pay_id(s: &str) -> Option<i64> {
    if !s.starts_with("pay_") {
        return None;
    }
    let rest = &s[4..];
    if rest.len() == 0 || rest.len() > 18 {
        return None;
    }
    for ch in rest.chars() {
        if !is_digit(ch) {
            return None;
        }
    }
    match rest.parse::<i64>() {
        Ok(n) => Some(n),
        Err(_) => None,
    }
}

fn load(db: &Db, id: i64) -> Result<Option<Pay>, Str> {
    let rows = db
        .query(&format!(
            "SELECT id, account, cents, currency, status, refunded FROM payments WHERE id = {}",
            id
        ))
        .map_err(|e| e.to_string())?;
    if rows.len() == 0 {
        return Ok(None);
    }
    let r = &rows[0];
    Ok(Some(Pay {
        id: r.get_int(0),
        account: r.get_str(1),
        cents: r.get_int(2),
        currency: r.get_str(3),
        status: r.get_str(4),
        refunded: r.get_int(5),
    }))
}

fn set_status(db: &Db, id: i64, status: &str, refunded: i64) -> Result<(), Str> {
    db.exec(&format!(
        "UPDATE payments SET status = {}, refunded = {} WHERE id = {}",
        sql_str(status),
        refunded,
        id
    ))
    .map_err(|e| e.to_string())?;
    Ok(())
}

fn handle(db: &Db, method: &str, path: &str, query: &str, body: &str) -> Result<(i64, Str), Str> {
    let segs: Vec<&str> = path.split('/').filter(|s| s.len() > 0).collect();
    if segs.len() == 0 || segs[0] != "payments" {
        return Ok((404, err("not found")));
    }
    if segs.len() == 1 {
        if method == "POST" {
            let v = match parse_json(body) {
                Some(v) => v,
                None => return Ok((422, err("invalid payment"))),
            };
            let mut account: Option<Str> = None;
            let mut cents: Option<i64> = None;
            let mut currency: Option<Str> = None;
            let mut ok = true;
            match &v {
                Json::Obj(items) => {
                    for (k, val) in items.iter() {
                        if k == "account" {
                            match val {
                                Json::Text(s) => {
                                    if s.len() > 0 { account = Some(s.clone()); } else { ok = false; }
                                }
                                _ => ok = false,
                            }
                        } else if k == "cents" {
                            match pos_int(val) {
                                Some(n) => cents = Some(n),
                                None => ok = false,
                            }
                        } else if k == "currency" {
                            match val {
                                Json::Text(s) => {
                                    if s == "EUR" || s == "USD" { currency = Some(s.clone()); } else { ok = false; }
                                }
                                _ => ok = false,
                            }
                        } else {
                            ok = false;
                        }
                    }
                }
                _ => ok = false,
            }
            if !ok || account.is_none() || cents.is_none() || currency.is_none() {
                return Ok((422, err("invalid payment")));
            }
            let a = account.unwrap();
            let c = cents.unwrap();
            let cur = currency.unwrap();
            db.exec(&format!(
                "INSERT INTO payments (account, cents, currency, status, refunded) VALUES ({}, {}, {}, 'pending', 0)",
                sql_str(&a),
                c,
                sql_str(&cur)
            ))
            .map_err(|e| e.to_string())?;
            let rows = db
                .query("SELECT MAX(id) FROM payments")
                .map_err(|e| e.to_string())?;
            let id = rows[0].get_int(0);
            return Ok((201, payment_json(id, &a, c, &cur, "pending", 0)));
        }
        if method == "GET" {
            let mut account = Str::new();
            for part in query.split('&') {
                if part.starts_with("account=") {
                    account = url_decode(&part[8..]);
                }
            }
            let rows = db
                .query(&format!(
                    "SELECT id, account, cents, currency, status, refunded FROM payments WHERE account = {} ORDER BY id",
                    sql_str(&account)
                ))
                .map_err(|e| e.to_string())?;
            let mut out = Str::from("[");
            let mut first = true;
            for r in rows.iter() {
                if !first {
                    out.push(',');
                }
                first = false;
                out.push_str(&payment_json(
                    r.get_int(0),
                    &r.get_str(1),
                    r.get_int(2),
                    &r.get_str(3),
                    &r.get_str(4),
                    r.get_int(5),
                ));
            }
            out.push(']');
            return Ok((200, out));
        }
        return Ok((404, err("not found")));
    }
    let id = match parse_pay_id(segs[1]) {
        Some(n) => n,
        None => return Ok((404, err("not found"))),
    };
    if segs.len() == 2 {
        if method != "GET" {
            return Ok((404, err("not found")));
        }
        return match load(db, id)? {
            Some(p) => Ok((200, pay_to_json(&p))),
            None => Ok((404, err("not found"))),
        };
    }
    if segs.len() != 3 || method != "POST" {
        return Ok((404, err("not found")));
    }
    let action = segs[2];
    if action != "capture" && action != "cancel" && action != "refund" {
        return Ok((404, err("not found")));
    }
    let mut p = match load(db, id)? {
        Some(p) => p,
        None => return Ok((404, err("not found"))),
    };
    if action == "capture" {
        if p.status == "pending" {
            set_status(db, id, "captured", p.refunded)?;
            p.status = Str::from("captured");
            return Ok((200, pay_to_json(&p)));
        }
        if p.status == "captured" {
            return Ok((200, pay_to_json(&p)));
        }
        return Ok((409, err("invalid transition")));
    }
    if action == "cancel" {
        if p.status == "pending" {
            set_status(db, id, "canceled", p.refunded)?;
            p.status = Str::from("canceled");
            return Ok((200, pay_to_json(&p)));
        }
        return Ok((409, err("invalid transition")));
    }
    // refund
    let mut amount: Option<i64> = None;
    match parse_json(body) {
        Some(Json::Obj(items)) => {
            for (k, val) in items.iter() {
                if k == "cents" {
                    amount = pos_int(val);
                }
            }
        }
        _ => {}
    }
    let n = match amount {
        Some(n) => n,
        None => return Ok((422, err("invalid refund"))),
    };
    if p.status != "captured" {
        return Ok((409, err("invalid transition")));
    }
    if p.refunded + n > p.cents {
        return Ok((409, err("exceeds captured")));
    }
    p.refunded = p.refunded + n;
    if p.refunded == p.cents {
        p.status = Str::from("refunded");
    }
    set_status(db, id, &p.status, p.refunded)?;
    Ok((200, pay_to_json(&p)))
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, Str> {
    db.exec("CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)")
        .map_err(|e| e.to_string())?;
    db.exec("CREATE TABLE IF NOT EXISTS idem (k TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL, status INTEGER NOT NULL, resp TEXT NOT NULL)")
        .map_err(|e| e.to_string())?;

    let method = req.method().to_string().to_uppercase();
    let full = req.path().to_string();
    let (path, query) = match full.find('?') {
        Some(i) => (full[..i].to_string(), full[i + 1..].to_string()),
        None => (full.clone(), Str::new()),
    };
    let body = req.body().to_string();

    let segs: Vec<&str> = path.split('/').filter(|s| s.len() > 0).collect();
    let needs_key = method == "POST"
        && ((segs.len() == 1 && segs[0] == "payments")
            || (segs.len() == 3 && segs[0] == "payments" && segs[2] == "refund"));

    let mut status: i64 = 0;
    let mut out = Str::new();
    let mut done = false;
    let mut key: Option<Str> = None;
    let canon_body = match parse_json(&body) {
        Some(v) => canon(&v),
        None => body.clone(),
    };

    if needs_key {
        match req.header("idempotency-key") {
            Some(k) => {
                let k = k.to_string();
                let rows = db
                    .query(&format!(
                        "SELECT method, path, body, status, resp FROM idem WHERE k = {}",
                        sql_str(&k)
                    ))
                    .map_err(|e| e.to_string())?;
                if rows.len() > 0 {
                    let r = &rows[0];
                    if r.get_str(0) == method && r.get_str(1) == full && r.get_str(2) == canon_body {
                        status = r.get_int(3);
                        out = r.get_str(4);
                    } else {
                        status = 409;
                        out = err("key reused");
                    }
                    done = true;
                }
                key = Some(k);
            }
            None => {
                status = 400;
                out = err("missing idempotency key");
                done = true;
            }
        }
    }

    if !done {
        let (s, b) = handle(&db, &method, &path, &query, &body)?;
        status = s;
        out = b;
        if let Some(k) = key {
            if status >= 200 && status < 300 {
                db.exec(&format!(
                    "INSERT OR REPLACE INTO idem (k, method, path, body, status, resp) VALUES ({}, {}, {}, {}, {}, {})",
                    sql_str(&k),
                    sql_str(&method),
                    sql_str(&full),
                    sql_str(&canon_body),
                    status,
                    sql_str(&out)
                ))
                .map_err(|e| e.to_string())?;
            }
        }
    }

    res.status(status as u16);
    res.header("content-type", "application/json");
    Ok(out)
}

enum Json {
    Null,
    Bool(bool),
    Num(Str),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct Parser {
    c: Vec<char>,
    i: usize,
}

fn skip_ws(mut p: Parser) -> Parser {
    while p.i < p.c.len() {
        let ch = p.c[p.i];
        if ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' {
            p.i += 1;
        } else {
            break;
        }
    }
    p
}

fn hex4(mut p: Parser) -> Option<(Parser, u32)> {
    if p.i + 4 > p.c.len() {
        return None;
    }
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        let d = p.c[p.i].to_digit(16)?;
        v = v * 16 + d;
        p.i += 1;
        k += 1;
    }
    Some((p, v))
}

fn parse_string(mut p: Parser) -> Option<(Parser, Str)> {
    if p.i >= p.c.len() || p.c[p.i] != '"' {
        return None;
    }
    p.i += 1;
    let mut out = Str::new();
    loop {
        if p.i >= p.c.len() {
            return None;
        }
        let ch = p.c[p.i];
        p.i += 1;
        if ch == '"' {
            return Some((p, out));
        }
        if (ch as u32) < 0x20 {
            return None;
        }
        if ch == '\\' {
            if p.i >= p.c.len() {
                return None;
            }
            let e = p.c[p.i];
            p.i += 1;
            if e == '"' {
                out.push('"');
            } else if e == '\\' {
                out.push('\\');
            } else if e == '/' {
                out.push('/');
            } else if e == 'b' {
                out.push('\u{8}');
            } else if e == 'f' {
                out.push('\u{c}');
            } else if e == 'n' {
                out.push('\n');
            } else if e == 'r' {
                out.push('\r');
            } else if e == 't' {
                out.push('\t');
            } else if e == 'u' {
                let (p2, first) = hex4(p)?;
                p = p2;
                let mut cp = first;
                if cp >= 0xD800 && cp < 0xDC00 {
                    if p.i + 1 < p.c.len() && p.c[p.i] == '\\' && p.c[p.i + 1] == 'u' {
                        p.i += 2;
                        let (p3, lo) = hex4(p)?;
                        p = p3;
                        if lo >= 0xDC00 && lo < 0xE000 {
                            cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                        } else {
                            return None;
                        }
                    } else {
                        return None;
                    }
                }
                let c2 = char::from_u32(cp)?;
                out.push(c2);
            } else {
                return None;
            }
        } else {
            out.push(ch);
        }
    }
}

fn is_digit(ch: char) -> bool {
    ch >= '0' && ch <= '9'
}

fn parse_number(mut p: Parser) -> Option<(Parser, Str)> {
    let start = p.i;
    if p.i < p.c.len() && p.c[p.i] == '-' {
        p.i += 1;
    }
    if p.i >= p.c.len() || !is_digit(p.c[p.i]) {
        return None;
    }
    if p.c[p.i] == '0' {
        p.i += 1;
    } else {
        while p.i < p.c.len() && is_digit(p.c[p.i]) {
            p.i += 1;
        }
    }
    if p.i < p.c.len() && p.c[p.i] == '.' {
        p.i += 1;
        if p.i >= p.c.len() || !is_digit(p.c[p.i]) {
            return None;
        }
        while p.i < p.c.len() && is_digit(p.c[p.i]) {
            p.i += 1;
        }
    }
    if p.i < p.c.len() && (p.c[p.i] == 'e' || p.c[p.i] == 'E') {
        p.i += 1;
        if p.i < p.c.len() && (p.c[p.i] == '+' || p.c[p.i] == '-') {
            p.i += 1;
        }
        if p.i >= p.c.len() || !is_digit(p.c[p.i]) {
            return None;
        }
        while p.i < p.c.len() && is_digit(p.c[p.i]) {
            p.i += 1;
        }
    }
    let mut s = Str::new();
    let mut k = start;
    while k < p.i {
        s.push(p.c[k]);
        k += 1;
    }
    Some((p, s))
}

fn lit(mut p: Parser, w: Str) -> Option<Parser> {
    let wc: Vec<char> = w.chars().collect();
    if p.i + wc.len() > p.c.len() {
        return None;
    }
    let mut k = 0;
    while k < wc.len() {
        if p.c[p.i + k] != wc[k] {
            return None;
        }
        k += 1;
    }
    p.i += wc.len();
    Some(p)
}

fn parse_value(p0: Parser) -> Option<(Parser, Json)> {
    let mut p = skip_ws(p0);
    if p.i >= p.c.len() {
        return None;
    }
    let ch = p.c[p.i];
    if ch == '{' {
        p.i += 1;
        let mut items: Vec<(Str, Json)> = Vec::new();
        p = skip_ws(p);
        if p.i < p.c.len() && p.c[p.i] == '}' {
            p.i += 1;
            return Some((p, Json::Obj(items)));
        }
        loop {
            p = skip_ws(p);
            let (p2, k) = parse_string(p)?;
            p = skip_ws(p2);
            if p.i >= p.c.len() || p.c[p.i] != ':' {
                return None;
            }
            p.i += 1;
            let (p3, v) = parse_value(p)?;
            p = skip_ws(p3);
            items.push((k, v));
            if p.i >= p.c.len() {
                return None;
            }
            if p.c[p.i] == ',' {
                p.i += 1;
            } else if p.c[p.i] == '}' {
                p.i += 1;
                return Some((p, Json::Obj(items)));
            } else {
                return None;
            }
        }
    } else if ch == '[' {
        p.i += 1;
        let mut items: Vec<Json> = Vec::new();
        p = skip_ws(p);
        if p.i < p.c.len() && p.c[p.i] == ']' {
            p.i += 1;
            return Some((p, Json::Arr(items)));
        }
        loop {
            let (p2, v) = parse_value(p)?;
            p = skip_ws(p2);
            items.push(v);
            if p.i >= p.c.len() {
                return None;
            }
            if p.c[p.i] == ',' {
                p.i += 1;
            } else if p.c[p.i] == ']' {
                p.i += 1;
                return Some((p, Json::Arr(items)));
            } else {
                return None;
            }
        }
    } else if ch == '"' {
        let (p2, s) = parse_string(p)?;
        Some((p2, Json::Text(s)))
    } else if ch == 't' {
        let p2 = lit(p, Str::from("true"))?;
        Some((p2, Json::Bool(true)))
    } else if ch == 'f' {
        let p2 = lit(p, Str::from("false"))?;
        Some((p2, Json::Bool(false)))
    } else if ch == 'n' {
        let p2 = lit(p, Str::from("null"))?;
        Some((p2, Json::Null))
    } else {
        let (p2, n) = parse_number(p)?;
        Some((p2, Json::Num(n)))
    }
}

fn parse_json(s: Str) -> Option<Json> {
    let p = Parser { c: s.chars().collect(), i: 0 };
    let (p2, v) = parse_value(p)?;
    let p3 = skip_ws(p2);
    if p3.i != p3.c.len() {
        return None;
    }
    Some(v)
}

fn hexd(n: u32) -> char {
    let d: Vec<char> = "0123456789abcdef".chars().collect();
    d[n as usize]
}

fn json_str(s: Str) -> Str {
    let mut out = Str::new();
    out.push('"');
    for ch in s.chars() {
        if ch == '"' {
            out.push('\\');
            out.push('"');
        } else if ch == '\\' {
            out.push('\\');
            out.push('\\');
        } else if ch == '\n' {
            out.push('\\');
            out.push('n');
        } else if ch == '\r' {
            out.push('\\');
            out.push('r');
        } else if ch == '\t' {
            out.push('\\');
            out.push('t');
        } else if (ch as u32) < 0x20 {
            let v = ch as u32;
            out.push('\\');
            out.push('u');
            out.push('0');
            out.push('0');
            out.push(hexd(v / 16));
            out.push(hexd(v % 16));
        } else {
            out.push(ch);
        }
    }
    out.push('"');
    out
}

fn canon(v: Json) -> Str {
    match v {
        Json::Null => Str::from("null"),
        Json::Bool(b) => {
            if b { Str::from("true") } else { Str::from("false") }
        }
        Json::Num(n) => n,
        Json::Text(s) => json_str(s),
        Json::Arr(items) => {
            let mut out = Str::from("[");
            let mut first = true;
            for it in items {
                if !first {
                    out.push(',');
                }
                first = false;
                out.push_str(canon(it));
            }
            out.push(']');
            out
        }
        Json::Obj(items) => {
            let mut parts: Vec<(Str, Str)> = Vec::new();
            for (k, val) in items {
                parts.push((k, canon(val)));
            }
            let n = parts.len();
            let mut i = 1;
            while i < n {
                let mut j = i;
                while j > 0 && parts[j - 1].0 > parts[j].0 {
                    parts.swap(j - 1, j);
                    j -= 1;
                }
                i += 1;
            }
            let mut out = Str::from("{");
            let mut first = true;
            for (k, cv) in parts {
                if !first {
                    out.push(',');
                }
                first = false;
                out.push_str(json_str(k));
                out.push(':');
                out.push_str(cv);
            }
            out.push('}');
            out
        }
    }
}

fn pos_int(v: Json) -> Option<i64> {
    match v {
        Json::Num(n) => {
            if n.len() == 0 || n.len() > 15 {
                return None;
            }
            let mut x: i64 = 0;
            for ch in n.chars() {
                if !is_digit(ch) {
                    return None;
                }
                x = x * 10 + (ch as i64 - '0' as i64);
            }
            if x > 0 { Some(x) } else { None }
        }
        _ => None,
    }
}

fn sql_str(s: Str) -> Str {
    let mut out = Str::from("'");
    for ch in s.chars() {
        if ch == '\'' {
            out.push('\'');
            out.push('\'');
        } else {
            out.push(ch);
        }
    }
    out.push('\'');
    out
}

fn err(msg: Str) -> Str {
    format!("{{\"error\":{}}}", json_str(msg))
}

fn flush_bytes(buf: Vec<u8>, mut out: Str) -> Str {
    let mut i = 0;
    let n = buf.len();
    while i < n {
        let b0 = buf[i] as u32;
        let mut need = 0;
        let mut cp: u32 = 0;
        if b0 < 0x80 {
            cp = b0;
        } else if b0 >= 0xC0 && b0 < 0xE0 {
            need = 1;
            cp = b0 & 0x1F;
        } else if b0 >= 0xE0 && b0 < 0xF0 {
            need = 2;
            cp = b0 & 0x0F;
        } else if b0 >= 0xF0 && b0 < 0xF8 {
            need = 3;
            cp = b0 & 0x07;
        } else {
            out.push('\u{FFFD}');
            i += 1;
            continue;
        }
        if i + need >= n + 0 && need > 0 && i + need > n - 1 {
            out.push('\u{FFFD}');
            i += 1;
            continue;
        }
        let mut k = 1;
        let mut good = true;
        while k <= need {
            let b = buf[i + k] as u32;
            if b < 0x80 || b >= 0xC0 {
                good = false;
                break;
            }
            cp = (cp << 6) | (b & 0x3F);
            k += 1;
        }
        if !good {
            out.push('\u{FFFD}');
            i += 1;
            continue;
        }
        match char::from_u32(cp) {
            Some(c) => out.push(c),
            None => out.push('\u{FFFD}'),
        }
        i += need + 1;
    }
    out
}

fn url_decode(s: Str) -> Str {
    let c: Vec<char> = s.chars().collect();
    let mut out = Str::new();
    let mut buf: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < c.len() {
        if c[i] == '%' && i + 2 < c.len() + 0 + 0 && i + 2 <= c.len() - 1 {
            match (c[i + 1].to_digit(16), c[i + 2].to_digit(16)) {
                (Some(a), Some(b)) => {
                    buf.push((a * 16 + b) as u8);
                    i += 3;
                    continue;
                }
                _ => {}
            }
        }
        if buf.len() > 0 {
            out = flush_bytes(buf, out);
            buf = Vec::new();
        }
        if c[i] == '+' {
            out.push(' ');
        } else {
            out.push(c[i]);
        }
        i += 1;
    }
    if buf.len() > 0 {
        out = flush_bytes(buf, out);
    }
    out
}

fn payment_json(id: i64, account: Str, cents: i64, currency: Str, status: Str, refunded: i64) -> Str {
    format!(
        "{{\"id\":\"pay_{}\",\"account\":{},\"cents\":{},\"currency\":{},\"status\":{},\"refunded\":{}}}",
        id,
        json_str(account),
        cents,
        json_str(currency),
        json_str(status),
        refunded
    )
}

struct Pay {
    id: i64,
    account: Str,
    cents: i64,
    currency: Str,
    status: Str,
    refunded: i64,
}

fn pay_to_json(p: Pay) -> Str {
    payment_json(p.id, p.account, p.cents, p.currency, p.status, p.refunded)
}

fn parse_pay_id(s: Str) -> Option<i64> {
    let c: Vec<char> = s.chars().collect();
    if c.len() < 5 || c.len() > 19 {
        return None;
    }
    if c[0] != 'p' || c[1] != 'a' || c[2] != 'y' || c[3] != '_' {
        return None;
    }
    let mut x: i64 = 0;
    let mut i = 4;
    while i < c.len() {
        if !is_digit(c[i]) {
            return None;
        }
        x = x * 10 + (c[i] as i64 - '0' as i64);
        i += 1;
    }
    Some(x)
}

fn split_on(s: Str, sep: char) -> Vec<Str> {
    let mut segs: Vec<Str> = Vec::new();
    let mut cur = Str::new();
    for ch in s.chars() {
        if ch == sep {
            if cur.len() > 0 {
                segs.push(cur);
                cur = Str::new();
            }
        } else {
            cur.push(ch);
        }
    }
    if cur.len() > 0 {
        segs.push(cur);
    }
    segs
}

fn query_account(q: Str) -> Str {
    let mut account = Str::new();
    for part in split_on(q, '&') {
        let pc: Vec<char> = part.chars().collect();
        let pre: Vec<char> = "account=".chars().collect();
        if pc.len() >= pre.len() {
            let mut same = true;
            let mut k = 0;
            while k < pre.len() {
                if pc[k] != pre[k] {
                    same = false;
                    break;
                }
                k += 1;
            }
            if same {
                let mut raw = Str::new();
                let mut j = pre.len();
                while j < pc.len() {
                    raw.push(pc[j]);
                    j += 1;
                }
                account = url_decode(raw);
            }
        }
    }
    account
}

fn handle(db: Db, method: Str, path: Str, query: Str, body: Str) -> Result<(Db, i64, Str), Str> {
    let segs = split_on(path, '/');
    if segs.len() == 0 || segs[0] != "payments" {
        return Ok((db, 404, err(Str::from("not found"))));
    }
    if segs.len() == 1 {
        if method == "POST" {
            let mut account: Option<Str> = None;
            let mut cents: Option<i64> = None;
            let mut currency: Option<Str> = None;
            let mut ok = true;
            match parse_json(body) {
                Some(Json::Obj(items)) => {
                    for (k, val) in items {
                        if k == "account" {
                            match val {
                                Json::Text(s) => {
                                    if s.len() > 0 {
                                        account = Some(s);
                                    } else {
                                        ok = false;
                                    }
                                }
                                _ => {
                                    ok = false;
                                }
                            }
                        } else if k == "cents" {
                            match pos_int(val) {
                                Some(n) => {
                                    cents = Some(n);
                                }
                                None => {
                                    ok = false;
                                }
                            }
                        } else if k == "currency" {
                            match val {
                                Json::Text(s) => {
                                    if s == "EUR" || s == "USD" {
                                        currency = Some(s);
                                    } else {
                                        ok = false;
                                    }
                                }
                                _ => {
                                    ok = false;
                                }
                            }
                        } else {
                            ok = false;
                        }
                    }
                }
                _ => {
                    ok = false;
                }
            }
            if !ok {
                return Ok((db, 422, err(Str::from("invalid payment"))));
            }
            let a = match account {
                Some(x) => x,
                None => return Ok((db, 422, err(Str::from("invalid payment")))),
            };
            let c = match cents {
                Some(x) => x,
                None => return Ok((db, 422, err(Str::from("invalid payment")))),
            };
            let cur = match currency {
                Some(x) => x,
                None => return Ok((db, 422, err(Str::from("invalid payment")))),
            };
            db.exec(format!(
                "INSERT INTO payments (account, cents, currency, status, refunded) VALUES ({}, {}, {}, 'pending', 0)",
                sql_str(a.clone()),
                c,
                sql_str(cur.clone())
            ))
            .map_err(|e| e.to_string())?;
            let rows = db
                .query(Str::from("SELECT MAX(id) FROM payments"))
                .map_err(|e| e.to_string())?;
            let id = rows[0].get_int(0);
            let out = payment_json(id, a, c, cur, Str::from("pending"), 0);
            return Ok((db, 201, out));
        }
        if method == "GET" {
            let account = query_account(query);
            let rows = db
                .query(format!(
                    "SELECT id, account, cents, currency, status, refunded FROM payments WHERE account = {} ORDER BY id",
                    sql_str(account)
                ))
                .map_err(|e| e.to_string())?;
            let mut out = Str::from("[");
            let mut first = true;
            for r in rows {
                if !first {
                    out.push(',');
                }
                first = false;
                out.push_str(payment_json(
                    r.get_int(0),
                    r.get_str(1),
                    r.get_int(2),
                    r.get_str(3),
                    r.get_str(4),
                    r.get_int(5),
                ));
            }
            out.push(']');
            return Ok((db, 200, out));
        }
        return Ok((db, 404, err(Str::from("not found"))));
    }
    if segs.len() > 3 {
        return Ok((db, 404, err(Str::from("not found"))));
    }
    if segs.len() == 2 && method != "GET" {
        return Ok((db, 404, err(Str::from("not found"))));
    }
    let mut action = Str::new();
    if segs.len() == 3 {
        action = segs[2].clone();
        if method != "POST" || (action != "capture" && action != "cancel" && action != "refund") {
            return Ok((db, 404, err(Str::from("not found"))));
        }
    }
    let id = match parse_pay_id(segs[1].clone()) {
        Some(n) => n,
        None => return Ok((db, 404, err(Str::from("not found")))),
    };
    let rows = db
        .query(format!(
            "SELECT id, account, cents, currency, status, refunded FROM payments WHERE id = {}",
            id
        ))
        .map_err(|e| e.to_string())?;
    if rows.len() == 0 {
        return Ok((db, 404, err(Str::from("not found"))));
    }
    let mut p = Pay {
        id: rows[0].get_int(0),
        account: rows[0].get_str(1),
        cents: rows[0].get_int(2),
        currency: rows[0].get_str(3),
        status: rows[0].get_str(4),
        refunded: rows[0].get_int(5),
    };
    if segs.len() == 2 {
        return Ok((db, 200, pay_to_json(p)));
    }
    if action == "capture" {
        if p.status == "pending" {
            db.exec(format!("UPDATE payments SET status = 'captured' WHERE id = {}", id))
                .map_err(|e| e.to_string())?;
            p.status = Str::from("captured");
            return Ok((db, 200, pay_to_json(p)));
        }
        if p.status == "captured" {
            return Ok((db, 200, pay_to_json(p)));
        }
        return Ok((db, 409, err(Str::from("invalid transition"))));
    }
    if action == "cancel" {
        if p.status == "pending" {
            db.exec(format!("UPDATE payments SET status = 'canceled' WHERE id = {}", id))
                .map_err(|e| e.to_string())?;
            p.status = Str::from("canceled");
            return Ok((db, 200, pay_to_json(p)));
        }
        return Ok((db, 409, err(Str::from("invalid transition"))));
    }
    let mut amount: Option<i64> = None;
    let mut ok = true;
    match parse_json(body) {
        Some(Json::Obj(items)) => {
            for (k, val) in items {
                if k == "cents" {
                    amount = pos_int(val);
                    if amount.is_none() {
                        ok = false;
                    }
                }
            }
        }
        _ => {
            ok = false;
        }
    }
    let n = match amount {
        Some(n) => n,
        None => return Ok((db, 422, err(Str::from("invalid refund")))),
    };
    if !ok {
        return Ok((db, 422, err(Str::from("invalid refund"))));
    }
    if p.status != "captured" {
        return Ok((db, 409, err(Str::from("invalid transition"))));
    }
    if p.refunded + n > p.cents {
        return Ok((db, 409, err(Str::from("exceeds captured"))));
    }
    p.refunded = p.refunded + n;
    if p.refunded == p.cents {
        p.status = Str::from("refunded");
    }
    db.exec(format!(
        "UPDATE payments SET status = {}, refunded = {} WHERE id = {}",
        sql_str(p.status.clone()),
        p.refunded,
        id
    ))
    .map_err(|e| e.to_string())?;
    Ok((db, 200, pay_to_json(p)))
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, Str> {
    db.exec(Str::from("CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)"))
        .map_err(|e| e.to_string())?;
    db.exec(Str::from("CREATE TABLE IF NOT EXISTS idem (k TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL, status INTEGER NOT NULL, resp TEXT NOT NULL)"))
        .map_err(|e| e.to_string())?;

    let method = req.method().to_string().to_uppercase();
    let full = req.path().to_string();
    let mut path = Str::new();
    let mut query = Str::new();
    let mut inq = false;
    for ch in full.chars() {
        if inq {
            query.push(ch);
        } else if ch == '?' {
            inq = true;
        } else {
            path.push(ch);
        }
    }
    let body = req.body().to_string();

    let segs = split_on(path.clone(), '/');
    let needs_key = method == "POST"
        && ((segs.len() == 1 && segs[0] == "payments")
            || (segs.len() == 3 && segs[0] == "payments" && segs[2] == "refund"));

    let canon_body = match parse_json(body.clone()) {
        Some(v) => canon(v),
        None => body.clone(),
    };

    let mut status: i64 = 0;
    let mut out = Str::new();
    let mut done = false;
    let mut key: Option<Str> = None;

    if needs_key {
        let hk: Option<Str> = match req.header("idempotency-key") {
            Some(k0) => {
                let k = k0.to_string();
                if k.len() > 0 { Some(k) } else { None }
            }
            None => None,
        };
        match hk {
            Some(k) => {
                let rows = db
                    .query(format!(
                        "SELECT method, path, body, status, resp FROM idem WHERE k = {}",
                        sql_str(k.clone())
                    ))
                    .map_err(|e| e.to_string())?;
                if rows.len() > 0 {
                    if rows[0].get_str(0) == method && rows[0].get_str(1) == full && rows[0].get_str(2) == canon_body {
                        status = rows[0].get_int(3);
                        out = rows[0].get_str(4);
                    } else {
                        status = 409;
                        out = err(Str::from("key reused"));
                    }
                    done = true;
                }
                key = Some(k);
            }
            None => {
                status = 400;
                out = err(Str::from("missing idempotency key"));
                done = true;
            }
        }
    }

    if !done {
        let (db2, s, b) = handle(db, method.clone(), path, query, body)?;
        status = s;
        out = b;
        match key {
            Some(k) => {
                if status >= 200 && status < 300 {
                    db2.exec(format!(
                        "INSERT OR REPLACE INTO idem (k, method, path, body, status, resp) VALUES ({}, {}, {}, {}, {}, {})",
                        sql_str(k),
                        sql_str(method.clone()),
                        sql_str(full.clone()),
                        sql_str(canon_body.clone()),
                        status,
                        sql_str(out.clone())
                    ))
                    .map_err(|e| e.to_string())?;
                }
            }
            None => {}
        }
    }

    res.status(status as u16);
    res.header("content-type", "application/json");
    Ok(out)
}

enum Json {
    Null,
    Bool(bool),
    Num(Str),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct Parser {
    c: Vec<Str>,
    i: usize,
}

fn ascii_table() -> Vec<Str> {
    Str::from(" !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~")
        .chars()
        .collect()
}

fn digit_val(s: Str) -> Option<i64> {
    let mut k: i64 = 0;
    for d in Str::from("0123456789").chars() {
        if d == s {
            return Some(k);
        }
        k += 1;
    }
    None
}

fn is_digit(s: Str) -> bool {
    digit_val(s).is_some()
}

fn hex_val(s: Str) -> Option<u32> {
    let mut k: u32 = 0;
    for d in Str::from("0123456789abcdef").chars() {
        if d == s {
            return Some(k);
        }
        k += 1;
    }
    k = 10;
    for d in Str::from("ABCDEF").chars() {
        if d == s {
            return Some(k);
        }
        k += 1;
    }
    None
}

fn skip_ws(mut p: Parser) -> Parser {
    while p.i < p.c.len() {
        let ch = p.c[p.i].clone();
        if ch == " " || ch == "\n" || ch == "\r" || ch == "\t" {
            p.i += 1;
        } else {
            break;
        }
    }
    p
}

fn hex4(mut p: Parser) -> Option<(Parser, u32, Str)> {
    if p.i + 4 > p.c.len() {
        return None;
    }
    let mut v: u32 = 0;
    let mut raw = Str::new();
    let mut k = 0;
    while k < 4 {
        let d = hex_val(p.c[p.i].clone())?;
        raw.push_str(p.c[p.i].clone());
        v = v * 16 + d;
        p.i += 1;
        k += 1;
    }
    Some((p, v, raw))
}

fn parse_string(mut p: Parser) -> Option<(Parser, Str)> {
    if p.i >= p.c.len() || p.c[p.i] != "\"" {
        return None;
    }
    p.i += 1;
    let mut out = Str::new();
    loop {
        if p.i >= p.c.len() {
            return None;
        }
        let ch = p.c[p.i].clone();
        p.i += 1;
        if ch == "\"" {
            return Some((p, out));
        }
        if ch == "\n" || ch == "\r" || ch == "\t" {
            return None;
        }
        if ch == "\\" {
            if p.i >= p.c.len() {
                return None;
            }
            let e = p.c[p.i].clone();
            p.i += 1;
            if e == "\"" {
                out.push_str(Str::from("\""));
            } else if e == "\\" {
                out.push_str(Str::from("\\"));
            } else if e == "/" {
                out.push_str(Str::from("/"));
            } else if e == "b" {
                out.push_str(Str::from("\\u0008"));
            } else if e == "f" {
                out.push_str(Str::from("\\u000c"));
            } else if e == "n" {
                out.push_str(Str::from("\n"));
            } else if e == "r" {
                out.push_str(Str::from("\r"));
            } else if e == "t" {
                out.push_str(Str::from("\t"));
            } else if e == "u" {
                let (p2, cp, raw) = hex4(p)?;
                p = p2;
                if cp >= 0x20 && cp < 0x7f {
                    let t = ascii_table();
                    out.push_str(t[(cp - 0x20) as usize].clone());
                } else if cp == 0x0a {
                    out.push_str(Str::from("\n"));
                } else if cp == 0x0d {
                    out.push_str(Str::from("\r"));
                } else if cp == 0x09 {
                    out.push_str(Str::from("\t"));
                } else {
                    out.push_str(Str::from("\\u"));
                    out.push_str(raw.to_lowercase());
                }
            } else {
                return None;
            }
        } else {
            out.push_str(ch);
        }
    }
}

fn parse_number(mut p: Parser) -> Option<(Parser, Str)> {
    let start = p.i;
    if p.i < p.c.len() && p.c[p.i] == "-" {
        p.i += 1;
    }
    if p.i >= p.c.len() || !is_digit(p.c[p.i].clone()) {
        return None;
    }
    if p.c[p.i] == "0" {
        p.i += 1;
    } else {
        while p.i < p.c.len() && is_digit(p.c[p.i].clone()) {
            p.i += 1;
        }
    }
    if p.i < p.c.len() && p.c[p.i] == "." {
        p.i += 1;
        if p.i >= p.c.len() || !is_digit(p.c[p.i].clone()) {
            return None;
        }
        while p.i < p.c.len() && is_digit(p.c[p.i].clone()) {
            p.i += 1;
        }
    }
    if p.i < p.c.len() && (p.c[p.i] == "e" || p.c[p.i] == "E") {
        p.i += 1;
        if p.i < p.c.len() && (p.c[p.i] == "+" || p.c[p.i] == "-") {
            p.i += 1;
        }
        if p.i >= p.c.len() || !is_digit(p.c[p.i].clone()) {
            return None;
        }
        while p.i < p.c.len() && is_digit(p.c[p.i].clone()) {
            p.i += 1;
        }
    }
    let mut s = Str::new();
    let mut k = start;
    while k < p.i {
        s.push_str(p.c[k].clone());
        k += 1;
    }
    Some((p, s))
}

fn lit(mut p: Parser, w: Str) -> Option<Parser> {
    let wc: Vec<Str> = w.chars().collect();
    if p.i + wc.len() > p.c.len() {
        return None;
    }
    let mut k = 0;
    while k < wc.len() {
        if p.c[p.i + k] != wc[k] {
            return None;
        }
        k += 1;
    }
    p.i += wc.len();
    Some(p)
}

fn parse_value(p0: Parser) -> Option<(Parser, Json)> {
    let mut p = skip_ws(p0);
    if p.i >= p.c.len() {
        return None;
    }
    let ch = p.c[p.i].clone();
    if ch == "{" {
        p.i += 1;
        let mut items: Vec<(Str, Json)> = Vec::new();
        p = skip_ws(p);
        if p.i < p.c.len() && p.c[p.i] == "}" {
            p.i += 1;
            return Some((p, Json::Obj(items)));
        }
        loop {
            p = skip_ws(p);
            let (p2, k) = parse_string(p)?;
            p = skip_ws(p2);
            if p.i >= p.c.len() || p.c[p.i] != ":" {
                return None;
            }
            p.i += 1;
            let (p3, v) = parse_value(p)?;
            p = skip_ws(p3);
            items.push((k, v));
            if p.i >= p.c.len() {
                return None;
            }
            if p.c[p.i] == "," {
                p.i += 1;
            } else if p.c[p.i] == "}" {
                p.i += 1;
                return Some((p, Json::Obj(items)));
            } else {
                return None;
            }
        }
    } else if ch == "[" {
        p.i += 1;
        let mut items: Vec<Json> = Vec::new();
        p = skip_ws(p);
        if p.i < p.c.len() && p.c[p.i] == "]" {
            p.i += 1;
            return Some((p, Json::Arr(items)));
        }
        loop {
            let (p2, v) = parse_value(p)?;
            p = skip_ws(p2);
            items.push(v);
            if p.i >= p.c.len() {
                return None;
            }
            if p.c[p.i] == "," {
                p.i += 1;
            } else if p.c[p.i] == "]" {
                p.i += 1;
                return Some((p, Json::Arr(items)));
            } else {
                return None;
            }
        }
    } else if ch == "\"" {
        let (p2, s) = parse_string(p)?;
        Some((p2, Json::Text(s)))
    } else if ch == "t" {
        let p2 = lit(p, Str::from("true"))?;
        Some((p2, Json::Bool(true)))
    } else if ch == "f" {
        let p2 = lit(p, Str::from("false"))?;
        Some((p2, Json::Bool(false)))
    } else if ch == "n" {
        let p2 = lit(p, Str::from("null"))?;
        Some((p2, Json::Null))
    } else {
        let (p2, n) = parse_number(p)?;
        Some((p2, Json::Num(n)))
    }
}

fn parse_json(s: Str) -> Option<Json> {
    let p = Parser { c: s.chars().collect(), i: 0 };
    let (p2, v) = parse_value(p)?;
    let p3 = skip_ws(p2);
    if p3.i != p3.c.len() {
        return None;
    }
    Some(v)
}

fn json_str(s: Str) -> Str {
    let mut out = Str::from("\"");
    for ch in s.chars() {
        if ch == "\"" {
            out.push_str(Str::from("\\\""));
        } else if ch == "\\" {
            out.push_str(Str::from("\\\\"));
        } else if ch == "\n" {
            out.push_str(Str::from("\\n"));
        } else if ch == "\r" {
            out.push_str(Str::from("\\r"));
        } else if ch == "\t" {
            out.push_str(Str::from("\\t"));
        } else {
            out.push_str(ch);
        }
    }
    out.push_str(Str::from("\""));
    out
}

fn canon(v: Json) -> Str {
    match v {
        Json::Null => Str::from("null"),
        Json::Bool(b) => {
            if b { Str::from("true") } else { Str::from("false") }
        }
        Json::Num(n) => n,
        Json::Text(s) => json_str(s),
        Json::Arr(items) => {
            let mut out = Str::from("[");
            let mut first = true;
            for it in items {
                if !first {
                    out.push_str(Str::from(","));
                }
                first = false;
                out.push_str(canon(it));
            }
            out.push_str(Str::from("]"));
            out
        }
        Json::Obj(items) => {
            let mut parts: Vec<(Str, Str)> = Vec::new();
            for (k, val) in items {
                parts.push((k, canon(val)));
            }
            let n = parts.len();
            let mut i = 1;
            while i < n {
                let mut j = i;
                while j > 0 && parts[j - 1].0 > parts[j].0 {
                    parts.swap(j - 1, j);
                    j -= 1;
                }
                i += 1;
            }
            let mut out = Str::from("{");
            let mut first = true;
            for (k, cv) in parts {
                if !first {
                    out.push_str(Str::from(","));
                }
                first = false;
                out.push_str(json_str(k));
                out.push_str(Str::from(":"));
                out.push_str(cv);
            }
            out.push_str(Str::from("}"));
            out
        }
    }
}

fn pos_int(v: Json) -> Option<i64> {
    match v {
        Json::Num(n) => {
            if n.len() == 0 || n.len() > 15 {
                return None;
            }
            let mut x: i64 = 0;
            for ch in n.chars() {
                let d = digit_val(ch)?;
                x = x * 10 + d;
            }
            if x > 0 { Some(x) } else { None }
        }
        _ => None,
    }
}

fn sql_str(s: Str) -> Str {
    let mut out = Str::from("'");
    for ch in s.chars() {
        if ch == "'" {
            out.push_str(Str::from("''"));
        } else {
            out.push_str(ch);
        }
    }
    out.push_str(Str::from("'"));
    out
}

fn err(msg: Str) -> Str {
    format!("{{\"error\":{}}}", json_str(msg))
}

fn url_decode(s: Str) -> Str {
    let c: Vec<Str> = s.chars().collect();
    let t = ascii_table();
    let mut out = Str::new();
    let mut i = 0;
    while i < c.len() {
        if c[i] == "%" && i + 2 < c.len() {
            match (hex_val(c[i + 1].clone()), hex_val(c[i + 2].clone())) {
                (Some(a), Some(b)) => {
                    let v = a * 16 + b;
                    if v >= 0x20 && v < 0x7f {
                        out.push_str(t[(v - 0x20) as usize].clone());
                        i += 3;
                        continue;
                    }
                }
                _ => {}
            }
        }
        if c[i] == "+" {
            out.push_str(Str::from(" "));
        } else {
            out.push_str(c[i].clone());
        }
        i += 1;
    }
    out
}

fn payment_json(id: i64, account: Str, cents: i64, currency: Str, status: Str, refunded: i64) -> Str {
    format!(
        "{{\"id\":\"pay_{}\",\"account\":{},\"cents\":{},\"currency\":{},\"status\":{},\"refunded\":{}}}",
        id,
        json_str(account),
        cents,
        json_str(currency),
        json_str(status),
        refunded
    )
}

struct Pay {
    id: i64,
    account: Str,
    cents: i64,
    currency: Str,
    status: Str,
    refunded: i64,
}

fn pay_to_json(p: Pay) -> Str {
    payment_json(p.id, p.account, p.cents, p.currency, p.status, p.refunded)
}

fn parse_pay_id(s: Str) -> Option<i64> {
    let c: Vec<Str> = s.chars().collect();
    if c.len() < 5 || c.len() > 19 {
        return None;
    }
    if c[0] != "p" || c[1] != "a" || c[2] != "y" || c[3] != "_" {
        return None;
    }
    let mut x: i64 = 0;
    let mut i = 4;
    while i < c.len() {
        let d = digit_val(c[i].clone())?;
        x = x * 10 + d;
        i += 1;
    }
    Some(x)
}

fn split_on(s: Str, sep: Str) -> Vec<Str> {
    let mut segs: Vec<Str> = Vec::new();
    let mut cur = Str::new();
    for ch in s.chars() {
        if ch == sep {
            if cur.len() > 0 {
                segs.push(cur);
                cur = Str::new();
            }
        } else {
            cur.push_str(ch);
        }
    }
    if cur.len() > 0 {
        segs.push(cur);
    }
    segs
}

fn query_account(q: Str) -> Str {
    let mut account = Str::new();
    let pre: Vec<Str> = Str::from("account=").chars().collect();
    for part in split_on(q, Str::from("&")) {
        let pc: Vec<Str> = part.chars().collect();
        if pc.len() >= pre.len() {
            let mut same = true;
            let mut k = 0;
            while k < pre.len() {
                if pc[k] != pre[k] {
                    same = false;
                    break;
                }
                k += 1;
            }
            if same {
                let mut raw = Str::new();
                let mut j = pre.len();
                while j < pc.len() {
                    raw.push_str(pc[j].clone());
                    j += 1;
                }
                account = url_decode(raw);
            }
        }
    }
    account
}

fn handle(db: Db, method: Str, path: Str, query: Str, body: Str) -> Result<(Db, i64, Str), Str> {
    let segs = split_on(path, Str::from("/"));
    if segs.len() == 0 || segs[0] != "payments" {
        return Ok((db, 404, err(Str::from("not found"))));
    }
    if segs.len() == 1 {
        if method == "POST" {
            let mut account: Option<Str> = None;
            let mut cents: Option<i64> = None;
            let mut currency: Option<Str> = None;
            let mut ok = true;
            match parse_json(body) {
                Some(Json::Obj(items)) => {
                    for (k, val) in items {
                        if k == "account" {
                            match val {
                                Json::Text(s) => {
                                    if s.len() > 0 {
                                        account = Some(s);
                                    } else {
                                        ok = false;
                                    }
                                }
                                _ => {
                                    ok = false;
                                }
                            }
                        } else if k == "cents" {
                            match pos_int(val) {
                                Some(n) => {
                                    cents = Some(n);
                                }
                                None => {
                                    ok = false;
                                }
                            }
                        } else if k == "currency" {
                            match val {
                                Json::Text(s) => {
                                    if s == "EUR" || s == "USD" {
                                        currency = Some(s);
                                    } else {
                                        ok = false;
                                    }
                                }
                                _ => {
                                    ok = false;
                                }
                            }
                        } else {
                            ok = false;
                        }
                    }
                }
                _ => {
                    ok = false;
                }
            }
            if !ok {
                return Ok((db, 422, err(Str::from("invalid payment"))));
            }
            let a = match account {
                Some(x) => x,
                None => return Ok((db, 422, err(Str::from("invalid payment")))),
            };
            let c = match cents {
                Some(x) => x,
                None => return Ok((db, 422, err(Str::from("invalid payment")))),
            };
            let cur = match currency {
                Some(x) => x,
                None => return Ok((db, 422, err(Str::from("invalid payment")))),
            };
            db.exec(format!(
                "INSERT INTO payments (account, cents, currency, status, refunded) VALUES ({}, {}, {}, 'pending', 0)",
                sql_str(a.clone()),
                c,
                sql_str(cur.clone())
            ))
            .map_err(|e| e.to_string())?;
            let rows = db
                .query(Str::from("SELECT MAX(id) FROM payments"))
                .map_err(|e| e.to_string())?;
            let id = rows[0].get_int(0);
            let out = payment_json(id, a, c, cur, Str::from("pending"), 0);
            return Ok((db, 201, out));
        }
        if method == "GET" {
            let account = query_account(query);
            let rows = db
                .query(format!(
                    "SELECT id, account, cents, currency, status, refunded FROM payments WHERE account = {} ORDER BY id",
                    sql_str(account)
                ))
                .map_err(|e| e.to_string())?;
            let mut out = Str::from("[");
            let mut first = true;
            for r in rows {
                if !first {
                    out.push_str(Str::from(","));
                }
                first = false;
                out.push_str(payment_json(
                    r.get_int(0),
                    r.get_str(1),
                    r.get_int(2),
                    r.get_str(3),
                    r.get_str(4),
                    r.get_int(5),
                ));
            }
            out.push_str(Str::from("]"));
            return Ok((db, 200, out));
        }
        return Ok((db, 404, err(Str::from("not found"))));
    }
    if segs.len() > 3 {
        return Ok((db, 404, err(Str::from("not found"))));
    }
    if segs.len() == 2 && method != "GET" {
        return Ok((db, 404, err(Str::from("not found"))));
    }
    let mut action = Str::new();
    if segs.len() == 3 {
        action = segs[2].clone();
        if method != "POST" || (action != "capture" && action != "cancel" && action != "refund") {
            return Ok((db, 404, err(Str::from("not found"))));
        }
    }
    let id = match parse_pay_id(segs[1].clone()) {
        Some(n) => n,
        None => return Ok((db, 404, err(Str::from("not found")))),
    };
    let rows = db
        .query(format!(
            "SELECT id, account, cents, currency, status, refunded FROM payments WHERE id = {}",
            id
        ))
        .map_err(|e| e.to_string())?;
    if rows.len() == 0 {
        return Ok((db, 404, err(Str::from("not found"))));
    }
    let mut p = Pay {
        id: rows[0].get_int(0),
        account: rows[0].get_str(1),
        cents: rows[0].get_int(2),
        currency: rows[0].get_str(3),
        status: rows[0].get_str(4),
        refunded: rows[0].get_int(5),
    };
    if segs.len() == 2 {
        return Ok((db, 200, pay_to_json(p)));
    }
    if action == "capture" {
        if p.status == "pending" {
            db.exec(format!("UPDATE payments SET status = 'captured' WHERE id = {}", id))
                .map_err(|e| e.to_string())?;
            p.status = Str::from("captured");
            return Ok((db, 200, pay_to_json(p)));
        }
        if p.status == "captured" {
            return Ok((db, 200, pay_to_json(p)));
        }
        return Ok((db, 409, err(Str::from("invalid transition"))));
    }
    if action == "cancel" {
        if p.status == "pending" {
            db.exec(format!("UPDATE payments SET status = 'canceled' WHERE id = {}", id))
                .map_err(|e| e.to_string())?;
            p.status = Str::from("canceled");
            return Ok((db, 200, pay_to_json(p)));
        }
        return Ok((db, 409, err(Str::from("invalid transition"))));
    }
    let mut amount: Option<i64> = None;
    let mut ok = true;
    match parse_json(body) {
        Some(Json::Obj(items)) => {
            for (k, val) in items {
                if k == "cents" {
                    amount = pos_int(val);
                    if amount.is_none() {
                        ok = false;
                    }
                }
            }
        }
        _ => {
            ok = false;
        }
    }
    let n = match amount {
        Some(n) => n,
        None => return Ok((db, 422, err(Str::from("invalid refund")))),
    };
    if !ok {
        return Ok((db, 422, err(Str::from("invalid refund"))));
    }
    if p.status != "captured" {
        return Ok((db, 409, err(Str::from("invalid transition"))));
    }
    if p.refunded + n > p.cents {
        return Ok((db, 409, err(Str::from("exceeds captured"))));
    }
    p.refunded = p.refunded + n;
    if p.refunded == p.cents {
        p.status = Str::from("refunded");
    }
    db.exec(format!(
        "UPDATE payments SET status = {}, refunded = {} WHERE id = {}",
        sql_str(p.status.clone()),
        p.refunded,
        id
    ))
    .map_err(|e| e.to_string())?;
    Ok((db, 200, pay_to_json(p)))
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, Str> {
    db.exec(Str::from("CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)"))
        .map_err(|e| e.to_string())?;
    db.exec(Str::from("CREATE TABLE IF NOT EXISTS idem (k TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL, status INTEGER NOT NULL, resp TEXT NOT NULL)"))
        .map_err(|e| e.to_string())?;

    let method = req.method().to_string().to_uppercase();
    let full = req.path().to_string();
    let mut path = Str::new();
    let mut query = Str::new();
    let mut inq = false;
    for ch in full.chars() {
        if inq {
            query.push_str(ch);
        } else if ch == "?" {
            inq = true;
        } else {
            path.push_str(ch);
        }
    }
    let body = req.body().to_string();

    let segs = split_on(path.clone(), Str::from("/"));
    let needs_key = method == "POST"
        && ((segs.len() == 1 && segs[0] == "payments")
            || (segs.len() == 3 && segs[0] == "payments" && segs[2] == "refund"));

    let canon_body = match parse_json(body.clone()) {
        Some(v) => canon(v),
        None => body.clone(),
    };

    let mut status: i64 = 0;
    let mut out = Str::new();
    let mut done = false;
    let mut key: Option<Str> = None;

    if needs_key {
        let hk: Option<Str> = match req.header("idempotency-key") {
            Some(k0) => {
                let k = k0.to_string();
                if k.len() > 0 { Some(k) } else { None }
            }
            None => None,
        };
        match hk {
            Some(k) => {
                let rows = db
                    .query(format!(
                        "SELECT method, path, body, status, resp FROM idem WHERE k = {}",
                        sql_str(k.clone())
                    ))
                    .map_err(|e| e.to_string())?;
                if rows.len() > 0 {
                    if rows[0].get_str(0) == method && rows[0].get_str(1) == full && rows[0].get_str(2) == canon_body {
                        status = rows[0].get_int(3);
                        out = rows[0].get_str(4);
                    } else {
                        status = 409;
                        out = err(Str::from("key reused"));
                    }
                    done = true;
                }
                key = Some(k);
            }
            None => {
                status = 400;
                out = err(Str::from("missing idempotency key"));
                done = true;
            }
        }
    }

    if !done {
        let (db2, s, b) = handle(db, method.clone(), path, query, body)?;
        status = s;
        out = b;
        match key {
            Some(k) => {
                if status >= 200 && status < 300 {
                    db2.exec(format!(
                        "INSERT OR REPLACE INTO idem (k, method, path, body, status, resp) VALUES ({}, {}, {}, {}, {}, {})",
                        sql_str(k),
                        sql_str(method.clone()),
                        sql_str(full.clone()),
                        sql_str(canon_body.clone()),
                        status,
                        sql_str(out.clone())
                    ))
                    .map_err(|e| e.to_string())?;
                }
            }
            None => {}
        }
    }

    res.status(status as u16);
    res.header("content-type", "application/json");
    Ok(out)
}

enum Json {
    Null,
    Bool(bool),
    Num(Str),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<Member>),
}

struct Member {
    k: Str,
    v: Json,
}

struct Parser {
    c: Vec<Str>,
    i: usize,
}

struct PStr {
    p: Parser,
    s: Str,
}

struct PVal {
    p: Parser,
    v: Json,
}

struct PHex {
    p: Parser,
    v: u32,
    raw: Str,
}

struct KV {
    k: Str,
    v: Str,
}

struct Resp {
    db: Db,
    status: i64,
    body: Str,
}

fn ascii_table() -> Vec<Str> {
    Str::from(" !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~")
        .chars()
        .collect()
}

fn digit_val(s: Str) -> Option<i64> {
    let mut k: i64 = 0;
    for d in Str::from("0123456789").chars() {
        if d == s {
            return Some(k);
        }
        k += 1;
    }
    None
}

fn is_digit(s: Str) -> bool {
    digit_val(s).is_some()
}

fn hex_val(s: Str) -> Option<u32> {
    let mut k: u32 = 0;
    for d in Str::from("0123456789abcdef").chars() {
        if d == s {
            return Some(k);
        }
        k += 1;
    }
    k = 10;
    for d in Str::from("ABCDEF").chars() {
        if d == s {
            return Some(k);
        }
        k += 1;
    }
    None
}

fn skip_ws(mut p: Parser) -> Parser {
    while p.i < p.c.len() {
        let ch = p.c[p.i].clone();
        if ch == " " || ch == "\n" || ch == "\r" || ch == "\t" {
            p.i += 1;
        } else {
            break;
        }
    }
    p
}

fn hex4(mut p: Parser) -> Option<PHex> {
    if p.i + 4 > p.c.len() {
        return None;
    }
    let mut v: u32 = 0;
    let mut raw = Str::new();
    let mut k = 0;
    while k < 4 {
        let d = hex_val(p.c[p.i].clone())?;
        raw.push_str(p.c[p.i].clone());
        v = v * 16 + d;
        p.i += 1;
        k += 1;
    }
    Some(PHex { p: p, v: v, raw: raw })
}

fn parse_string(mut p: Parser) -> Option<PStr> {
    if p.i >= p.c.len() || p.c[p.i] != "\"" {
        return None;
    }
    p.i += 1;
    let mut out = Str::new();
    loop {
        if p.i >= p.c.len() {
            return None;
        }
        let ch = p.c[p.i].clone();
        p.i += 1;
        if ch == "\"" {
            return Some(PStr { p: p, s: out });
        }
        if ch == "\n" || ch == "\r" || ch == "\t" {
            return None;
        }
        if ch == "\\" {
            if p.i >= p.c.len() {
                return None;
            }
            let e = p.c[p.i].clone();
            p.i += 1;
            if e == "\"" {
                out.push_str(Str::from("\""));
            } else if e == "\\" {
                out.push_str(Str::from("\\"));
            } else if e == "/" {
                out.push_str(Str::from("/"));
            } else if e == "b" {
                out.push_str(Str::from("\\u0008"));
            } else if e == "f" {
                out.push_str(Str::from("\\u000c"));
            } else if e == "n" {
                out.push_str(Str::from("\n"));
            } else if e == "r" {
                out.push_str(Str::from("\r"));
            } else if e == "t" {
                out.push_str(Str::from("\t"));
            } else if e == "u" {
                let h = hex4(p)?;
                p = h.p;
                let cp = h.v;
                if cp >= 0x20 && cp < 0x7f {
                    let t = ascii_table();
                    out.push_str(t[(cp - 0x20) as usize].clone());
                } else if cp == 0x0a {
                    out.push_str(Str::from("\n"));
                } else if cp == 0x0d {
                    out.push_str(Str::from("\r"));
                } else if cp == 0x09 {
                    out.push_str(Str::from("\t"));
                } else {
                    out.push_str(Str::from("\\u"));
                    out.push_str(h.raw.to_lowercase());
                }
            } else {
                return None;
            }
        } else {
            out.push_str(ch);
        }
    }
}

fn parse_number(mut p: Parser) -> Option<PStr> {
    let start = p.i;
    if p.i < p.c.len() && p.c[p.i] == "-" {
        p.i += 1;
    }
    if p.i >= p.c.len() || !is_digit(p.c[p.i].clone()) {
        return None;
    }
    if p.c[p.i] == "0" {
        p.i += 1;
    } else {
        while p.i < p.c.len() && is_digit(p.c[p.i].clone()) {
            p.i += 1;
        }
    }
    if p.i < p.c.len() && p.c[p.i] == "." {
        p.i += 1;
        if p.i >= p.c.len() || !is_digit(p.c[p.i].clone()) {
            return None;
        }
        while p.i < p.c.len() && is_digit(p.c[p.i].clone()) {
            p.i += 1;
        }
    }
    if p.i < p.c.len() && (p.c[p.i] == "e" || p.c[p.i] == "E") {
        p.i += 1;
        if p.i < p.c.len() && (p.c[p.i] == "+" || p.c[p.i] == "-") {
            p.i += 1;
        }
        if p.i >= p.c.len() || !is_digit(p.c[p.i].clone()) {
            return None;
        }
        while p.i < p.c.len() && is_digit(p.c[p.i].clone()) {
            p.i += 1;
        }
    }
    let mut s = Str::new();
    let mut k = start;
    while k < p.i {
        s.push_str(p.c[k].clone());
        k += 1;
    }
    Some(PStr { p: p, s: s })
}

fn lit(mut p: Parser, w: Str) -> Option<Parser> {
    let wc: Vec<Str> = w.chars().collect();
    if p.i + wc.len() > p.c.len() {
        return None;
    }
    let mut k = 0;
    while k < wc.len() {
        if p.c[p.i + k] != wc[k] {
            return None;
        }
        k += 1;
    }
    p.i += wc.len();
    Some(p)
}

fn parse_value(p0: Parser) -> Option<PVal> {
    let mut p = skip_ws(p0);
    if p.i >= p.c.len() {
        return None;
    }
    let ch = p.c[p.i].clone();
    if ch == "{" {
        p.i += 1;
        let mut items: Vec<Member> = Vec::new();
        p = skip_ws(p);
        if p.i < p.c.len() && p.c[p.i] == "}" {
            p.i += 1;
            return Some(PVal { p: p, v: Json::Obj(items) });
        }
        loop {
            p = skip_ws(p);
            let ks = parse_string(p)?;
            p = skip_ws(ks.p);
            let k = ks.s;
            if p.i >= p.c.len() || p.c[p.i] != ":" {
                return None;
            }
            p.i += 1;
            let pv = parse_value(p)?;
            p = skip_ws(pv.p);
            items.push(Member { k: k, v: pv.v });
            if p.i >= p.c.len() {
                return None;
            }
            if p.c[p.i] == "," {
                p.i += 1;
            } else if p.c[p.i] == "}" {
                p.i += 1;
                return Some(PVal { p: p, v: Json::Obj(items) });
            } else {
                return None;
            }
        }
    } else if ch == "[" {
        p.i += 1;
        let mut items: Vec<Json> = Vec::new();
        p = skip_ws(p);
        if p.i < p.c.len() && p.c[p.i] == "]" {
            p.i += 1;
            return Some(PVal { p: p, v: Json::Arr(items) });
        }
        loop {
            let pv = parse_value(p)?;
            p = skip_ws(pv.p);
            items.push(pv.v);
            if p.i >= p.c.len() {
                return None;
            }
            if p.c[p.i] == "," {
                p.i += 1;
            } else if p.c[p.i] == "]" {
                p.i += 1;
                return Some(PVal { p: p, v: Json::Arr(items) });
            } else {
                return None;
            }
        }
    } else if ch == "\"" {
        let ps = parse_string(p)?;
        Some(PVal { p: ps.p, v: Json::Text(ps.s) })
    } else if ch == "t" {
        let p2 = lit(p, Str::from("true"))?;
        Some(PVal { p: p2, v: Json::Bool(true) })
    } else if ch == "f" {
        let p2 = lit(p, Str::from("false"))?;
        Some(PVal { p: p2, v: Json::Bool(false) })
    } else if ch == "n" {
        let p2 = lit(p, Str::from("null"))?;
        Some(PVal { p: p2, v: Json::Null })
    } else {
        let ps = parse_number(p)?;
        Some(PVal { p: ps.p, v: Json::Num(ps.s) })
    }
}

fn parse_json(s: Str) -> Option<Json> {
    let p = Parser { c: s.chars().collect(), i: 0 };
    let pv = parse_value(p)?;
    let p3 = skip_ws(pv.p);
    if p3.i != p3.c.len() {
        return None;
    }
    Some(pv.v)
}

fn json_str(s: Str) -> Str {
    let mut out = Str::from("\"");
    for ch in s.chars() {
        if ch == "\"" {
            out.push_str(Str::from("\\\""));
        } else if ch == "\\" {
            out.push_str(Str::from("\\\\"));
        } else if ch == "\n" {
            out.push_str(Str::from("\\n"));
        } else if ch == "\r" {
            out.push_str(Str::from("\\r"));
        } else if ch == "\t" {
            out.push_str(Str::from("\\t"));
        } else {
            out.push_str(ch);
        }
    }
    out.push_str(Str::from("\""));
    out
}

fn canon(v: Json) -> Str {
    match v {
        Json::Null => Str::from("null"),
        Json::Bool(b) => {
            if b { Str::from("true") } else { Str::from("false") }
        }
        Json::Num(n) => n,
        Json::Text(s) => json_str(s),
        Json::Arr(items) => {
            let mut out = Str::from("[");
            let mut first = true;
            for it in items {
                if !first {
                    out.push_str(Str::from(","));
                }
                first = false;
                out.push_str(canon(it));
            }
            out.push_str(Str::from("]"));
            out
        }
        Json::Obj(items) => {
            let mut parts: Vec<KV> = Vec::new();
            for m in items {
                let k = m.k;
                let val = m.v;
                parts.push(KV { k: k, v: canon(val) });
            }
            let n = parts.len();
            let mut i = 1;
            while i < n {
                let mut j = i;
                while j > 0 && parts[j - 1].k > parts[j].k {
                    parts.swap(j - 1, j);
                    j -= 1;
                }
                i += 1;
            }
            let mut out = Str::from("{");
            let mut first = true;
            for kv in parts {
                if !first {
                    out.push_str(Str::from(","));
                }
                first = false;
                out.push_str(json_str(kv.k));
                out.push_str(Str::from(":"));
                out.push_str(kv.v);
            }
            out.push_str(Str::from("}"));
            out
        }
    }
}

fn pos_int(v: Json) -> Option<i64> {
    match v {
        Json::Num(n) => {
            if n.len() == 0 || n.len() > 15 {
                return None;
            }
            let mut x: i64 = 0;
            for ch in n.chars() {
                let d = digit_val(ch)?;
                x = x * 10 + d;
            }
            if x > 0 { Some(x) } else { None }
        }
        _ => None,
    }
}

fn sql_str(s: Str) -> Str {
    let mut out = Str::from("'");
    for ch in s.chars() {
        if ch == "'" {
            out.push_str(Str::from("''"));
        } else {
            out.push_str(ch);
        }
    }
    out.push_str(Str::from("'"));
    out
}

fn err(msg: Str) -> Str {
    format!("{{\"error\":{}}}", json_str(msg))
}

fn url_decode(s: Str) -> Str {
    let c: Vec<Str> = s.chars().collect();
    let t = ascii_table();
    let mut out = Str::new();
    let mut i = 0;
    while i < c.len() {
        if c[i] == "%" && i + 2 < c.len() {
            let a = hex_val(c[i + 1].clone());
            let b = hex_val(c[i + 2].clone());
            if a.is_some() && b.is_some() {
                let v = a.unwrap() * 16 + b.unwrap();
                if v >= 0x20 && v < 0x7f {
                    out.push_str(t[(v - 0x20) as usize].clone());
                    i += 3;
                    continue;
                }
            }
        }
        if c[i] == "+" {
            out.push_str(Str::from(" "));
        } else {
            out.push_str(c[i].clone());
        }
        i += 1;
    }
    out
}

fn payment_json(id: i64, account: Str, cents: i64, currency: Str, status: Str, refunded: i64) -> Str {
    format!(
        "{{\"id\":\"pay_{}\",\"account\":{},\"cents\":{},\"currency\":{},\"status\":{},\"refunded\":{}}}",
        id,
        json_str(account),
        cents,
        json_str(currency),
        json_str(status),
        refunded
    )
}

struct Pay {
    id: i64,
    account: Str,
    cents: i64,
    currency: Str,
    status: Str,
    refunded: i64,
}

fn pay_to_json(p: Pay) -> Str {
    payment_json(p.id, p.account, p.cents, p.currency, p.status, p.refunded)
}

fn parse_pay_id(s: Str) -> Option<i64> {
    let c: Vec<Str> = s.chars().collect();
    if c.len() < 5 || c.len() > 19 {
        return None;
    }
    if c[0] != "p" || c[1] != "a" || c[2] != "y" || c[3] != "_" {
        return None;
    }
    let mut x: i64 = 0;
    let mut i = 4;
    while i < c.len() {
        let d = digit_val(c[i].clone())?;
        x = x * 10 + d;
        i += 1;
    }
    Some(x)
}

fn split_on(s: Str, sep: Str) -> Vec<Str> {
    let mut segs: Vec<Str> = Vec::new();
    let mut cur = Str::new();
    for ch in s.chars() {
        if ch == sep {
            if cur.len() > 0 {
                segs.push(cur);
                cur = Str::new();
            }
        } else {
            cur.push_str(ch);
        }
    }
    if cur.len() > 0 {
        segs.push(cur);
    }
    segs
}

fn query_account(q: Str) -> Str {
    let mut account = Str::new();
    let pre: Vec<Str> = Str::from("account=").chars().collect();
    for part in split_on(q, Str::from("&")) {
        let pc: Vec<Str> = part.chars().collect();
        if pc.len() >= pre.len() {
            let mut same = true;
            let mut k = 0;
            while k < pre.len() {
                if pc[k] != pre[k] {
                    same = false;
                    break;
                }
                k += 1;
            }
            if same {
                let mut raw = Str::new();
                let mut j = pre.len();
                while j < pc.len() {
                    raw.push_str(pc[j].clone());
                    j += 1;
                }
                account = url_decode(raw);
            }
        }
    }
    account
}

fn reply(db: Db, status: i64, body: Str) -> Result<Resp, Str> {
    Ok(Resp { db: db, status: status, body: body })
}

fn handle(db: Db, method: Str, path: Str, query: Str, body: Str) -> Result<Resp, Str> {
    let segs = split_on(path, Str::from("/"));
    if segs.len() == 0 || segs[0] != "payments" {
        return reply(db, 404, err(Str::from("not found")));
    }
    if segs.len() == 1 {
        if method == "POST" {
            let mut account: Option<Str> = None;
            let mut cents: Option<i64> = None;
            let mut currency: Option<Str> = None;
            let mut ok = true;
            match parse_json(body) {
                Some(Json::Obj(items)) => {
                    for m in items {
                        let k = m.k;
                        let val = m.v;
                        if k == "account" {
                            match val {
                                Json::Text(s) => {
                                    if s.len() > 0 {
                                        account = Some(s);
                                    } else {
                                        ok = false;
                                    }
                                }
                                _ => {
                                    ok = false;
                                }
                            }
                        } else if k == "cents" {
                            match pos_int(val) {
                                Some(n) => {
                                    cents = Some(n);
                                }
                                None => {
                                    ok = false;
                                }
                            }
                        } else if k == "currency" {
                            match val {
                                Json::Text(s) => {
                                    if s == "EUR" || s == "USD" {
                                        currency = Some(s);
                                    } else {
                                        ok = false;
                                    }
                                }
                                _ => {
                                    ok = false;
                                }
                            }
                        } else {
                            ok = false;
                        }
                    }
                }
                _ => {
                    ok = false;
                }
            }
            if !ok {
                return reply(db, 422, err(Str::from("invalid payment")));
            }
            let a = match account {
                Some(x) => x,
                None => return reply(db, 422, err(Str::from("invalid payment"))),
            };
            let c = match cents {
                Some(x) => x,
                None => return reply(db, 422, err(Str::from("invalid payment"))),
            };
            let cur = match currency {
                Some(x) => x,
                None => return reply(db, 422, err(Str::from("invalid payment"))),
            };
            db.exec(format!(
                "INSERT INTO payments (account, cents, currency, status, refunded) VALUES ({}, {}, {}, 'pending', 0)",
                sql_str(a.clone()),
                c,
                sql_str(cur.clone())
            ))
            .map_err(|e| e.to_string())?;
            let rows = db
                .query(Str::from("SELECT MAX(id) FROM payments"))
                .map_err(|e| e.to_string())?;
            let id = rows[0].get_int(0);
            let out = payment_json(id, a, c, cur, Str::from("pending"), 0);
            return reply(db, 201, out);
        }
        if method == "GET" {
            let account = query_account(query);
            let rows = db
                .query(format!(
                    "SELECT id, account, cents, currency, status, refunded FROM payments WHERE account = {} ORDER BY id",
                    sql_str(account)
                ))
                .map_err(|e| e.to_string())?;
            let mut out = Str::from("[");
            let mut first = true;
            for r in rows {
                if !first {
                    out.push_str(Str::from(","));
                }
                first = false;
                out.push_str(payment_json(
                    r.get_int(0),
                    r.get_str(1),
                    r.get_int(2),
                    r.get_str(3),
                    r.get_str(4),
                    r.get_int(5),
                ));
            }
            out.push_str(Str::from("]"));
            return reply(db, 200, out);
        }
        return reply(db, 404, err(Str::from("not found")));
    }
    if segs.len() > 3 {
        return reply(db, 404, err(Str::from("not found")));
    }
    if segs.len() == 2 && method != "GET" {
        return reply(db, 404, err(Str::from("not found")));
    }
    let mut action = Str::new();
    if segs.len() == 3 {
        action = segs[2].clone();
        if method != "POST" || (action != "capture" && action != "cancel" && action != "refund") {
            return reply(db, 404, err(Str::from("not found")));
        }
    }
    let id = match parse_pay_id(segs[1].clone()) {
        Some(n) => n,
        None => return reply(db, 404, err(Str::from("not found"))),
    };
    let rows = db
        .query(format!(
            "SELECT id, account, cents, currency, status, refunded FROM payments WHERE id = {}",
            id
        ))
        .map_err(|e| e.to_string())?;
    if rows.len() == 0 {
        return reply(db, 404, err(Str::from("not found")));
    }
    let mut p = Pay {
        id: rows[0].get_int(0),
        account: rows[0].get_str(1),
        cents: rows[0].get_int(2),
        currency: rows[0].get_str(3),
        status: rows[0].get_str(4),
        refunded: rows[0].get_int(5),
    };
    if segs.len() == 2 {
        return reply(db, 200, pay_to_json(p));
    }
    if action == "capture" {
        if p.status == "pending" {
            db.exec(format!("UPDATE payments SET status = 'captured' WHERE id = {}", id))
                .map_err(|e| e.to_string())?;
            p.status = Str::from("captured");
            return reply(db, 200, pay_to_json(p));
        }
        if p.status == "captured" {
            return reply(db, 200, pay_to_json(p));
        }
        return reply(db, 409, err(Str::from("invalid transition")));
    }
    if action == "cancel" {
        if p.status == "pending" {
            db.exec(format!("UPDATE payments SET status = 'canceled' WHERE id = {}", id))
                .map_err(|e| e.to_string())?;
            p.status = Str::from("canceled");
            return reply(db, 200, pay_to_json(p));
        }
        return reply(db, 409, err(Str::from("invalid transition")));
    }
    let mut amount: Option<i64> = None;
    let mut ok = true;
    match parse_json(body) {
        Some(Json::Obj(items)) => {
            for m in items {
                let k = m.k;
                let val = m.v;
                if k == "cents" {
                    amount = pos_int(val);
                    if amount.is_none() {
                        ok = false;
                    }
                }
            }
        }
        _ => {
            ok = false;
        }
    }
    let n = match amount {
        Some(n) => n,
        None => return reply(db, 422, err(Str::from("invalid refund"))),
    };
    if !ok {
        return reply(db, 422, err(Str::from("invalid refund")));
    }
    if p.status != "captured" {
        return reply(db, 409, err(Str::from("invalid transition")));
    }
    if p.refunded + n > p.cents {
        return reply(db, 409, err(Str::from("exceeds captured")));
    }
    p.refunded = p.refunded + n;
    if p.refunded == p.cents {
        p.status = Str::from("refunded");
    }
    db.exec(format!(
        "UPDATE payments SET status = {}, refunded = {} WHERE id = {}",
        sql_str(p.status.clone()),
        p.refunded,
        id
    ))
    .map_err(|e| e.to_string())?;
    reply(db, 200, pay_to_json(p))
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, Str> {
    db.exec(Str::from("CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)"))
        .map_err(|e| e.to_string())?;
    db.exec(Str::from("CREATE TABLE IF NOT EXISTS idem (k TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL, status INTEGER NOT NULL, resp TEXT NOT NULL)"))
        .map_err(|e| e.to_string())?;

    let method = req.method().to_string().to_uppercase();
    let full = req.path().to_string();
    let mut path = Str::new();
    let mut query = Str::new();
    let mut inq = false;
    for ch in full.chars() {
        if inq {
            query.push_str(ch);
        } else if ch == "?" {
            inq = true;
        } else {
            path.push_str(ch);
        }
    }
    let body = req.body().to_string();

    let segs = split_on(path.clone(), Str::from("/"));
    let needs_key = method == "POST"
        && ((segs.len() == 1 && segs[0] == "payments")
            || (segs.len() == 3 && segs[0] == "payments" && segs[2] == "refund"));

    let canon_body = match parse_json(body.clone()) {
        Some(v) => canon(v),
        None => body.clone(),
    };

    let mut status: i64 = 0;
    let mut out = Str::new();
    let mut done = false;
    let mut key: Option<Str> = None;

    if needs_key {
        let hk: Option<Str> = match req.header("idempotency-key") {
            Some(k0) => {
                let k = k0.to_string();
                if k.len() > 0 { Some(k) } else { None }
            }
            None => None,
        };
        match hk {
            Some(k) => {
                let rows = db
                    .query(format!(
                        "SELECT method, path, body, status, resp FROM idem WHERE k = {}",
                        sql_str(k.clone())
                    ))
                    .map_err(|e| e.to_string())?;
                if rows.len() > 0 {
                    if rows[0].get_str(0) == method && rows[0].get_str(1) == full && rows[0].get_str(2) == canon_body {
                        status = rows[0].get_int(3);
                        out = rows[0].get_str(4);
                    } else {
                        status = 409;
                        out = err(Str::from("key reused"));
                    }
                    done = true;
                }
                key = Some(k);
            }
            None => {
                status = 400;
                out = err(Str::from("missing idempotency key"));
                done = true;
            }
        }
    }

    if !done {
        let r = handle(db, method.clone(), path, query, body)?;
        status = r.status;
        out = r.body;
        let db2 = r.db;
        match key {
            Some(k) => {
                if status >= 200 && status < 300 {
                    db2.exec(format!(
                        "INSERT OR REPLACE INTO idem (k, method, path, body, status, resp) VALUES ({}, {}, {}, {}, {}, {})",
                        sql_str(k),
                        sql_str(method.clone()),
                        sql_str(full.clone()),
                        sql_str(canon_body.clone()),
                        status,
                        sql_str(out.clone())
                    ))
                    .map_err(|e| e.to_string())?;
                }
            }
            None => {}
        }
    }

    res.status(status as u16);
    res.header("content-type", "application/json");
    Ok(out)
}

enum Json {
    Null,
    Bool(bool),
    Num(Str),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<Member>),
}

struct Member {
    k: Str,
    v: Json,
}

struct Parser {
    c: Vec<Str>,
    i: usize,
}

struct PStr {
    p: Parser,
    s: Str,
}

struct PVal {
    p: Parser,
    v: Json,
}

struct PHex {
    p: Parser,
    v: u32,
    raw: Str,
}

struct KV {
    k: Str,
    v: Str,
}

struct Resp {
    db: Db,
    status: i64,
    body: Str,
}

fn ascii_table() -> Vec<Str> {
    Str::from(" !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~")
        .chars()
        .collect()
}

fn digit_val(s: Str) -> Option<i64> {
    let mut k: i64 = 0;
    for d in Str::from("0123456789").chars() {
        if d == s {
            return Some(k);
        }
        k += 1;
    }
    None
}

fn is_digit(s: Str) -> bool {
    digit_val(s).is_some()
}

fn hex_val(s: Str) -> Option<u32> {
    let mut k: u32 = 0;
    for d in Str::from("0123456789abcdef").chars() {
        if d == s {
            return Some(k);
        }
        k += 1;
    }
    k = 10;
    for d in Str::from("ABCDEF").chars() {
        if d == s {
            return Some(k);
        }
        k += 1;
    }
    None
}

fn skip_ws(p0: Parser) -> Parser {
    let mut p = p0;
    while p.i < p.c.len() {
        let ch = p.c[p.i].clone();
        if ch == " " || ch == "\n" || ch == "\r" || ch == "\t" {
            p.i += 1;
        } else {
            break;
        }
    }
    p
}

fn hex4(p0: Parser) -> Option<PHex> {
    let mut p = p0;
    if p.i + 4 > p.c.len() {
        return None;
    }
    let mut v: u32 = 0;
    let mut raw = Str::new();
    let mut k = 0;
    while k < 4 {
        let d = hex_val(p.c[p.i].clone())?;
        raw.push_str(p.c[p.i].clone());
        v = v * 16 + d;
        p.i += 1;
        k += 1;
    }
    Some(PHex { p: p, v: v, raw: raw })
}

fn parse_string(p0: Parser) -> Option<PStr> {
    let mut p = p0;
    if p.i >= p.c.len() || p.c[p.i] != "\"" {
        return None;
    }
    p.i += 1;
    let mut out = Str::new();
    loop {
        if p.i >= p.c.len() {
            return None;
        }
        let ch = p.c[p.i].clone();
        p.i += 1;
        if ch == "\"" {
            return Some(PStr { p: p, s: out });
        }
        if ch == "\n" || ch == "\r" || ch == "\t" {
            return None;
        }
        if ch == "\\" {
            if p.i >= p.c.len() {
                return None;
            }
            let e = p.c[p.i].clone();
            p.i += 1;
            if e == "\"" {
                out.push_str(Str::from("\""));
            } else if e == "\\" {
                out.push_str(Str::from("\\"));
            } else if e == "/" {
                out.push_str(Str::from("/"));
            } else if e == "b" {
                out.push_str(Str::from("\\u0008"));
            } else if e == "f" {
                out.push_str(Str::from("\\u000c"));
            } else if e == "n" {
                out.push_str(Str::from("\n"));
            } else if e == "r" {
                out.push_str(Str::from("\r"));
            } else if e == "t" {
                out.push_str(Str::from("\t"));
            } else if e == "u" {
                let h = hex4(p)?;
                p = h.p;
                let cp = h.v;
                if cp >= 0x20 && cp < 0x7f {
                    let t = ascii_table();
                    out.push_str(t[(cp - 0x20) as usize].clone());
                } else if cp == 0x0a {
                    out.push_str(Str::from("\n"));
                } else if cp == 0x0d {
                    out.push_str(Str::from("\r"));
                } else if cp == 0x09 {
                    out.push_str(Str::from("\t"));
                } else {
                    out.push_str(Str::from("\\u"));
                    out.push_str(h.raw.to_lowercase());
                }
            } else {
                return None;
            }
        } else {
            out.push_str(ch);
        }
    }
}

fn parse_number(p0: Parser) -> Option<PStr> {
    let mut p = p0;
    let start = p.i;
    if p.i < p.c.len() && p.c[p.i] == "-" {
        p.i += 1;
    }
    if p.i >= p.c.len() || !is_digit(p.c[p.i].clone()) {
        return None;
    }
    if p.c[p.i] == "0" {
        p.i += 1;
    } else {
        while p.i < p.c.len() && is_digit(p.c[p.i].clone()) {
            p.i += 1;
        }
    }
    if p.i < p.c.len() && p.c[p.i] == "." {
        p.i += 1;
        if p.i >= p.c.len() || !is_digit(p.c[p.i].clone()) {
            return None;
        }
        while p.i < p.c.len() && is_digit(p.c[p.i].clone()) {
            p.i += 1;
        }
    }
    if p.i < p.c.len() && (p.c[p.i] == "e" || p.c[p.i] == "E") {
        p.i += 1;
        if p.i < p.c.len() && (p.c[p.i] == "+" || p.c[p.i] == "-") {
            p.i += 1;
        }
        if p.i >= p.c.len() || !is_digit(p.c[p.i].clone()) {
            return None;
        }
        while p.i < p.c.len() && is_digit(p.c[p.i].clone()) {
            p.i += 1;
        }
    }
    let mut s = Str::new();
    let mut k = start;
    while k < p.i {
        s.push_str(p.c[k].clone());
        k += 1;
    }
    Some(PStr { p: p, s: s })
}

fn lit(p0: Parser, w: Str) -> Option<Parser> {
    let mut p = p0;
    let wc: Vec<Str> = w.chars().collect();
    if p.i + wc.len() > p.c.len() {
        return None;
    }
    let mut k = 0;
    while k < wc.len() {
        if p.c[p.i + k] != wc[k] {
            return None;
        }
        k += 1;
    }
    p.i += wc.len();
    Some(p)
}

fn parse_value(p0: Parser) -> Option<PVal> {
    let mut p = skip_ws(p0);
    if p.i >= p.c.len() {
        return None;
    }
    let ch = p.c[p.i].clone();
    if ch == "{" {
        p.i += 1;
        let mut items: Vec<Member> = Vec::new();
        p = skip_ws(p);
        if p.i < p.c.len() && p.c[p.i] == "}" {
            p.i += 1;
            return Some(PVal { p: p, v: Json::Obj(items) });
        }
        loop {
            p = skip_ws(p);
            let ks = parse_string(p)?;
            p = skip_ws(ks.p);
            let k = ks.s;
            if p.i >= p.c.len() || p.c[p.i] != ":" {
                return None;
            }
            p.i += 1;
            let pv = parse_value(p)?;
            p = skip_ws(pv.p);
            items.push(Member { k: k, v: pv.v });
            if p.i >= p.c.len() {
                return None;
            }
            if p.c[p.i] == "," {
                p.i += 1;
            } else if p.c[p.i] == "}" {
                p.i += 1;
                return Some(PVal { p: p, v: Json::Obj(items) });
            } else {
                return None;
            }
        }
    } else if ch == "[" {
        p.i += 1;
        let mut items: Vec<Json> = Vec::new();
        p = skip_ws(p);
        if p.i < p.c.len() && p.c[p.i] == "]" {
            p.i += 1;
            return Some(PVal { p: p, v: Json::Arr(items) });
        }
        loop {
            let pv = parse_value(p)?;
            p = skip_ws(pv.p);
            items.push(pv.v);
            if p.i >= p.c.len() {
                return None;
            }
            if p.c[p.i] == "," {
                p.i += 1;
            } else if p.c[p.i] == "]" {
                p.i += 1;
                return Some(PVal { p: p, v: Json::Arr(items) });
            } else {
                return None;
            }
        }
    } else if ch == "\"" {
        let ps = parse_string(p)?;
        Some(PVal { p: ps.p, v: Json::Text(ps.s) })
    } else if ch == "t" {
        let p2 = lit(p, Str::from("true"))?;
        Some(PVal { p: p2, v: Json::Bool(true) })
    } else if ch == "f" {
        let p2 = lit(p, Str::from("false"))?;
        Some(PVal { p: p2, v: Json::Bool(false) })
    } else if ch == "n" {
        let p2 = lit(p, Str::from("null"))?;
        Some(PVal { p: p2, v: Json::Null })
    } else {
        let ps = parse_number(p)?;
        Some(PVal { p: ps.p, v: Json::Num(ps.s) })
    }
}

fn parse_json(s: Str) -> Option<Json> {
    let p = Parser { c: s.chars().collect(), i: 0 };
    let pv = parse_value(p)?;
    let p3 = skip_ws(pv.p);
    if p3.i != p3.c.len() {
        return None;
    }
    Some(pv.v)
}

fn json_str(s: Str) -> Str {
    let mut out = Str::from("\"");
    for ch in s.chars() {
        if ch == "\"" {
            out.push_str(Str::from("\\\""));
        } else if ch == "\\" {
            out.push_str(Str::from("\\\\"));
        } else if ch == "\n" {
            out.push_str(Str::from("\\n"));
        } else if ch == "\r" {
            out.push_str(Str::from("\\r"));
        } else if ch == "\t" {
            out.push_str(Str::from("\\t"));
        } else {
            out.push_str(ch);
        }
    }
    out.push_str(Str::from("\""));
    out
}

fn canon(v: Json) -> Str {
    match v {
        Json::Null => Str::from("null"),
        Json::Bool(b) => {
            if b { Str::from("true") } else { Str::from("false") }
        }
        Json::Num(n) => n,
        Json::Text(s) => json_str(s),
        Json::Arr(items) => {
            let mut out = Str::from("[");
            let mut first = true;
            for it in items {
                if !first {
                    out.push_str(Str::from(","));
                }
                first = false;
                out.push_str(canon(it));
            }
            out.push_str(Str::from("]"));
            out
        }
        Json::Obj(items) => {
            let mut parts: Vec<KV> = Vec::new();
            for m in items {
                let k = m.k;
                let val = m.v;
                parts.push(KV { k: k, v: canon(val) });
            }
            let n = parts.len();
            let mut i = 1;
            while i < n {
                let mut j = i;
                while j > 0 && parts[j - 1].k > parts[j].k {
                    parts.swap(j - 1, j);
                    j -= 1;
                }
                i += 1;
            }
            let mut out = Str::from("{");
            let mut first = true;
            for kv in parts {
                if !first {
                    out.push_str(Str::from(","));
                }
                first = false;
                out.push_str(json_str(kv.k));
                out.push_str(Str::from(":"));
                out.push_str(kv.v);
            }
            out.push_str(Str::from("}"));
            out
        }
    }
}

fn pos_int(v: Json) -> Option<i64> {
    match v {
        Json::Num(n) => {
            if n.len() == 0 || n.len() > 15 {
                return None;
            }
            let mut x: i64 = 0;
            for ch in n.chars() {
                let d = digit_val(ch)?;
                x = x * 10 + d;
            }
            if x > 0 { Some(x) } else { None }
        }
        _ => None,
    }
}

fn sql_str(s: Str) -> Str {
    let mut out = Str::from("'");
    for ch in s.chars() {
        if ch == "'" {
            out.push_str(Str::from("''"));
        } else {
            out.push_str(ch);
        }
    }
    out.push_str(Str::from("'"));
    out
}

fn err(msg: Str) -> Str {
    format!("{{\"error\":{}}}", json_str(msg))
}

fn url_decode(s: Str) -> Str {
    let c: Vec<Str> = s.chars().collect();
    let t = ascii_table();
    let mut out = Str::new();
    let mut i = 0;
    while i < c.len() {
        if c[i] == "%" && i + 2 < c.len() {
            let a = hex_val(c[i + 1].clone());
            let b = hex_val(c[i + 2].clone());
            if a.is_some() && b.is_some() {
                let v = a.unwrap() * 16 + b.unwrap();
                if v >= 0x20 && v < 0x7f {
                    out.push_str(t[(v - 0x20) as usize].clone());
                    i += 3;
                    continue;
                }
            }
        }
        if c[i] == "+" {
            out.push_str(Str::from(" "));
        } else {
            out.push_str(c[i].clone());
        }
        i += 1;
    }
    out
}

fn payment_json(id: i64, account: Str, cents: i64, currency: Str, status: Str, refunded: i64) -> Str {
    format!(
        "{{\"id\":\"pay_{}\",\"account\":{},\"cents\":{},\"currency\":{},\"status\":{},\"refunded\":{}}}",
        id,
        json_str(account),
        cents,
        json_str(currency),
        json_str(status),
        refunded
    )
}

struct Pay {
    id: i64,
    account: Str,
    cents: i64,
    currency: Str,
    status: Str,
    refunded: i64,
}

fn pay_to_json(p: Pay) -> Str {
    payment_json(p.id, p.account, p.cents, p.currency, p.status, p.refunded)
}

fn parse_pay_id(s: Str) -> Option<i64> {
    let c: Vec<Str> = s.chars().collect();
    if c.len() < 5 || c.len() > 19 {
        return None;
    }
    if c[0] != "p" || c[1] != "a" || c[2] != "y" || c[3] != "_" {
        return None;
    }
    let mut x: i64 = 0;
    let mut i = 4;
    while i < c.len() {
        let d = digit_val(c[i].clone())?;
        x = x * 10 + d;
        i += 1;
    }
    Some(x)
}

fn split_on(s: Str, sep: Str) -> Vec<Str> {
    let mut segs: Vec<Str> = Vec::new();
    let mut cur = Str::new();
    for ch in s.chars() {
        if ch == sep {
            if cur.len() > 0 {
                segs.push(cur);
                cur = Str::new();
            }
        } else {
            cur.push_str(ch);
        }
    }
    if cur.len() > 0 {
        segs.push(cur);
    }
    segs
}

fn query_account(q: Str) -> Str {
    let mut account = Str::new();
    let pre: Vec<Str> = Str::from("account=").chars().collect();
    for part in split_on(q, Str::from("&")) {
        let pc: Vec<Str> = part.chars().collect();
        if pc.len() >= pre.len() {
            let mut same = true;
            let mut k = 0;
            while k < pre.len() {
                if pc[k] != pre[k] {
                    same = false;
                    break;
                }
                k += 1;
            }
            if same {
                let mut raw = Str::new();
                let mut j = pre.len();
                while j < pc.len() {
                    raw.push_str(pc[j].clone());
                    j += 1;
                }
                account = url_decode(raw);
            }
        }
    }
    account
}

fn reply(db: Db, status: i64, body: Str) -> Result<Resp, Str> {
    Ok(Resp { db: db, status: status, body: body })
}

fn handle(db: Db, method: Str, path: Str, query: Str, body: Str) -> Result<Resp, Str> {
    let segs = split_on(path, Str::from("/"));
    if segs.len() == 0 || segs[0] != "payments" {
        return reply(db, 404, err(Str::from("not found")));
    }
    if segs.len() == 1 {
        if method == "POST" {
            let mut account: Option<Str> = None;
            let mut cents: Option<i64> = None;
            let mut currency: Option<Str> = None;
            let mut ok = true;
            match parse_json(body) {
                Some(Json::Obj(items)) => {
                    for m in items {
                        let k = m.k;
                        let val = m.v;
                        if k == "account" {
                            match val {
                                Json::Text(s) => {
                                    if s.len() > 0 {
                                        account = Some(s);
                                    } else {
                                        ok = false;
                                    }
                                }
                                _ => {
                                    ok = false;
                                }
                            }
                        } else if k == "cents" {
                            match pos_int(val) {
                                Some(n) => {
                                    cents = Some(n);
                                }
                                None => {
                                    ok = false;
                                }
                            }
                        } else if k == "currency" {
                            match val {
                                Json::Text(s) => {
                                    if s == "EUR" || s == "USD" {
                                        currency = Some(s);
                                    } else {
                                        ok = false;
                                    }
                                }
                                _ => {
                                    ok = false;
                                }
                            }
                        } else {
                            ok = false;
                        }
                    }
                }
                _ => {
                    ok = false;
                }
            }
            if !ok {
                return reply(db, 422, err(Str::from("invalid payment")));
            }
            let a = match account {
                Some(x) => x,
                None => return reply(db, 422, err(Str::from("invalid payment"))),
            };
            let c = match cents {
                Some(x) => x,
                None => return reply(db, 422, err(Str::from("invalid payment"))),
            };
            let cur = match currency {
                Some(x) => x,
                None => return reply(db, 422, err(Str::from("invalid payment"))),
            };
            db.exec(format!(
                "INSERT INTO payments (account, cents, currency, status, refunded) VALUES ({}, {}, {}, 'pending', 0)",
                sql_str(a.clone()),
                c,
                sql_str(cur.clone())
            ))
            .map_err(|e| e.to_string())?;
            let rows = db
                .query(Str::from("SELECT MAX(id) FROM payments"))
                .map_err(|e| e.to_string())?;
            let id = rows[0].get_int(0);
            let out = payment_json(id, a, c, cur, Str::from("pending"), 0);
            return reply(db, 201, out);
        }
        if method == "GET" {
            let account = query_account(query);
            let rows = db
                .query(format!(
                    "SELECT id, account, cents, currency, status, refunded FROM payments WHERE account = {} ORDER BY id",
                    sql_str(account)
                ))
                .map_err(|e| e.to_string())?;
            let mut out = Str::from("[");
            let mut first = true;
            for r in rows {
                if !first {
                    out.push_str(Str::from(","));
                }
                first = false;
                out.push_str(payment_json(
                    r.get_int(0),
                    r.get_str(1),
                    r.get_int(2),
                    r.get_str(3),
                    r.get_str(4),
                    r.get_int(5),
                ));
            }
            out.push_str(Str::from("]"));
            return reply(db, 200, out);
        }
        return reply(db, 404, err(Str::from("not found")));
    }
    if segs.len() > 3 {
        return reply(db, 404, err(Str::from("not found")));
    }
    if segs.len() == 2 && method != "GET" {
        return reply(db, 404, err(Str::from("not found")));
    }
    let mut action = Str::new();
    if segs.len() == 3 {
        action = segs[2].clone();
        if method != "POST" || (action != "capture" && action != "cancel" && action != "refund") {
            return reply(db, 404, err(Str::from("not found")));
        }
    }
    let id = match parse_pay_id(segs[1].clone()) {
        Some(n) => n,
        None => return reply(db, 404, err(Str::from("not found"))),
    };
    let rows = db
        .query(format!(
            "SELECT id, account, cents, currency, status, refunded FROM payments WHERE id = {}",
            id
        ))
        .map_err(|e| e.to_string())?;
    if rows.len() == 0 {
        return reply(db, 404, err(Str::from("not found")));
    }
    let mut p = Pay {
        id: rows[0].get_int(0),
        account: rows[0].get_str(1),
        cents: rows[0].get_int(2),
        currency: rows[0].get_str(3),
        status: rows[0].get_str(4),
        refunded: rows[0].get_int(5),
    };
    if segs.len() == 2 {
        return reply(db, 200, pay_to_json(p));
    }
    if action == "capture" {
        if p.status == "pending" {
            db.exec(format!("UPDATE payments SET status = 'captured' WHERE id = {}", id))
                .map_err(|e| e.to_string())?;
            p.status = Str::from("captured");
            return reply(db, 200, pay_to_json(p));
        }
        if p.status == "captured" {
            return reply(db, 200, pay_to_json(p));
        }
        return reply(db, 409, err(Str::from("invalid transition")));
    }
    if action == "cancel" {
        if p.status == "pending" {
            db.exec(format!("UPDATE payments SET status = 'canceled' WHERE id = {}", id))
                .map_err(|e| e.to_string())?;
            p.status = Str::from("canceled");
            return reply(db, 200, pay_to_json(p));
        }
        return reply(db, 409, err(Str::from("invalid transition")));
    }
    let mut amount: Option<i64> = None;
    let mut ok = true;
    match parse_json(body) {
        Some(Json::Obj(items)) => {
            for m in items {
                let k = m.k;
                let val = m.v;
                if k == "cents" {
                    amount = pos_int(val);
                    if amount.is_none() {
                        ok = false;
                    }
                }
            }
        }
        _ => {
            ok = false;
        }
    }
    let n = match amount {
        Some(n) => n,
        None => return reply(db, 422, err(Str::from("invalid refund"))),
    };
    if !ok {
        return reply(db, 422, err(Str::from("invalid refund")));
    }
    if p.status != "captured" {
        return reply(db, 409, err(Str::from("invalid transition")));
    }
    if p.refunded + n > p.cents {
        return reply(db, 409, err(Str::from("exceeds captured")));
    }
    p.refunded = p.refunded + n;
    if p.refunded == p.cents {
        p.status = Str::from("refunded");
    }
    db.exec(format!(
        "UPDATE payments SET status = {}, refunded = {} WHERE id = {}",
        sql_str(p.status.clone()),
        p.refunded,
        id
    ))
    .map_err(|e| e.to_string())?;
    reply(db, 200, pay_to_json(p))
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, Str> {
    db.exec(Str::from("CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)"))
        .map_err(|e| e.to_string())?;
    db.exec(Str::from("CREATE TABLE IF NOT EXISTS idem (k TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL, status INTEGER NOT NULL, resp TEXT NOT NULL)"))
        .map_err(|e| e.to_string())?;

    let method = req.method().to_string().to_uppercase();
    let full = req.path().to_string();
    let mut path = Str::new();
    let mut query = Str::new();
    let mut inq = false;
    for ch in full.chars() {
        if inq {
            query.push_str(ch);
        } else if ch == "?" {
            inq = true;
        } else {
            path.push_str(ch);
        }
    }
    let body = req.body().to_string();

    let segs = split_on(path.clone(), Str::from("/"));
    let needs_key = method == "POST"
        && ((segs.len() == 1 && segs[0] == "payments")
            || (segs.len() == 3 && segs[0] == "payments" && segs[2] == "refund"));

    let canon_body = match parse_json(body.clone()) {
        Some(v) => canon(v),
        None => body.clone(),
    };

    let mut status: i64 = 0;
    let mut out = Str::new();
    let mut done = false;
    let mut key: Option<Str> = None;

    if needs_key {
        let hk: Option<Str> = match req.header("idempotency-key") {
            Some(k0) => {
                let k = k0.to_string();
                if k.len() > 0 { Some(k) } else { None }
            }
            None => None,
        };
        match hk {
            Some(k) => {
                let rows = db
                    .query(format!(
                        "SELECT method, path, body, status, resp FROM idem WHERE k = {}",
                        sql_str(k.clone())
                    ))
                    .map_err(|e| e.to_string())?;
                if rows.len() > 0 {
                    if rows[0].get_str(0) == method && rows[0].get_str(1) == full && rows[0].get_str(2) == canon_body {
                        status = rows[0].get_int(3);
                        out = rows[0].get_str(4);
                    } else {
                        status = 409;
                        out = err(Str::from("key reused"));
                    }
                    done = true;
                }
                key = Some(k);
            }
            None => {
                status = 400;
                out = err(Str::from("missing idempotency key"));
                done = true;
            }
        }
    }

    if !done {
        let r = handle(db, method.clone(), path, query, body)?;
        status = r.status;
        out = r.body;
        let db2 = r.db;
        match key {
            Some(k) => {
                if status >= 200 && status < 300 {
                    db2.exec(format!(
                        "INSERT OR REPLACE INTO idem (k, method, path, body, status, resp) VALUES ({}, {}, {}, {}, {}, {})",
                        sql_str(k),
                        sql_str(method.clone()),
                        sql_str(full.clone()),
                        sql_str(canon_body.clone()),
                        status,
                        sql_str(out.clone())
                    ))
                    .map_err(|e| e.to_string())?;
                }
            }
            None => {}
        }
    }

    res.status(status as u16);
    res.header("content-type", "application/json");
    Ok(out)
}

fn is_digits(s: &str) -> bool {
    if s.len() == 0 {
        return false;
    }
    for c in s.chars() {
        if !(c >= '0' && c <= '9') {
            return false;
        }
    }
    true
}

fn num(s: &str) -> i64 {
    let mut v: i64 = 0;
    for c in s.chars() {
        v = v * 10 + ((c as i64) - ('0' as i64));
    }
    v
}

fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in_month(y: i64, m: i64) -> i64 {
    if m == 2 {
        if is_leap(y) { 29 } else { 28 }
    } else if m == 4 || m == 6 || m == 9 || m == 11 {
        30
    } else {
        31
    }
}

fn days_from_civil(y0: i64, m: i64, d: i64) -> i64 {
    let y = if m <= 2 { y0 - 1 } else { y0 };
    let era = if y >= 0 { y / 400 } else { (y - 399) / 400 };
    let yoe = y - era * 400;
    let mp = if m > 2 { m - 3 } else { m + 9 };
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn parse_time(t: &str) -> Option<i64> {
    if t.len() != 20 || !t.is_ascii() {
        return None;
    }
    let b = t.as_bytes();
    if b[4] != b'-' || b[7] != b'-' || b[10] != b'T' || b[13] != b':' || b[16] != b':' || b[19] != b'Z' {
        return None;
    }
    let ys = &t[0..4];
    let mos = &t[5..7];
    let ds = &t[8..10];
    let hs = &t[11..13];
    let mis = &t[14..16];
    let ss = &t[17..19];
    if !is_digits(ys) || !is_digits(mos) || !is_digits(ds) || !is_digits(hs) || !is_digits(mis) || !is_digits(ss) {
        return None;
    }
    let y = num(ys);
    let mo = num(mos);
    let d = num(ds);
    let h = num(hs);
    let mi = num(mis);
    let s = num(ss);
    if mo < 1 || mo > 12 {
        return None;
    }
    if d < 1 || d > days_in_month(y, mo) {
        return None;
    }
    if h > 23 || mi > 59 || s > 59 {
        return None;
    }
    Some(days_from_civil(y, mo, d) * 86400 + h * 3600 + mi * 60 + s)
}

fn fmt_dur(d: i64) -> String {
    let h = d / 3600;
    let m = (d % 3600) / 60;
    let s = d % 60;
    format!("{:02}:{:02}:{:02}", h, m, s)
}

fn main(input: Dir) -> Result<String, String> {
    let text = match input.read_to_string("events.log") {
        Ok(t) => t,
        Err(e) => return Err(format!("cannot read events.log: {}", e)),
    };

    let mut malformed: i64 = 0;
    // (line, user, time, page)
    let mut recs: Vec<(String, String, i64, String)> = Vec::new();

    for raw in text.split('\n') {
        let line = if raw.ends_with('\r') { &raw[0..raw.len() - 1] } else { raw };
        if line.trim().is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split(' ').collect();
        if parts.len() != 3 || parts[1].is_empty() || parts[2].is_empty() {
            malformed += 1;
            continue;
        }
        match parse_time(parts[0]) {
            Some(t) => {
                recs.push((line.to_string(), parts[1].to_string(), t, parts[2].to_string()));
            }
            None => {
                malformed += 1;
            }
        }
    }

    // Deduplicate by exact line
    recs.sort_by(|a, b| a.0.cmp(&b.0));
    let mut duplicates: i64 = 0;
    let mut events: Vec<(String, i64, String)> = Vec::new();
    let mut i = 0;
    while i < recs.len() {
        if i > 0 && recs[i].0 == recs[i - 1].0 {
            duplicates += 1;
        } else {
            events.push((recs[i].1.clone(), recs[i].2, recs[i].3.clone()));
        }
        i += 1;
    }

    let mut out = String::new();

    if events.len() > 0 {
        events.sort_by(|a, b| {
            let c = a.0.cmp(&b.0);
            if c != std::cmp::Ordering::Equal { c } else { a.1.cmp(&b.1) }
        });

        let mut all_durs: Vec<i64> = Vec::new();
        let n = events.len();
        let mut i = 0;
        while i < n {
            let mut j = i;
            while j < n && events[j].0 == events[i].0 {
                j += 1;
            }
            let user = events[i].0.clone();
            let mut sessions: i64 = 0;
            let mut longest: i64 = 0;
            let mut start = events[i].1;
            let mut prev = events[i].1;
            let mut pages: Vec<String> = Vec::new();
            let mut k = i;
            while k < j {
                let t = events[k].1;
                if k > i && t - prev > 1800 {
                    let d = prev - start;
                    all_durs.push(d);
                    if d > longest { longest = d; }
                    sessions += 1;
                    start = t;
                }
                prev = t;
                pages.push(events[k].2.clone());
                k += 1;
            }
            let d = prev - start;
            all_durs.push(d);
            if d > longest { longest = d; }
            sessions += 1;

            pages.sort();
            pages.dedup();

            out.push_str(&format!(
                "{} sessions {} events {} longest {} pages {}\n",
                user,
                sessions,
                j - i,
                fmt_dur(longest),
                pages.len()
            ));
            i = j;
        }

        all_durs.sort();
        let med = all_durs[(all_durs.len() - 1) / 2];
        out.push_str(&format!("median {}\n", med));

        let mut allp: Vec<String> = Vec::new();
        for e in events.iter() {
            allp.push(e.2.clone());
        }
        allp.sort();
        let mut counts: Vec<(i64, String)> = Vec::new();
        let mut a = 0;
        while a < allp.len() {
            let mut b = a;
            while b < allp.len() && allp[b] == allp[a] {
                b += 1;
            }
            counts.push(((b - a) as i64, allp[a].clone()));
            a = b;
        }
        counts.sort_by(|x, y| {
            let c = y.0.cmp(&x.0);
            if c != std::cmp::Ordering::Equal { c } else { x.1.cmp(&y.1) }
        });
        let mut items: Vec<String> = Vec::new();
        let mut q = 0;
        while q < counts.len() && q < 3 {
            items.push(format!("{} ({})", counts[q].1, counts[q].0));
            q += 1;
        }
        out.push_str(&format!("top: {}\n", items.join(", ")));
    }

    out.push_str(&format!("malformed {} duplicates {}", malformed, duplicates));
    Ok(out)
}

fn digits_at(cs: Vec<char>, a: i64, b: i64) -> Option<i64> {
    let mut v: i64 = 0;
    let mut i = a;
    while i < b {
        let c = cs[i as usize];
        if c < '0' || c > '9' {
            return None;
        }
        v = v * 10 + ((c as i64) - ('0' as i64));
        i += 1;
    }
    Some(v)
}

