fn num_part(p: Str, n: i64) -> Option<i64> {
    if (p.len() as i64) != n {
        return None;
    }
    if p.starts_with("+") || p.starts_with("-") {
        return None;
    }
    match p.parse::<i64>() {
        Ok(v) => Some(v),
        Err(_) => None,
    }
}

