fn parse_time(t: Str) -> Option<i64> {
    if t.len() != 20 {
        return None;
    }
    if !t.ends_with("Z") {
        return None;
    }
    let halves: Vec<Str> = t.split("T").map(|p| p.to_string()).collect();
    if halves.len() != 2 {
        return None;
    }
    let dparts: Vec<Str> = halves[0].split("-").map(|p| p.to_string()).collect();
    if dparts.len() != 3 {
        return None;
    }
    let tparts: Vec<Str> = halves[1].split(":").map(|p| p.to_string()).collect();
    if tparts.len() != 3 {
        return None;
    }
    if tparts[2].len() != 3 || !tparts[2].ends_with("Z") {
        return None;
    }
    let secs: Str = tparts[2].trim_end_matches("Z").to_string();
    let y = match num_part(dparts[0].clone(), 4) { Some(v) => v, None => return None };
    let mo = match num_part(dparts[1].clone(), 2) { Some(v) => v, None => return None };
    let d = match num_part(dparts[2].clone(), 2) { Some(v) => v, None => return None };
    let h = match num_part(tparts[0].clone(), 2) { Some(v) => v, None => return None };
    let mi = match num_part(tparts[1].clone(), 2) { Some(v) => v, None => return None };
    let s = match num_part(secs, 2) { Some(v) => v, None => return None };
    if mo < 1 || mo > 12 {
        return None;
    }
    if d < 1 || d > days_in_month(y, mo) {
        return None;
    }
    if h > 23 || mi > 59 || s > 59 {
        return None;
    }
    Some(days_from_civil(y, mo, d) * 86400 + h * 3600 + mi * 60 + s)
}

