fn main(input: Dir) -> Result<Str, Str> {
    let text = match input.read_to_string("events.log") {
        Ok(t) => t,
        Err(e) => return Err(format!("cannot read events.log: {}", e)),
    };

    let mut malformed: i64 = 0;
    let mut recs: Vec<(Str, i64, Str)> = Vec::new();

    for line in text.lines() {
        if line.trim().is_empty() {
            continue;
        }
        let parts: Vec<Str> = line.split(" ").map(|p| p.to_string()).collect();
        if parts.len() != 3 || parts[1].is_empty() || parts[2].is_empty() {
            malformed += 1;
            continue;
        }
        match parse_time(parts[0].clone()) {
            Some(t) => {
                recs.push((parts[1].clone(), t, parts[2].clone()));
            }
            None => {
                malformed += 1;
            }
        }
    }

    recs.sort();
    let mut duplicates: i64 = 0;
    let mut events: Vec<(Str, i64, Str)> = Vec::new();
    let mut i = 0;
    while i < recs.len() {
        if i > 0 && recs[i] == recs[i - 1] {
            duplicates += 1;
        } else {
            events.push(recs[i].clone());
        }
        i += 1;
    }

    let mut lines: Vec<Str> = Vec::new();

    if events.len() > 0 {
        let mut all_durs: Vec<i64> = Vec::new();
        let n = events.len();
        let mut i = 0;
        while i < n {
            let mut j = i;
            while j < n && events[j].0 == events[i].0 {
                j += 1;
            }
            let user = events[i].0.clone();
            let mut sessions: i64 = 0;
            let mut longest: i64 = 0;
            let mut start = events[i].1;
            let mut prev = events[i].1;
            let mut pages: Vec<Str> = Vec::new();
            let mut k = i;
            while k < j {
                let t = events[k].1;
                if k > i && t - prev > 1800 {
                    let d = prev - start;
                    all_durs.push(d);
                    if d > longest { longest = d; }
                    sessions += 1;
                    start = t;
                }
                prev = t;
                pages.push(events[k].2.clone());
                k += 1;
            }
            let d = prev - start;
            all_durs.push(d);
            if d > longest { longest = d; }
            sessions += 1;

            pages.sort();
            pages.dedup();

            lines.push(format!(
                "{} sessions {} events {} longest {} pages {}",
                user,
                sessions,
                j - i,
                fmt_dur(longest),
                pages.len()
            ));
            i = j;
        }

        all_durs.sort();
        let med = all_durs[(all_durs.len() - 1) / 2];
        lines.push(format!("median {}", med));

        let mut allp: Vec<Str> = Vec::new();
        for e in events.iter() {
            allp.push(e.2.clone());
        }
        allp.sort();
        let mut counts: Vec<(i64, Str)> = Vec::new();
        let mut a = 0;
        while a < allp.len() {
            let mut b = a;
            while b < allp.len() && allp[b] == allp[a] {
                b += 1;
            }
            counts.push((0 - ((b - a) as i64), allp[a].clone()));
            a = b;
        }
        counts.sort();
        let mut items: Vec<Str> = Vec::new();
        let mut q = 0;
        while q < counts.len() && q < 3 {
            items.push(format!("{} ({})", counts[q].1, 0 - counts[q].0));
            q += 1;
        }
        lines.push(format!("top: {}", items.join(", ")));
    }

    lines.push(format!("malformed {} duplicates {}", malformed, duplicates));
    Ok(lines.join("\n"))
}

fn num_part(p: Str, n: i64) -> Option<i64> {
    let mut c: i64 = 0;
    for _ch in p.chars() {
        c += 1;
    }
    if c != n {
        return None;
    }
    if p.starts_with("+") || p.starts_with("-") {
        return None;
    }
    match p.parse::<i64>() {
        Ok(v) => Some(v),
        Err(_) => None,
    }
}

fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in_month(y: i64, m: i64) -> i64 {
    if m == 2 {
        if is_leap(y) { 29 } else { 28 }
    } else if m == 4 || m == 6 || m == 9 || m == 11 {
        30
    } else {
        31
    }
}

fn days_from_civil(y0: i64, m: i64, d: i64) -> i64 {
    let y = if m <= 2 { y0 - 1 } else { y0 };
    let era = if y >= 0 { y / 400 } else { (y - 399) / 400 };
    let yoe = y - era * 400;
    let mp = if m > 2 { m - 3 } else { m + 9 };
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn parse_time(t: Str) -> Option<i64> {
    if t.len() != 20 {
        return None;
    }
    if !t.ends_with("Z") {
        return None;
    }
    let halves: Vec<Str> = t.split("T").map(|p| p.to_string()).collect();
    if halves.len() != 2 {
        return None;
    }
    let dparts: Vec<Str> = halves[0].split("-").map(|p| p.to_string()).collect();
    if dparts.len() != 3 {
        return None;
    }
    let tparts: Vec<Str> = halves[1].split(":").map(|p| p.to_string()).collect();
    if tparts.len() != 3 {
        return None;
    }
    if tparts[2].len() != 3 || !tparts[2].ends_with("Z") {
        return None;
    }
    let secs: Str = tparts[2].trim_end_matches("Z").to_string();
    let y = match num_part(dparts[0].clone(), 4) { Some(v) => v, None => return None };
    let mo = match num_part(dparts[1].clone(), 2) { Some(v) => v, None => return None };
    let d = match num_part(dparts[2].clone(), 2) { Some(v) => v, None => return None };
    let h = match num_part(tparts[0].clone(), 2) { Some(v) => v, None => return None };
    let mi = match num_part(tparts[1].clone(), 2) { Some(v) => v, None => return None };
    let s = match num_part(secs, 2) { Some(v) => v, None => return None };
    if mo < 1 || mo > 12 {
        return None;
    }
    if d < 1 || d > days_in_month(y, mo) {
        return None;
    }
    if h > 23 || mi > 59 || s > 59 {
        return None;
    }
    Some(days_from_civil(y, mo, d) * 86400 + h * 3600 + mi * 60 + s)
}

fn pad2(v: i64) -> Str {
    if v < 10 {
        format!("0{}", v)
    } else {
        format!("{}", v)
    }
}

fn fmt_dur(d: i64) -> Str {
    let h = d / 3600;
    let m = (d % 3600) / 60;
    let s = d % 60;
    format!("{}:{}:{}", pad2(h), pad2(m), pad2(s))
}

