fn digit_val(ch: char) -> Option<i64> {
    match ch {
        '0' => Some(0),
        '1' => Some(1),
        '2' => Some(2),
        '3' => Some(3),
        '4' => Some(4),
        '5' => Some(5),
        '6' => Some(6),
        '7' => Some(7),
        '8' => Some(8),
        '9' => Some(9),
        _ => None,
    }
}

fn num_part(p: Str, n: i64) -> Option<i64> {
    let mut c: i64 = 0;
    let mut v: i64 = 0;
    for ch in p.chars() {
        c += 1;
        let dv = match digit_val(ch) {
            Some(x) => x,
            None => return None,
        };
        v = v * 10 + dv;
    }
    if c != n {
        return None;
    }
    Some(v)
}

