fn is_digit(c: char) -> bool {
    c >= '0' && c <= '9'
}

fn digit_val(c: char) -> i64 {
    (c as i64) - ('0' as i64)
}

fn parse_qty(s: &Str) -> Option<i64> {
    let cs: Vec<char> = s.chars().collect();
    let n = cs.len();
    if n == 0 {
        return None;
    }
    let mut i = 0;
    let mut neg = false;
    if cs[0] == '-' {
        neg = true;
        i = 1;
    }
    if i >= n {
        return None;
    }
    let mut v: i64 = 0;
    while i < n {
        if !is_digit(cs[i]) {
            return None;
        }
        v = v * 10 + digit_val(cs[i]);
        i += 1;
    }
    if neg {
        Some(-v)
    } else {
        Some(v)
    }
}

fn parse_price(s: &Str) -> Option<i64> {
    let cs: Vec<char> = s.chars().collect();
    let n = cs.len();
    let mut i = 0;
    let mut whole: i64 = 0;
    while i < n && is_digit(cs[i]) {
        whole = whole * 10 + digit_val(cs[i]);
        i += 1;
    }
    if i == 0 {
        return None;
    }
    if i == n {
        return Some(whole * 100);
    }
    if cs[i] != '.' {
        return None;
    }
    i += 1;
    let rest = n - i;
    if rest < 1 || rest > 2 {
        return None;
    }
    let mut frac: i64 = 0;
    let mut k = 0;
    while i < n {
        if !is_digit(cs[i]) {
            return None;
        }
        frac = frac * 10 + digit_val(cs[i]);
        i += 1;
        k += 1;
    }
    if k == 1 {
        frac = frac * 10;
    }
    Some(whole * 100 + frac)
}

fn fmt_cents(c: i64) -> Str {
    let neg = c < 0;
    let a = if neg { -c } else { c };
    let w = a / 100;
    let f = a % 100;
    let mut s = Str::new();
    if neg {
        s.push_str("-");
    }
    s.push_str(&format!("{}", w));
    s.push_str(".");
    if f < 10 {
        s.push_str("0");
    }
    s.push_str(&format!("{}", f));
    s
}

fn needs_quote(s: &Str) -> bool {
    for c in s.chars() {
        if c == ',' || c == '"' || c == '\r' || c == '\n' {
            return true;
        }
    }
    false
}

fn out_field(s: &Str) -> Str {
    if needs_quote(s) {
        let mut r = Str::new();
        r.push('"');
        for c in s.chars() {
            if c == '"' {
                r.push('"');
                r.push('"');
            } else {
                r.push(c);
            }
        }
        r.push('"');
        r
    } else {
        s.clone()
    }
}

fn main(input: Dir, out: Dir) -> Result<Str, Str> {
    let text = input.read("sales.csv")?;
    let cs: Vec<char> = text.chars().collect();
    let n = cs.len();

    let mut recs: Vec<Vec<Str>> = Vec::new();
    let mut bads: Vec<bool> = Vec::new();

    let mut i = 0;
    while i < n {
        if cs[i] == '\n' {
            i += 1;
            continue;
        }
        if cs[i] == '\r' && i + 1 < n && cs[i + 1] == '\n' {
            i += 2;
            continue;
        }
        let mut fields: Vec<Str> = Vec::new();
        let mut bad = false;
        loop {
            let mut f = Str::new();
            if i < n && cs[i] == '"' {
                i += 1;
                let mut closed = false;
                while i < n {
                    if cs[i] == '"' {
                        if i + 1 < n && cs[i + 1] == '"' {
                            f.push('"');
                            i += 2;
                        } else {
                            i += 1;
                            closed = true;
                            break;
                        }
                    } else {
                        f.push(cs[i]);
                        i += 1;
                    }
                }
                if !closed {
                    bad = true;
                }
                // anything after closing quote before delimiter is junk
                while i < n {
                    let c = cs[i];
                    if c == ',' || c == '\n' {
                        break;
                    }
                    if c == '\r' && i + 1 < n && cs[i + 1] == '\n' {
                        break;
                    }
                    bad = true;
                    f.push(c);
                    i += 1;
                }
            } else {
                while i < n {
                    let c = cs[i];
                    if c == ',' || c == '\n' {
                        break;
                    }
                    if c == '\r' && i + 1 < n && cs[i + 1] == '\n' {
                        break;
                    }
                    if c == '"' {
                        bad = true;
                    }
                    f.push(c);
                    i += 1;
                }
            }
            fields.push(f);
            if i >= n {
                break;
            }
            if cs[i] == ',' {
                i += 1;
                continue;
            }
            if cs[i] == '\n' {
                i += 1;
                break;
            }
            if cs[i] == '\r' {
                i += 2;
                break;
            }
            break;
        }
        recs.push(fields);
        bads.push(bad);
    }

    let mut clean = Str::new();
    clean.push_str("region,product,qty,price,note\n");

