        let mut p: i64 = 0;
        if ok {
            if fs[0].len() == 0 || fs[1].len() == 0 {
                ok = false;
            }
        }
        if ok {
            match parse_qty(&fs[2]) {
                Some(v) => {
                    q = v;
                }
                None => {
                    ok = false;
                }
            }
        }
        if ok {
            match parse_price(&fs[3]) {
                Some(v) => {
                    p = v;
                }
                None => {
                    ok = false;
                }
            }
        }
        if !ok {
