fn strip_digits(s: Str) -> Str {
    let mut t = s.clone();
    t = t.replace("0", "");
    t = t.replace("1", "");
    t = t.replace("2", "");
    t = t.replace("3", "");
    t = t.replace("4", "");
    t = t.replace("5", "");
    t = t.replace("6", "");
    t = t.replace("7", "");
    t = t.replace("8", "");
    t = t.replace("9", "");
    t
}

fn all_digits(s: Str) -> bool {
    if s.len() == 0 {
        return false;
    }
    strip_digits(s).len() == 0
}

fn to_int(s: Str) -> Option<i64> {
    let r: Result<i64, _> = s.parse();
    match r {
        Ok(v) => Some(v),
        Err(_) => None,
    }
}

fn parse_qty(s: Str) -> Option<i64> {
    if s.starts_with("-") {
        let rest = s.replacen("-", "", 1);
        if !all_digits(rest.clone()) {
            return None;
        }
        match to_int(rest) {
            Some(v) => Some(-v),
            None => None,
        }
    } else {
        if !all_digits(s.clone()) {
            return None;
        }
        to_int(s)
    }
}

fn parse_price(s: Str) -> Option<i64> {
    let mut parts: Vec<Str> = Vec::new();
    for p in s.split(".") {
        parts.push(p.to_str());
    }
    if parts.len() == 1 {
        if !all_digits(parts[0].clone()) {
            return None;
        }
        match to_int(parts[0].clone()) {
            Some(w) => Some(w * 100),
            None => None,
        }
    } else if parts.len() == 2 {
        if !all_digits(parts[0].clone()) || !all_digits(parts[1].clone()) {
            return None;
        }
        let fl = parts[1].len();
        if fl < 1 || fl > 2 {
            return None;
        }
        let w = match to_int(parts[0].clone()) {
            Some(v) => v,
            None => {
                return None;
            }
        };
        let mut f = match to_int(parts[1].clone()) {
            Some(v) => v,
            None => {
                return None;
            }
        };
        if fl == 1 {
            f = f * 10;
        }
        Some(w * 100 + f)
    } else {
        None
    }
}

fn fmt_cents(c: i64) -> Str {
    let neg = c < 0;
    let a = if neg { -c } else { c };
    let w = a / 100;
    let f = a % 100;
    let mut s = Str::new();
    if neg {
        s.push_str("-");
    }
    s.push_str(w.to_str());
    s.push_str(".");
    if f < 10 {
        s.push_str("0");
    }
    s.push_str(f.to_str());
    s
}

fn needs_quote(s: Str) -> bool {
    s.contains(",") || s.contains("\"") || s.contains("\r") || s.contains("\n")
}

fn out_field(s: Str) -> Str {
    if needs_quote(s.clone()) {
        let mut r = Str::new();
        r.push_str("\"");
        r.push_str(s.replace("\"", "\"\""));
        r.push_str("\"");
        r
    } else {
        s.clone()
    }
}

