            continue;
        }
        let price_s = fmt_cents(p);
        clean.push_str(out_field(fs[0].clone()));
        clean.push_str(",");
        clean.push_str(out_field(fs[1].clone()));
        clean.push_str(",");
        clean.push_str(out_field(fs[2].clone()));
        clean.push_str(",");
        clean.push_str(price_s);
        clean.push_str(",");
        clean.push_str(out_field(fs[4].clone()));
        clean.push_str("\n");

        let rev = q * p;
        let mut found = false;
        let mut k = 0;
        while k < reg_names.len() {
            if reg_names[k] == fs[0] {
                reg_rev[k] += rev;
                reg_qty[k] += q;
                found = true;
                break;
            }
            k += 1;
        }
        if !found {
            reg_names.push(fs[0].clone());
            reg_rev.push(rev);
            reg_qty.push(q);
        }
        let mut pf = false;
        let mut m = 0;
        while m < prod_name.len() {
            if prod_reg[m] == fs[0] && prod_name[m] == fs[1] {
                prod_rev[m] += rev;
                pf = true;
                break;
            }
            m += 1;
        }
        if !pf {
            prod_reg.push(fs[0].clone());
            prod_name.push(fs[1].clone());
            prod_rev.push(rev);
        }
        r += 1;
    }

    out.write("clean.csv", clean.clone())?;

    let mut idx: Vec<usize> = Vec::new();
    let mut a = 0;
    while a < reg_names.len() {
        idx.push(a);
        a += 1;
    }
    let mut x = 1;
    while x < idx.len() {
        let mut y = x;
        while y > 0 && reg_names[idx[y]] < reg_names[idx[y - 1]] {
            let t = idx[y];
            idx[y] = idx[y - 1];
            idx[y - 1] = t;
            y -= 1;
        }
        x += 1;
    }

    let mut res = Str::new();
    let mut z = 0;
    while z < idx.len() {
        let k = idx[z];
        let name = reg_names[k].clone();
        let mut best: Str = Str::new();
        let mut best_rev: i64 = 0;
        let mut have = false;
        let mut m = 0;
        while m < prod_name.len() {
            if prod_reg[m] == name {
                if !have
                    || prod_rev[m] > best_rev
                    || (prod_rev[m] == best_rev && prod_name[m] < best)
                {
                    best = prod_name[m].clone();
                    best_rev = prod_rev[m];
                    have = true;
                }
            }
            m += 1;
        }
        res.push_str(name.clone());
        res.push_str(" revenue ");
        res.push_str(fmt_cents(reg_rev[k]));
        res.push_str(" items ");
        res.push_str(reg_qty[k].to_str());
        res.push_str(" top ");
        res.push_str(best);
        res.push_str("\n");
        z += 1;
    }

    res.push_str("records ");
    res.push_str(total.to_str());
    res.push_str(" bad ");
    res.push_str(bad_nums.len().to_str());
    if bad_nums.len() > 0 {
        res.push_str(":");
        let mut b = 0;
        while b < bad_nums.len() {
            if b > 0 {
                res.push_str(",");
            }
            res.push_str(" ");
            res.push_str(bad_nums[b].to_str());
            b += 1;
        }
    }
    res.push_str("\n");
    Ok(res)
}

fn walk(docs: &Dir, rel: &Str, out: &mut Vec<Str>) -> Result<(), Error> {
    let target = if rel.is_empty() { Str::from(".") } else { rel.clone() };
    let entries = docs.read_dir(&target)?;
    for e in entries {
        let name = e.name.clone();
        let path = if rel.is_empty() {
            name.clone()
        } else {
            let mut p = rel.clone();
            p.push_str("/");
            p.push_str(&name);
            p
        };
        if e.is_dir {
            walk(docs, &path, out)?;
        } else {
            out.push(path);
        }
    }
    Ok(())
}

fn words_of(text: &Str) -> Vec<Str> {
    let mut out: Vec<Str> = Vec::new();
    let mut cur = Str::new();
    for c in text.chars() {
        if c.is_ascii() && !c.is_ascii_alphanumeric() {
            if !cur.is_empty() {
                out.push(cur.to_lowercase());
                cur = Str::new();
            }
        } else {
            cur.push(c);
        }
    }
    if !cur.is_empty() {
        out.push(cur.to_lowercase());
    }
    out
}

fn uniq(mut v: Vec<Str>) -> Vec<Str> {
    v.sort();
    v.dedup();
    v
}

fn hash_of(text: &Str) -> Str {
    let mut h: u64 = 14695981039346656037;
    let mut n: u64 = 0;
    for b in text.bytes() {
        h = h ^ (b as u64);
        h = h.wrapping_mul(1099511628211);
        n = n + 1;
    }
    let mut s = h.to_string();
    s.push_str("-");
    s.push_str(&n.to_string());
    s
}

fn split_lines(s: &Str) -> Vec<Str> {
    let mut out: Vec<Str> = Vec::new();
    for l in s.split('\n') {
        if !l.is_empty() {
            out.push(Str::from(l));
        }
    }
    out
}

fn join_lines(v: &Vec<Str>) -> Str {
    let mut s = Str::new();
    for x in v {
        s.push_str(x);
        s.push_str("\n");
    }
    s
}

fn word_key(w: &Str) -> Str {
    let mut k = Str::from("w:");
    k.push_str(w);
    k
}

fn file_key(p: &Str) -> Str {
    let mut k = Str::from("f:");
    k.push_str(p);
    k
}

fn get_list(index: &Kv, key: &Str) -> Result<Vec<Str>, Error> {
    match index.get(key)? {
        Some(v) => Ok(split_lines(&v)),
        None => Ok(Vec::new()),
    }
}

fn put_list(index: &Kv, key: &Str, v: &Vec<Str>) -> Result<(), Error> {
    if v.is_empty() {
        index.delete(key)?;
    } else {
        index.set(key, &join_lines(v))?;
    }
    Ok(())
}

fn unindex(index: &Kv, path: &Str) -> Result<(), Error> {
    let fk = file_key(path);
    let old_words = get_list(index, &fk)?;
    for w in old_words.iter() {
        let wk = word_key(w);
        let list = get_list(index, &wk)?;
        let mut kept: Vec<Str> = Vec::new();
        for p in list {
            if p != *path {
                kept.push(p);
            }
        }
        put_list(index, &wk, &kept)?;
    }
    index.delete(&fk)?;
    Ok(())
}

fn add_index(index: &Kv, path: &Str, words: &Vec<Str>) -> Result<(), Error> {
    for w in words.iter() {
        let wk = word_key(w);
        let mut list = get_list(index, &wk)?;
        let mut found = false;
        for p in list.iter() {
            if *p == *path {
                found = true;
            }
        }
        if !found {
            list.push(path.clone());
            list.sort();
        }
        put_list(index, &wk, &list)?;
    }
    put_list(index, &file_key(path), words)?;
    Ok(())
}

fn main(docs: Dir, queries: Dir, index: Kv) -> Result<Str, Error> {
    // previous state: lines "path\thash"
    let mut old_paths: Vec<Str> = Vec::new();
    let mut old_hashes: Vec<Str> = Vec::new();
    for line in get_list(&index, &Str::from("files"))? {
        let parts: Vec<&str> = line.split('\t').collect();
        if parts.len() == 2 {
            old_paths.push(Str::from(parts[0]));
            old_hashes.push(Str::from(parts[1]));
        }
    }

    let mut paths: Vec<Str> = Vec::new();
    walk(&docs, &Str::new(), &mut paths)?;
    paths.sort();

    let mut events: Vec<Str> = Vec::new();
    let mut unchanged: u64 = 0;
    let mut new_state: Vec<Str> = Vec::new();

    for p in paths.iter() {
        let text = docs.read_to_string(p)?;
        let h = hash_of(&text);
        let mut prev: Option<Str> = None;
        let mut i = 0;
        while i < old_paths.len() {
            if old_paths[i] == *p {
                prev = Some(old_hashes[i].clone());
            }
            i = i + 1;
        }
        match prev {
            None => {
                let mut e = Str::from("added ");
                e.push_str(p);
                events.push(e);
                add_index(&index, p, &uniq(words_of(&text)))?;
            }
            Some(oh) => {
                if oh == h {
                    unchanged = unchanged + 1;
                } else {
                    let mut e = Str::from("changed ");
                    e.push_str(p);
                    events.push(e);
                    unindex(&index, p)?;
                    add_index(&index, p, &uniq(words_of(&text)))?;
                }
            }
        }
        let mut st = p.clone();
        st.push_str("\t");
        st.push_str(&h);
        new_state.push(st);
    }

    for op in old_paths.iter() {
        let mut present = false;
        for p in paths.iter() {
            if *p == *op {
                present = true;
            }
        }
        if !present {
            let mut e = Str::from("removed ");
            e.push_str(op);
            events.push(e);
            unindex(&index, op)?;
        }
    }

    put_list(&index, &Str::from("files"), &new_state)?;

    // sort events by path
    let mut keyed: Vec<(Str, Str)> = Vec::new();
    for e in events {
        let idx = e.find(' ').unwrap();
        let path = Str::from(&e[idx + 1..]);
        keyed.push((path, e));
    }
    keyed.sort();

    let mut out = Str::new();
    for (_, e) in keyed.iter() {
        out.push_str(e);
        out.push_str("\n");
    }
    out.push_str("unchanged ");
    out.push_str(&unchanged.to_string());
    out.push_str("\n");

    let qtext = queries.read_to_string(&Str::from("queries.txt"))?;
    for raw in qtext.split('\n') {
        let line = Str::from(raw.trim_end_matches('\r'));
        if line.trim().is_empty() {
            continue;
        }
        let qw = uniq(words_of(&line));
        let mut result: Vec<Str> = paths.clone();
        for w in qw.iter() {
            let list = get_list(&index, &word_key(w))?;
            let mut next: Vec<Str> = Vec::new();
            for p in result.iter() {
                let mut hit = false;
                for q in list.iter() {
                    if *q == *p {
                        hit = true;
                    }
                }
                if hit {
                    next.push(p.clone());
                }
            }
            result = next;
        }
        result.sort();
        out.push_str(&line);
        out.push_str(": ");
        if result.is_empty() {
            out.push_str("none");
        } else {
            let mut first = true;
            for p in result.iter() {
                if !first {
                    out.push_str(", ");
                }
                out.push_str(p);
                first = false;
            }
        }
        out.push_str("\n");
    }

    Ok(out)
}

