            }
        }
    }
    paths.sort();

    let mut events: Vec<(Str, Str)> = Vec::new();
    let mut unchanged: Int = 0;
    let mut new_state: Vec<Str> = Vec::new();
    let mut to_unindex: Vec<Str> = Vec::new();
    let mut add_paths: Vec<Str> = Vec::new();
    let mut add_words: Vec<Vec<Str>> = Vec::new();

    for p in paths.clone() {
        let text = docs.read_to_string(p.clone())?;
        let h = hash_of(text.clone());
        let mut prev: Option<Str> = None;
        let mut i = 0;
        while i < old_paths.len() {
            if old_paths[i].clone() == p {
                prev = Some(old_hashes[i].clone());
            }
            i = i + 1;
        }
        match prev {
            None => {
                events.push((p.clone(), Str::from("added ")));
                add_paths.push(p.clone());
                add_words.push(uniq(words_of(text)));
            }
            Some(oh) => {
                if oh == h {
                    unchanged = unchanged + 1;
                } else {
                    events.push((p.clone(), Str::from("changed ")));
                    to_unindex.push(p.clone());
                    add_paths.push(p.clone());
                    add_words.push(uniq(words_of(text)));
                }
            }
        }
        new_state.push(cat(cat(p.clone(), Str::from("\t")), h));
    }

    for op in old_paths.clone() {
        if !contains(paths.clone(), op.clone()) {
            events.push((op.clone(), Str::from("removed ")));
            to_unindex.push(op.clone());
        }
    }

    // remove old index entries
    for path in to_unindex {
        let fk = cat(Str::from("f:"), path.clone());
        let old_raw = match index.get(fk.clone())? {
            Some(v) => v,
            None => Str::new(),
        };
        for w in nonempty_lines(old_raw) {
            let wk = cat(Str::from("w:"), w);
            let raw = match index.get(wk.clone())? {
                Some(v) => v,
                None => Str::new(),
            };
            let mut kept: Vec<Str> = Vec::new();
            for q in nonempty_lines(raw) {
                if q != path {
                    kept.push(q);
                }
            }
            if kept.is_empty() {
                index.delete(wk)?;
            } else {
                index.set(wk, join_lines(kept))?;
            }
        }
        index.delete(fk)?;
    }

    // add new index entries
    let mut k = 0;
    while k < add_paths.len() {
        let path = add_paths[k].clone();
        let words = add_words[k].clone();
        for w in words.clone() {
            let wk = cat(Str::from("w:"), w);
            let raw = match index.get(wk.clone())? {
                Some(v) => v,
                None => Str::new(),
            };
            let mut list = nonempty_lines(raw);
            if !contains(list.clone(), path.clone()) {
                list.push(path.clone());
                list.sort();
            }
            index.set(wk, join_lines(list))?;
        }
        let fk = cat(Str::from("f:"), path.clone());
        if words.is_empty() {
            index.delete(fk)?;
        } else {
            index.set(fk, join_lines(words))?;
        }
        k = k + 1;
    }

    if new_state.is_empty() {
        index.delete(Str::from("files"))?;
    } else {
        index.set(Str::from("files"), join_lines(new_state))?;
    }

    events.sort();
    let mut out = Str::new();
    for ev in events {
        out.push_str(ev.1.clone());
        out.push_str(ev.0.clone());
        out.push_str(Str::from("\n"));
    }
    out.push_str(Str::from("unchanged "));
    out.push_str(unchanged.to_string());
    out.push_str(Str::from("\n"));

    let qtext = queries.read_to_string(Str::from("queries.txt"))?;
    for raw in split_char(qtext, '\n') {
        let line = strip_cr(raw);
        if line.trim().is_empty() {
            continue;
        }
        let qw = uniq(words_of(line.clone()));
        let mut result: Vec<Str> = paths.clone();
        for w in qw {
            let wk = cat(Str::from("w:"), w);
            let lraw = match index.get(wk)? {
                Some(v) => v,
                None => Str::new(),
            };
            let list = nonempty_lines(lraw);
            let mut next: Vec<Str> = Vec::new();
            for p in result {
                if contains(list.clone(), p.clone()) {
                    next.push(p);
                }
            }
            result = next;
        }
        result.sort();
        out.push_str(line);
        out.push_str(Str::from(": "));
        if result.is_empty() {
            out.push_str(Str::from("none"));
        } else {
            let mut first = true;
            for p in result {
                if !first {
                    out.push_str(Str::from(", "));
                }
                out.push_str(p);
                first = false;
            }
        }
        out.push_str(Str::from("\n"));
    }

    Ok(out)
}

