fn hash_of(text: Str) -> Str {
    let mut h1: Int = 0;
    let mut h2: Int = 0;
    let mut n: Int = 0;
    for b in text.bytes() {
        let x = (b as Int) + 1;
        h1 = (h1 * 257 + x) % 1000000007;
        h2 = (h2 * 263 + x) % 998244353;
        n = n + 1;
    }
    let mut s = h1.to_string();
    s.push_str(Str::from("-"));
    s.push_str(h2.to_string());
    s.push_str(Str::from("-"));
    s.push_str(n.to_string());
    s
}

