fn enc(s: Str) -> Str {
    let mut out: Str = "".to_string();
    for b in s.bytes() {
        let c = b as char;
        if c.is_ascii_alphanumeric() || c == '-' || c == '_' || c == '.' || c == '~' {
            out = format!("{}{}", out, c);
        } else {
            out = format!("{}%{:02X}", out, b);
        }
    }
    out
}

