fn is_unreserved(b: i64) -> bool {
    (b >= 48 && b <= 57) || (b >= 65 && b <= 90) || (b >= 97 && b <= 122) || b == 45 || b == 95 || b == 46 || b == 126
}

fn enc(s: Str) -> Str {
    let mut plain = true;
    for b in s.bytes() {
        let n = b as i64;
        if !is_unreserved(n) {
            plain = false;
        }
    }
    if plain {
        return s;
    }
    let mut out: Str = "".to_string();
    for b in s.bytes() {
        let n = b as i64;
        out = format!("{}%{:02X}", out, n);
    }
    out
}

