fn hex_of(c: char) -> Option<Str> {
    let table = " !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~";
    let mut i: i64 = 32;
    for d in table.chars() {
        if d == c {
            return Some(format!("{:02X}", i));
        }
        i += 1;
    }
    None
}

fn enc(s: Str) -> Str {
    let mut out: Str = "".to_string();
    for c in s.chars() {
        if c.is_ascii_alphanumeric() || c == '-' || c == '_' || c == '.' || c == '~' {
            out = format!("{}{}", out, c);
        } else {
            match hex_of(c) {
                Some(h) => { out = format!("{}%{}", out, h); }
                None => { out = format!("{}{}", out, c); }
            }
        }
    }
    out
}

