                    [Value::from(sku.clone()), Value::from(version)],
                )?;
                pa += 1;
            } else {
                pi += 1;
            }
        }
        let new_cursor: Str = match next.clone() { Some(n) => n, None => cursor.clone() };
        db.execute(
            "INSERT INTO sync_state (id, cursor) VALUES (1, ?1) ON CONFLICT(id) DO UPDATE SET cursor = excluded.cursor",
            [Value::from(new_cursor.clone())],
        )?;
        db.execute("COMMIT", [])?;

        pages += 1;
        applied += pa;
        stale += ps;
        invalid += pi;

        match next {
            Some(n) => { cursor = n; }
            None => {
                status_line = "complete".to_string();
                break;
            }
        }
    }

    let mut out = format!("pages {} applied {} stale {} invalid {}\n{}\n", pages, applied, stale, invalid, status_line);
    let items = db.query("SELECT sku, qty, name FROM items WHERE present = 1 ORDER BY CAST(sku AS BLOB)", [])?;
    for r in items {
        let sku = r.get_str(0)?;
        let qty = r.get_i64(1)?;
        let name = r.get_str(2)?;
        out = format!("{}{} {} {}\n", out, sku, qty, name);
    }
    Ok(out)
}

fn enc(s: Str) -> Str {
    let mut out: Str = s.replace("%", "%25");
    out = out.replace(" ", "%20");
    out = out.replace("!", "%21");
    out = out.replace("\"", "%22");
    out = out.replace("#", "%23");
    out = out.replace("$", "%24");
    out = out.replace("&", "%26");
    out = out.replace("'", "%27");
    out = out.replace("(", "%28");
    out = out.replace(")", "%29");
    out = out.replace("*", "%2A");
    out = out.replace("+", "%2B");
    out = out.replace(",", "%2C");
    out = out.replace("/", "%2F");
    out = out.replace(":", "%3A");
    out = out.replace(";", "%3B");
    out = out.replace("<", "%3C");
    out = out.replace("=", "%3D");
    out = out.replace(">", "%3E");
    out = out.replace("?", "%3F");
    out = out.replace("@", "%40");
    out = out.replace("[", "%5B");
    out = out.replace("\\", "%5C");
    out = out.replace("]", "%5D");
    out = out.replace("^", "%5E");
    out = out.replace("`", "%60");
    out = out.replace("{", "%7B");
    out = out.replace("|", "%7C");
    out = out.replace("}", "%7D");
    out
}

fn int_of(v: Json) -> Option<i64> {
    v.as_i64()
}

fn last_version(db: Db, sku: Str) -> Result<Option<i64>, Str> {
    let rows = db.query("SELECT version FROM items WHERE sku = ?1", [Value::from(sku)])?;
    if rows.len() == 0 {
        Ok(None)
    } else {
        Ok(Some(rows[0].get_i64(0)?))
    }
}

fn main(api: Http, db: Db) -> Result<Str, Str> {
    db.execute("CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL, present INTEGER NOT NULL, version INTEGER NOT NULL)", [])?;
    db.execute("CREATE TABLE IF NOT EXISTS sync_state (id INTEGER PRIMARY KEY, cursor TEXT NOT NULL)", [])?;

    let rows = db.query("SELECT cursor FROM sync_state WHERE id = 1", [])?;
    let mut cursor: Str = if rows.len() == 0 { "0".to_string() } else { rows[0].get_str(0)? };

    let mut pages: i64 = 0;
    let mut applied: i64 = 0;
    let mut stale: i64 = 0;
    let mut invalid: i64 = 0;
    let mut status_line: Str = "".to_string();

    loop {
        let url = format!("/changes?cursor={}", enc(cursor.clone()));
        let resp = match api.get(url) {
            Ok(r) => r,
            Err(_) => {
                status_line = format!("stopped at {} (no response)", cursor);
                break;
            }
        };
        if resp.status != 200 {
            status_line = format!("stopped at {} (status {})", cursor, resp.status);
            break;
        }
        let body = match json::parse(resp.body.clone()) {
            Ok(j) => j,
            Err(_) => {
                status_line = format!("stopped at {} (invalid page)", cursor);
                break;
            }
        };
        if !body.is_object() {
            status_line = format!("stopped at {} (invalid page)", cursor);
            break;
        }
        let changes = match body.get("changes") {
            Some(c) => match c.as_array() {
                Some(a) => a,
                None => {
                    status_line = format!("stopped at {} (invalid page)", cursor);
                    break;
                }
            },
            None => {
                status_line = format!("stopped at {} (invalid page)", cursor);
                break;
            }
        };
        let next: Option<Str> = match body.get("next") {
            Some(n) => {
                if let Some(s) = n.as_str() {
                    Some(s.to_string())
                } else if let Some(i) = int_of(n.clone()) {
                    Some(format!("{}", i))
                } else {
                    None
                }
            }
            None => None,
        };

        let mut pa: i64 = 0;
        let mut ps: i64 = 0;
        let mut pi: i64 = 0;

        db.execute("BEGIN", [])?;
        for ch in changes {
            if !ch.is_object() {
                pi += 1;
                continue;
            }
            let op: Str = match ch.get("op") {
                Some(o) => match o.as_str() { Some(s) => s.to_string(), None => { pi += 1; continue; } },
                None => { pi += 1; continue; }
            };
            let sku: Str = match ch.get("sku") {
                Some(o) => match o.as_str() { Some(s) => s.to_string(), None => { pi += 1; continue; } },
                None => { pi += 1; continue; }
            };
            let version = match ch.get("version") {
                Some(o) => match int_of(o) { Some(v) => v, None => { pi += 1; continue; } },
                None => { pi += 1; continue; }
            };
            if op == "upsert" {
                let name: Str = match ch.get("name") {
                    Some(o) => match o.as_str() { Some(s) => s.to_string(), None => { pi += 1; continue; } },
                    None => { pi += 1; continue; }
                };
                let qty = match ch.get("qty") {
                    Some(o) => match int_of(o) { Some(v) => v, None => { pi += 1; continue; } },
                    None => { pi += 1; continue; }
                };
                let lv = last_version(db.clone(), sku.clone())?;
                let is_stale = match lv { Some(v) => version <= v, None => false };
                if is_stale {
                    ps += 1;
                    continue;
                }
                db.execute(
                    "INSERT INTO items (sku, name, qty, present, version) VALUES (?1, ?2, ?3, 1, ?4) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty, present = 1, version = excluded.version",
                    [Value::from(sku.clone()), Value::from(name), Value::from(qty), Value::from(version)],
                )?;
                pa += 1;
            } else if op == "delete" {
                let lv = last_version(db.clone(), sku.clone())?;
                let is_stale = match lv { Some(v) => version <= v, None => false };
                if is_stale {
                    ps += 1;
                    continue;
                }
                db.execute(
                    "INSERT INTO items (sku, name, qty, present, version) VALUES (?1, '', 0, 0, ?2) ON CONFLICT(sku) DO UPDATE SET present = 0, version = excluded.version",
                    [Value::from(sku.clone()), Value::from(version)],
                )?;
                pa += 1;
            } else {
                pi += 1;
            }
        }
        let new_cursor: Str = match next.clone() { Some(n) => n, None => cursor.clone() };
        db.execute(
            "INSERT INTO sync_state (id, cursor) VALUES (1, ?1) ON CONFLICT(id) DO UPDATE SET cursor = excluded.cursor",
            [Value::from(new_cursor.clone())],
        )?;
        db.execute("COMMIT", [])?;

        pages += 1;
        applied += pa;
        stale += ps;
        invalid += pi;

        match next {
            Some(n) => { cursor = n; }
            None => {
                status_line = "complete".to_string();
                break;
            }
        }
    }

    let mut out = format!("pages {} applied {} stale {} invalid {}\n{}\n", pages, applied, stale, invalid, status_line);
    let items = db.query("SELECT sku, qty, name FROM items WHERE present = 1 ORDER BY CAST(sku AS BLOB)", [])?;
    for r in items {
        let sku = r.get_str(0)?;
        let qty = r.get_i64(1)?;
        let name = r.get_str(2)?;
        out = format!("{}{} {} {}\n", out, sku, qty, name);
    }
    Ok(out)
}

enum Json {
    Null,
    Bool(bool),
    Num(Str),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct P {
    b: Vec<u8>,
    i: usize,
}

fn ws(p: &mut P) {
    while p.i < p.b.len() {
        let c = p.b[p.i];
        if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' {
            p.i += 1;
        } else {
            break;
        }
    }
}

fn hexval(c: u8) -> Option<u32> {
    if c >= b'0' && c <= b'9' {
        Some((c - b'0') as u32)
    } else if c >= b'a' && c <= b'f' {
        Some((c - b'a' + 10) as u32)
    } else if c >= b'A' && c <= b'F' {
        Some((c - b'A' + 10) as u32)
    } else {
        None
    }
}

fn read_hex4(p: &mut P) -> Option<u32> {
    if p.i + 4 > p.b.len() {
        return None;
    }
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        let h = hexval(p.b[p.i + k])?;
        v = v * 16 + h;
        k += 1;
    }
    p.i += 4;
    Some(v)
}

fn push_utf8(out: &mut Vec<u8>, cp: u32) {
    if cp < 0x80 {
        out.push(cp as u8);
    } else if cp < 0x800 {
        out.push((0xC0 | (cp >> 6)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    } else if cp < 0x10000 {
        out.push((0xE0 | (cp >> 12)) as u8);
        out.push((0x80 | ((cp >> 6) & 0x3F)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    } else {
        out.push((0xF0 | (cp >> 18)) as u8);
        out.push((0x80 | ((cp >> 12) & 0x3F)) as u8);
        out.push((0x80 | ((cp >> 6) & 0x3F)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    }
}

fn parse_string(p: &mut P) -> Option<Str> {
    if p.i >= p.b.len() || p.b[p.i] != b'"' {
        return None;
    }
    p.i += 1;
    let mut out: Vec<u8> = Vec::new();
    loop {
        if p.i >= p.b.len() {
            return None;
        }
        let c = p.b[p.i];
        p.i += 1;
        if c == b'"' {
            break;
        } else if c == b'\\' {
            if p.i >= p.b.len() {
                return None;
            }
            let e = p.b[p.i];
            p.i += 1;
            if e == b'"' {
                out.push(b'"');
            } else if e == b'\\' {
                out.push(b'\\');
            } else if e == b'/' {
                out.push(b'/');
            } else if e == b'b' {
                out.push(8);
            } else if e == b'f' {
                out.push(12);
            } else if e == b'n' {
                out.push(b'\n');
            } else if e == b'r' {
                out.push(b'\r');
            } else if e == b't' {
                out.push(b'\t');
            } else if e == b'u' {
                let mut cp = read_hex4(p)?;
                if cp >= 0xD800 && cp < 0xDC00 {
                    if p.i + 1 < p.b.len() && p.b[p.i] == b'\\' && p.b[p.i + 1] == b'u' {
                        p.i += 2;
                        let lo = read_hex4(p)?;
                        if lo >= 0xDC00 && lo < 0xE000 {
                            cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                        } else {
                            return None;
                        }
                    } else {
                        return None;
                    }
                } else if cp >= 0xDC00 && cp < 0xE000 {
                    return None;
                }
                push_utf8(&mut out, cp);
            } else {
                return None;
            }
        } else if c < 0x20 {
            return None;
        } else {
            out.push(c);
        }
    }
    match Str::from_utf8(out) {
        Ok(s) => Some(s),
        Err(_) => None,
    }
}

fn is_digit(c: u8) -> bool {
    c >= b'0' && c <= b'9'
}

fn parse_number(p: &mut P) -> Option<Json> {
    let start = p.i;
    if p.i < p.b.len() && p.b[p.i] == b'-' {
        p.i += 1;
    }
    let ds = p.i;
    while p.i < p.b.len() && is_digit(p.b[p.i]) {
        p.i += 1;
    }
    if p.i == ds {
        return None;
    }
    if p.i - ds > 1 && p.b[ds] == b'0' {
        return None;
    }
    if p.i < p.b.len() && p.b[p.i] == b'.' {
        p.i += 1;
        let fs = p.i;
        while p.i < p.b.len() && is_digit(p.b[p.i]) {
            p.i += 1;
        }
        if p.i == fs {
            return None;
        }
    }
    if p.i < p.b.len() && (p.b[p.i] == b'e' || p.b[p.i] == b'E') {
        p.i += 1;
        if p.i < p.b.len() && (p.b[p.i] == b'+' || p.b[p.i] == b'-') {
            p.i += 1;
        }
        let es = p.i;
        while p.i < p.b.len() && is_digit(p.b[p.i]) {
            p.i += 1;
        }
        if p.i == es {
            return None;
        }
    }
    let mut raw: Vec<u8> = Vec::new();
    let mut k = start;
    while k < p.i {
        raw.push(p.b[k]);
        k += 1;
    }
    match Str::from_utf8(raw) {
        Ok(s) => Some(Json::Num(s)),
        Err(_) => None,
    }
}

fn expect_word(p: &mut P, w: &str) -> bool {
    let wb = w.as_bytes();
    if p.i + wb.len() > p.b.len() {
        return false;
    }
    let mut k = 0;
    while k < wb.len() {
        if p.b[p.i + k] != wb[k] {
            return false;
        }
        k += 1;
    }
    p.i += wb.len();
    true
}

fn parse_value(p: &mut P, depth: usize) -> Option<Json> {
    if depth > 200 {
        return None;
    }
    ws(p);
    if p.i >= p.b.len() {
        return None;
    }
    let c = p.b[p.i];
    if c == b'{' {
        p.i += 1;
        let mut items: Vec<(Str, Json)> = Vec::new();
        ws(p);
        if p.i < p.b.len() && p.b[p.i] == b'}' {
            p.i += 1;
            return Some(Json::Obj(items));
        }
        loop {
            ws(p);
            let k = parse_string(p)?;
            ws(p);
            if p.i >= p.b.len() || p.b[p.i] != b':' {
                return None;
            }
            p.i += 1;
            let v = parse_value(p, depth + 1)?;
            items.push((k, v));
            ws(p);
            if p.i >= p.b.len() {
                return None;
            }
            if p.b[p.i] == b',' {
                p.i += 1;
            } else if p.b[p.i] == b'}' {
                p.i += 1;
                return Some(Json::Obj(items));
            } else {
                return None;
            }
        }
    } else if c == b'[' {
        p.i += 1;
        let mut items: Vec<Json> = Vec::new();
        ws(p);
        if p.i < p.b.len() && p.b[p.i] == b']' {
            p.i += 1;
            return Some(Json::Arr(items));
        }
        loop {
            let v = parse_value(p, depth + 1)?;
            items.push(v);
            ws(p);
            if p.i >= p.b.len() {
                return None;
            }
            if p.b[p.i] == b',' {
                p.i += 1;
            } else if p.b[p.i] == b']' {
                p.i += 1;
                return Some(Json::Arr(items));
            } else {
                return None;
            }
        }
    } else if c == b'"' {
        let s = parse_string(p)?;
        Some(Json::Text(s))
    } else if c == b't' {
        if expect_word(p, "true") { Some(Json::Bool(true)) } else { None }
    } else if c == b'f' {
        if expect_word(p, "false") { Some(Json::Bool(false)) } else { None }
    } else if c == b'n' {
        if expect_word(p, "null") { Some(Json::Null) } else { None }
    } else {
        parse_number(p)
    }
}

fn parse_json(s: &str) -> Option<Json> {
    let mut p = P { b: s.as_bytes().to_vec(), i: 0 };
    let v = parse_value(&mut p, 0)?;
    ws(&mut p);
    if p.i != p.b.len() {
        return None;
    }
    Some(v)
}

fn parse_int(s: &str) -> Option<i64> {
    let b = s.as_bytes();
    let mut i = 0;
    let mut neg = false;
    if i < b.len() && b[i] == b'-' {
        neg = true;
        i += 1;
    }
    if i >= b.len() {
        return None;
    }
    let mut v: i64 = 0;
    while i < b.len() {
        let c = b[i];
        if !is_digit(c) {
            return None;
        }
        let d = (c - b'0') as i64;
        v = v.checked_mul(10)?;
        if neg {
            v = v.checked_sub(d)?;
        } else {
            v = v.checked_add(d)?;
        }
        i += 1;
    }
    Some(v)
}

fn hex_encode(s: &str) -> Str {
    let digits = b"0123456789abcdef";
    let mut out: Vec<u8> = Vec::new();
    for c in s.as_bytes() {
        out.push(digits[(*c >> 4) as usize]);
        out.push(digits[(*c & 15) as usize]);
    }
    if out.len() == 0 {
        out.push(b'-');
    }
    match Str::from_utf8(out) {
        Ok(x) => x,
        Err(_) => Str::new(),
    }
}

fn hex_decode(s: &str) -> Option<Str> {
    if s == "-" {
        return Some(Str::new());
    }
    let b = s.as_bytes();
    if b.len() % 2 != 0 {
        return None;
    }
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let h = hexval(b[i])?;
        let l = hexval(b[i + 1])?;
        out.push((h * 16 + l) as u8);
        i += 2;
    }
    match Str::from_utf8(out) {
        Ok(x) => Some(x),
        Err(_) => None,
    }
}

struct Job {
    id: Str,
    priority: i64,
    due: i64,
    attempts: i64,
    state: i64,
}

fn find_job(jobs: &Vec<Job>, id: &str) -> Option<usize> {
    let mut i = 0;
    while i < jobs.len() {
        if jobs[i].id.as_str() == id {
            return Some(i);
        }
        i += 1;
    }
    None
}

fn obj_get<'a>(items: &'a Vec<(Str, Json)>, key: &str) -> Option<&'a Json> {
    let mut found: Option<&'a Json> = None;
    for (k, v) in items.iter() {
        if k.as_str() == key {
            found = Some(v);
        }
    }
    found
}

fn better(a: &Job, b: &Job) -> bool {
    if a.priority != b.priority {
        return a.priority > b.priority;
    }
    if a.due != b.due {
        return a.due < b.due;
    }
    a.id.as_bytes() < b.id.as_bytes()
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
    let now: i64 = clock.now();
    let mut out: Vec<Str> = Vec::new();

    let mut jobs: Vec<Job> = Vec::new();
    match queue.get("jobs") {
        Some(data) => {
            for line in data.split('\n') {
                let parts: Vec<&str> = line.split(' ').collect();
                if parts.len() != 5 {
                    continue;
                }
                let st = parse_int(parts[0]);
                let pr = parse_int(parts[1]);
                let du = parse_int(parts[2]);
                let at = parse_int(parts[3]);
                let id = hex_decode(parts[4]);
                match (st, pr, du, at, id) {
                    (Some(st), Some(pr), Some(du), Some(at), Some(id)) => {
                        jobs.push(Job { id: id, priority: pr, due: du, attempts: at, state: st });
                    }
                    _ => {}
                }
            }
        }
        None => {}
    }

    let enq: Str = match input.read("enqueue.jsonl") {
        Ok(s) => s,
        Err(_) => Str::new(),
    };
    let mut lineno = 0;
    for raw in enq.split('\n') {
        lineno += 1;
        let line = raw.trim();
        if line.len() == 0 {
            continue;
        }
        let mut parsed: Option<(Str, i64)> = None;
        match parse_json(line) {
            Some(Json::Obj(items)) => {
                let idv = obj_get(&items, "id");
                let pv = obj_get(&items, "priority");
                match (idv, pv) {
                    (Some(Json::Text(id)), Some(Json::Num(n))) => match parse_int(n.as_str()) {
                        Some(pr) => {
                            parsed = Some((id.clone(), pr));
                        }
                        None => {}
                    },
                    _ => {}
                }
            }
            _ => {}
        }
        match parsed {
            None => {
                out.push(format!("invalid line {}", lineno));
            }
            Some((id, pr)) => {
                if find_job(&jobs, id.as_str()).is_some() {
                    out.push(format!("duplicate {}", id));
                } else {
                    jobs.push(Job { id: id, priority: pr, due: now, attempts: 0, state: 0 });
                }
            }
        }
    }

    let script: Option<Json> = match input.read("script.json") {
        Ok(s) => parse_json(s.as_str()),
        Err(_) => None,
    };

    let mut ran: Vec<bool> = Vec::new();
    let mut i = 0;
    while i < jobs.len() {
        ran.push(false);
        i += 1;
    }

    let mut count = 0;
    while count < 5 {
        let mut best: Option<usize> = None;
        let mut j = 0;
        while j < jobs.len() {
            if !ran[j] && jobs[j].state == 0 && jobs[j].due <= now {
                match best {
                    None => {
                        best = Some(j);
                    }
                    Some(b) => {
                        if better(&jobs[j], &jobs[b]) {
                            best = Some(j);
                        }
                    }
                }
            }
            j += 1;
        }
        let b = match best {
            Some(b) => b,
            None => break,
        };
        ran[b] = true;
        count += 1;
        jobs[b].attempts += 1;
        let attempt = jobs[b].attempts;

        let mut fail = false;
        match &script {
            Some(Json::Obj(items)) => match obj_get(items, jobs[b].id.as_str()) {
                Some(Json::Arr(list)) => {
                    if list.len() > 0 {
                        let mut idx = (attempt - 1) as usize;
                        if idx >= list.len() {
                            idx = list.len() - 1;
                        }
                        match &list[idx] {
                            Json::Text(s) => {
                                if s.as_str() == "fail" {
                                    fail = true;
                                }
                            }
                            _ => {}
                        }
                    }
                }
                _ => {}
            },
            _ => {}
        }

        if !fail {
            jobs[b].state = 1;
            out.push(format!("done {}", jobs[b].id));
        } else if attempt >= 4 {
            jobs[b].state = 2;
            out.push(format!("dead {}", jobs[b].id));
        } else {
            let mut secs: i64 = 60;
            let mut k = 1;
            while k < attempt {
                secs = secs * 2;
                k += 1;
            }
            jobs[b].due = now + secs * 1000;
            out.push(format!("retry {} in {}", jobs[b].id, secs));
        }
    }

    let mut pending = 0;
    let mut done = 0;
    let mut dead = 0;
    let mut data = Str::new();
    for job in jobs.iter() {
        if job.state == 0 {
            pending += 1;
        } else if job.state == 1 {
            done += 1;
        } else {
            dead += 1;
        }
        data.push_str(&format!(
            "{} {} {} {} {}\n",
            job.state,
            job.priority,
            job.due,
            job.attempts,
            hex_encode(job.id.as_str())
        ));
    }
    queue.set("jobs", data.as_str());

    out.push(format!("pending {} done {} dead {}", pending, done, dead));
    Ok(out.join("\n"))
}

enum Json {
    Null,
    Bool(bool),
    Num(Str),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct P {
    b: Vec<u8>,
    i: usize,
}

fn ws(p: P) -> P {
    let mut p = p;
    while p.i < p.b.len() {
        let c = p.b[p.i];
        if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' {
            p.i += 1;
        } else {
            break;
        }
    }
    p
}

fn hexval(c: u8) -> Option<u32> {
    if c >= b'0' && c <= b'9' {
        Some((c - b'0') as u32)
    } else if c >= b'a' && c <= b'f' {
        Some((c - b'a' + 10) as u32)
    } else if c >= b'A' && c <= b'F' {
        Some((c - b'A' + 10) as u32)
    } else {
        None
    }
}

fn read_hex4(p: P) -> (P, Option<u32>) {
    let mut p = p;
    if p.i + 4 > p.b.len() {
        return (p, None);
    }
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        match hexval(p.b[p.i + k]) {
            Some(h) => {
                v = v * 16 + h;
            }
            None => {
                return (p, None);
            }
        }
        k += 1;
    }
    p.i += 4;
    (p, Some(v))
}

fn push_utf8(out: Vec<u8>, cp: u32) -> Vec<u8> {
    let mut out = out;
    if cp < 0x80 {
        out.push(cp as u8);
    } else if cp < 0x800 {
        out.push((0xC0 | (cp >> 6)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    } else if cp < 0x10000 {
        out.push((0xE0 | (cp >> 12)) as u8);
        out.push((0x80 | ((cp >> 6) & 0x3F)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    } else {
        out.push((0xF0 | (cp >> 18)) as u8);
        out.push((0x80 | ((cp >> 12) & 0x3F)) as u8);
        out.push((0x80 | ((cp >> 6) & 0x3F)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    }
    out
}

fn parse_string(p: P) -> (P, Option<Str>) {
    let mut p = p;
    if p.i >= p.b.len() || p.b[p.i] != b'"' {
        return (p, None);
    }
    p.i += 1;
    let mut out: Vec<u8> = Vec::new();
    loop {
        if p.i >= p.b.len() {
            return (p, None);
        }
        let c = p.b[p.i];
        p.i += 1;
        if c == b'"' {
            break;
        } else if c == b'\\' {
            if p.i >= p.b.len() {
                return (p, None);
            }
            let e = p.b[p.i];
            p.i += 1;
            if e == b'"' {
                out.push(b'"');
            } else if e == b'\\' {
                out.push(b'\\');
            } else if e == b'/' {
                out.push(b'/');
            } else if e == b'b' {
                out.push(8);
            } else if e == b'f' {
                out.push(12);
            } else if e == b'n' {
                out.push(b'\n');
            } else if e == b'r' {
                out.push(b'\r');
            } else if e == b't' {
                out.push(b'\t');
            } else if e == b'u' {
                let (np, h) = read_hex4(p);
                p = np;
                let mut cp = match h {
                    Some(v) => v,
                    None => {
                        return (p, None);
                    }
                };
                if cp >= 0xD800 && cp < 0xDC00 {
                    if p.i + 1 < p.b.len() && p.b[p.i] == b'\\' && p.b[p.i + 1] == b'u' {
                        p.i += 2;
                        let (np2, h2) = read_hex4(p);
                        p = np2;
                        let lo = match h2 {
                            Some(v) => v,
                            None => {
                                return (p, None);
                            }
                        };
                        if lo >= 0xDC00 && lo < 0xE000 {
                            cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                        } else {
                            return (p, None);
                        }
                    } else {
                        return (p, None);
                    }
                } else if cp >= 0xDC00 && cp < 0xE000 {
                    return (p, None);
                }
                out = push_utf8(out, cp);
            } else {
                return (p, None);
            }
        } else if c < 0x20 {
            return (p, None);
        } else {
            out.push(c);
        }
    }
    match Str::from_utf8(out) {
        Ok(s) => (p, Some(s)),
        Err(_) => (p, None),
    }
}

fn is_digit(c: u8) -> bool {
    c >= b'0' && c <= b'9'
}

fn parse_number(p: P) -> (P, Option<Json>) {
    let mut p = p;
    let start = p.i;
    if p.i < p.b.len() && p.b[p.i] == b'-' {
        p.i += 1;
    }
    let ds = p.i;
    while p.i < p.b.len() && is_digit(p.b[p.i]) {
        p.i += 1;
    }
    if p.i == ds {
        return (p, None);
    }
    if p.i - ds > 1 && p.b[ds] == b'0' {
        return (p, None);
    }
    if p.i < p.b.len() && p.b[p.i] == b'.' {
        p.i += 1;
        let fs = p.i;
        while p.i < p.b.len() && is_digit(p.b[p.i]) {
            p.i += 1;
        }
        if p.i == fs {
            return (p, None);
        }
    }
    if p.i < p.b.len() && (p.b[p.i] == b'e' || p.b[p.i] == b'E') {
        p.i += 1;
        if p.i < p.b.len() && (p.b[p.i] == b'+' || p.b[p.i] == b'-') {
            p.i += 1;
        }
        let es = p.i;
        while p.i < p.b.len() && is_digit(p.b[p.i]) {
            p.i += 1;
        }
        if p.i == es {
            return (p, None);
        }
    }
    let mut raw: Vec<u8> = Vec::new();
    let mut k = start;
    while k < p.i {
        raw.push(p.b[k]);
        k += 1;
    }
    match Str::from_utf8(raw) {
        Ok(s) => (p, Some(Json::Num(s))),
        Err(_) => (p, None),
    }
}

fn expect_word(p: P, wb: Vec<u8>) -> (P, bool) {
    let mut p = p;
    if p.i + wb.len() > p.b.len() {
        return (p, false);
    }
    let mut k = 0;
    while k < wb.len() {
        if p.b[p.i + k] != wb[k] {
            return (p, false);
        }
        k += 1;
    }
    p.i += wb.len();
    (p, true)
}

fn parse_value(p: P, depth: usize) -> (P, Option<Json>) {
    let mut p = p;
    if depth > 200 {
        return (p, None);
    }
    p = ws(p);
    if p.i >= p.b.len() {
        return (p, None);
    }
    let c = p.b[p.i];
    if c == b'{' {
        p.i += 1;
        let mut items: Vec<(Str, Json)> = Vec::new();
        p = ws(p);
        if p.i < p.b.len() && p.b[p.i] == b'}' {
            p.i += 1;
            return (p, Some(Json::Obj(items)));
        }
        loop {
            p = ws(p);
            let (np, ko) = parse_string(p);
            p = np;
            let k = match ko {
                Some(k) => k,
                None => {
                    return (p, None);
                }
            };
            p = ws(p);
            if p.i >= p.b.len() || p.b[p.i] != b':' {
                return (p, None);
            }
            p.i += 1;
            let (np2, vo) = parse_value(p, depth + 1);
            p = np2;
            let v = match vo {
                Some(v) => v,
                None => {
                    return (p, None);
                }
            };
            items.push((k, v));
            p = ws(p);
            if p.i >= p.b.len() {
                return (p, None);
            }
            if p.b[p.i] == b',' {
                p.i += 1;
            } else if p.b[p.i] == b'}' {
                p.i += 1;
                return (p, Some(Json::Obj(items)));
            } else {
                return (p, None);
            }
        }
    } else if c == b'[' {
        p.i += 1;
        let mut items: Vec<Json> = Vec::new();
        p = ws(p);
        if p.i < p.b.len() && p.b[p.i] == b']' {
            p.i += 1;
            return (p, Some(Json::Arr(items)));
        }
        loop {
            let (np, vo) = parse_value(p, depth + 1);
            p = np;
            let v = match vo {
                Some(v) => v,
                None => {
                    return (p, None);
                }
            };
            items.push(v);
            p = ws(p);
            if p.i >= p.b.len() {
                return (p, None);
            }
            if p.b[p.i] == b',' {
                p.i += 1;
            } else if p.b[p.i] == b']' {
                p.i += 1;
                return (p, Some(Json::Arr(items)));
            } else {
                return (p, None);
            }
        }
    } else if c == b'"' {
        let (np, so) = parse_string(p);
        match so {
            Some(s) => (np, Some(Json::Text(s))),
            None => (np, None),
        }
    } else if c == b't' {
        let (np, ok) = expect_word(p, vec![b't', b'r', b'u', b'e']);
        if ok { (np, Some(Json::Bool(true))) } else { (np, None) }
    } else if c == b'f' {
        let (np, ok) = expect_word(p, vec![b'f', b'a', b'l', b's', b'e']);
        if ok { (np, Some(Json::Bool(false))) } else { (np, None) }
    } else if c == b'n' {
        let (np, ok) = expect_word(p, vec![b'n', b'u', b'l', b'l']);
        if ok { (np, Some(Json::Null)) } else { (np, None) }
    } else {
        parse_number(p)
    }
}

fn parse_json(s: Str) -> Option<Json> {
    let p = P { b: s.into_bytes(), i: 0 };
    let (np, vo) = parse_value(p, 0);
    let v = match vo {
        Some(v) => v,
        None => {
            return None;
        }
    };
    let np = ws(np);
    if np.i != np.b.len() {
        return None;
    }
    Some(v)
}

fn parse_int(s: Str) -> Option<i64> {
    let b = s.into_bytes();
    let mut i = 0;
    let mut neg = false;
    if i < b.len() && b[i] == b'-' {
        neg = true;
        i += 1;
    }
    if i >= b.len() {
        return None;
    }
    let mut v: i64 = 0;
    while i < b.len() {
        let c = b[i];
        if !is_digit(c) {
            return None;
        }
        let d = (c - b'0') as i64;
        v = match v.checked_mul(10) {
            Some(x) => x,
            None => {
                return None;
            }
        };
        if neg {
            v = match v.checked_sub(d) {
                Some(x) => x,
                None => {
                    return None;
                }
            };
        } else {
            v = match v.checked_add(d) {
                Some(x) => x,
                None => {
                    return None;
                }
            };
        }
        i += 1;
    }
    Some(v)
}

fn hex_digit(v: u8) -> u8 {
    if v < 10 {
        b'0' + v
    } else {
        b'a' + (v - 10)
    }
}

fn hex_encode(s: Str) -> Str {
    let b = s.into_bytes();
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        out.push(hex_digit(c >> 4));
        out.push(hex_digit(c & 15));
        i += 1;
    }
    if out.len() == 0 {
        out.push(b'-');
    }
    match Str::from_utf8(out) {
        Ok(x) => x,
        Err(_) => Str::new(),
    }
}

fn hex_decode(s: Str) -> Option<Str> {
    if s == "-" {
        return Some(Str::new());
    }
    let b = s.into_bytes();
    if b.len() % 2 != 0 {
        return None;
    }
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let h = match hexval(b[i]) {
            Some(x) => x,
            None => {
                return None;
            }
        };
        let l = match hexval(b[i + 1]) {
            Some(x) => x,
            None => {
                return None;
            }
        };
        out.push((h * 16 + l) as u8);
        i += 2;
    }
    match Str::from_utf8(out) {
        Ok(x) => Some(x),
        Err(_) => None,
    }
}

struct Job {
    id: Str,
    priority: i64,
    due: i64,
    attempts: i64,
    state: i64,
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
    let now: i64 = clock.now();
    let mut out: Vec<Str> = Vec::new();

    let mut jobs: Vec<Job> = Vec::new();
    match queue.get("jobs") {
        Some(data) => {
            for line in data.split('\n') {
                let parts: Vec<Str> = line.split(' ').map(|x| x.to_string()).collect();
                if parts.len() != 5 {
                    continue;
                }
                let st = parse_int(parts[0].clone());
                let pr = parse_int(parts[1].clone());
                let du = parse_int(parts[2].clone());
                let at = parse_int(parts[3].clone());
                let id = hex_decode(parts[4].clone());
                match (st, pr, du, at, id) {
                    (Some(st), Some(pr), Some(du), Some(at), Some(id)) => {
                        jobs.push(Job { id: id, priority: pr, due: du, attempts: at, state: st });
                    }
                    _ => {}
                }
            }
        }
        None => {}
    }

    let enq: Str = match input.read("enqueue.jsonl") {
        Ok(s) => s,
        Err(_) => Str::new(),
    };
    let mut lineno = 0;
    for raw in enq.split('\n') {
        lineno += 1;
        let line: Str = raw.trim().to_string();
        if line.len() == 0 {
            continue;
        }
        let mut parsed: Option<(Str, i64)> = None;
        match parse_json(line) {
            Some(Json::Obj(items)) => {
                let mut idv: Option<Json> = None;
                let mut pv: Option<Json> = None;
                for item in items {
                    let (k, v) = item;
                    if k == "id" {
                        idv = Some(v);
                    } else if k == "priority" {
                        pv = Some(v);
                    }
                }
                match (idv, pv) {
                    (Some(Json::Text(id)), Some(Json::Num(n))) => match parse_int(n) {
                        Some(pr) => {
                            parsed = Some((id, pr));
                        }
                        None => {}
                    },
                    _ => {}
                }
            }
            _ => {}
        }
        match parsed {
            None => {
                out.push(format!("invalid line {}", lineno));
            }
            Some((id, pr)) => {
                let mut exists = false;
                let mut j = 0;
                while j < jobs.len() {
                    if jobs[j].id == id {
                        exists = true;
                    }
                    j += 1;
                }
                if exists {
                    out.push(format!("duplicate {}", id));
                } else {
                    jobs.push(Job { id: id, priority: pr, due: now, attempts: 0, state: 0 });
                }
            }
        }
    }

    let mut script: Vec<(Str, Vec<Str>)> = Vec::new();
    match input.read("script.json") {
        Ok(s) => match parse_json(s) {
            Some(Json::Obj(items)) => {
                for item in items {
                    let (k, v) = item;
                    let mut outs: Vec<Str> = Vec::new();
                    match v {
                        Json::Arr(list) => {
                            for e in list {
                                match e {
                                    Json::Text(t) => {
                                        outs.push(t);
                                    }
                                    _ => {
                                        outs.push(Str::new());
                                    }
                                }
                            }
                        }
                        _ => {}
                    }
                    script.push((k, outs));
                }
            }
            _ => {}
        },
        Err(_) => {}
    }

    let mut ran: Vec<bool> = Vec::new();
    let mut i = 0;
    while i < jobs.len() {
        ran.push(false);
        i += 1;
    }

    let mut count = 0;
    while count < 5 {
        let mut best: Option<usize> = None;
        let mut j = 0;
        while j < jobs.len() {
            if !ran[j] && jobs[j].state == 0 && jobs[j].due <= now {
                match best {
                    None => {
                        best = Some(j);
                    }
                    Some(b) => {
                        let better = if jobs[j].priority != jobs[b].priority {
                            jobs[j].priority > jobs[b].priority
                        } else if jobs[j].due != jobs[b].due {
                            jobs[j].due < jobs[b].due
                        } else {
                            jobs[j].id < jobs[b].id
                        };
                        if better {
                            best = Some(j);
                        }
                    }
                }
            }
            j += 1;
        }
        let b = match best {
            Some(b) => b,
            None => break,
        };
        ran[b] = true;
        count += 1;
        jobs[b].attempts += 1;
        let attempt = jobs[b].attempts;

        let mut found: Option<usize> = None;
        let mut s = 0;
        while s < script.len() {
            if script[s].0 == jobs[b].id {
                found = Some(s);
            }
            s += 1;
        }
        let mut fail = false;
        match found {
            Some(si) => {
                let n = script[si].1.len();
                if n > 0 {
                    let mut idx = (attempt - 1) as usize;
                    if idx >= n {
                        idx = n - 1;
                    }
                    if script[si].1[idx] == "fail" {
                        fail = true;
                    }
                }
            }
            None => {}
        }

        if !fail {
            jobs[b].state = 1;
            out.push(format!("done {}", jobs[b].id));
        } else if attempt >= 4 {
            jobs[b].state = 2;
            out.push(format!("dead {}", jobs[b].id));
        } else {
            let mut secs: i64 = 60;
            let mut k = 1;
            while k < attempt {
                secs = secs * 2;
                k += 1;
            }
            jobs[b].due = now + secs * 1000;
            out.push(format!("retry {} in {}", jobs[b].id, secs));
        }
    }

    let mut pending = 0;
    let mut done = 0;
    let mut dead = 0;
    let mut data = Str::new();
    let mut j = 0;
    while j < jobs.len() {
        if jobs[j].state == 0 {
            pending += 1;
        } else if jobs[j].state == 1 {
            done += 1;
        } else {
            dead += 1;
        }
        let line = format!(
            "{} {} {} {} {}\n",
            jobs[j].state,
            jobs[j].priority,
            jobs[j].due,
            jobs[j].attempts,
            hex_encode(jobs[j].id.clone())
        );
        data = data + line;
        j += 1;
    }
    queue.set("jobs", data);

    out.push(format!("pending {} done {} dead {}", pending, done, dead));
    Ok(out.join("\n"))
}

enum Json {
    Null,
    Bool(bool),
    Num(Str),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct P {
    b: Vec<u8>,
    i: usize,
}

fn ws(p: P) -> P {
    let mut p = p;
    while p.i < p.b.len() {
        let c = p.b[p.i];
        if c == 32 || c == 9 || c == 10 || c == 13 {
            p.i += 1;
        } else {
            break;
        }
    }
    p
}

fn hexval(c: u8) -> Option<u32> {
    if c >= 48 && c <= 57 {
        Some((c - 48) as u32)
    } else if c >= 97 && c <= 102 {
        Some((c - 97 + 10) as u32)
    } else if c >= 65 && c <= 70 {
        Some((c - 65 + 10) as u32)
    } else {
        None
    }
}

fn read_hex4(p: P) -> (P, Option<u32>) {
    let mut p = p;
    if p.i + 4 > p.b.len() {
        return (p, None);
    }
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        match hexval(p.b[p.i + k]) {
            Some(h) => {
                v = v * 16 + h;
            }
            None => {
                return (p, None);
            }
        }
        k += 1;
    }
    p.i += 4;
    (p, Some(v))
}

fn push_utf8(out: Vec<u8>, cp: u32) -> Vec<u8> {
    let mut out = out;
    if cp < 0x80 {
        out.push(cp as u8);
    } else if cp < 0x800 {
        out.push((0xC0 | (cp >> 6)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    } else if cp < 0x10000 {
        out.push((0xE0 | (cp >> 12)) as u8);
        out.push((0x80 | ((cp >> 6) & 0x3F)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    } else {
        out.push((0xF0 | (cp >> 18)) as u8);
        out.push((0x80 | ((cp >> 12) & 0x3F)) as u8);
        out.push((0x80 | ((cp >> 6) & 0x3F)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    }
    out
}

fn parse_string(p: P) -> (P, Option<Str>) {
    let mut p = p;
    if p.i >= p.b.len() || p.b[p.i] != 34 {
        return (p, None);
    }
    p.i += 1;
    let mut out: Vec<u8> = Vec::new();
    loop {
        if p.i >= p.b.len() {
            return (p, None);
        }
        let c = p.b[p.i];
        p.i += 1;
        if c == 34 {
            break;
        } else if c == 92 {
            if p.i >= p.b.len() {
                return (p, None);
            }
            let e = p.b[p.i];
            p.i += 1;
            if e == 34 {
                out.push(34);
            } else if e == 92 {
                out.push(92);
            } else if e == 47 {
                out.push(47);
            } else if e == 98 {
                out.push(8);
            } else if e == 102 {
                out.push(12);
            } else if e == 110 {
                out.push(10);
            } else if e == 114 {
                out.push(13);
            } else if e == 116 {
                out.push(9);
            } else if e == 117 {
                let (np, h) = read_hex4(p);
                p = np;
                let mut cp = match h {
                    Some(v) => v,
                    None => {
                        return (p, None);
                    }
                };
                if cp >= 0xD800 && cp < 0xDC00 {
                    if p.i + 1 < p.b.len() && p.b[p.i] == 92 && p.b[p.i + 1] == 117 {
                        p.i += 2;
                        let (np2, h2) = read_hex4(p);
                        p = np2;
                        let lo = match h2 {
                            Some(v) => v,
                            None => {
                                return (p, None);
                            }
                        };
                        if lo >= 0xDC00 && lo < 0xE000 {
                            cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                        } else {
                            return (p, None);
                        }
                    } else {
                        return (p, None);
                    }
                } else if cp >= 0xDC00 && cp < 0xE000 {
                    return (p, None);
                }
                out = push_utf8(out, cp);
            } else {
                return (p, None);
            }
        } else if c < 0x20 {
            return (p, None);
        } else {
            out.push(c);
        }
    }
    match Str::from_utf8(out) {
        Ok(s) => (p, Some(s)),
        Err(_) => (p, None),
    }
}

fn is_digit(c: u8) -> bool {
    c >= 48 && c <= 57
}

fn parse_number(p: P) -> (P, Option<Json>) {
    let mut p = p;
    let start = p.i;
    if p.i < p.b.len() && p.b[p.i] == 45 {
        p.i += 1;
    }
    let ds = p.i;
    while p.i < p.b.len() && is_digit(p.b[p.i]) {
        p.i += 1;
    }
    if p.i == ds {
        return (p, None);
    }
    if p.i - ds > 1 && p.b[ds] == 48 {
        return (p, None);
    }
    if p.i < p.b.len() && p.b[p.i] == 46 {
        p.i += 1;
        let fs = p.i;
        while p.i < p.b.len() && is_digit(p.b[p.i]) {
            p.i += 1;
        }
        if p.i == fs {
            return (p, None);
        }
    }
    if p.i < p.b.len() && (p.b[p.i] == 101 || p.b[p.i] == 69) {
        p.i += 1;
        if p.i < p.b.len() && (p.b[p.i] == 43 || p.b[p.i] == 45) {
            p.i += 1;
        }
        let es = p.i;
        while p.i < p.b.len() && is_digit(p.b[p.i]) {
            p.i += 1;
        }
        if p.i == es {
            return (p, None);
        }
    }
    let mut raw: Vec<u8> = Vec::new();
    let mut k = start;
    while k < p.i {
        raw.push(p.b[k]);
        k += 1;
    }
    match Str::from_utf8(raw) {
        Ok(s) => (p, Some(Json::Num(s))),
        Err(_) => (p, None),
    }
}

fn expect_word(p: P, wb: Vec<u8>) -> (P, bool) {
    let mut p = p;
    if p.i + wb.len() > p.b.len() {
        return (p, false);
    }
    let mut k = 0;
    while k < wb.len() {
        if p.b[p.i + k] != wb[k] {
            return (p, false);
        }
        k += 1;
    }
    p.i += wb.len();
    (p, true)
}

fn parse_value(p: P, depth: usize) -> (P, Option<Json>) {
    let mut p = p;
    if depth > 200 {
        return (p, None);
    }
    p = ws(p);
    if p.i >= p.b.len() {
        return (p, None);
    }
    let c = p.b[p.i];
    if c == 123 {
        p.i += 1;
        let mut items: Vec<(Str, Json)> = Vec::new();
        p = ws(p);
        if p.i < p.b.len() && p.b[p.i] == 125 {
            p.i += 1;
            return (p, Some(Json::Obj(items)));
        }
        loop {
            p = ws(p);
            let (np, ko) = parse_string(p);
            p = np;
            let k = match ko {
                Some(k) => k,
                None => {
                    return (p, None);
                }
            };
            p = ws(p);
            if p.i >= p.b.len() || p.b[p.i] != 58 {
                return (p, None);
            }
            p.i += 1;
            let (np2, vo) = parse_value(p, depth + 1);
            p = np2;
            let v = match vo {
                Some(v) => v,
                None => {
                    return (p, None);
                }
            };
            items.push((k, v));
            p = ws(p);
            if p.i >= p.b.len() {
                return (p, None);
            }
            if p.b[p.i] == 44 {
                p.i += 1;
            } else if p.b[p.i] == 125 {
                p.i += 1;
                return (p, Some(Json::Obj(items)));
            } else {
                return (p, None);
            }
        }
    } else if c == 91 {
        p.i += 1;
        let mut items: Vec<Json> = Vec::new();
        p = ws(p);
        if p.i < p.b.len() && p.b[p.i] == 93 {
            p.i += 1;
            return (p, Some(Json::Arr(items)));
        }
        loop {
            let (np, vo) = parse_value(p, depth + 1);
            p = np;
            let v = match vo {
                Some(v) => v,
                None => {
                    return (p, None);
                }
            };
            items.push(v);
            p = ws(p);
            if p.i >= p.b.len() {
                return (p, None);
            }
            if p.b[p.i] == 44 {
                p.i += 1;
            } else if p.b[p.i] == 93 {
                p.i += 1;
                return (p, Some(Json::Arr(items)));
            } else {
                return (p, None);
            }
        }
    } else if c == 34 {
        let (np, so) = parse_string(p);
        match so {
            Some(s) => (np, Some(Json::Text(s))),
            None => (np, None),
        }
    } else if c == 116 {
        let w: Vec<u8> = vec![116, 114, 117, 101];
        let (np, ok) = expect_word(p, w);
        if ok { (np, Some(Json::Bool(true))) } else { (np, None) }
    } else if c == 102 {
        let w: Vec<u8> = vec![102, 97, 108, 115, 101];
        let (np, ok) = expect_word(p, w);
        if ok { (np, Some(Json::Bool(false))) } else { (np, None) }
    } else if c == 110 {
        let w: Vec<u8> = vec![110, 117, 108, 108];
        let (np, ok) = expect_word(p, w);
        if ok { (np, Some(Json::Null)) } else { (np, None) }
    } else {
        parse_number(p)
    }
}

fn parse_json(s: Str) -> Option<Json> {
    let p = P { b: s.into_bytes(), i: 0 };
    let (np, vo) = parse_value(p, 0);
    let v = match vo {
        Some(v) => v,
        None => {
            return None;
        }
    };
    let np = ws(np);
    if np.i != np.b.len() {
        return None;
    }
    Some(v)
}

fn parse_int(s: Str) -> Option<i64> {
    let b = s.into_bytes();
    let mut i = 0;
    let mut neg = false;
    if i < b.len() && b[i] == 45 {
        neg = true;
        i += 1;
    }
    if i >= b.len() {
        return None;
    }
    let mut v: i64 = 0;
    while i < b.len() {
        let c = b[i];
        if !is_digit(c) {
            return None;
        }
        let d = (c - 48) as i64;
        v = match v.checked_mul(10) {
            Some(x) => x,
            None => {
                return None;
            }
        };
        if neg {
            v = match v.checked_sub(d) {
                Some(x) => x,
                None => {
                    return None;
                }
            };
        } else {
            v = match v.checked_add(d) {
                Some(x) => x,
                None => {
                    return None;
                }
            };
        }
        i += 1;
    }
    Some(v)
}

fn hex_digit(v: u8) -> u8 {
    if v < 10 {
        48 + v
    } else {
        97 + (v - 10)
    }
}

fn hex_encode(s: Str) -> Str {
    let b = s.into_bytes();
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        out.push(hex_digit(c >> 4));
        out.push(hex_digit(c & 15));
        i += 1;
    }
    if out.len() == 0 {
        out.push(45);
    }
    match Str::from_utf8(out) {
        Ok(x) => x,
        Err(_) => Str::new(),
    }
}

fn hex_decode(s: Str) -> Option<Str> {
    if s == "-" {
        return Some(Str::new());
    }
    let b = s.into_bytes();
    if b.len() % 2 != 0 {
        return None;
    }
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let h = match hexval(b[i]) {
            Some(x) => x,
            None => {
                return None;
            }
        };
        let l = match hexval(b[i + 1]) {
            Some(x) => x,
            None => {
                return None;
            }
        };
        out.push((h * 16 + l) as u8);
        i += 2;
    }
    match Str::from_utf8(out) {
        Ok(x) => Some(x),
        Err(_) => None,
    }
}

struct Job {
    id: Str,
    priority: i64,
    due: i64,
    attempts: i64,
    state: i64,
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
    let now: i64 = clock.now();
    let mut out: Vec<Str> = Vec::new();

    let mut jobs: Vec<Job> = Vec::new();
    match queue.get("jobs") {
        Some(data) => {
            for line in data.split("\n") {
                let parts: Vec<Str> = line.split(" ").map(|x| x.to_string()).collect();
                if parts.len() != 5 {
                    continue;
                }
                let st = parse_int(parts[0].clone());
                let pr = parse_int(parts[1].clone());
                let du = parse_int(parts[2].clone());
                let at = parse_int(parts[3].clone());
                let id = hex_decode(parts[4].clone());
                match (st, pr, du, at, id) {
                    (Some(st), Some(pr), Some(du), Some(at), Some(id)) => {
                        jobs.push(Job { id: id, priority: pr, due: du, attempts: at, state: st });
                    }
                    _ => {}
                }
            }
        }
        None => {}
    }

    let enq: Str = match input.read("enqueue.jsonl") {
        Ok(s) => s,
        Err(_) => Str::new(),
    };
    let mut lineno = 0;
    for raw in enq.split("\n") {
        lineno += 1;
        let line: Str = raw.trim().to_string();
        if line.len() == 0 {
            continue;
        }
        let mut parsed: Option<(Str, i64)> = None;
        match parse_json(line) {
            Some(Json::Obj(items)) => {
                let mut idv: Option<Json> = None;
                let mut pv: Option<Json> = None;
                for item in items {
                    let (k, v) = item;
                    if k == "id" {
                        idv = Some(v);
                    } else if k == "priority" {
                        pv = Some(v);
                    }
                }
                match (idv, pv) {
                    (Some(Json::Text(id)), Some(Json::Num(n))) => match parse_int(n) {
                        Some(pr) => {
                            parsed = Some((id, pr));
                        }
                        None => {}
                    },
                    _ => {}
                }
            }
            _ => {}
        }
        match parsed {
            None => {
                out.push(format!("invalid line {}", lineno));
            }
            Some((id, pr)) => {
                let mut exists = false;
                let mut j = 0;
                while j < jobs.len() {
                    if jobs[j].id == id {
                        exists = true;
                    }
                    j += 1;
                }
                if exists {
                    out.push(format!("duplicate {}", id));
                } else {
                    jobs.push(Job { id: id, priority: pr, due: now, attempts: 0, state: 0 });
                }
            }
        }
    }

    let mut script: Vec<(Str, Vec<Str>)> = Vec::new();
    match input.read("script.json") {
        Ok(s) => match parse_json(s) {
            Some(Json::Obj(items)) => {
                for item in items {
                    let (k, v) = item;
                    let mut outs: Vec<Str> = Vec::new();
                    match v {
                        Json::Arr(list) => {
                            for e in list {
                                match e {
                                    Json::Text(t) => {
                                        outs.push(t);
                                    }
                                    _ => {
                                        outs.push(Str::new());
                                    }
                                }
                            }
                        }
                        _ => {}
                    }
                    script.push((k, outs));
                }
            }
            _ => {}
        },
        Err(_) => {}
    }

    let mut ran: Vec<bool> = Vec::new();
    let mut i = 0;
    while i < jobs.len() {
        ran.push(false);
        i += 1;
    }

    let mut count = 0;
    while count < 5 {
        let mut best: Option<usize> = None;
        let mut j = 0;
        while j < jobs.len() {
            if !ran[j] && jobs[j].state == 0 && jobs[j].due <= now {
                match best {
                    None => {
                        best = Some(j);
                    }
                    Some(b) => {
                        let better = if jobs[j].priority != jobs[b].priority {
                            jobs[j].priority > jobs[b].priority
                        } else if jobs[j].due != jobs[b].due {
                            jobs[j].due < jobs[b].due
                        } else {
                            jobs[j].id < jobs[b].id
                        };
                        if better {
                            best = Some(j);
                        }
                    }
                }
            }
            j += 1;
        }
        let b = match best {
            Some(b) => b,
            None => break,
        };
        ran[b] = true;
        count += 1;
        jobs[b].attempts += 1;
        let attempt = jobs[b].attempts;

        let mut found: Option<usize> = None;
        let mut s = 0;
        while s < script.len() {
            if script[s].0 == jobs[b].id {
                found = Some(s);
            }
            s += 1;
        }
        let mut fail = false;
        match found {
            Some(si) => {
                let n = script[si].1.len();
                if n > 0 {
                    let mut idx = (attempt - 1) as usize;
                    if idx >= n {
                        idx = n - 1;
                    }
                    if script[si].1[idx] == "fail" {
                        fail = true;
                    }
                }
            }
            None => {}
        }

        if !fail {
            jobs[b].state = 1;
            out.push(format!("done {}", jobs[b].id));
        } else if attempt >= 4 {
            jobs[b].state = 2;
            out.push(format!("dead {}", jobs[b].id));
        } else {
            let mut secs: i64 = 60;
            let mut k = 1;
            while k < attempt {
                secs = secs * 2;
                k += 1;
            }
            jobs[b].due = now + secs * 1000;
            out.push(format!("retry {} in {}", jobs[b].id, secs));
        }
    }

    let mut pending = 0;
    let mut done = 0;
    let mut dead = 0;
    let mut data = Str::new();
    let mut j = 0;
    while j < jobs.len() {
        if jobs[j].state == 0 {
            pending += 1;
        } else if jobs[j].state == 1 {
            done += 1;
        } else {
            dead += 1;
        }
        let line = format!(
            "{} {} {} {} {}\n",
            jobs[j].state,
            jobs[j].priority,
            jobs[j].due,
            jobs[j].attempts,
            hex_encode(jobs[j].id.clone())
        );
        data = data + line;
        j += 1;
    }
    queue.set("jobs", data);

    out.push(format!("pending {} done {} dead {}", pending, done, dead));
    Ok(out.join("\n"))
}

enum Json {
    Null,
    Bool(bool),
    Num(Str),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct P {
    b: Vec<u8>,
    i: usize,
}

fn ws(p: P) -> P {
    let mut p = p;
    while p.i < p.b.len() {
        let c = p.b[p.i];
        if c == 32 || c == 9 || c == 10 || c == 13 {
            p.i += 1;
        } else {
            break;
        }
    }
    p
}

fn hexval(c: u8) -> Option<u32> {
    if c >= 48 && c <= 57 {
        Some((c - 48) as u32)
    } else if c >= 97 && c <= 102 {
        Some((c - 97 + 10) as u32)
    } else if c >= 65 && c <= 70 {
        Some((c - 65 + 10) as u32)
    } else {
        None
    }
}

fn read_hex4(p: P) -> (P, Option<u32>) {
    let mut p = p;
    if p.i + 4 > p.b.len() {
        return (p, None);
    }
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        match hexval(p.b[p.i + k]) {
            Some(h) => {
                v = v * 16 + h;
            }
            None => {
                return (p, None);
            }
        }
        k += 1;
    }
    p.i += 4;
    (p, Some(v))
}

fn push_utf8(out: Vec<u8>, cp: u32) -> Vec<u8> {
    let mut out = out;
    if cp < 128 {
        out.push(cp as u8);
    } else if cp < 2048 {
        out.push((192 + cp / 64) as u8);
        out.push((128 + cp % 64) as u8);
    } else if cp < 65536 {
        out.push((224 + cp / 4096) as u8);
        out.push((128 + (cp / 64) % 64) as u8);
        out.push((128 + cp % 64) as u8);
    } else {
        out.push((240 + cp / 262144) as u8);
        out.push((128 + (cp / 4096) % 64) as u8);
        out.push((128 + (cp / 64) % 64) as u8);
        out.push((128 + cp % 64) as u8);
    }
    out
}

fn parse_string(p: P) -> (P, Option<Str>) {
    let mut p = p;
    if p.i >= p.b.len() || p.b[p.i] != 34 {
        return (p, None);
    }
    p.i += 1;
    let mut out: Vec<u8> = Vec::new();
    loop {
        if p.i >= p.b.len() {
            return (p, None);
        }
        let c = p.b[p.i];
        p.i += 1;
        if c == 34 {
            break;
        } else if c == 92 {
            if p.i >= p.b.len() {
                return (p, None);
            }
            let e = p.b[p.i];
            p.i += 1;
            if e == 34 {
                out.push(34);
            } else if e == 92 {
                out.push(92);
            } else if e == 47 {
                out.push(47);
            } else if e == 98 {
                out.push(8);
            } else if e == 102 {
                out.push(12);
            } else if e == 110 {
                out.push(10);
            } else if e == 114 {
                out.push(13);
            } else if e == 116 {
                out.push(9);
            } else if e == 117 {
                let (np, h) = read_hex4(p);
                p = np;
                let mut cp = match h {
                    Some(v) => v,
                    None => {
                        return (p, None);
                    }
                };
                if cp >= 55296 && cp < 56320 {
                    if p.i + 1 < p.b.len() && p.b[p.i] == 92 && p.b[p.i + 1] == 117 {
                        p.i += 2;
                        let (np2, h2) = read_hex4(p);
                        p = np2;
                        let lo = match h2 {
                            Some(v) => v,
                            None => {
                                return (p, None);
                            }
                        };
                        if lo >= 56320 && lo < 57344 {
                            cp = 65536 + (cp - 55296) * 1024 + (lo - 56320);
                        } else {
                            return (p, None);
                        }
                    } else {
                        return (p, None);
                    }
                } else if cp >= 56320 && cp < 57344 {
                    return (p, None);
                }
                out = push_utf8(out, cp);
            } else {
                return (p, None);
            }
        } else if c < 32 {
            return (p, None);
        } else {
            out.push(c);
        }
    }
    match Str::from_utf8(out) {
        Ok(s) => (p, Some(s)),
        Err(_) => (p, None),
    }
}

fn is_digit(c: u8) -> bool {
    c >= 48 && c <= 57
}

fn parse_number(p: P) -> (P, Option<Json>) {
    let mut p = p;
    let start = p.i;
    if p.i < p.b.len() && p.b[p.i] == 45 {
        p.i += 1;
    }
    let ds = p.i;
    while p.i < p.b.len() && is_digit(p.b[p.i]) {
        p.i += 1;
    }
    if p.i == ds {
        return (p, None);
    }
    if p.i - ds > 1 && p.b[ds] == 48 {
        return (p, None);
    }
    if p.i < p.b.len() && p.b[p.i] == 46 {
        p.i += 1;
        let fs = p.i;
        while p.i < p.b.len() && is_digit(p.b[p.i]) {
            p.i += 1;
        }
        if p.i == fs {
            return (p, None);
        }
    }
    if p.i < p.b.len() && (p.b[p.i] == 101 || p.b[p.i] == 69) {
        p.i += 1;
        if p.i < p.b.len() && (p.b[p.i] == 43 || p.b[p.i] == 45) {
            p.i += 1;
        }
        let es = p.i;
        while p.i < p.b.len() && is_digit(p.b[p.i]) {
            p.i += 1;
        }
        if p.i == es {
            return (p, None);
        }
    }
    let mut raw: Vec<u8> = Vec::new();
    let mut k = start;
    while k < p.i {
        raw.push(p.b[k]);
        k += 1;
    }
    match Str::from_utf8(raw) {
        Ok(s) => (p, Some(Json::Num(s))),
        Err(_) => (p, None),
    }
}

fn expect_word(p: P, wb: Vec<u8>) -> (P, bool) {
    let mut p = p;
    if p.i + wb.len() > p.b.len() {
        return (p, false);
    }
    let mut k = 0;
    while k < wb.len() {
        if p.b[p.i + k] != wb[k] {
            return (p, false);
        }
        k += 1;
    }
    p.i += wb.len();
    (p, true)
}

fn parse_value(p: P, depth: usize) -> (P, Option<Json>) {
    let mut p = p;
    if depth > 200 {
        return (p, None);
    }
    p = ws(p);
    if p.i >= p.b.len() {
        return (p, None);
    }
    let c = p.b[p.i];
    if c == 123 {
        p.i += 1;
        let mut items: Vec<(Str, Json)> = Vec::new();
        p = ws(p);
        if p.i < p.b.len() && p.b[p.i] == 125 {
            p.i += 1;
            return (p, Some(Json::Obj(items)));
        }
        loop {
            p = ws(p);
            let (np, ko) = parse_string(p);
            p = np;
            let k = match ko {
                Some(k) => k,
                None => {
                    return (p, None);
                }
            };
            p = ws(p);
            if p.i >= p.b.len() || p.b[p.i] != 58 {
                return (p, None);
            }
            p.i += 1;
            let (np2, vo) = parse_value(p, depth + 1);
            p = np2;
            let v = match vo {
                Some(v) => v,
                None => {
                    return (p, None);
                }
            };
            items.push((k, v));
            p = ws(p);
            if p.i >= p.b.len() {
                return (p, None);
            }
            if p.b[p.i] == 44 {
                p.i += 1;
            } else if p.b[p.i] == 125 {
                p.i += 1;
                return (p, Some(Json::Obj(items)));
            } else {
                return (p, None);
            }
        }
    } else if c == 91 {
        p.i += 1;
        let mut items: Vec<Json> = Vec::new();
        p = ws(p);
        if p.i < p.b.len() && p.b[p.i] == 93 {
            p.i += 1;
            return (p, Some(Json::Arr(items)));
        }
        loop {
            let (np, vo) = parse_value(p, depth + 1);
            p = np;
            let v = match vo {
                Some(v) => v,
                None => {
                    return (p, None);
                }
            };
            items.push(v);
            p = ws(p);
            if p.i >= p.b.len() {
                return (p, None);
            }
            if p.b[p.i] == 44 {
                p.i += 1;
            } else if p.b[p.i] == 93 {
                p.i += 1;
                return (p, Some(Json::Arr(items)));
            } else {
                return (p, None);
            }
        }
    } else if c == 34 {
        let (np, so) = parse_string(p);
        match so {
            Some(s) => (np, Some(Json::Text(s))),
            None => (np, None),
        }
    } else if c == 116 {
        let w: Vec<u8> = vec![116, 114, 117, 101];
        let (np, ok) = expect_word(p, w);
        if ok { (np, Some(Json::Bool(true))) } else { (np, None) }
    } else if c == 102 {
        let w: Vec<u8> = vec![102, 97, 108, 115, 101];
        let (np, ok) = expect_word(p, w);
        if ok { (np, Some(Json::Bool(false))) } else { (np, None) }
    } else if c == 110 {
        let w: Vec<u8> = vec![110, 117, 108, 108];
        let (np, ok) = expect_word(p, w);
        if ok { (np, Some(Json::Null)) } else { (np, None) }
    } else {
        parse_number(p)
    }
}

fn parse_json(s: Str) -> Option<Json> {
    let p = P { b: s.into_bytes(), i: 0 };
    let (np, vo) = parse_value(p, 0);
    let v = match vo {
        Some(v) => v,
        None => {
            return None;
        }
    };
    let np = ws(np);
    if np.i != np.b.len() {
        return None;
    }
    Some(v)
}

fn parse_int(s: Str) -> Option<i64> {
    let b = s.into_bytes();
    let mut i = 0;
    let mut neg = false;
    if i < b.len() && b[i] == 45 {
        neg = true;
        i += 1;
    }
    if i >= b.len() {
        return None;
    }
    let mut v: i64 = 0;
    while i < b.len() {
        let c = b[i];
        if !is_digit(c) {
            return None;
        }
        let d = (c - 48) as i64;
        v = match v.checked_mul(10) {
            Some(x) => x,
            None => {
                return None;
            }
        };
        if neg {
            v = match v.checked_sub(d) {
                Some(x) => x,
                None => {
                    return None;
                }
            };
        } else {
            v = match v.checked_add(d) {
                Some(x) => x,
                None => {
                    return None;
                }
            };
        }
        i += 1;
    }
    Some(v)
}

fn hex_digit(v: u8) -> u8 {
    if v < 10 {
        48 + v
    } else {
        97 + (v - 10)
    }
}

fn hex_encode(s: Str) -> Str {
    let b = s.into_bytes();
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        out.push(hex_digit(c / 16));
        out.push(hex_digit(c % 16));
        i += 1;
    }
    if out.len() == 0 {
        out.push(45);
    }
    match Str::from_utf8(out) {
        Ok(x) => x,
        Err(_) => Str::new(),
    }
}

fn hex_decode(s: Str) -> Option<Str> {
    if s == "-" {
        return Some(Str::new());
    }
    let b = s.into_bytes();
    if b.len() % 2 != 0 {
        return None;
    }
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let h = match hexval(b[i]) {
            Some(x) => x,
            None => {
                return None;
            }
        };
        let l = match hexval(b[i + 1]) {
            Some(x) => x,
            None => {
                return None;
            }
        };
        out.push((h * 16 + l) as u8);
        i += 2;
    }
    match Str::from_utf8(out) {
        Ok(x) => Some(x),
        Err(_) => None,
    }
}

struct Job {
    id: Str,
    priority: i64,
    due: i64,
    attempts: i64,
    state: i64,
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
    let now: i64 = clock.now();
    let mut out: Vec<Str> = Vec::new();

    let mut jobs: Vec<Job> = Vec::new();
    match queue.get("jobs") {
        Some(data) => {
            for line in data.split("\n") {
                let parts: Vec<Str> = line.split(" ").map(|x| x.to_string()).collect();
                if parts.len() != 5 {
                    continue;
                }
                let st = parse_int(parts[0].clone());
                let pr = parse_int(parts[1].clone());
                let du = parse_int(parts[2].clone());
                let at = parse_int(parts[3].clone());
                let id = hex_decode(parts[4].clone());
                match (st, pr, du, at, id) {
                    (Some(st), Some(pr), Some(du), Some(at), Some(id)) => {
                        jobs.push(Job { id: id, priority: pr, due: du, attempts: at, state: st });
                    }
                    _ => {}
                }
            }
        }
        None => {}
    }

    let enq: Str = match input.read("enqueue.jsonl") {
        Ok(s) => s,
        Err(_) => Str::new(),
    };
    let mut lineno = 0;
    for raw in enq.split("\n") {
        lineno += 1;
        let line: Str = raw.trim().to_string();
        if line.len() == 0 {
            continue;
        }
        let mut parsed: Option<(Str, i64)> = None;
        match parse_json(line) {
            Some(Json::Obj(items)) => {
                let mut idv: Option<Json> = None;
                let mut pv: Option<Json> = None;
                for item in items {
                    let (k, v) = item;
                    if k == "id" {
                        idv = Some(v);
                    } else if k == "priority" {
                        pv = Some(v);
                    }
                }
                match (idv, pv) {
                    (Some(Json::Text(id)), Some(Json::Num(n))) => match parse_int(n) {
                        Some(pr) => {
                            parsed = Some((id, pr));
                        }
                        None => {}
                    },
                    _ => {}
                }
            }
            _ => {}
        }
        match parsed {
            None => {
                out.push(format!("invalid line {}", lineno));
            }
            Some((id, pr)) => {
                let mut exists = false;
                let mut j = 0;
                while j < jobs.len() {
                    if jobs[j].id == id {
                        exists = true;
                    }
                    j += 1;
                }
                if exists {
                    out.push(format!("duplicate {}", id));
                } else {
                    jobs.push(Job { id: id, priority: pr, due: now, attempts: 0, state: 0 });
                }
            }
        }
    }

    let mut script: Vec<(Str, Vec<Str>)> = Vec::new();
    match input.read("script.json") {
        Ok(s) => match parse_json(s) {
            Some(Json::Obj(items)) => {
                for item in items {
                    let (k, v) = item;
                    let mut outs: Vec<Str> = Vec::new();
                    match v {
                        Json::Arr(list) => {
                            for e in list {
                                match e {
                                    Json::Text(t) => {
                                        outs.push(t);
                                    }
                                    _ => {
                                        outs.push(Str::new());
                                    }
                                }
                            }
                        }
                        _ => {}
                    }
                    script.push((k, outs));
                }
            }
            _ => {}
        },
        Err(_) => {}
    }

    let mut ran: Vec<bool> = Vec::new();
    let mut i = 0;
    while i < jobs.len() {
        ran.push(false);
        i += 1;
    }

    let mut count = 0;
    while count < 5 {
        let mut best: Option<usize> = None;
        let mut j = 0;
        while j < jobs.len() {
            if !ran[j] && jobs[j].state == 0 && jobs[j].due <= now {
                match best {
                    None => {
                        best = Some(j);
                    }
                    Some(b) => {
                        let better = if jobs[j].priority != jobs[b].priority {
                            jobs[j].priority > jobs[b].priority
                        } else if jobs[j].due != jobs[b].due {
                            jobs[j].due < jobs[b].due
                        } else {
                            jobs[j].id < jobs[b].id
                        };
                        if better {
                            best = Some(j);
                        }
                    }
                }
            }
            j += 1;
        }
        let b = match best {
            Some(b) => b,
            None => break,
        };
        ran[b] = true;
        count += 1;
        jobs[b].attempts += 1;
        let attempt = jobs[b].attempts;

        let mut found: Option<usize> = None;
        let mut s = 0;
        while s < script.len() {
            if script[s].0 == jobs[b].id {
                found = Some(s);
            }
            s += 1;
        }
        let mut fail = false;
        match found {
            Some(si) => {
                let n = script[si].1.len();
                if n > 0 {
                    let mut idx = (attempt - 1) as usize;
                    if idx >= n {
                        idx = n - 1;
                    }
                    if script[si].1[idx] == "fail" {
                        fail = true;
                    }
                }
            }
            None => {}
        }

        if !fail {
            jobs[b].state = 1;
            out.push(format!("done {}", jobs[b].id));
        } else if attempt >= 4 {
            jobs[b].state = 2;
            out.push(format!("dead {}", jobs[b].id));
        } else {
            let mut secs: i64 = 60;
            let mut k = 1;
            while k < attempt {
                secs = secs * 2;
                k += 1;
            }
            jobs[b].due = now + secs * 1000;
            out.push(format!("retry {} in {}", jobs[b].id, secs));
        }
    }

    let mut pending = 0;
    let mut done = 0;
    let mut dead = 0;
    let mut data = Str::new();
    let mut j = 0;
    while j < jobs.len() {
        if jobs[j].state == 0 {
            pending += 1;
        } else if jobs[j].state == 1 {
            done += 1;
        } else {
            dead += 1;
        }
        let line = format!(
            "{} {} {} {} {}\n",
            jobs[j].state,
            jobs[j].priority,
            jobs[j].due,
            jobs[j].attempts,
            hex_encode(jobs[j].id.clone())
        );
        data = data + line;
        j += 1;
    }
    queue.set("jobs", data);

    out.push(format!("pending {} done {} dead {}", pending, done, dead));
    Ok(out.join("\n"))
}

enum Json {
    Null,
    Bool(bool),
    Num(Str),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<Member>),
}

struct Member {
    key: Str,
    val: Json,
}

struct P {
    b: Vec<u8>,
    i: usize,
}

struct PH {
    p: P,
    h: Option<u32>,
}

struct PS {
    p: P,
    s: Option<Str>,
}

struct PR {
    p: P,
    v: Option<Json>,
}

struct PB {
    p: P,
    ok: bool,
}

fn ws(p: P) -> P {
    let mut p = p;
    while p.i < p.b.len() {
        let c = p.b[p.i];
        if c == 32 || c == 9 || c == 10 || c == 13 {
            p.i += 1;
        } else {
            break;
        }
    }
    p
}

fn hexval(c: u8) -> Option<u32> {
    if c >= 48 && c <= 57 {
        Some((c - 48) as u32)
    } else if c >= 97 && c <= 102 {
        Some((c - 97 + 10) as u32)
    } else if c >= 65 && c <= 70 {
        Some((c - 65 + 10) as u32)
    } else {
        None
    }
}

fn read_hex4(p: P) -> PH {
    let mut p = p;
    if p.i + 4 > p.b.len() {
        return PH { p: p, h: None };
    }
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        match hexval(p.b[p.i + k]) {
            Some(h) => {
                v = v * 16 + h;
            }
            None => {
                return PH { p: p, h: None };
            }
        }
        k += 1;
    }
    p.i += 4;
    PH { p: p, h: Some(v) }
}

fn push_utf8(out: Vec<u8>, cp: u32) -> Vec<u8> {
    let mut out = out;
    if cp < 128 {
        out.push(cp as u8);
    } else if cp < 2048 {
        out.push((192 + cp / 64) as u8);
        out.push((128 + cp % 64) as u8);
    } else if cp < 65536 {
        out.push((224 + cp / 4096) as u8);
        out.push((128 + (cp / 64) % 64) as u8);
        out.push((128 + cp % 64) as u8);
    } else {
        out.push((240 + cp / 262144) as u8);
        out.push((128 + (cp / 4096) % 64) as u8);
        out.push((128 + (cp / 64) % 64) as u8);
        out.push((128 + cp % 64) as u8);
    }
    out
}

fn parse_string(p: P) -> PS {
    let mut p = p;
    if p.i >= p.b.len() || p.b[p.i] != 34 {
        return PS { p: p, s: None };
    }
    p.i += 1;
    let mut out: Vec<u8> = Vec::new();
    loop {
        if p.i >= p.b.len() {
            return PS { p: p, s: None };
        }
        let c = p.b[p.i];
        p.i += 1;
        if c == 34 {
            break;
        } else if c == 92 {
            if p.i >= p.b.len() {
                return PS { p: p, s: None };
            }
            let e = p.b[p.i];
            p.i += 1;
            if e == 34 {
                out.push(34);
            } else if e == 92 {
                out.push(92);
            } else if e == 47 {
                out.push(47);
            } else if e == 98 {
                out.push(8);
            } else if e == 102 {
                out.push(12);
            } else if e == 110 {
                out.push(10);
            } else if e == 114 {
                out.push(13);
            } else if e == 116 {
                out.push(9);
            } else if e == 117 {
                let r = read_hex4(p);
                p = r.p;
                let mut cp = match r.h {
                    Some(v) => v,
                    None => {
                        return PS { p: p, s: None };
                    }
                };
                if cp >= 55296 && cp < 56320 {
                    if p.i + 1 < p.b.len() && p.b[p.i] == 92 && p.b[p.i + 1] == 117 {
                        p.i += 2;
                        let r2 = read_hex4(p);
                        p = r2.p;
                        let lo = match r2.h {
                            Some(v) => v,
                            None => {
                                return PS { p: p, s: None };
                            }
                        };
                        if lo >= 56320 && lo < 57344 {
                            cp = 65536 + (cp - 55296) * 1024 + (lo - 56320);
                        } else {
                            return PS { p: p, s: None };
                        }
                    } else {
                        return PS { p: p, s: None };
                    }
                } else if cp >= 56320 && cp < 57344 {
                    return PS { p: p, s: None };
                }
                out = push_utf8(out, cp);
            } else {
                return PS { p: p, s: None };
            }
        } else if c < 32 {
            return PS { p: p, s: None };
        } else {
            out.push(c);
        }
    }
    match Str::from_utf8(out) {
        Ok(s) => PS { p: p, s: Some(s) },
        Err(_) => PS { p: p, s: None },
    }
}

fn is_digit(c: u8) -> bool {
    c >= 48 && c <= 57
}

fn parse_number(p: P) -> PR {
    let mut p = p;
    let start = p.i;
    if p.i < p.b.len() && p.b[p.i] == 45 {
        p.i += 1;
    }
    let ds = p.i;
    while p.i < p.b.len() && is_digit(p.b[p.i]) {
        p.i += 1;
    }
    if p.i == ds {
        return PR { p: p, v: None };
    }
    if p.i - ds > 1 && p.b[ds] == 48 {
        return PR { p: p, v: None };
    }
    if p.i < p.b.len() && p.b[p.i] == 46 {
        p.i += 1;
        let fs = p.i;
        while p.i < p.b.len() && is_digit(p.b[p.i]) {
            p.i += 1;
        }
        if p.i == fs {
            return PR { p: p, v: None };
        }
    }
    if p.i < p.b.len() && (p.b[p.i] == 101 || p.b[p.i] == 69) {
        p.i += 1;
        if p.i < p.b.len() && (p.b[p.i] == 43 || p.b[p.i] == 45) {
            p.i += 1;
        }
        let es = p.i;
        while p.i < p.b.len() && is_digit(p.b[p.i]) {
            p.i += 1;
        }
        if p.i == es {
            return PR { p: p, v: None };
        }
    }
    let mut raw: Vec<u8> = Vec::new();
    let mut k = start;
    while k < p.i {
        raw.push(p.b[k]);
        k += 1;
    }
    match Str::from_utf8(raw) {
        Ok(s) => PR { p: p, v: Some(Json::Num(s)) },
        Err(_) => PR { p: p, v: None },
    }
}

fn expect_word(p: P, wb: Vec<u8>) -> PB {
    let mut p = p;
    if p.i + wb.len() > p.b.len() {
        return PB { p: p, ok: false };
    }
    let mut k = 0;
    while k < wb.len() {
        if p.b[p.i + k] != wb[k] {
            return PB { p: p, ok: false };
        }
        k += 1;
    }
    p.i += wb.len();
    PB { p: p, ok: true }
}

fn parse_value(p: P, depth: usize) -> PR {
    let mut p = p;
    if depth > 200 {
        return PR { p: p, v: None };
    }
    p = ws(p);
    if p.i >= p.b.len() {
        return PR { p: p, v: None };
    }
    let c = p.b[p.i];
    if c == 123 {
        p.i += 1;
        let mut items: Vec<Member> = Vec::new();
        p = ws(p);
        if p.i < p.b.len() && p.b[p.i] == 125 {
            p.i += 1;
            return PR { p: p, v: Some(Json::Obj(items)) };
        }
        loop {
            p = ws(p);
            let r = parse_string(p);
            p = r.p;
            let k = match r.s {
                Some(k) => k,
                None => {
                    return PR { p: p, v: None };
                }
            };
            p = ws(p);
            if p.i >= p.b.len() || p.b[p.i] != 58 {
                return PR { p: p, v: None };
            }
            p.i += 1;
            let r2 = parse_value(p, depth + 1);
            p = r2.p;
            let v = match r2.v {
                Some(v) => v,
                None => {
                    return PR { p: p, v: None };
                }
            };
            items.push(Member { key: k, val: v });
            p = ws(p);
            if p.i >= p.b.len() {
                return PR { p: p, v: None };
            }
            if p.b[p.i] == 44 {
                p.i += 1;
            } else if p.b[p.i] == 125 {
                p.i += 1;
                return PR { p: p, v: Some(Json::Obj(items)) };
            } else {
                return PR { p: p, v: None };
            }
        }
    } else if c == 91 {
        p.i += 1;
        let mut items: Vec<Json> = Vec::new();
        p = ws(p);
        if p.i < p.b.len() && p.b[p.i] == 93 {
            p.i += 1;
            return PR { p: p, v: Some(Json::Arr(items)) };
        }
        loop {
            let r = parse_value(p, depth + 1);
            p = r.p;
            let v = match r.v {
                Some(v) => v,
                None => {
                    return PR { p: p, v: None };
                }
            };
            items.push(v);
            p = ws(p);
            if p.i >= p.b.len() {
                return PR { p: p, v: None };
            }
            if p.b[p.i] == 44 {
                p.i += 1;
            } else if p.b[p.i] == 93 {
                p.i += 1;
                return PR { p: p, v: Some(Json::Arr(items)) };
            } else {
                return PR { p: p, v: None };
            }
        }
    } else if c == 34 {
        let r = parse_string(p);
        match r.s {
            Some(s) => PR { p: r.p, v: Some(Json::Text(s)) },
            None => PR { p: r.p, v: None },
        }
    } else if c == 116 {
        let w: Vec<u8> = vec![116, 114, 117, 101];
        let r = expect_word(p, w);
        if r.ok { PR { p: r.p, v: Some(Json::Bool(true)) } } else { PR { p: r.p, v: None } }
    } else if c == 102 {
        let w: Vec<u8> = vec![102, 97, 108, 115, 101];
        let r = expect_word(p, w);
        if r.ok { PR { p: r.p, v: Some(Json::Bool(false)) } } else { PR { p: r.p, v: None } }
    } else if c == 110 {
        let w: Vec<u8> = vec![110, 117, 108, 108];
        let r = expect_word(p, w);
        if r.ok { PR { p: r.p, v: Some(Json::Null) } } else { PR { p: r.p, v: None } }
    } else {
        parse_number(p)
    }
}

fn parse_json(s: Str) -> Option<Json> {
    let p = P { b: s.into_bytes(), i: 0 };
    let r = parse_value(p, 0);
    let v = match r.v {
        Some(v) => v,
        None => {
            return None;
        }
    };
    let np = ws(r.p);
    if np.i != np.b.len() {
        return None;
    }
    Some(v)
}

fn parse_int(s: Str) -> Option<i64> {
    let b = s.into_bytes();
    let mut i = 0;
    let mut neg = false;
    if i < b.len() && b[i] == 45 {
        neg = true;
        i += 1;
    }
    if i >= b.len() {
        return None;
    }
    let mut v: i64 = 0;
    while i < b.len() {
        let c = b[i];
        if !is_digit(c) {
            return None;
        }
        let d = (c - 48) as i64;
        v = match v.checked_mul(10) {
            Some(x) => x,
            None => {
                return None;
            }
        };
        if neg {
            v = match v.checked_sub(d) {
                Some(x) => x,
                None => {
                    return None;
                }
            };
        } else {
            v = match v.checked_add(d) {
                Some(x) => x,
                None => {
                    return None;
                }
            };
        }
        i += 1;
    }
    Some(v)
}

fn hex_digit(v: u8) -> u8 {
    if v < 10 {
        48 + v
    } else {
        97 + (v - 10)
    }
}

fn hex_encode(s: Str) -> Str {
    let b = s.into_bytes();
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        out.push(hex_digit(c / 16));
        out.push(hex_digit(c % 16));
        i += 1;
    }
    if out.len() == 0 {
        out.push(45);
    }
    match Str::from_utf8(out) {
        Ok(x) => x,
        Err(_) => Str::new(),
    }
}

fn hex_decode(s: Str) -> Option<Str> {
    if s == "-" {
        return Some(Str::new());
    }
    let b = s.into_bytes();
    if b.len() % 2 != 0 {
        return None;
    }
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let h = match hexval(b[i]) {
            Some(x) => x,
            None => {
                return None;
            }
        };
        let l = match hexval(b[i + 1]) {
            Some(x) => x,
            None => {
                return None;
            }
        };
        out.push((h * 16 + l) as u8);
        i += 2;
    }
    match Str::from_utf8(out) {
        Ok(x) => Some(x),
        Err(_) => None,
    }
}

struct Job {
    id: Str,
    priority: i64,
    due: i64,
    attempts: i64,
    state: i64,
}

struct Entry {
    id: Str,
    pr: i64,
}

struct ScriptEntry {
    id: Str,
    outs: Vec<Str>,
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
    let now: i64 = clock.now();
    let mut out: Vec<Str> = Vec::new();

    let mut jobs: Vec<Job> = Vec::new();
    match queue.get("jobs") {
        Some(data) => {
            for line in data.split("\n") {
                let parts: Vec<Str> = line.split(" ").map(|x| x.to_string()).collect();
                if parts.len() != 5 {
                    continue;
                }
                let st = match parse_int(parts[0].clone()) {
                    Some(x) => x,
                    None => {
                        continue;
                    }
                };
                let pr = match parse_int(parts[1].clone()) {
                    Some(x) => x,
                    None => {
                        continue;
                    }
                };
                let du = match parse_int(parts[2].clone()) {
                    Some(x) => x,
                    None => {
                        continue;
                    }
                };
                let at = match parse_int(parts[3].clone()) {
                    Some(x) => x,
                    None => {
                        continue;
                    }
                };
                let id = match hex_decode(parts[4].clone()) {
                    Some(x) => x,
                    None => {
                        continue;
                    }
                };
                jobs.push(Job { id: id, priority: pr, due: du, attempts: at, state: st });
            }
        }
        None => {}
    }

    let enq: Str = match input.read("enqueue.jsonl") {
        Ok(s) => s,
        Err(_) => Str::new(),
    };
    let mut lineno = 0;
    for raw in enq.split("\n") {
        lineno += 1;
        let line: Str = raw.trim().to_string();
        if line.len() == 0 {
            continue;
        }
        let mut parsed: Option<Entry> = None;
        match parse_json(line) {
            Some(Json::Obj(items)) => {
                let mut idv: Option<Json> = None;
                let mut pv: Option<Json> = None;
                for item in items {
                    if item.key == "id" {
                        idv = Some(item.val);
                    } else if item.key == "priority" {
                        pv = Some(item.val);
                    }
                }
                match idv {
                    Some(Json::Text(id)) => match pv {
                        Some(Json::Num(n)) => match parse_int(n) {
                            Some(pr) => {
                                parsed = Some(Entry { id: id, pr: pr });
                            }
                            None => {}
                        },
                        _ => {}
                    },
                    _ => {}
                }
            }
            _ => {}
        }
        match parsed {
            None => {
                out.push(format!("invalid line {}", lineno));
            }
            Some(e) => {
                let mut exists = false;
                let mut j = 0;
                while j < jobs.len() {
                    if jobs[j].id == e.id {
                        exists = true;
                    }
                    j += 1;
                }
                if exists {
                    out.push(format!("duplicate {}", e.id));
                } else {
                    jobs.push(Job { id: e.id, priority: e.pr, due: now, attempts: 0, state: 0 });
                }
            }
        }
    }

    let mut script: Vec<ScriptEntry> = Vec::new();
    match input.read("script.json") {
        Ok(s) => match parse_json(s) {
            Some(Json::Obj(items)) => {
                for item in items {
                    let mut outs: Vec<Str> = Vec::new();
                    match item.val {
                        Json::Arr(list) => {
                            for e in list {
                                match e {
                                    Json::Text(t) => {
                                        outs.push(t);
                                    }
                                    _ => {
                                        outs.push(Str::new());
                                    }
                                }
                            }
                        }
                        _ => {}
                    }
                    script.push(ScriptEntry { id: item.key, outs: outs });
                }
            }
            _ => {}
        },
        Err(_) => {}
    }

    let mut ran: Vec<bool> = Vec::new();
    let mut i = 0;
    while i < jobs.len() {
        ran.push(false);
        i += 1;
    }

    let mut count = 0;
    while count < 5 {
        let mut best: Option<usize> = None;
        let mut j = 0;
        while j < jobs.len() {
            if !ran[j] && jobs[j].state == 0 && jobs[j].due <= now {
                match best {
                    None => {
                        best = Some(j);
                    }
                    Some(b) => {
                        let better = if jobs[j].priority != jobs[b].priority {
                            jobs[j].priority > jobs[b].priority
                        } else if jobs[j].due != jobs[b].due {
                            jobs[j].due < jobs[b].due
                        } else {
                            jobs[j].id < jobs[b].id
                        };
                        if better {
                            best = Some(j);
                        }
                    }
                }
            }
            j += 1;
        }
        let b = match best {
            Some(b) => b,
            None => break,
        };
        ran[b] = true;
        count += 1;
        jobs[b].attempts += 1;
        let attempt = jobs[b].attempts;

        let mut found: Option<usize> = None;
        let mut s = 0;
        while s < script.len() {
            if script[s].id == jobs[b].id {
                found = Some(s);
            }
            s += 1;
        }
        let mut fail = false;
        match found {
            Some(si) => {
                let n = script[si].outs.len();
                if n > 0 {
                    let mut idx = (attempt - 1) as usize;
                    if idx >= n {
                        idx = n - 1;
                    }
                    if script[si].outs[idx] == "fail" {
                        fail = true;
                    }
                }
            }
            None => {}
        }

        if !fail {
            jobs[b].state = 1;
            out.push(format!("done {}", jobs[b].id));
        } else if attempt >= 4 {
            jobs[b].state = 2;
            out.push(format!("dead {}", jobs[b].id));
        } else {
            let mut secs: i64 = 60;
            let mut k = 1;
            while k < attempt {
                secs = secs * 2;
                k += 1;
            }
            jobs[b].due = now + secs * 1000;
            out.push(format!("retry {} in {}", jobs[b].id, secs));
        }
    }

    let mut pending = 0;
    let mut done = 0;
    let mut dead = 0;
    let mut data = Str::new();
    let mut j = 0;
    while j < jobs.len() {
        if jobs[j].state == 0 {
            pending += 1;
        } else if jobs[j].state == 1 {
            done += 1;
        } else {
            dead += 1;
        }
        let line = format!(
            "{} {} {} {} {}\n",
            jobs[j].state,
            jobs[j].priority,
            jobs[j].due,
            jobs[j].attempts,
            hex_encode(jobs[j].id.clone())
        );
        data = data + line;
        j += 1;
    }
    queue.set("jobs", data);

    out.push(format!("pending {} done {} dead {}", pending, done, dead));
    Ok(out.join("\n"))
}

enum Tok {
    Int(Str),
    Name(Str),
    Sym(char),
}

enum Node {
    Num(Str),
    Var(Str),
    Neg(usize),
    Bin(char, usize, usize),
    Call(Str, Vec<usize>),
}

fn is_name_start(c: char) -> bool {
    c.is_ascii_alphabetic() || c == '_'
}

fn is_name_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

fn tokenize(cs: &Vec<char>) -> Option<Vec<Tok>> {
    let mut out: Vec<Tok> = Vec::new();
    let mut i: usize = 0;
    while i < cs.len() {
        let c = cs[i];
        if c == ' ' || c == '\t' || c == '\r' {
            i += 1;
        } else if c.is_ascii_digit() {
            let mut s = Str::new();
            while i < cs.len() && cs[i].is_ascii_digit() {
                s.push(cs[i]);
                i += 1;
            }
            out.push(Tok::Int(s));
        } else if is_name_start(c) {
            let mut s = Str::new();
            while i < cs.len() && is_name_char(cs[i]) {
                s.push(cs[i]);
                i += 1;
            }
            out.push(Tok::Name(s));
        } else if c == '+' || c == '-' || c == '*' || c == '/' || c == '%' || c == '^'
            || c == '(' || c == ')' || c == ',' || c == '='
        {
            out.push(Tok::Sym(c));
            i += 1;
        } else {
            return None;
        }
    }
    Some(out)
}

struct Parser {
    toks: Vec<Tok>,
    pos: usize,
    nodes: Vec<Node>,
}

impl Parser {
    fn peek_sym(&self, c: char) -> bool {
        if self.pos < self.toks.len() {
            match &self.toks[self.pos] {
                Tok::Sym(d) => *d == c,
                _ => false,
            }
        } else {
            false
        }
    }

    fn add(&mut self, n: Node) -> usize {
        self.nodes.push(n);
        self.nodes.len() - 1
    }

    fn expr(&mut self) -> Option<usize> {
        let mut left = self.term()?;
        loop {
            let op = if self.peek_sym('+') {
                '+'
            } else if self.peek_sym('-') {
                '-'
            } else {
                break;
            };
            self.pos += 1;
            let right = self.term()?;
            left = self.add(Node::Bin(op, left, right));
        }
        Some(left)
    }

    fn term(&mut self) -> Option<usize> {
        let mut left = self.factor()?;
        loop {
            let op = if self.peek_sym('*') {
                '*'
            } else if self.peek_sym('/') {
                '/'
            } else if self.peek_sym('%') {
                '%'
            } else {
                break;
            };
            self.pos += 1;
            let right = self.factor()?;
            left = self.add(Node::Bin(op, left, right));
        }
        Some(left)
    }

    fn factor(&mut self) -> Option<usize> {
        if self.peek_sym('-') {
            self.pos += 1;
            let f = self.factor()?;
            return Some(self.add(Node::Neg(f)));
        }
        self.power()
    }

    fn power(&mut self) -> Option<usize> {
        let a = self.atom()?;
        if self.peek_sym('^') {
            self.pos += 1;
            let e = self.factor()?;
            return Some(self.add(Node::Bin('^', a, e)));
        }
        Some(a)
    }

    fn atom(&mut self) -> Option<usize> {
        if self.pos >= self.toks.len() {
            return None;
        }
        let mut int_val: Option<Str> = None;
        let mut name_val: Option<Str> = None;
        match &self.toks[self.pos] {
            Tok::Int(s) => {
                int_val = Some(s.clone());
            }
            Tok::Name(s) => {
                name_val = Some(s.clone());
            }
            Tok::Sym(_) => {}
        }
        if let Some(s) = int_val {
            self.pos += 1;
            return Some(self.add(Node::Num(s)));
        }
        if let Some(name) = name_val {
            self.pos += 1;
            if self.peek_sym('(') {
                self.pos += 1;
                let mut args: Vec<usize> = Vec::new();
                let first = self.expr()?;
                args.push(first);
                while self.peek_sym(',') {
                    self.pos += 1;
                    let a = self.expr()?;
                    args.push(a);
                }
                if !self.peek_sym(')') {
                    return None;
                }
                self.pos += 1;
                return Some(self.add(Node::Call(name, args)));
            }
            return Some(self.add(Node::Var(name)));
        }
        if self.peek_sym('(') {
            self.pos += 1;
            let e = self.expr()?;
            if !self.peek_sym(')') {
                return None;
            }
            self.pos += 1;
            return Some(e);
        }
        None
    }
}

fn parse_lit(s: &Str) -> Result<i64, Str> {
    let mut v: i64 = 0;
    for c in s.chars() {
        let d = (c as i64) - ('0' as i64);
        v = match v.checked_mul(10) {
            Some(x) => x,
            None => return Err(Str::from("overflow")),
        };
        v = match v.checked_add(d) {
            Some(x) => x,
            None => return Err(Str::from("overflow")),
        };
    }
    Ok(v)
}

fn ipow(base: i64, exp: i64) -> Result<i64, Str> {
    let mut result: i64 = 1;
    let mut b = base;
    let mut e = exp;
    while e > 0 {
        if e % 2 == 1 {
            result = match result.checked_mul(b) {
                Some(x) => x,
                None => return Err(Str::from("overflow")),
            };
        }
        e = e / 2;
        if e > 0 {
            b = match b.checked_mul(b) {
                Some(x) => x,
                None => return Err(Str::from("overflow")),
            };
        }
    }
    Ok(result)
}

fn eval(nodes: &Vec<Node>, id: usize, vars: &Vec<(Str, i64)>) -> Result<i64, Str> {
    match &nodes[id] {
        Node::Num(s) => parse_lit(s),
        Node::Var(name) => {
            let mut i = vars.len();
            while i > 0 {
                i -= 1;
                if vars[i].0 == *name {
                    return Ok(vars[i].1);
                }
            }
            Err(format!("unknown variable {}", name))
        }
        Node::Neg(a) => {
            let v = eval(nodes, *a, vars)?;
            match v.checked_neg() {
                Some(x) => Ok(x),
                None => Err(Str::from("overflow")),
            }
        }
        Node::Bin(op, a, b) => {
            let x = eval(nodes, *a, vars)?;
            let y = eval(nodes, *b, vars)?;
            let op = *op;
            if op == '+' {
                match x.checked_add(y) {
                    Some(r) => Ok(r),
                    None => Err(Str::from("overflow")),
                }
            } else if op == '-' {
                match x.checked_sub(y) {
                    Some(r) => Ok(r),
                    None => Err(Str::from("overflow")),
                }
            } else if op == '*' {
                match x.checked_mul(y) {
                    Some(r) => Ok(r),
                    None => Err(Str::from("overflow")),
                }
            } else if op == '/' {
                if y == 0 {
                    return Err(Str::from("division by zero"));
                }
                match x.checked_div(y) {
                    Some(r) => Ok(r),
                    None => Err(Str::from("overflow")),
                }
            } else if op == '%' {
                if y == 0 {
                    return Err(Str::from("division by zero"));
                }
                if y == -1 {
                    return Ok(0);
                }
                Ok(x % y)
            } else {
                if y < 0 {
                    return Err(Str::from("negative exponent"));
                }
                ipow(x, y)
            }
        }
        Node::Call(name, args) => {
            let n: usize;
            if *name == "min" || *name == "max" {
                n = 2;
            } else if *name == "abs" {
                n = 1;
            } else {
                return Err(format!("unknown function {}", name));
            }
            if args.len() != n {
                return Err(format!("wrong number of arguments to {}", name));
            }
            let mut vals: Vec<i64> = Vec::new();
            for a in args.iter() {
                let v = eval(nodes, *a, vars)?;
                vals.push(v);
            }
            if *name == "abs" {
                match vals[0].checked_abs() {
                    Some(r) => Ok(r),
                    None => Err(Str::from("overflow")),
                }
            } else if *name == "min" {
                if vals[0] < vals[1] { Ok(vals[0]) } else { Ok(vals[1]) }
            } else {
                if vals[0] > vals[1] { Ok(vals[0]) } else { Ok(vals[1]) }
            }
        }
    }
}

fn main(input: Dir) -> Result<Str, Error> {
    let text = input.read("program.txt")?;
    let mut vars: Vec<(Str, i64)> = Vec::new();
    let mut out: Vec<Str> = Vec::new();
    let mut lineno: usize = 0;
    for line in text.lines() {
        lineno += 1;
        let cs: Vec<char> = line.chars().collect();
        let mut blank = true;
        for c in cs.iter() {
            if *c != ' ' && *c != '\t' && *c != '\r' {
                blank = false;
            }
        }
        if blank {
            continue;
        }
        let toks = match tokenize(&cs) {
            Some(t) => t,
            None => {
                out.push(format!("{}: error: syntax error", lineno));
                continue;
            }
        };
        let mut let_name: Option<Str> = None;
        let mut start: usize = 0;
        let mut is_let = false;
        if toks.len() > 0 {
            if let Tok::Name(s) = &toks[0] {
                if *s == "let" {
                    is_let = true;
                }
            }
        }
        let mut ok = true;
        if is_let {
            if toks.len() >= 3 {
                if let Tok::Name(s) = &toks[1] {
                    let_name = Some(s.clone());
                }
                let mut eq = false;
                if let Tok::Sym(c) = &toks[2] {
                    if *c == '=' {
                        eq = true;
                    }
                }
                if let_name.is_none() || !eq {
                    ok = false;
                }
                start = 3;
            } else {
                ok = false;
            }
        }
        if !ok {
            out.push(format!("{}: error: syntax error", lineno));
            continue;
        }
        let mut p = Parser { toks: toks, pos: start, nodes: Vec::new() };
        let root = p.expr();
        let root = match root {
            Some(r) => {
                if p.pos == p.toks.len() { r } else {
                    out.push(format!("{}: error: syntax error", lineno));
                    continue;
                }
            }
            None => {
                out.push(format!("{}: error: syntax error", lineno));
                continue;
            }
        };
        match eval(&p.nodes, root, &vars) {
            Ok(v) => match let_name {
                Some(name) => {
                    out.push(format!("{}: {} = {}", lineno, name, v));
                    vars.push((name, v));
                }
                None => {
                    out.push(format!("{}: {}", lineno, v));
                }
            },
            Err(e) => {
                out.push(format!("{}: error: {}", lineno, e));
            }
        }
    }
    let mut result = Str::new();
    for l in out.iter() {
        result.push_str(l);
        result.push('\n');
    }
    Ok(result)
}

enum Tok {
    Int(Str),
    Name(Str),
    Sym(Str),
}

enum Node {
    Num(Str),
    Var(Str),
    Neg(usize),
    Bin(Str, usize, usize),
    Call(Str, Vec<usize>),
}

fn in_set(c: &Str, set: Str) -> bool {
    for d in set.chars() {
        if d == *c {
            return true;
        }
    }
    false
}

fn is_digit(c: &Str) -> bool {
    in_set(c, Str::from("0123456789"))
}

fn is_alpha(c: &Str) -> bool {
    in_set(c, Str::from("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"))
}

fn is_name_start(c: &Str) -> bool {
    is_alpha(c) || *c == "_"
}

fn is_name_char(c: &Str) -> bool {
    is_alpha(c) || is_digit(c) || *c == "_"
}

fn is_space(c: &Str) -> bool {
    *c == " " || *c == "\t" || *c == "\r"
}

fn digit_val(c: &Str) -> i64 {
    let mut v: i64 = 0;
    for d in Str::from("0123456789").chars() {
        if d == *c {
            return v;
        }
        v += 1;
    }
    0
}

fn tokenize(cs: &Vec<Str>) -> Option<Vec<Tok>> {
    let mut out: Vec<Tok> = Vec::new();
    let mut i: usize = 0;
    while i < cs.len() {
        let c = cs[i].clone();
        if is_space(&c) {
            i += 1;
        } else if is_digit(&c) {
            let mut s = Str::new();
            while i < cs.len() && is_digit(&cs[i]) {
                s.push_str(&cs[i]);
                i += 1;
            }
            out.push(Tok::Int(s));
        } else if is_name_start(&c) {
            let mut s = Str::new();
            while i < cs.len() && is_name_char(&cs[i]) {
                s.push_str(&cs[i]);
                i += 1;
            }
            out.push(Tok::Name(s));
        } else if in_set(&c, Str::from("+-*/%^(),=")) {
            out.push(Tok::Sym(c));
            i += 1;
        } else {
            return None;
        }
    }
    Some(out)
}

struct Parser {
    toks: Vec<Tok>,
    pos: usize,
    nodes: Vec<Node>,
}

impl Parser {
    fn peek_sym(&self, c: Str) -> bool {
        if self.pos < self.toks.len() {
            match &self.toks[self.pos] {
                Tok::Sym(d) => *d == c,
                _ => false,
            }
        } else {
            false
        }
    }

    fn add(&mut self, n: Node) -> usize {
        self.nodes.push(n);
        self.nodes.len() - 1
    }

    fn expr(&mut self) -> Option<usize> {
        let mut left = self.term()?;
        loop {
            let op = if self.peek_sym(Str::from("+")) {
                Str::from("+")
            } else if self.peek_sym(Str::from("-")) {
                Str::from("-")
            } else {
                break;
            };
            self.pos += 1;
            let right = self.term()?;
            left = self.add(Node::Bin(op, left, right));
        }
        Some(left)
    }

    fn term(&mut self) -> Option<usize> {
        let mut left = self.factor()?;
        loop {
            let op = if self.peek_sym(Str::from("*")) {
                Str::from("*")
            } else if self.peek_sym(Str::from("/")) {
                Str::from("/")
            } else if self.peek_sym(Str::from("%")) {
                Str::from("%")
            } else {
                break;
            };
            self.pos += 1;
            let right = self.factor()?;
            left = self.add(Node::Bin(op, left, right));
        }
        Some(left)
    }

    fn factor(&mut self) -> Option<usize> {
        if self.peek_sym(Str::from("-")) {
            self.pos += 1;
            let f = self.factor()?;
            return Some(self.add(Node::Neg(f)));
        }
        self.power()
    }

    fn power(&mut self) -> Option<usize> {
        let a = self.atom()?;
        if self.peek_sym(Str::from("^")) {
            self.pos += 1;
            let e = self.factor()?;
            return Some(self.add(Node::Bin(Str::from("^"), a, e)));
        }
        Some(a)
    }

    fn atom(&mut self) -> Option<usize> {
        if self.pos >= self.toks.len() {
            return None;
        }
        let mut int_val: Option<Str> = None;
        let mut name_val: Option<Str> = None;
        match &self.toks[self.pos] {
            Tok::Int(s) => {
                int_val = Some(s.clone());
            }
            Tok::Name(s) => {
                name_val = Some(s.clone());
            }
            Tok::Sym(_) => {}
        }
        if let Some(s) = int_val {
            self.pos += 1;
            return Some(self.add(Node::Num(s)));
        }
        if let Some(name) = name_val {
            self.pos += 1;
            if self.peek_sym(Str::from("(")) {
                self.pos += 1;
                let mut args: Vec<usize> = Vec::new();
                let first = self.expr()?;
                args.push(first);
                while self.peek_sym(Str::from(",")) {
                    self.pos += 1;
                    let a = self.expr()?;
                    args.push(a);
                }
                if !self.peek_sym(Str::from(")")) {
                    return None;
                }
                self.pos += 1;
                return Some(self.add(Node::Call(name, args)));
            }
            return Some(self.add(Node::Var(name)));
        }
        if self.peek_sym(Str::from("(")) {
            self.pos += 1;
            let e = self.expr()?;
            if !self.peek_sym(Str::from(")")) {
                return None;
            }
            self.pos += 1;
            return Some(e);
        }
        None
    }
}

fn parse_lit(s: &Str) -> Result<i64, Str> {
    let mut v: i64 = 0;
    for c in s.chars() {
        let d = digit_val(&c);
        v = match v.checked_mul(10) {
            Some(x) => x,
            None => return Err(Str::from("overflow")),
        };
        v = match v.checked_add(d) {
            Some(x) => x,
            None => return Err(Str::from("overflow")),
        };
    }
    Ok(v)
}

fn ipow(base: i64, exp: i64) -> Result<i64, Str> {
    let mut result: i64 = 1;
    let mut b = base;
    let mut e = exp;
    while e > 0 {
        if e % 2 == 1 {
            result = match result.checked_mul(b) {
                Some(x) => x,
                None => return Err(Str::from("overflow")),
            };
        }
        e = e / 2;
        if e > 0 {
            b = match b.checked_mul(b) {
                Some(x) => x,
                None => return Err(Str::from("overflow")),
            };
        }
    }
    Ok(result)
}

fn eval(nodes: &Vec<Node>, id: usize, vars: &Vec<(Str, i64)>) -> Result<i64, Str> {
    match &nodes[id] {
        Node::Num(s) => parse_lit(s),
        Node::Var(name) => {
            let mut i = vars.len();
            while i > 0 {
                i -= 1;
                if vars[i].0 == *name {
                    return Ok(vars[i].1);
                }
            }
            Err(format!("unknown variable {}", name))
        }
        Node::Neg(a) => {
            let v = eval(nodes, *a, vars)?;
            match v.checked_neg() {
                Some(x) => Ok(x),
                None => Err(Str::from("overflow")),
            }
        }
        Node::Bin(op, a, b) => {
            let x = eval(nodes, *a, vars)?;
            let y = eval(nodes, *b, vars)?;
            if *op == "+" {
                match x.checked_add(y) {
                    Some(r) => Ok(r),
                    None => Err(Str::from("overflow")),
                }
            } else if *op == "-" {
                match x.checked_sub(y) {
                    Some(r) => Ok(r),
                    None => Err(Str::from("overflow")),
                }
            } else if *op == "*" {
                match x.checked_mul(y) {
                    Some(r) => Ok(r),
                    None => Err(Str::from("overflow")),
                }
            } else if *op == "/" {
                if y == 0 {
                    return Err(Str::from("division by zero"));
                }
                match x.checked_div(y) {
                    Some(r) => Ok(r),
                    None => Err(Str::from("overflow")),
                }
            } else if *op == "%" {
                if y == 0 {
                    return Err(Str::from("division by zero"));
                }
                if y == -1 {
                    return Ok(0);
                }
                Ok(x % y)
            } else {
                if y < 0 {
                    return Err(Str::from("negative exponent"));
                }
                ipow(x, y)
            }
        }
        Node::Call(name, args) => {
            let n: usize;
            if *name == "min" || *name == "max" {
                n = 2;
            } else if *name == "abs" {
                n = 1;
            } else {
                return Err(format!("unknown function {}", name));
            }
            if args.len() != n {
                return Err(format!("wrong number of arguments to {}", name));
            }
            let mut vals: Vec<i64> = Vec::new();
            for a in args.iter() {
                let v = eval(nodes, *a, vars)?;
                vals.push(v);
            }
            if *name == "abs" {
                match vals[0].checked_abs() {
                    Some(r) => Ok(r),
                    None => Err(Str::from("overflow")),
                }
            } else if *name == "min" {
                if vals[0] < vals[1] { Ok(vals[0]) } else { Ok(vals[1]) }
            } else {
                if vals[0] > vals[1] { Ok(vals[0]) } else { Ok(vals[1]) }
            }
        }
    }
}

fn main(input: Dir) -> Result<Str, Error> {
    let text = input.read("program.txt")?;
    let mut vars: Vec<(Str, i64)> = Vec::new();
    let mut out: Vec<Str> = Vec::new();
    let mut lineno: usize = 0;
    for line in text.lines() {
        lineno += 1;
        let cs: Vec<Str> = line.chars().collect();
        let mut blank = true;
        for c in cs.iter() {
            if !is_space(c) {
                blank = false;
            }
        }
        if blank {
            continue;
        }
        let toks = match tokenize(&cs) {
            Some(t) => t,
            None => {
                out.push(format!("{}: error: syntax error", lineno));
                continue;
            }
        };
        let mut let_name: Option<Str> = None;
        let mut start: usize = 0;
        let mut is_let = false;
        if toks.len() > 0 {
            if let Tok::Name(s) = &toks[0] {
                if *s == "let" {
                    is_let = true;
                }
            }
        }
        let mut ok = true;
        if is_let {
            if toks.len() >= 3 {
                if let Tok::Name(s) = &toks[1] {
                    let_name = Some(s.clone());
                }
                let mut eq = false;
                if let Tok::Sym(c) = &toks[2] {
                    if *c == "=" {
                        eq = true;
                    }
                }
                if let_name.is_none() || !eq {
                    ok = false;
                }
                start = 3;
            } else {
                ok = false;
            }
        }
        if !ok {
            out.push(format!("{}: error: syntax error", lineno));
            continue;
        }
        let mut p = Parser { toks: toks, pos: start, nodes: Vec::new() };
        let root = p.expr();
        let root = match root {
            Some(r) => {
                if p.pos == p.toks.len() {
                    r
                } else {
                    out.push(format!("{}: error: syntax error", lineno));
                    continue;
                }
            }
            None => {
                out.push(format!("{}: error: syntax error", lineno));
                continue;
            }
        };
        match eval(&p.nodes, root, &vars) {
            Ok(v) => match let_name {
                Some(name) => {
                    out.push(format!("{}: {} = {}", lineno, name, v));
                    vars.push((name, v));
                }
                None => {
                    out.push(format!("{}: {}", lineno, v));
                }
            },
            Err(e) => {
                out.push(format!("{}: error: {}", lineno, e));
            }
        }
    }
    let mut result = Str::new();
    for l in out.iter() {
        result.push_str(l);
        result.push_str("\n");
    }
    Ok(result)
}

enum Node {
    Num(Str),
    Var(Str),
    Neg(usize),
    Bin(Str, usize, usize),
    Call(Str, Vec<usize>),
}

struct Parser {
    toks: Vec<Str>,
    pos: usize,
    nodes: Vec<Node>,
}

fn in_set(c: Str, set: Str) -> bool {
    for d in set.chars() {
        if d == c {
            return true;
        }
    }
    false
}

fn is_digit(c: Str) -> bool {
    in_set(c, Str::from("0123456789"))
}

fn is_alpha(c: Str) -> bool {
    in_set(c, Str::from("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"))
}

fn is_name_start(c: Str) -> bool {
    c == "_" || is_alpha(c)
}

fn is_name_char(c: Str) -> bool {
    c == "_" || is_alpha(c.clone()) || is_digit(c)
}

fn is_space(c: Str) -> bool {
    c == " " || c == "\t" || c == "\r"
}

fn digit_val(c: Str) -> i64 {
    let mut v: i64 = 0;
    for d in Str::from("0123456789").chars() {
        if d == c {
            return v;
        }
        v += 1;
    }
    0
}

fn first_char(t: Str) -> Str {
    for c in t.chars() {
        return c;
    }
    Str::new()
}

fn tokenize(cs: Vec<Str>) -> Option<Vec<Str>> {
    let mut out: Vec<Str> = Vec::new();
    let mut i: usize = 0;
    while i < cs.len() {
        let c = cs[i].clone();
        if is_space(c.clone()) {
            i += 1;
        } else if is_digit(c.clone()) {
            let mut s = Str::new();
            while i < cs.len() && is_digit(cs[i].clone()) {
                s.push_str(cs[i].clone());
                i += 1;
            }
            out.push(s);
        } else if is_name_start(c.clone()) {
            let mut s = Str::new();
            while i < cs.len() && is_name_char(cs[i].clone()) {
                s.push_str(cs[i].clone());
                i += 1;
            }
            out.push(s);
        } else if in_set(c.clone(), Str::from("+-*/%^(),=")) {
            out.push(c);
            i += 1;
        } else {
            return None;
        }
    }
    Some(out)
}

fn peek(p: Parser) -> (Parser, Str) {
    let mut s = Str::new();
    if p.pos < p.toks.len() {
        s = p.toks[p.pos].clone();
    }
    (p, s)
}

fn expr(p0: Parser) -> (Parser, Option<usize>) {
    let (q0, l) = term(p0);
    let mut p = q0;
    let mut left = match l {
        Some(x) => x,
        None => return (p, None),
    };
    loop {
        let (q, t) = peek(p);
        p = q;
        if t == "+" || t == "-" {
            p.pos += 1;
            let (q2, r) = term(p);
            p = q2;
            let right = match r {
                Some(x) => x,
                None => return (p, None),
            };
            p.nodes.push(Node::Bin(t, left, right));
            left = p.nodes.len() - 1;
        } else {
            break;
        }
    }
    (p, Some(left))
}

fn term(p0: Parser) -> (Parser, Option<usize>) {
    let (q0, l) = factor(p0);
    let mut p = q0;
    let mut left = match l {
        Some(x) => x,
        None => return (p, None),
    };
    loop {
        let (q, t) = peek(p);
        p = q;
        if t == "*" || t == "/" || t == "%" {
            p.pos += 1;
            let (q2, r) = factor(p);
            p = q2;
            let right = match r {
                Some(x) => x,
                None => return (p, None),
            };
            p.nodes.push(Node::Bin(t, left, right));
            left = p.nodes.len() - 1;
        } else {
            break;
        }
    }
    (p, Some(left))
}

fn factor(p0: Parser) -> (Parser, Option<usize>) {
    let (q, t) = peek(p0);
    let mut p = q;
    if t == "-" {
        p.pos += 1;
        let (q2, f) = factor(p);
        p = q2;
        let fi = match f {
            Some(x) => x,
            None => return (p, None),
        };
        p.nodes.push(Node::Neg(fi));
        let id = p.nodes.len() - 1;
        return (p, Some(id));
    }
    power(p)
}

fn power(p0: Parser) -> (Parser, Option<usize>) {
    let (q0, a) = atom(p0);
    let mut p = q0;
    let ai = match a {
        Some(x) => x,
        None => return (p, None),
    };
    let (q, t) = peek(p);
    p = q;
    if t == "^" {
        p.pos += 1;
        let (q2, e) = factor(p);
        p = q2;
        let ei = match e {
            Some(x) => x,
            None => return (p, None),
        };
        p.nodes.push(Node::Bin(Str::from("^"), ai, ei));
        let id = p.nodes.len() - 1;
        return (p, Some(id));
    }
    (p, Some(ai))
}

fn atom(p0: Parser) -> (Parser, Option<usize>) {
    let (q, t) = peek(p0);
    let mut p = q;
    if t == "" {
        return (p, None);
    }
    let fc = first_char(t.clone());
    if is_digit(fc.clone()) {
        p.pos += 1;
        p.nodes.push(Node::Num(t));
        let id = p.nodes.len() - 1;
        return (p, Some(id));
    }
    if is_name_start(fc) {
        p.pos += 1;
        let (q2, nt) = peek(p);
        p = q2;
        if nt == "(" {
            p.pos += 1;
            let mut args: Vec<usize> = Vec::new();
            let (q3, first) = expr(p);
            p = q3;
            match first {
                Some(x) => args.push(x),
                None => return (p, None),
            }
            loop {
                let (q4, s) = peek(p);
                p = q4;
                if s == "," {
                    p.pos += 1;
                    let (q5, a) = expr(p);
                    p = q5;
                    match a {
                        Some(x) => args.push(x),
                        None => return (p, None),
                    }
                } else {
                    break;
                }
            }
            let (q6, close) = peek(p);
            p = q6;
            if close != ")" {
                return (p, None);
            }
            p.pos += 1;
            p.nodes.push(Node::Call(t, args));
            let id = p.nodes.len() - 1;
            return (p, Some(id));
        }
        p.nodes.push(Node::Var(t));
        let id = p.nodes.len() - 1;
        return (p, Some(id));
    }
    if t == "(" {
        p.pos += 1;
        let (q2, e) = expr(p);
        p = q2;
        let ei = match e {
            Some(x) => x,
            None => return (p, None),
        };
        let (q3, close) = peek(p);
        p = q3;
        if close != ")" {
            return (p, None);
        }
        p.pos += 1;
        return (p, Some(ei));
    }
    (p, None)
}

fn parse_lit(s: Str) -> Result<i64, Str> {
    let mut v: i64 = 0;
    for c in s.chars() {
        let d = digit_val(c);
        v = match v.checked_mul(10) {
            Some(x) => x,
            None => return Err(Str::from("overflow")),
        };
        v = match v.checked_add(d) {
            Some(x) => x,
            None => return Err(Str::from("overflow")),
        };
    }
    Ok(v)
}

fn ipow(base: i64, exp: i64) -> Result<i64, Str> {
    let mut result: i64 = 1;
    let mut b = base;
    let mut e = exp;
    while e > 0 {
        if e % 2 == 1 {
            result = match result.checked_mul(b) {
                Some(x) => x,
                None => return Err(Str::from("overflow")),
            };
        }
        e = e / 2;
        if e > 0 {
            b = match b.checked_mul(b) {
                Some(x) => x,
                None => return Err(Str::from("overflow")),
            };
        }
    }
    Ok(result)
}

fn ovf(r: Option<i64>) -> Result<i64, Str> {
    match r {
        Some(x) => Ok(x),
        None => Err(Str::from("overflow")),
    }
}

fn eval(nodes: Vec<Node>, id: usize, names: Vec<Str>, vals: Vec<i64>) -> Result<i64, Str> {
    match nodes[id].clone() {
        Node::Num(s) => parse_lit(s),
        Node::Var(name) => {
            let mut i = names.len();
            while i > 0 {
                i -= 1;
                if names[i] == name {
                    return Ok(vals[i]);
                }
            }
            Err(format!("unknown variable {}", name))
        }
        Node::Neg(a) => {
            let v = eval(nodes.clone(), a, names.clone(), vals.clone())?;
            ovf(v.checked_neg())
        }
        Node::Bin(op, a, b) => {
            let x = eval(nodes.clone(), a, names.clone(), vals.clone())?;
            let y = eval(nodes.clone(), b, names.clone(), vals.clone())?;
            if op == "+" {
                ovf(x.checked_add(y))
            } else if op == "-" {
                ovf(x.checked_sub(y))
            } else if op == "*" {
                ovf(x.checked_mul(y))
            } else if op == "/" {
                if y == 0 {
                    return Err(Str::from("division by zero"));
                }
                ovf(x.checked_div(y))
            } else if op == "%" {
                if y == 0 {
                    return Err(Str::from("division by zero"));
                }
                if y == -1 {
                    return Ok(0);
                }
                Ok(x % y)
            } else {
                if y < 0 {
                    return Err(Str::from("negative exponent"));
                }
                ipow(x, y)
            }
        }
        Node::Call(name, args) => {
            let n: usize;
            if name == "min" || name == "max" {
                n = 2;
            } else if name == "abs" {
                n = 1;
            } else {
                return Err(format!("unknown function {}", name));
            }
            if args.len() != n {
                return Err(format!("wrong number of arguments to {}", name));
            }
            let mut vs: Vec<i64> = Vec::new();
            for a in args {
                let v = eval(nodes.clone(), a, names.clone(), vals.clone())?;
                vs.push(v);
            }
            if name == "abs" {
                ovf(vs[0].checked_abs())
            } else if name == "min" {
                if vs[0] < vs[1] { Ok(vs[0]) } else { Ok(vs[1]) }
            } else {
                if vs[0] > vs[1] { Ok(vs[0]) } else { Ok(vs[1]) }
            }
        }
    }
}

fn main(input: Dir) -> Result<Str, Error> {
    let text = input.read("program.txt")?;
    let mut names: Vec<Str> = Vec::new();
    let mut vals: Vec<i64> = Vec::new();
    let mut result = Str::new();
    let mut lineno: usize = 0;
    for line in text.lines() {
        lineno += 1;
        let cs: Vec<Str> = line.chars().collect();
        let mut blank = true;
        for c in cs.clone() {
            if !is_space(c) {
                blank = false;
            }
        }
        if blank {
            continue;
        }
        let toks = match tokenize(cs) {
            Some(t) => t,
            None => {
                result.push_str(format!("{}: error: syntax error\n", lineno));
                continue;
            }
        };
        let mut let_name: Option<Str> = None;
        let mut start: usize = 0;
        let mut ok = true;
        if toks.len() > 0 && toks[0] == "let" {
            if toks.len() >= 3 {
                let nm = toks[1].clone();
                let fc = first_char(nm.clone());
                if is_name_start(fc) && toks[2] == "=" {
                    let_name = Some(nm);
                } else {
                    ok = false;
                }
                start = 3;
            } else {
                ok = false;
            }
        }
        if !ok {
            result.push_str(format!("{}: error: syntax error\n", lineno));
            continue;
        }
        let ntoks = toks.len();
        let p = Parser { toks: toks, pos: start, nodes: Vec::new() };
        let (p2, root) = expr(p);
        let r = match root {
            Some(r) => r,
            None => {
                result.push_str(format!("{}: error: syntax error\n", lineno));
                continue;
            }
        };
        if p2.pos != ntoks {
            result.push_str(format!("{}: error: syntax error\n", lineno));
            continue;
        }
        match eval(p2.nodes, r, names.clone(), vals.clone()) {
            Ok(v) => match let_name {
                Some(name) => {
                    result.push_str(format!("{}: {} = {}\n", lineno, name, v));
                    names.push(name);
                    vals.push(v);
                }
                None => {
                    result.push_str(format!("{}: {}\n", lineno, v));
                }
            },
            Err(e) => {
                result.push_str(format!("{}: error: {}\n", lineno, e));
            }
        }
    }
    Ok(result)
}

enum Node {
