}

fn expr(p0: Parser) -> PR {
    let res = term(p0);
    let mut p = res.p;
    let mut left = match res.r {
        Some(x) => x,
        None => return PR { p: p, r: None },
    };
    loop {
        let pk = peek(p);
        p = pk.p;
        let t = pk.s;
        if t == "+" || t == "-" {
            p.pos += 1;
            let res2 = term(p);
            p = res2.p;
            let right = match res2.r {
                Some(x) => x,
                None => return PR { p: p, r: None },
            };
            p.nodes.push(Node::Bin(t, left, right));
            left = p.nodes.len() - 1;
        } else {
            break;
        }
    }
    PR { p: p, r: Some(left) }
}

fn term(p0: Parser) -> PR {
    let res = factor(p0);
    let mut p = res.p;
    let mut left = match res.r {
        Some(x) => x,
        None => return PR { p: p, r: None },
    };
    loop {
        let pk = peek(p);
