}

fn factor(p0: Parser) -> PR {
    let pk = peek(p0);
    let mut p = pk.p;
    let t = pk.s;
    if t == "-" {
        p.pos += 1;
        let res = factor(p);
        p = res.p;
        let fi = match res.r {
            Some(x) => x,
            None => return PR { p: p, r: None },
        };
        p.nodes.push(Node::Neg(fi));
        let id = p.nodes.len() - 1;
        return PR { p: p, r: Some(id) };
    }
    power(p)
}

fn power(p0: Parser) -> PR {
    let res = atom(p0);
    let mut p = res.p;
    let ai = match res.r {
        Some(x) => x,
        None => return PR { p: p, r: None },
    };
    let pk = peek(p);
    p = pk.p;
    if pk.s == "^" {
        p.pos += 1;
        let res2 = factor(p);
        p = res2.p;
        let ei = match res2.r {
            Some(x) => x,
            None => return PR { p: p, r: None },
        };
        p.nodes.push(Node::Bin(Str::from("^"), ai, ei));
        let id = p.nodes.len() - 1;
        return PR { p: p, r: Some(id) };
    }
    PR { p: p, r: Some(ai) }
}

fn atom(p0: Parser) -> PR {
    let pk = peek(p0);
    let mut p = pk.p;
    let t = pk.s;
    if t == "" {
        return PR { p: p, r: None };
    }
    let fc = first_char(t.clone());
    if is_digit(fc.clone()) {
        p.pos += 1;
        p.nodes.push(Node::Num(t));
        let id = p.nodes.len() - 1;
        return PR { p: p, r: Some(id) };
    }
    if is_name_start(fc) {
        p.pos += 1;
        let pk2 = peek(p);
        p = pk2.p;
        if pk2.s == "(" {
            p.pos += 1;
            let mut args: Vec<usize> = Vec::new();
            let res = expr(p);
            p = res.p;
            match res.r {
                Some(x) => args.push(x),
                None => return PR { p: p, r: None },
            }
            loop {
                let pk3 = peek(p);
                p = pk3.p;
                if pk3.s == "," {
                    p.pos += 1;
                    let res2 = expr(p);
                    p = res2.p;
                    match res2.r {
                        Some(x) => args.push(x),
                        None => return PR { p: p, r: None },
                    }
                } else {
                    break;
                }
            }
            let pk4 = peek(p);
            p = pk4.p;
            if pk4.s != ")" {
                return PR { p: p, r: None };
            }
            p.pos += 1;
            p.nodes.push(Node::Call(t, args));
            let id = p.nodes.len() - 1;
            return PR { p: p, r: Some(id) };
        }
        p.nodes.push(Node::Var(t));
        let id = p.nodes.len() - 1;
        return PR { p: p, r: Some(id) };
    }
    if t == "(" {
        p.pos += 1;
        let res = expr(p);
        p = res.p;
        let ei = match res.r {
            Some(x) => x,
            None => return PR { p: p, r: None },
        };
        let pk2 = peek(p);
        p = pk2.p;
        if pk2.s != ")" {
            return PR { p: p, r: None };
        }
        p.pos += 1;
        return PR { p: p, r: Some(ei) };
    }
    PR { p: p, r: None }
}

fn parse_lit(s: Str) -> Result<i64, Str> {
    let mut v: i64 = 0;
    for c in s.chars() {
        let d = digit_val(c);
        v = match v.checked_mul(10) {
            Some(x) => x,
            None => return Err(Str::from("overflow")),
        };
        v = match v.checked_add(d) {
            Some(x) => x,
            None => return Err(Str::from("overflow")),
        };
    }
    Ok(v)
}

fn ipow(base: i64, exp: i64) -> Result<i64, Str> {
    let mut result: i64 = 1;
    let mut b = base;
    let mut e = exp;
    while e > 0 {
        if e % 2 == 1 {
            result = match result.checked_mul(b) {
                Some(x) => x,
                None => return Err(Str::from("overflow")),
            };
        }
        e = e / 2;
        if e > 0 {
            b = match b.checked_mul(b) {
                Some(x) => x,
                None => return Err(Str::from("overflow")),
            };
        }
    }
    Ok(result)
}

fn ovf(r: Option<i64>) -> Result<i64, Str> {
    match r {
        Some(x) => Ok(x),
        None => Err(Str::from("overflow")),
    }
}

fn eval(nodes: Vec<Node>, id: usize, names: Vec<Str>, vals: Vec<i64>) -> Result<i64, Str> {
    match nodes[id].clone() {
        Node::Num(s) => parse_lit(s),
        Node::Var(name) => {
            let mut i = names.len();
            while i > 0 {
                i -= 1;
                if names[i] == name {
                    return Ok(vals[i]);
                }
            }
            Err(format!("unknown variable {}", name))
        }
        Node::Neg(a) => {
            let v = eval(nodes.clone(), a, names.clone(), vals.clone())?;
            ovf(v.checked_neg())
        }
        Node::Bin(op, a, b) => {
            let x = eval(nodes.clone(), a, names.clone(), vals.clone())?;
            let y = eval(nodes.clone(), b, names.clone(), vals.clone())?;
            if op == "+" {
                ovf(x.checked_add(y))
            } else if op == "-" {
                ovf(x.checked_sub(y))
            } else if op == "*" {
                ovf(x.checked_mul(y))
            } else if op == "/" {
                if y == 0 {
                    return Err(Str::from("division by zero"));
                }
                ovf(x.checked_div(y))
            } else if op == "%" {
                if y == 0 {
                    return Err(Str::from("division by zero"));
                }
                if y == -1 {
                    return Ok(0);
                }
                Ok(x % y)
            } else {
                if y < 0 {
                    return Err(Str::from("negative exponent"));
                }
                ipow(x, y)
            }
        }
        Node::Call(name, args) => {
            let mut n: usize = 0;
            if name == "min" || name == "max" {
                n = 2;
            } else if name == "abs" {
                n = 1;
            } else {
                return Err(format!("unknown function {}", name));
            }
            if args.len() != n {
                return Err(format!("wrong number of arguments to {}", name));
            }
            let mut vs: Vec<i64> = Vec::new();
            for a in args {
                let v = eval(nodes.clone(), a, names.clone(), vals.clone())?;
                vs.push(v);
            }
            if name == "abs" {
                ovf(vs[0].checked_abs())
            } else if name == "min" {
                if vs[0] < vs[1] { Ok(vs[0]) } else { Ok(vs[1]) }
            } else {
                if vs[0] > vs[1] { Ok(vs[0]) } else { Ok(vs[1]) }
            }
        }
    }
}

fn main(input: Dir) -> Result<Str, Error> {
    let text = input.read("program.txt")?;
    let mut names: Vec<Str> = Vec::new();
    let mut vals: Vec<i64> = Vec::new();
    let mut result = Str::new();
    let mut lineno: usize = 0;
    for line in text.lines() {
        lineno += 1;
        let cs: Vec<Str> = line.chars().collect();
        let mut blank = true;
        for c in cs.clone() {
            if !is_space(c) {
                blank = false;
            }
        }
        if blank {
            continue;
        }
        let toks = match tokenize(cs) {
            Some(t) => t,
            None => {
                result.push_str(format!("{}: error: syntax error\n", lineno));
                continue;
            }
        };
        let mut let_name: Option<Str> = None;
        let mut start: usize = 0;
        let mut ok = true;
        if toks.len() > 0 && toks[0] == "let" {
            if toks.len() >= 3 {
                let nm = toks[1].clone();
                let fc = first_char(nm.clone());
                if is_name_start(fc) && toks[2] == "=" {
                    let_name = Some(nm);
                } else {
                    ok = false;
                }
                start = 3;
            } else {
                ok = false;
            }
        }
        if !ok {
            result.push_str(format!("{}: error: syntax error\n", lineno));
            continue;
        }
        let ntoks = toks.len();
        let p = Parser { toks: toks, pos: start, nodes: Vec::new() };
        let res = expr(p);
        let p2 = res.p;
        let r = match res.r {
            Some(r) => r,
            None => {
                result.push_str(format!("{}: error: syntax error\n", lineno));
                continue;
            }
        };
        if p2.pos != ntoks {
            result.push_str(format!("{}: error: syntax error\n", lineno));
            continue;
        }
        match eval(p2.nodes, r, names.clone(), vals.clone()) {
            Ok(v) => match let_name {
                Some(name) => {
                    result.push_str(format!("{}: {} = {}\n", lineno, name, v));
                    names.push(name);
                    vals.push(v);
                }
                None => {
                    result.push_str(format!("{}: {}\n", lineno, v));
                }
            },
            Err(e) => {
                result.push_str(format!("{}: error: {}\n", lineno, e));
            }
        }
    }
    Ok(result)
}

