    }
}

fn eval(nodes: Vec<Node>, id: usize, names: Vec<Str>, vals: Vec<i64>) -> Result<i64, Str> {
    match nodes[id].clone() {
        Node::Num(s) => parse_lit(s),
        Node::Var(name) => {
            let mut i = names.len();
            while i > 0 {
                i -= 1;
                if names[i] == name {
                    return Ok(vals[i]);
                }
            }
            Err(Str::from("unknown variable ") + name)
        }
        Node::Neg(a) => {
            let v = eval(nodes.clone(), a, names.clone(), vals.clone())?;
            ovf(v.checked_neg())
        }
        Node::Bin(op, a, b) => {
            let x = eval(nodes.clone(), a, names.clone(), vals.clone())?;
            let y = eval(nodes.clone(), b, names.clone(), vals.clone())?;
            if op == "+" {
                ovf(x.checked_add(y))
            } else if op == "-" {
                ovf(x.checked_sub(y))
            } else if op == "*" {
                ovf(x.checked_mul(y))
            } else if op == "/" {
                if y == 0 {
                    return Err(Str::from("division by zero"));
                }
                ovf(x.checked_div(y))
            } else if op == "%" {
                if y == 0 {
                    return Err(Str::from("division by zero"));
                }
                if y == -1 {
                    return Ok(0);
                }
                Ok(x % y)
            } else {
                if y < 0 {
                    return Err(Str::from("negative exponent"));
                }
                ipow(x, y)
            }
        }
        Node::Call(name, args) => {
            let mut n: usize = 0;
            if name == "min" || name == "max" {
                n = 2;
            } else if name == "abs" {
                n = 1;
            } else {
                return Err(Str::from("unknown function ") + name);
            }
            if args.len() != n {
                return Err(Str::from("wrong number of arguments to ") + name);
            }
            let mut vs: Vec<i64> = Vec::new();
            for a in args {
                let v = eval(nodes.clone(), a, names.clone(), vals.clone())?;
                vs.push(v);
            }
            if name == "abs" {
                ovf(vs[0].checked_abs())
            } else if name == "min" {
                if vs[0] < vs[1] { Ok(vs[0]) } else { Ok(vs[1]) }
            } else {
                if vs[0] > vs[1] { Ok(vs[0]) } else { Ok(vs[1]) }
            }
        }
    }
}

fn err_line(n: usize, msg: Str) -> Str {
    n.to_str() + Str::from(": error: ") + msg + Str::from("\n")
}

fn main(input: Dir) -> Result<Str, Error> {
    let text = input.read("program.txt")?;
    let mut names: Vec<Str> = Vec::new();
    let mut vals: Vec<i64> = Vec::new();
    let mut result = Str::new();
    let mut lineno: usize = 0;
    for line in text.lines() {
        lineno += 1;
        let cs: Vec<Str> = line.chars().collect();
        let mut blank = true;
        for c in cs.clone() {
            if !is_space(c) {
                blank = false;
            }
        }
        if blank {
            continue;
        }
        let toks = match tokenize(cs) {
            Some(t) => t,
            None => {
                result.push_str(err_line(lineno, Str::from("syntax error")));
                continue;
            }
        };
        let mut let_name: Option<Str> = None;
        let mut start: usize = 0;
        let mut ok = true;
        if toks.len() > 0 && toks[0] == "let" {
            if toks.len() >= 3 {
                let nm = toks[1].clone();
                let fc = first_char(nm.clone());
                if is_name_start(fc) && toks[2] == "=" {
                    let_name = Some(nm);
                } else {
                    ok = false;
                }
                start = 3;
            } else {
                ok = false;
            }
        }
        if !ok {
            result.push_str(err_line(lineno, Str::from("syntax error")));
            continue;
        }
        let ntoks = toks.len();
        let p = Parser { toks: toks, pos: start, nodes: Vec::new() };
        let res = expr(p);
        let p2 = res.p;
        let r = match res.r {
            Some(r) => r,
            None => {
                result.push_str(err_line(lineno, Str::from("syntax error")));
                continue;
            }
        };
        if p2.pos != ntoks {
            result.push_str(err_line(lineno, Str::from("syntax error")));
            continue;
        }
        match eval(p2.nodes, r, names.clone(), vals.clone()) {
            Ok(v) => match let_name {
                Some(name) => {
                    result.push_str(lineno.to_str() + Str::from(": ") + name.clone() + Str::from(" = ") + v.to_str() + Str::from("\n"));
                    names.push(name);
                    vals.push(v);
                }
                None => {
                    result.push_str(lineno.to_str() + Str::from(": ") + v.to_str() + Str::from("\n"));
                }
            },
            Err(e) => {
                result.push_str(err_line(lineno, e));
            }
        }
    }
    Ok(result)
}

use kio::http::{Incoming, Outgoing};
use kio::db::{Db, Value};
use kio::fs::Dir;
use kio::log::Log;
use kio::json::{self, Json};
use kio::crypto::{sha256, hex_lower, constant_time_eq};

fn reply(res: &mut Outgoing, status: u16, body: Json) -> Result<Str, Error> {
    let text = json::to_string(&body);
    res.status(status);
    res.header("content-type", "application/json");
    res.send(text.as_bytes())?;
    Ok(text)
}

fn err_obj(msg: &str) -> Json {
    json::object(vec![("error", Json::Str(msg.to_string()))])
}

fn status_obj(s: &str) -> Json {
    json::object(vec![("status", Json::Str(s.to_string()))])
}

fn ensure_schema(db: &mut Db) -> Result<(), Error> {
    db.execute(
        "CREATE TABLE IF NOT EXISTS events (
            id TEXT PRIMARY KEY,
            subscription TEXT NOT NULL,
            seq INTEGER NOT NULL,
            type TEXT NOT NULL,
            status TEXT NOT NULL
        )",
        &[],
    )?;
    db.execute(
        "CREATE TABLE IF NOT EXISTS subs (
            id TEXT PRIMARY KEY,
            state TEXT NOT NULL,
            seq INTEGER NOT NULL
        )",
        &[],
    )?;
    db.execute(
        "CREATE TABLE IF NOT EXISTS history (
            sub TEXT NOT NULL,
            n INTEGER NOT NULL,
            state TEXT NOT NULL,
            PRIMARY KEY (sub, n)
        )",
        &[],
    )?;
    Ok(())
}

fn transition(event_type: &str, from: &str) -> Option<Str> {
    match event_type {
        "subscription.created" => {
            if from == "none" { Some("created".to_string()) } else { None }
        }
        "subscription.activated" => {
            if from == "created" || from == "past_due" { Some("active".to_string()) } else { None }
        }
        "payment.failed" => {
            if from == "active" { Some("past_due".to_string()) } else { None }
        }
        "subscription.canceled" => {
            if from == "created" || from == "active" || from == "past_due" {
                Some("canceled".to_string())
            } else {
                None
            }
        }
        _ => None,
    }
}

fn load_sub(db: &mut Db, sub: &str) -> Result<(Str, i64), Error> {
    let rows = db.query(
        "SELECT state, seq FROM subs WHERE id = ?1",
        &[Value::Text(sub.to_string())],
    )?;
    if rows.len() == 0 {
        Ok(("none".to_string(), 0))
    } else {
        let st = rows[0].get_text(0)?;
        let sq = rows[0].get_int(1)?;
        Ok((st, sq))
    }
}

fn apply_one(
    db: &mut Db,
    log: &mut Log,
    sub: &str,
    event_id: &str,
    event_type: &str,
    seq: i64,
    state: &Str,
) -> Result<Str, Error> {
    let mut new_state = state.clone();
    match transition(event_type, state) {
        Some(next) => {
            let cnt = db.query(
                "SELECT COUNT(*) FROM history WHERE sub = ?1",
                &[Value::Text(sub.to_string())],
            )?;
            let n = cnt[0].get_int(0)?;
            db.execute(
                "INSERT INTO history (sub, n, state) VALUES (?1, ?2, ?3)",
                &[Value::Text(sub.to_string()), Value::Int(n + 1), Value::Text(next.clone())],
            )?;
            new_state = next;
        }
        None => {
            log.append(&format!("invalid transition {}", event_id))?;
        }
    }
    db.execute(
        "INSERT INTO subs (id, state, seq) VALUES (?1, ?2, ?3)
         ON CONFLICT(id) DO UPDATE SET state = excluded.state, seq = excluded.seq",
        &[Value::Text(sub.to_string()), Value::Text(new_state.clone()), Value::Int(seq)],
    )?;
    Ok(new_state)
}

fn read_secret(secrets: &Dir) -> Result<Vec<u8>, Error> {
    let mut key = secrets.read("webhook.key")?;
    if key.len() > 0 && key[key.len() - 1] == b'\n' {
        key.pop();
        if key.len() > 0 && key[key.len() - 1] == b'\r' {
            key.pop();
        }
    }
    Ok(key)
}

fn signature_ok(req: &Incoming, secret: &[u8], body: &[u8]) -> bool {
    let header = match req.header("x-signature") {
        Some(h) => h,
        None => return false,
    };
    let h = header.trim();
    if !h.starts_with("sha256=") {
        return false;
    }
    let given = &h[7..];
    let mut msg: Vec<u8> = Vec::new();
    msg.extend_from_slice(secret);
    msg.push(b'.');
    msg.extend_from_slice(body);
    let expected = hex_lower(&sha256(&msg));
    constant_time_eq(given.as_bytes(), expected.as_bytes())
}

fn handle_webhook(
    req: &mut Incoming,
    res: &mut Outgoing,
    db: &mut Db,
    secrets: &Dir,
    log: &mut Log,
) -> Result<Str, Error> {
    let body = req.body()?;
    let secret = read_secret(secrets)?;
    if !signature_ok(req, &secret, &body) {
        log.append("rejected signature")?;
        return reply(res, 401, err_obj("bad signature"));
    }

    let parsed = match json::parse_bytes(&body) {
        Ok(v) => v,
        Err(_) => return reply(res, 400, err_obj("invalid event")),
    };
    let obj = match parsed.as_object() {
        Some(o) => o,
        None => return reply(res, 400, err_obj("invalid event")),
    };
    let id = match obj.get("id").and_then(|v| v.as_str()) {
        Some(s) => s.to_string(),
        None => return reply(res, 400, err_obj("invalid event")),
    };
    let event_type = match obj.get("type").and_then(|v| v.as_str()) {
        Some(s) => s.to_string(),
        None => return reply(res, 400, err_obj("invalid event")),
    };
    if event_type != "subscription.created"
        && event_type != "subscription.activated"
        && event_type != "payment.failed"
        && event_type != "subscription.canceled"
    {
        return reply(res, 400, err_obj("invalid event"));
    }
    let sub = match obj.get("subscription").and_then(|v| v.as_str()) {
        Some(s) => s.to_string(),
        None => return reply(res, 400, err_obj("invalid event")),
    };
    let seq = match obj.get("seq").and_then(|v| v.as_i64()) {
        Some(n) => n,
        None => return reply(res, 400, err_obj("invalid event")),
    };
    if seq < 1 {
        return reply(res, 400, err_obj("invalid event"));
    }

    db.execute("BEGIN IMMEDIATE", &[])?;
    let result = process_event(db, log, &id, &event_type, &sub, seq);
    match result {
        Ok((code, body)) => {
            db.execute("COMMIT", &[])?;
            reply(res, code, body)
        }
        Err(e) => {
            let _ = db.execute("ROLLBACK", &[]);
            Err(e)
        }
    }
}

fn process_event(
    db: &mut Db,
    log: &mut Log,
    id: &str,
    event_type: &str,
    sub: &str,
    seq: i64,
) -> Result<(u16, Json), Error> {
    let dup = db.query(
        "SELECT 1 FROM events WHERE id = ?1",
        &[Value::Text(id.to_string())],
    )?;
    if dup.len() > 0 {
        return Ok((200, status_obj("duplicate")));
    }

    let (state, last) = load_sub(db, sub)?;

    if seq <= last {
        db.execute(
            "INSERT INTO events (id, subscription, seq, type, status) VALUES (?1, ?2, ?3, ?4, 'stale')",
            &[
                Value::Text(id.to_string()),
                Value::Text(sub.to_string()),
                Value::Int(seq),
                Value::Text(event_type.to_string()),
            ],
        )?;
        return Ok((200, status_obj("stale")));
    }

    if seq > last + 1 {
        db.execute(
            "INSERT INTO events (id, subscription, seq, type, status) VALUES (?1, ?2, ?3, ?4, 'queued')",
            &[
                Value::Text(id.to_string()),
                Value::Text(sub.to_string()),
                Value::Int(seq),
                Value::Text(event_type.to_string()),
            ],
        )?;
        return Ok((202, status_obj("queued")));
    }

    // seq == last + 1: apply now
    db.execute(
        "INSERT INTO events (id, subscription, seq, type, status) VALUES (?1, ?2, ?3, ?4, 'applied')",
        &[
            Value::Text(id.to_string()),
            Value::Text(sub.to_string()),
            Value::Int(seq),
            Value::Text(event_type.to_string()),
        ],
    )?;
    let mut cur_state = apply_one(db, log, sub, id, event_type, seq, &state)?;
    let mut cur_seq = seq;
    let mut applied: i64 = 1;

    loop {
        let next = cur_seq + 1;
        let rows = db.query(
            "SELECT id, type FROM events
             WHERE subscription = ?1 AND seq = ?2 AND status = 'queued'
             ORDER BY rowid LIMIT 1",
            &[Value::Text(sub.to_string()), Value::Int(next)],
        )?;
        if rows.len() == 0 {
            break;
        }
        let qid = rows[0].get_text(0)?;
        let qtype = rows[0].get_text(1)?;
        db.execute(
            "UPDATE events SET status = 'applied' WHERE id = ?1",
            &[Value::Text(qid.clone())],
        )?;
        cur_state = apply_one(db, log, sub, &qid, &qtype, next, &cur_state)?;
        cur_seq = next;
        applied = applied + 1;
    }

    // Any other queued events whose seq is now used up become stale.
    db.execute(
        "UPDATE events SET status = 'stale'
         WHERE subscription = ?1 AND status = 'queued' AND seq <= ?2",
        &[Value::Text(sub.to_string()), Value::Int(cur_seq)],
    )?;

    Ok((
        200,
        json::object(vec![
            ("status", Json::Str("applied".to_string())),
            ("applied", Json::Int(applied)),
        ]),
    ))
}

fn handle_get_sub(res: &mut Outgoing, db: &mut Db, sub: &str) -> Result<Str, Error> {
    let rows = db.query(
        "SELECT state, seq FROM subs WHERE id = ?1",
        &[Value::Text(sub.to_string())],
    )?;
    if rows.len() == 0 {
        return reply(res, 404, err_obj("not found"));
    }
    let state = rows[0].get_text(0)?;
    let seq = rows[0].get_int(1)?;
    let hrows = db.query(
        "SELECT state FROM history WHERE sub = ?1 ORDER BY n ASC",
        &[Value::Text(sub.to_string())],
    )?;
    let mut history: Vec<Json> = Vec::new();
    for r in hrows.iter() {
        history.push(Json::Str(r.get_text(0)?));
    }
    reply(
        res,
        200,
        json::object(vec![
            ("id", Json::Str(sub.to_string())),
            ("state", Json::Str(state)),
            ("seq", Json::Int(seq)),
            ("history", Json::Array(history)),
        ]),
    )
}

fn main(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<Str, Error> {
    let mut req = req;
    let mut res = res;
    let mut db = db;
    let mut log = log;
    ensure_schema(&mut db)?;

    let method = req.method().to_string();
    let full_path = req.path().to_string();
    let path = match full_path.find('?') {
        Some(i) => full_path[..i].to_string(),
        None => full_path.clone(),
    };

    if method == "POST" && path == "/webhooks" {
        return handle_webhook(&mut req, &mut res, &mut db, &secrets, &mut log);
    }

    if method == "GET" && path.starts_with("/subscriptions/") {
        let id = &path["/subscriptions/".len()..];
        if id.len() > 0 && !id.contains('/') {
            return handle_get_sub(&mut res, &mut db, id);
        }
    }

    reply(&mut res, 404, err_obj("not found"))
}

use kio::http::{Incoming, Outgoing};
use kio::db::{Db, Value};
use kio::fs::Dir;
use kio::log::Log;
use kio::json::{self, Json};
use kio::crypto::{sha256, hex_lower, constant_time_eq};

fn err_obj(msg: Str) -> Json {
    json::object(vec![("error", Json::Str(msg))])
}

fn status_obj(s: Str) -> Json {
    json::object(vec![("status", Json::Str(s))])
}

fn transition(event_type: Str, from: Str) -> Option<Str> {
    if event_type == "subscription.created" {
        if from == "none" { return Some("created".to_string()); }
        return None;
    }
    if event_type == "subscription.activated" {
        if from == "created" || from == "past_due" { return Some("active".to_string()); }
        return None;
    }
    if event_type == "payment.failed" {
        if from == "active" { return Some("past_due".to_string()); }
        return None;
    }
    if event_type == "subscription.canceled" {
        if from == "created" || from == "active" || from == "past_due" {
            return Some("canceled".to_string());
        }
        return None;
    }
    None
}

fn valid_type(t: Str) -> bool {
    t == "subscription.created"
        || t == "subscription.activated"
        || t == "payment.failed"
        || t == "subscription.canceled"
}

fn parse_event(body: Vec<u8>) -> Option<(Str, Str, Str, i64)> {
    let parsed = match json::parse_bytes(body) {
        Ok(v) => v,
        Err(_) => return None,
    };
    let obj = match parsed.as_object() {
        Some(o) => o,
        None => return None,
    };
    let id = match obj.get("id") {
        Some(Json::Str(s)) => s.clone(),
        _ => return None,
    };
    let event_type = match obj.get("type") {
        Some(Json::Str(s)) => s.clone(),
        _ => return None,
    };
    if !valid_type(event_type.clone()) {
        return None;
    }
    let sub = match obj.get("subscription") {
        Some(Json::Str(s)) => s.clone(),
        _ => return None,
    };
    let seq = match obj.get("seq") {
        Some(Json::Int(n)) => n.clone(),
        _ => return None,
    };
    if seq < 1 {
        return None;
    }
    Some((id, event_type, sub, seq))
}

fn main(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<Str, Error> {
    let mut req = req;
    let mut res = res;
    let mut db = db;
    let mut log = log;

    db.execute(
        "CREATE TABLE IF NOT EXISTS events (
            id TEXT PRIMARY KEY,
            subscription TEXT NOT NULL,
            seq INTEGER NOT NULL,
            type TEXT NOT NULL,
            status TEXT NOT NULL
        )",
        vec![],
    )?;
    db.execute(
        "CREATE TABLE IF NOT EXISTS subs (
            id TEXT PRIMARY KEY,
            state TEXT NOT NULL,
            seq INTEGER NOT NULL
        )",
        vec![],
    )?;
    db.execute(
        "CREATE TABLE IF NOT EXISTS history (
            sub TEXT NOT NULL,
            n INTEGER NOT NULL,
            state TEXT NOT NULL,
            PRIMARY KEY (sub, n)
        )",
        vec![],
    )?;

    let method = req.method().to_string();
    let path = req.path().to_string();

    let mut code: u16 = 404;
    let mut out: Json = err_obj("not found".to_string());

    if method == "POST" && path == "/webhooks" {
        let body: Vec<u8> = req.body()?;
        let mut secret: Vec<u8> = secrets.read("webhook.key")?;
        if secret.len() > 0 && secret[secret.len() - 1] == b'\n' {
            secret.pop();
            if secret.len() > 0 && secret[secret.len() - 1] == b'\r' {
                secret.pop();
            }
        }
        let mut msg: Vec<u8> = Vec::new();
        for b in secret.iter() {
            msg.push(b.clone());
        }
        msg.push(b'.');
        for b in body.iter() {
            msg.push(b.clone());
        }
        let expected: Str = format!("sha256={}", hex_lower(sha256(msg)));
        let sig_ok = match req.header("x-signature") {
            Some(h) => {
                let given: Str = h.trim().to_string();
                constant_time_eq(given.into_bytes(), expected.clone().into_bytes())
            }
            None => false,
        };

        if !sig_ok {
            log.append("rejected signature".to_string())?;
            code = 401;
            out = err_obj("bad signature".to_string());
        } else {
            match parse_event(body) {
                None => {
                    code = 400;
                    out = err_obj("invalid event".to_string());
                }
                Some((id, event_type, sub, seq)) => {
                    db.execute("BEGIN IMMEDIATE", vec![])?;

                    let dup = db.query(
                        "SELECT 1 FROM events WHERE id = ?1",
                        vec![Value::Text(id.clone())],
                    )?;
                    if dup.len() > 0 {
                        code = 200;
                        out = status_obj("duplicate".to_string());
                    } else {
                        let srows = db.query(
                            "SELECT state, seq FROM subs WHERE id = ?1",
                            vec![Value::Text(sub.clone())],
                        )?;
                        let mut state: Str = "none".to_string();
                        let mut last: i64 = 0;
                        if srows.len() > 0 {
                            state = srows[0].get_text(0)?;
                            last = srows[0].get_int(1)?;
                        }

                        if seq <= last {
                            db.execute(
                                "INSERT INTO events (id, subscription, seq, type, status) VALUES (?1, ?2, ?3, ?4, 'stale')",
                                vec![
                                    Value::Text(id.clone()),
                                    Value::Text(sub.clone()),
                                    Value::Int(seq),
                                    Value::Text(event_type.clone()),
                                ],
                            )?;
                            code = 200;
                            out = status_obj("stale".to_string());
                        } else if seq > last + 1 {
                            db.execute(
                                "INSERT INTO events (id, subscription, seq, type, status) VALUES (?1, ?2, ?3, ?4, 'queued')",
                                vec![
                                    Value::Text(id.clone()),
                                    Value::Text(sub.clone()),
                                    Value::Int(seq),
                                    Value::Text(event_type.clone()),
                                ],
                            )?;
                            code = 202;
                            out = status_obj("queued".to_string());
                        } else {
                            db.execute(
                                "INSERT INTO events (id, subscription, seq, type, status) VALUES (?1, ?2, ?3, ?4, 'applied')",
                                vec![
                                    Value::Text(id.clone()),
                                    Value::Text(sub.clone()),
                                    Value::Int(seq),
                                    Value::Text(event_type.clone()),
                                ],
                            )?;

                            let hc = db.query(
                                "SELECT COUNT(*) FROM history WHERE sub = ?1",
                                vec![Value::Text(sub.clone())],
                            )?;
                            let mut hist_n: i64 = hc[0].get_int(0)?;

                            let mut cur_id: Str = id.clone();
                            let mut cur_type: Str = event_type.clone();
                            let mut cur_seq: i64 = seq;
                            let mut applied: i64 = 0;

                            loop {
                                match transition(cur_type.clone(), state.clone()) {
                                    Some(next) => {
                                        hist_n = hist_n + 1;
                                        db.execute(
                                            "INSERT INTO history (sub, n, state) VALUES (?1, ?2, ?3)",
                                            vec![
                                                Value::Text(sub.clone()),
                                                Value::Int(hist_n),
                                                Value::Text(next.clone()),
                                            ],
                                        )?;
                                        state = next;
                                    }
                                    None => {
