                                }
                                cur_id = rows[0].get_text(0)?;
                                cur_type = rows[0].get_text(1)?;
                                cur_seq = nseq;
                                db.execute(
                                    "UPDATE events SET status = 'applied' WHERE id = ?1",
                                    vec![Value::Text(cur_id.clone())],
                                )?;
                            }

                            db.execute(
                                "UPDATE events SET status = 'stale'
                                 WHERE subscription = ?1 AND status = 'queued' AND seq <= ?2",
                                vec![Value::Text(sub.clone()), Value::Int(cur_seq)],
                            )?;

                            code = 200;
                            out = json::object(vec![
                                ("status", Json::Str("applied".to_string())),
                                ("applied", Json::Int(applied)),
                            ]);
                        }
                    }

                    db.execute("COMMIT", vec![])?;
                }
            }
        }
    } else if method == "GET" {
        match path.strip_prefix("/subscriptions/") {
            Some(rest) => {
                let id: Str = rest.to_string();
