    res.send(text.clone().into_bytes())?;
    Ok(text)
}

use kio::http::{Incoming, Outgoing};
use kio::db::{Db, Value};
use kio::fs::Dir;
use kio::log::Log;
use kio::json::{self, Json};
use kio::crypto::{sha256, hex_lower, constant_time_eq};

fn err_obj(msg: Str) -> Json {
    json::object(vec![("error", Json::Str(msg))])
}

fn status_obj(s: Str) -> Json {
    json::object(vec![("status", Json::Str(s))])
}

fn transition(event_type: Str, from: Str) -> Option<Str> {
    if event_type == "subscription.created" {
        if from == "none" { return Some("created".to_string()); }
        return None;
    }
    if event_type == "subscription.activated" {
        if from == "created" || from == "past_due" { return Some("active".to_string()); }
        return None;
    }
    if event_type == "payment.failed" {
        if from == "active" { return Some("past_due".to_string()); }
        return None;
    }
    if event_type == "subscription.canceled" {
        if from == "created" || from == "active" || from == "past_due" {
            return Some("canceled".to_string());
        }
        return None;
    }
    None
}

fn valid_type(t: Str) -> bool {
    t == "subscription.created"
        || t == "subscription.activated"
        || t == "payment.failed"
        || t == "subscription.canceled"
}

fn parse_event(body: Vec<u8>) -> Option<(Str, Str, Str, i64)> {
    let parsed = match json::parse_bytes(body) {
        Ok(v) => v,
        Err(_) => return None,
    };
    let obj = match parsed.as_object() {
        Some(o) => o,
        None => return None,
    };
    let id = match obj.get("id") {
        Some(Json::Str(s)) => s.clone(),
        _ => return None,
    };
    let event_type = match obj.get("type") {
        Some(Json::Str(s)) => s.clone(),
        _ => return None,
    };
    if !valid_type(event_type.clone()) {
        return None;
    }
    let sub = match obj.get("subscription") {
        Some(Json::Str(s)) => s.clone(),
        _ => return None,
    };
    let seq = match obj.get("seq") {
        Some(Json::Int(n)) => n.clone(),
        _ => return None,
    };
    if seq < 1 {
        return None;
    }
    Some((id, event_type, sub, seq))
}

fn main(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<Str, Error> {
