fn transition(event_type: Str, from: Str) -> Option<Str> {
    if event_type == "subscription.created" {
        if from == "none" { return Some("created".to_string()); }
        return None;
    }
    if event_type == "subscription.activated" {
        if from == "created" || from == "past_due" { return Some("active".to_string()); }
        return None;
    }
    if event_type == "payment.failed" {
        if from == "active" { return Some("past_due".to_string()); }
        return None;
    }
    if event_type == "subscription.canceled" {
        if from == "created" || from == "active" || from == "past_due" {
            return Some("canceled".to_string());
        }
        return None;
    }
    None
}

fn valid_type(t: Str) -> bool {
    t == "subscription.created"
        || t == "subscription.activated"
        || t == "payment.failed"
        || t == "subscription.canceled"
}

fn parse_event(body: Vec<u8>) -> Option<(Str, Str, Str, i64)> {
    let parsed = match json::parse_bytes(body) {
        Ok(v) => v,
        Err(_) => return None,
    };
    let obj = match parsed.as_object() {
        Some(o) => o,
        None => return None,
    };
    let id = match obj.get("id") {
        Some(json::Json::Str(s)) => s.clone(),
        _ => return None,
    };
    let event_type = match obj.get("type") {
        Some(json::Json::Str(s)) => s.clone(),
        _ => return None,
    };
    if !valid_type(event_type.clone()) {
        return None;
    }
    let sub = match obj.get("subscription") {
        Some(json::Json::Str(s)) => s.clone(),
        _ => return None,
    };
    let seq = match obj.get("seq") {
        Some(json::Json::Int(n)) => n.clone(),
        _ => return None,
    };
    if seq < 1 {
        return None;
    }
    Some((id, event_type, sub, seq))
}

fn main(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<Str, Error> {
    let mut req = req;
    let mut res = res;
    let mut db = db;
    let mut log = log;

    db.execute(
        "CREATE TABLE IF NOT EXISTS events (
            id TEXT PRIMARY KEY,
            subscription TEXT NOT NULL,
            seq INTEGER NOT NULL,
            type TEXT NOT NULL,
            status TEXT NOT NULL
        )",
        [],
    )?;
    db.execute(
        "CREATE TABLE IF NOT EXISTS subs (
            id TEXT PRIMARY KEY,
            state TEXT NOT NULL,
            seq INTEGER NOT NULL
        )",
        [],
    )?;
    db.execute(
        "CREATE TABLE IF NOT EXISTS history (
            sub TEXT NOT NULL,
            n INTEGER NOT NULL,
            state TEXT NOT NULL,
            PRIMARY KEY (sub, n)
        )",
        [],
    )?;

    let method = req.method().to_string();
    let path = req.path().to_string();

    let mut code: u16 = 404;
    let mut out: json::Json = err_obj("not found".to_string());

    let nl: u8 = 10;
    let cr: u8 = 13;
    let dot: u8 = 46;

    if method == "POST" && path == "/webhooks" {
        let body: Vec<u8> = req.body()?;
        let mut secret: Vec<u8> = secrets.read("webhook.key")?;
        if secret.len() > 0 && secret[secret.len() - 1] == nl {
            secret.pop();
            if secret.len() > 0 && secret[secret.len() - 1] == cr {
                secret.pop();
            }
        }
        let mut msg: Vec<u8> = Vec::new();
        for b in secret.iter() {
            msg.push(b.clone());
        }
        msg.push(dot);
        for b in body.iter() {
            msg.push(b.clone());
        }
        let expected: Str = "sha256=".to_string() + crypto::hex_lower(crypto::sha256(msg));
        let sig_ok = match req.header("x-signature") {
            Some(h) => {
                let given: Str = h.trim().to_string();
                crypto::constant_time_eq(given.into_bytes(), expected.clone().into_bytes())
            }
            None => false,
        };

        if !sig_ok {
            log.append("rejected signature".to_string())?;
            code = 401;
            out = err_obj("bad signature".to_string());
        } else {
            match parse_event(body) {
                None => {
                    code = 400;
                    out = err_obj("invalid event".to_string());
                }
                Some((id, event_type, sub, seq)) => {
                    db.execute("BEGIN IMMEDIATE", [])?;

                    let dup = db.query(
                        "SELECT 1 FROM events WHERE id = ?1",
                        [db::Value::Text(id.clone())],
                    )?;
                    if dup.len() > 0 {
                        code = 200;
                        out = status_obj("duplicate".to_string());
                    } else {
                        let srows = db.query(
                            "SELECT state, seq FROM subs WHERE id = ?1",
                            [db::Value::Text(sub.clone())],
                        )?;
                        let mut state: Str = "none".to_string();
                        let mut last: i64 = 0;
                        if srows.len() > 0 {
                            state = srows[0].get_text(0)?;
                            last = srows[0].get_int(1)?;
                        }

                        if seq <= last {
                            db.execute(
                                "INSERT INTO events (id, subscription, seq, type, status) VALUES (?1, ?2, ?3, ?4, 'stale')",
                                [
                                    db::Value::Text(id.clone()),
                                    db::Value::Text(sub.clone()),
                                    db::Value::Int(seq),
                                    db::Value::Text(event_type.clone()),
                                ],
                            )?;
                            code = 200;
                            out = status_obj("stale".to_string());
                        } else if seq > last + 1 {
                            db.execute(
                                "INSERT INTO events (id, subscription, seq, type, status) VALUES (?1, ?2, ?3, ?4, 'queued')",
                                [
                                    db::Value::Text(id.clone()),
                                    db::Value::Text(sub.clone()),
                                    db::Value::Int(seq),
                                    db::Value::Text(event_type.clone()),
                                ],
                            )?;
                            code = 202;
                            out = status_obj("queued".to_string());
                        } else {
                            db.execute(
                                "INSERT INTO events (id, subscription, seq, type, status) VALUES (?1, ?2, ?3, ?4, 'applied')",
                                [
                                    db::Value::Text(id.clone()),
                                    db::Value::Text(sub.clone()),
                                    db::Value::Int(seq),
                                    db::Value::Text(event_type.clone()),
                                ],
                            )?;

                            let hc = db.query(
                                "SELECT COUNT(*) FROM history WHERE sub = ?1",
                                [db::Value::Text(sub.clone())],
                            )?;
                            let mut hist_n: i64 = hc[0].get_int(0)?;

                            let mut cur_id: Str = id.clone();
                            let mut cur_type: Str = event_type.clone();
                            let mut cur_seq: i64 = seq;
                            let mut applied: i64 = 0;

                            loop {
                                match transition(cur_type.clone(), state.clone()) {
                                    Some(next) => {
                                        hist_n = hist_n + 1;
                                        db.execute(
                                            "INSERT INTO history (sub, n, state) VALUES (?1, ?2, ?3)",
                                            [
                                                db::Value::Text(sub.clone()),
                                                db::Value::Int(hist_n),
                                                db::Value::Text(next.clone()),
                                            ],
                                        )?;
                                        state = next;
                                    }
                                    None => {
                                        log.append("invalid transition ".to_string() + cur_id.clone())?;
                                    }
                                }
                                applied = applied + 1;
                                db.execute(
                                    "INSERT INTO subs (id, state, seq) VALUES (?1, ?2, ?3)
                                     ON CONFLICT(id) DO UPDATE SET state = excluded.state, seq = excluded.seq",
                                    [
                                        db::Value::Text(sub.clone()),
                                        db::Value::Text(state.clone()),
                                        db::Value::Int(cur_seq),
                                    ],
                                )?;

                                let nseq = cur_seq + 1;
                                let rows = db.query(
                                    "SELECT id, type FROM events
                                     WHERE subscription = ?1 AND seq = ?2 AND status = 'queued'
                                     ORDER BY rowid LIMIT 1",
                                    [db::Value::Text(sub.clone()), db::Value::Int(nseq)],
                                )?;
                                if rows.len() == 0 {
                                    break;
                                }
                                cur_id = rows[0].get_text(0)?;
                                cur_type = rows[0].get_text(1)?;
                                cur_seq = nseq;
                                db.execute(
                                    "UPDATE events SET status = 'applied' WHERE id = ?1",
                                    [db::Value::Text(cur_id.clone())],
                                )?;
                            }

                            db.execute(
                                "UPDATE events SET status = 'stale'
                                 WHERE subscription = ?1 AND status = 'queued' AND seq <= ?2",
                                [db::Value::Text(sub.clone()), db::Value::Int(cur_seq)],
                            )?;

                            code = 200;
                            out = json::object([
                                ("status", json::Json::Str("applied".to_string())),
                                ("applied", json::Json::Int(applied)),
                            ]);
                        }
                    }

                    db.execute("COMMIT", [])?;
                }
            }
        }
    } else if method == "GET" {
        match path.strip_prefix("/subscriptions/") {
            Some(rest) => {
                let id: Str = rest.to_string();
                if id.len() > 0 && !id.contains("/") {
                    let rows = db.query(
                        "SELECT state, seq FROM subs WHERE id = ?1",
                        [db::Value::Text(id.clone())],
                    )?;
                    if rows.len() > 0 {
                        let state = rows[0].get_text(0)?;
                        let seq = rows[0].get_int(1)?;
                        let hrows = db.query(
                            "SELECT state FROM history WHERE sub = ?1 ORDER BY n ASC",
                            [db::Value::Text(id.clone())],
                        )?;
                        let mut history: Vec<json::Json> = Vec::new();
                        for r in hrows.iter() {
                            history.push(json::Json::Str(r.get_text(0)?));
                        }
                        code = 200;
                        out = json::object([
                            ("id", json::Json::Str(id.clone())),
                            ("state", json::Json::Str(state)),
                            ("seq", json::Json::Int(seq)),
                            ("history", json::Json::Array(history)),
                        ]);
                    }
                }
            }
            None => {}
        }
    }

    let text: Str = json::to_string(out);
    res.status(code);
    res.header("content-type", "application/json");
    res.send(text.clone().into_bytes())?;
    Ok(text)
}
